const PIN_SESSION_KEY = "boa_hr_current_user_v1";
const APP_USERS_KEY = "boa_app_users_v1";

// Live PIN → user record store. Seeded from STAFF_USERS on first boot, then
// edited via the Settings tab. A copy is kept in window.__BOA_APP_USERS so
// the activity-log / sign-in helpers can resolve names without re-fetching.
// Returns the stored user map, or null ONLY when the query genuinely succeeds
// with no row (true first run). THROWS on any read failure (Supabase paused /
// network blip / client not ready) — the caller must be able to tell "read
// failed" apart from "no users", because the two used to look identical (both
// null) and a failed read was wrongly treated as first-run, re-seeding the
// built-in defaults OVER the real user list. That is exactly how every
// Settings-added login got wiped during a Supabase outage.
async function loadAppUsersFromDb() {
  if (!window.BOA_DB || !window.BOA_DB.sb) throw new Error("Supabase client not ready");
  const r = await window.BOA_DB.sb.from("app_state").select("value").eq("key", APP_USERS_KEY).maybeSingle();
  if (r.error) throw r.error;                              // read failed — do NOT treat as empty
  const v = r.data && r.data.value;
  if (v && typeof v === "object" && !Array.isArray(v)) return v;
  return null;                                             // query OK, no/empty row → genuine first run
}
async function saveAppUsersToDb(users) {
  if (!window.BOA_DB || !window.BOA_DB.sb) throw new Error("Supabase not ready");
  await window.BOA_DB.sb.from("app_state").upsert({ key: APP_USERS_KEY, value: users || {} });
}
function lookupUserByPin(pin) {
  if (window.__BOA_APP_USERS && window.__BOA_APP_USERS[pin]) return window.__BOA_APP_USERS[pin];
  return STAFF_USERS[pin] || null;
}

// ─── SUNDAY ROTATION PARITY ─────────────────────────────────────────────────
// The auto-fill / sync algorithms split nail techs into groups A and B and
// alternate which group is off each Sunday. Originally the parity was
// derived from `wIdx % 2` (the week's index inside the current cycle),
// which broke at every cycle boundary: the last Sunday of one month and
// the first Sunday of the next could both land on the same parity, so a
// tech ended up off two Sundays in a row (or working two in a row).
// This helper anchors the rotation to the Sunday's calendar date instead,
// so the alternation stays consistent across cycles, partial weeks, and
// re-runs of auto-fill.
function sundayDateParity(sundayDay) {
  if (!sundayDay) return "A";
  const ms = Date.UTC(sundayDay.year, sundayDay.monthIdx, sundayDay.d);
  const weeks = Math.floor(ms / (7 * 86400000));
  return (weeks % 2 === 0) ? "A" : "B";
}
// Convenience: take a week (array of day objects) and return the off-group
// for that week's Sunday. If the week has no Sunday (unusual partial week),
// returns null and the caller should skip Sunday rotation for that week.
function weekSundayOffGroup(week) {
  if (!week || !week.length) return null;
  const sun = week.find(d => d.dow === 0);
  if (!sun) return null;
  return sundayDateParity(sun);
}

// Demo-mode shim: when a `demo:true` user is signed in we replace every
// persistence method on window.BOA_DB with a no-op so changes never reach the
// server. Local React state still updates, so the user can practice editing
// staff / attendance / schedules — but a page reload wipes their changes.
function installDemoMode() {
  const apply = () => {
    if (!window.BOA_DB) { setTimeout(apply, 100); return; }
    if (window.__BOA_DEMO_INSTALLED) return;
    window.__BOA_DEMO_INSTALLED = true;
    let demoSeed = 900000;
    const passthrough = async (arg) => {
      if (arg && typeof arg === "object" && !Array.isArray(arg) && arg._id === undefined) {
        return { ...arg, _id: ++demoSeed };
      }
      return arg;
    };
    const noop = async () => { };
    ["saveStaff", "saveMat", "saveManager"].forEach(n => { window.BOA_DB[n] = passthrough; });
    ["saveSchedule", "saveAttendance", "saveAttendanceUndo", "clearAttendanceUndo", "saveEarlyLeaves", "saveOnboarding", "saveOffboarding",
      "saveLeaveRecords", "saveMgrRequests", "saveManagerPins", "saveOfficeHoursReview",
      "deleteMat", "deleteManager", "deleteSchedule", "appendActivity"
    ].forEach(n => { window.BOA_DB[n] = noop; });
  };
  apply();
}

// Per-tab read-only guard. Wraps every persistence call on window.BOA_DB
// once at boot. The wrappers consult `window.__BOA_RO_ACTIVE` (set by the
// App when the active tab is in the user's `readOnlyTabs` list); when the
// flag is true the call short-circuits with a friendly alert instead of
// hitting Supabase, so a user with view-only access can still see the
// edit UI but their changes never persist.
const READ_ONLY_GUARDED_METHODS = [
  "saveStaff", "saveMat", "saveManager", "saveSchedule", "saveAttendance", "saveEarlyLeaves",
  "saveOnboarding", "saveOffboarding", "saveLeaveRecords", "saveMgrRequests",
  "saveTechRequests", "saveManagerPins", "saveTrialPeriod", "saveInterviews", "deleteMat", "deleteManager", "deleteSchedule",
  "saveAttendanceUndo", "clearAttendanceUndo", "saveOfficeHoursReview"
];
function installReadOnlyGuard() {
  const apply = () => {
    if (!window.BOA_DB) { setTimeout(apply, 100); return; }
    if (window.__BOA_RO_INSTALLED) return;
    window.__BOA_RO_INSTALLED = true;
    window.__BOA_RO_ACTIVE = false;
    READ_ONLY_GUARDED_METHODS.forEach(n => {
      const fn = window.BOA_DB[n];
      if (typeof fn !== "function") return;
      const orig = fn.bind(window.BOA_DB);
      window.BOA_DB[n] = async (...args) => {
        if (window.__BOA_RO_ACTIVE) {
          alert("🔒 View-only access — your role can't make changes on this tab. Switching tabs lets you edit again where allowed.");
          return null;
        }
        return orig(...args);
      };
    });
  };
  apply();
}

// ─── HELPERS ────────────────────────────────────────────────────────────────────
// TODAY is the real current date, pinned to UTC midnight of the local
// calendar day so day-count maths against date-only strings (which parse as
// UTC midnight) come out as clean whole days. Previously this was hardcoded
// to a fixed date left over from development, which made every daysDiff()
// countdown (transfer ETAs, maternity returns, permit deadlines, …) read
// off the wrong "today".
const TODAY = (() => { const n = new Date(); return new Date(Date.UTC(n.getFullYear(), n.getMonth(), n.getDate())); })();
function daysDiff(d) { return d ? Math.ceil((new Date(d) - TODAY) / 86400000) : null; }
// Effective home branch on a given date (YYYY-MM-DD). A branch transfer is
// stored as flags (transferring/transferTo/transferDate) without rewriting the
// record's `branch`, so once the transfer date has arrived the stored branch is
// stale. Mirrors the "settle" rule used on Locations so a borrow/loan logged
// after a completed transfer attributes hours to the new home, not the old one.
function effHomeBranch(s, onDate) {
  if (!s) return "";
  if (s.transferring && s.transferTo && s.transferDate && onDate) {
    const td = String(s.transferDate).replace(/\//g, "-");
    if (td <= onDate) return s.transferTo;
  }
  return s.branch || "";
}
function fmt(d) { return d ? new Date(d).toLocaleDateString("en-ZA", { day: "2-digit", month: "short", year: "numeric" }) : "—"; }

// Catches a mistyped start-date YEAR (e.g. 2006 keyed instead of 2026, which
// showed up as "20 yrs tenure"). Returns a short human phrase to show in a
// confirm, or null when the date looks fine. `strict` is for new hires
// (onboarding) where the start should be around now; the looser default still
// flags dates that are implausible for anyone — well in the future, or so far
// back it's almost certainly a wrong year.
function startDateYearWarning(ymd, opts) {
  opts = opts || {};
  if (!ymd) return null;
  const d = new Date(ymd + "T00:00:00");
  if (isNaN(d.getTime())) return null;
  const yrs = (Date.now() - d.getTime()) / (365.25 * 86400000);
  const r = Math.abs(Math.round(yrs));
  if (yrs < -1.25) return "is about " + r + " year" + (r === 1 ? "" : "s") + " in the future";
  if (yrs > (opts.strict ? 1.25 : 15)) return "is about " + r + " years ago" + (opts.strict ? " — new starters begin around now" : "");
  return null;
}

// Compress an image File → JPEG data URL bounded by maxDim & quality.
// Matches the kiosk's helper of the same name so proof images stored
// from either side stay around the same KB envelope.
function compressImageDataUrl(file, maxDim, quality) {
  return new Promise((resolve, reject) => {
    if (!file || !file.type || file.type.indexOf("image/") !== 0) {
      reject(new Error("Only image files are accepted as proof.")); return;
    }
    const reader = new FileReader();
    reader.onerror = () => reject(new Error("Could not read file."));
    reader.onload = () => {
      const img = new Image();
      img.onerror = () => reject(new Error("Couldn't load image."));
      img.onload = () => {
        const ratio = Math.min((maxDim || 1600) / img.width, (maxDim || 1600) / img.height, 1);
        const w = Math.round(img.width * ratio), h = Math.round(img.height * ratio);
        const canvas = document.createElement("canvas");
        canvas.width = w; canvas.height = h;
        canvas.getContext("2d").drawImage(img, 0, 0, w, h);
        try { resolve(canvas.toDataURL("image/jpeg", quality || 0.8)); }
        catch (e) { reject(new Error("Could not compress image.")); }
      };
      img.src = reader.result;
    };
    reader.readAsDataURL(file);
  });
}

// Status options surfaced to ROMs when marking a manager's absence.
// Codes map straight onto STAT entries on the attendance grid so the
// reason renders the same colour & label that the tech statuses use.
const MGR_REASON_OPTIONS = [
  { code: "sick_n", label: "🤒 Sick + note", needsProof: true, needsNote: false, payroll: "Paid sick" },
  { code: "sick", label: "🤒 Sick NO note", needsProof: false, needsNote: false, payroll: "Unpaid sick" },
  { code: "frl", label: "👪 FRL + proof", needsProof: true, needsNote: false, payroll: "Paid Family Responsibility Leave" },
  { code: "absent", label: "🚫 Absent", needsProof: false, needsNote: true, payroll: "Unpaid" },
  { code: "no", label: "⛔ NO SHOW", needsProof: false, needsNote: false, payroll: "Unpaid" }
];
// ── Pay-cycle helpers (25th → 24th) — the ONE implementation for this file.
// Everything below (payrollYmFor, ymdToSchedYm, schedYmOf, the cycle-start
// computations) delegates here so a single rollover/anchor rule lives in one
// place. Kept file-local (pure date math, no dependency on the data layer's
// init). Companion copies: data.js (currentSchedYm), kiosk/data.js
// (ymForDate/scheduleDayToDate), myboa/cycle.js.
//   • END-month ym: the cycle is named by the month its 24th falls in, so a
//     day-of-month > 24 belongs to the NEXT calendar month's cycle.
//   • cycle-start date: the 25th that opens the cycle containing `d`.
function _rollToEndMonthYm(y, m, dom) {   // y, 1-indexed m, day-of-month → "YYYY-MM"
  if (dom > 24) { m += 1; if (m > 12) { m = 1; y += 1; } }
  return y + "-" + String(m).padStart(2, "0");
}
function _schedYmForYmd(ymd) {            // "YYYY-MM-DD" → END-month ym
  const [y, m, d] = ymd.split("-").map(Number);
  return _rollToEndMonthYm(y, m, d);
}
function _schedYmOfDate(dt) {             // Date → END-month ym
  return _rollToEndMonthYm(dt.getFullYear(), dt.getMonth() + 1, dt.getDate());
}
function _cycleStartDate(d) {             // Date → the 25th opening d's cycle
  return d.getDate() >= 25
    ? new Date(d.getFullYear(), d.getMonth(), 25)
    : new Date(d.getFullYear(), d.getMonth() - 1, 25);
}

// Payroll cycle (25th → 24th) helper. Used to lock editing for closed
// cycles so payroll figures don't shift after a run.
function payrollYmFor(ymd) {
  return _schedYmForYmd(ymd);
}

// Attendance grids (boa_att_<branch>_<ym>) are saved under the START-month ym
// of the 25th→24th cycle — 25 May → 24 Jun lives at "2026-05" — the opposite
// of payrollYmFor's end-month convention. Use this to look one up.
function attGridYmFor(ymd) {
  const [y, m, d] = ymd.split("-").map(Number);
  let yy = y, mm = m;
  if (d <= 24) { mm -= 1; if (mm < 1) { mm = 12; yy--; } }
  return yy + "-" + String(mm).padStart(2, "0");
}

// Modal body for marking / editing a manager's absence reason.
function MgrReasonModalBody({ modal, personStartDate, existing, locked, currentUserName, onClose, onSaved }) {
  const [status, setStatus] = useState(existing?.status || "");
  const [note, setNote] = useState(existing?.note || "");
  const [proof, setProof] = useState(existing?.proof || null);
  const [proofErr, setProofErr] = useState("");
  const [saving, setSaving] = useState(false);
  const opt = MGR_REASON_OPTIONS.find(o => o.code === status);
  const needsProof = !!(opt && opt.needsProof);
  const needsNote = !!(opt && opt.needsNote);
  const noteTrim = (note || "").trim();
  // For "Sick + note" specifically we no longer block save when there's
  // no proof — we just downgrade to "Sick NO note" (unpaid) on save.
  // FRL still requires its proof photo to qualify for paid Family
  // Responsibility Leave.
  const proofGate = !needsProof || !!proof || status === "sick_n";
  const canSave = !locked
    && !!status
    && proofGate
    && (!needsNote || noteTrim.length >= 3);
  const sickWillDowngrade = status === "sick_n" && !proof;

  async function handleFile(e) {
    setProofErr("");
    const file = e.target.files && e.target.files[0];
    if (!file) { setProof(null); return; }
    try { setProof(await compressImageDataUrl(file, 1600, 0.8)); }
    catch (err) { setProofErr(err.message || String(err)); setProof(null); }
  }

  async function save() {
    if (!canSave) return;
    // FRL gate — block paid Family Responsibility Leave when there are no days
    // left (or the person isn't eligible / can't be confirmed). The manager is
    // then steered to "Absent" (unpaid, with a note).
    if (status === "frl") {
      setSaving(true);
      const g = await frlMarkGuard({ ec: modal.ec, startDate: personStartDate, staffId: modal.staffId, isManager: true, branch: modal.branch, date: modal.date });
      setSaving(false);
      if (g.block) {
        if (window.confirm(g.message + "\n\nSwitch this to “Absent” (unpaid) now? You'll need to add a short note.")) setStatus("absent");
        return;
      }
    }
    setSaving(true);
    try {
      // "Sick + note" without a doctor's note → downgrade to "Sick NO
      // note" (unpaid). Keeps the absence on the manager's record but
      // doesn't burn a paid sick day without a medical certificate.
      const effectiveStatus = sickWillDowngrade ? "sick" : status;
      const effectiveProof = (sickWillDowngrade || !needsProof) ? null : proof;
      await window.BOA_DB.saveManagerDayStatus({
        staffId: modal.staffId,
        date: modal.date,
        status: effectiveStatus,
        note,
        proof: effectiveProof,
        recordedBy: currentUserName
      });
      await onSaved();
    } catch (e) {
      window.alert("Could not save: " + ((e && e.message) || e));
      setSaving(false);
    }
  }

  async function clearStatus() {
    if (!existing) return;
    if (locked) return;
    if (!window.confirm("Remove the recorded absence reason for this day?\n\nUse this when the schedule was corrected (e.g. day is actually OFF) and the tagged reason no longer applies.")) return;
    setSaving(true);
    try {
      await window.BOA_DB.deleteManagerDayStatus({ staffId: modal.staffId, date: modal.date });
      await onSaved();
    } catch (e) {
      window.alert("Could not clear: " + ((e && e.message) || e));
      setSaving(false);
    }
  }

  return (
    <div onClick={onClose} style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.6)", zIndex: 9999, display: "flex", alignItems: "center", justifyContent: "center", padding: 20 }}>
      <div onClick={e => e.stopPropagation()} style={{ background: "#fff", borderRadius: 16, padding: "20px 22px", width: "100%", maxWidth: 480, maxHeight: "90vh", overflow: "auto" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 10 }}>
          <div>
            <div style={{ fontFamily: "'Playfair Display',serif", fontSize: 19, color: "#831843", fontWeight: 700 }}>Mark absence reason</div>
            <div style={{ fontSize: 12, color: "#9ca3af" }}>{modal.name} · {modal.branch} · {new Date(modal.date + "T12:00:00").toLocaleDateString("en-ZA", { weekday: "short", day: "2-digit", month: "short", year: "numeric" })}</div>
          </div>
          <button onClick={onClose} style={{ background: "transparent", border: "none", fontSize: 22, cursor: "pointer", color: "#831843", lineHeight: 1 }}>×</button>
        </div>

        {locked && (
          <div style={{ marginTop: 12, background: "#fef3c7", border: "1px solid #fcd34d", color: "#92400e", borderRadius: 9, padding: "8px 10px", fontSize: 12 }}>
            🔒 This day is in a closed payroll cycle (25th → 24th). Ask an admin to override.
          </div>
        )}

        <div style={{ marginTop: 14, display: "grid", gridTemplateColumns: "1fr 1fr", gap: 6 }}>
          {MGR_REASON_OPTIONS.map(o => (
            <button key={o.code} disabled={locked}
              onClick={() => setStatus(o.code)}
              style={{
                padding: "9px 10px", borderRadius: 9, fontSize: 12, fontWeight: 700, cursor: locked ? "not-allowed" : "pointer",
                border: status === o.code ? "2px solid #BE185D" : "1px solid #FBCFE8",
                background: status === o.code ? "#FCE7F3" : "#fff",
                color: "#831843", textAlign: "left", opacity: locked ? 0.5 : 1
              }}>
              <div>{o.label}</div>
              <div style={{ fontSize: 10, color: "#9ca3af", fontWeight: 600, marginTop: 2 }}>{o.payroll}</div>
            </button>
          ))}
        </div>

        {needsProof && (
          <div style={{ marginTop: 14 }}>
            <label style={{ fontSize: 10, fontWeight: 800, color: "#F472B6", letterSpacing: "0.06em" }}>{opt.code === "sick_n" ? "DOCTOR'S NOTE (required for paid Sick + note)" : "PROOF PHOTO (required for FRL)"}</label>
            {/* No `capture="environment"` here — that attribute force-opens
                the camera on mobile, but ROMs usually already have the
                doctor's note in their photo library (forwarded by the
                manager via WhatsApp/email). Dropping it lets the mobile
                file picker offer both Camera and Photo Library options. */}
            <input type="file" accept="image/*" onChange={handleFile} disabled={locked}
              style={{ display: "block", marginTop: 4, fontSize: 13 }} />
            <div style={{ fontSize: 10, color: "#9ca3af", marginTop: 4, fontStyle: "italic" }}>📷 Take a new photo, or 🖼 pick one your phone already has — both work.</div>
            {proofErr && <div style={{ fontSize: 11, color: "#7f1d1d", marginTop: 4 }}>{proofErr}</div>}
            {proof && <img src={proof} alt="proof" style={{ marginTop: 8, maxWidth: "100%", maxHeight: 180, borderRadius: 8, border: "1px solid #FBCFE8", display: "block" }} />}
            {sickWillDowngrade && (
              <div style={{ marginTop: 8, background: "#fef3c7", border: "1px solid #fcd34d", color: "#92400e", borderRadius: 8, padding: "8px 10px", fontSize: 11, fontWeight: 600 }}>
                ⚠ No doctor's note uploaded — saving will mark this day as <strong>Sick NO note (unpaid)</strong> on the attendance sheet. Upload the medical certificate to keep it paid.
              </div>
            )}
          </div>
        )}

        <div style={{ marginTop: 14 }}>
          <label style={{ fontSize: 10, fontWeight: 800, color: needsNote ? "#7f1d1d" : "#F472B6", letterSpacing: "0.06em" }}>
            {needsNote ? "REASON (required for Absent)" : "NOTE (optional)"}
          </label>
          <textarea value={note} disabled={locked} onChange={e => setNote(e.target.value)} rows={2}
            placeholder={needsNote ? "Why was the manager absent? e.g. unauthorised, family emergency, no contact…" : "e.g. spoke to her Monday, flu — back Wed"}
            style={{ display: "block", width: "100%", marginTop: 4, padding: "8px 10px", borderRadius: 8, border: "1px solid " + (needsNote && noteTrim.length < 3 ? "#fca5a5" : "#FBCFE8"), fontSize: 13, fontFamily: "inherit", boxSizing: "border-box" }} />
        </div>

        {existing && (
          <div style={{ marginTop: 10, fontSize: 11, color: "#9ca3af" }}>
            Last updated by {existing.updated_by || existing.recorded_by || "?"} on {new Date(existing.updated_at || existing.created_at).toLocaleString("en-ZA", { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" })}
          </div>
        )}

        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8, marginTop: 16, flexWrap: "wrap" }}>
          <div>
            {existing && !locked && (
              <button onClick={clearStatus} disabled={saving}
                style={{ padding: "9px 14px", borderRadius: 9, border: "1px solid #fecaca", background: "#fff", color: "#7f1d1d", fontWeight: 700, fontSize: 12, cursor: saving ? "not-allowed" : "pointer" }}>
                🗑 Clear reason
              </button>
            )}
          </div>
          <div style={{ display: "flex", gap: 8 }}>
            <button onClick={onClose} style={{ padding: "9px 16px", borderRadius: 9, border: "1px solid #FBCFE8", background: "#fff", color: "#831843", fontWeight: 700, fontSize: 13, cursor: "pointer" }}>Cancel</button>
            <button onClick={save} disabled={!canSave || saving}
              style={{ padding: "9px 20px", borderRadius: 9, border: "none", background: canSave && !saving ? "#BE185D" : "#FBCFE8", color: "#fff", fontWeight: 700, fontSize: 13, cursor: canSave && !saving ? "pointer" : "not-allowed" }}>
              {saving ? "Saving…" : sickWillDowngrade ? "💾 Save as Sick NO note (unpaid)" : (existing ? "💾 Update" : "💾 Save reason")}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

// Sort by B-number: extract numeric part after "B", sort ascending; T-codes go after
function ecSort(a, b) {
  const parse = ec => {
    const m = String(ec).match(/^([A-Za-z]+)(\d+)/);
    if (!m) return [ec, 9999];
    return [m[1].toUpperCase(), parseInt(m[2], 10)];
  };
  const [al, an] = parse(a.ec);
  const [bl, bn] = parse(b.ec);
  if (al !== bl) return al < bl ? -1 : 1;
  return an - bn;
}

// ─── SCHEDULE EXPORT HELPERS (CSV / PDF) ─────────────────────────────────────
// Shared by the tech and manager schedule editors. Both editors hold their
// data as { ec → { dayKey → cellCode } } so a single set of helpers covers
// them — the caller passes columns (date headers) and rows (staff + values).
//
// CSV: a flat grid where each row is one staff member, columns are days.
//      A "WORKING TOTAL" row is appended so the spreadsheet shows coverage.
// PDF: opens a print-styled window with a colour-coded HTML table — the
//      user picks "Save as PDF" in their browser's print dialog. No extra
//      runtime dependency required.
function _csvEscape(v) {
  const s = (v == null) ? "" : String(v);
  if (/[",\n\r]/.test(s)) return '"' + s.replace(/"/g, '""') + '"';
  return s;
}
function _safeFile(s) { return String(s || "").replace(/[^A-Za-z0-9._-]+/g, "_"); }
function _triggerDownload(filename, content, mime) {
  const blob = new Blob([content], { type: (mime || "text/plain") + ";charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url; a.download = filename;
  document.body.appendChild(a); a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
// Human-readable status for a staff/manager row in the staff-list export.
function _staffStatusLabel(p) {
  const isTerm = p.status === "terminated" || p.active === "false" || p.active === false;
  if (isTerm) return "Terminated";
  const departed = p.offboarded && p.offDaysSinceLeft != null && p.offDaysSinceLeft >= 0;
  if (departed) return "Left" + (p.leftDate ? " " + p.leftDate : "");
  if (p.offboarded && p.offDaysSinceLeft != null && p.offDaysSinceLeft < 0) return "On notice" + (p.leftDate ? " (until " + p.leftDate + ")" : "");
  if (p.onMat) return "Maternity leave";
  if (p.pregnant) return "Pregnant";
  return "Active";
}
// Build the staff-list CSV from the currently-shown managers + techs. Leads
// with EC and names (the columns asked for), then a few useful extras.
function _staffRowsToCsv(mgrs, techs) {
  const head = ["EC", "First Name", "Surname", "Full Name", "Branch", "Role", "Start Date", "Bargaining Council", "Status"];
  const lines = [head.map(_csvEscape).join(",")];
  const split = (full) => { const t = (full || "").trim(); const i = t.indexOf(" "); return i < 0 ? { f: t, s: "" } : { f: t.slice(0, i), s: t.slice(i + 1).trim() }; };
  const row = (p, roleLabel) => {
    const sn = split(p.name);
    return [p.ec || "", p.firstName || sn.f || "", p.surname || sn.s || "", p.name || "", p.branch || "", roleLabel, p.startDate || "", p.bargainingCouncil ? "Yes" : "No", _staffStatusLabel(p)].map(_csvEscape).join(",");
  };
  (mgrs || []).forEach(m => lines.push(row(m, m.effectiveRole || m.role || "Manager")));
  (techs || []).forEach(t => lines.push(row(t, "Nail Tech")));
  return lines.join("\r\n");
}
// Office Staff List CSV. A sibling of _staffRowsToCsv rather than a mode of it:
// that one hardcodes a Branch column and a "Nail Tech" role label, neither of
// which applies here — every office person shares one branch, and Department is
// derived, not stored.
function _officeRowsToCsv(hoRows, ccRows, roleLabels) {
  const head = ["EC", "First Name", "Surname", "Full Name", "Department", "Role", "Start Date", "Bargaining Council", "Status"];
  const lines = [head.map(_csvEscape).join(",")];
  const split = (full) => { const t = (full || "").trim(); const i = t.indexOf(" "); return i < 0 ? { f: t, s: "" } : { f: t.slice(0, i), s: t.slice(i + 1).trim() }; };
  const row = (p, dept) => {
    const sn = split(p.name);
    const roleLabel = (roleLabels && roleLabels[p.role]) || p.role || "";
    return [p.ec || "", p.firstName || sn.f || "", p.surname || sn.s || "", p.name || "", dept, roleLabel, p.startDate || "", p.bargainingCouncil ? "Yes" : "No", _staffStatusLabel(p)].map(_csvEscape).join(",");
  };
  (hoRows || []).forEach(p => lines.push(row(p, "Head Office")));
  (ccRows || []).forEach(p => lines.push(row(p, "Call Centre & Sales")));
  return lines.join("\r\n");
}
// Fillable trial-evaluation modal — used in the HR portal for the AM Week-1
// review that the trainers (HQ) complete. Mirrors the kiosk evaluation form:
// score each criterion 1–5, with per-point guidance and a live tally. A pass
// needs the form's pass mark AND every Key Indicator at/above its minimum.
// `onSubmit({ scores, by, notes })` hands the raw form back to the caller,
// which validates completeness, confirms, and persists/advances.
function TrialEvalModal({ name, which, sections, max, keyMin, pass, onClose, onSubmit }) {
  const [scores, setScores] = React.useState({});
  const [by, setBy] = React.useState("");
  const [notes, setNotes] = React.useState("");
  const [guide, setGuide] = React.useState(false);
  const [openK, setOpenK] = React.useState({});
  let total = 0, answered = 0, count = 0, keyOk = true;
  sections.forEach(sec => sec.items.forEach(it => { count++; const v = Number(scores[it.k]) || 0; if (v >= 1 && v <= 5) { total += v; answered++; if (it.key && v < keyMin) keyOk = false; } }));
  const complete = answered === count;
  const willPass = complete && total >= pass && keyOk;
  const title = which === "final" ? "Final evaluation" : "Week 1 evaluation";
  return (
    <div onClick={onClose} style={{ position: "fixed", inset: 0, background: "rgba(17,24,39,0.55)", zIndex: 100001, display: "flex", alignItems: "flex-start", justifyContent: "center", padding: "40px 16px", overflowY: "auto" }}>
      <div onClick={e => e.stopPropagation()} style={{ background: "#fff", borderRadius: 16, maxWidth: 580, width: "100%", padding: "20px 22px", boxShadow: "0 24px 70px rgba(0,0,0,0.35)" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 12 }}>
          <div style={{ fontFamily: "'Playfair Display',serif", fontSize: 20, fontWeight: 700, color: "#7c3aed" }}>📋 {title} — {name}</div>
          <button onClick={onClose} style={{ background: "none", border: "none", cursor: "pointer", color: "#9ca3af", fontSize: 20, lineHeight: 1, padding: 0 }}>✕</button>
        </div>
        <div style={{ fontSize: 12, color: "#6b7280", margin: "6px 0 2px", lineHeight: 1.5 }}>Score each criterion 1 (poor) – 5 (excellent). A pass needs <b>{pass}/{max}</b> and every Key Indicator at <b>{keyMin}+</b>. The form is submitted to HR either way.</div>
        <div style={{ display: "flex", gap: 8, alignItems: "center", margin: "6px 0" }}>
          <button onClick={() => setGuide(g => !g)} style={{ border: "1px solid #ddd6fe", background: "#f5f3ff", color: "#6b21a8", borderRadius: 8, padding: "6px 11px", fontSize: 11.5, fontWeight: 800, cursor: "pointer" }}>{guide ? "ⓘ Hide guidance" : "ⓘ Show guidance for every point"}</button>
        </div>
        {sections.map(sec => {
          const sub = sec.items.reduce((a, it) => a + (Number(scores[it.k]) || 0), 0);
          return (
            <div key={sec.title} style={{ marginTop: 12 }}>
              <div style={{ display: "flex", justifyContent: "space-between", fontSize: 13, fontWeight: 800, color: "#6b21a8" }}>
                <span>{sec.title}</span><span style={{ color: "#9ca3af" }}>{sub}/{sec.max}</span>
              </div>
              {sec.items.map(it => {
                const v = Number(scores[it.k]) || 0;
                const show = guide || openK[it.k];
                return (
                  <div key={it.k} style={{ padding: "7px 0", borderTop: "1px solid #f3f4f6" }}>
                    <div style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 5, flexWrap: "wrap" }}>
                      <span style={{ fontSize: 12.5, fontWeight: 700, color: "#374151" }}>{it.label}</span>
                      {it.key && <span style={{ background: "#fef3c7", color: "#92400e", borderRadius: 4, padding: "0 6px", fontSize: 9, fontWeight: 800 }}>Key · min {keyMin}</span>}
                      {it.desc && <button onClick={() => setOpenK(o => ({ ...o, [it.k]: !o[it.k] }))} style={{ border: "1px solid #c4b5fd", background: show ? "#6b21a8" : "#ede9fe", color: show ? "#fff" : "#6b21a8", borderRadius: 99, padding: "2px 9px", fontSize: 10, fontWeight: 800, cursor: "pointer" }}>{show ? "Hide" : "Details"}</button>}
                    </div>
                    {it.desc && show && <div style={{ fontSize: 11.5, color: "#6b21a8", background: "#f5f3ff", border: "1px solid #ede9fe", borderRadius: 7, padding: "6px 9px", marginBottom: 7, lineHeight: 1.45 }}>{it.desc}</div>}
                    <div style={{ display: "flex", gap: 5 }}>
                      {[1, 2, 3, 4, 5].map(n => {
                        const on = v === n;
                        const low = it.key && on && n < keyMin;
                        return <button key={n} onClick={() => setScores(s => ({ ...s, [it.k]: n }))} style={{ flex: 1, minWidth: 34, padding: "8px 0", borderRadius: 7, border: "1px solid " + (on ? (low ? "#dc2626" : "#7c3aed") : "#e5e7eb"), background: on ? (low ? "#dc2626" : "#7c3aed") : "#fff", color: on ? "#fff" : "#374151", fontWeight: 800, fontSize: 13, cursor: "pointer" }}>{n}</button>;
                      })}
                    </div>
                  </div>
                );
              })}
            </div>
          );
        })}
        <label style={{ display: "block", fontSize: 11, fontWeight: 700, color: "#374151", margin: "14px 0 4px" }}>Evaluator name</label>
        <input value={by} onChange={e => setBy(e.target.value)} placeholder="Trainer / evaluator full name" style={{ width: "100%", boxSizing: "border-box", padding: "8px 10px", border: "1px solid #e5e7eb", borderRadius: 8, fontSize: 13, fontFamily: "inherit" }} />
        <label style={{ display: "block", fontSize: 11, fontWeight: 700, color: "#374151", margin: "10px 0 4px" }}>Notes (optional)</label>
        <textarea value={notes} onChange={e => setNotes(e.target.value)} rows={2} placeholder="Anything HR should know" style={{ width: "100%", boxSizing: "border-box", padding: "8px 10px", border: "1px solid #e5e7eb", borderRadius: 8, fontSize: 13, fontFamily: "inherit", resize: "vertical" }} />
        <div style={{ marginTop: 12, display: "flex", justifyContent: "space-between", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
          <div style={{ fontSize: 13, fontWeight: 800, color: willPass ? "#16a34a" : "#6b21a8" }}>Total: {total} / {max}{complete ? (willPass ? " · PASS ✓" : " · below pass — holds for HR") : " · score all " + count}</div>
          <div style={{ display: "flex", gap: 8 }}>
            <button onClick={onClose} style={{ background: "#fff", color: "#6b7280", border: "1px solid #e5e7eb", borderRadius: 8, padding: "8px 14px", fontSize: 12, fontWeight: 700, cursor: "pointer" }}>Cancel</button>
            <button onClick={() => onSubmit({ scores, by, notes })} style={{ background: "#7c3aed", color: "#fff", border: "none", borderRadius: 8, padding: "8px 16px", fontSize: 12, fontWeight: 800, cursor: "pointer" }}>Submit evaluation</button>
          </div>
        </div>
      </div>
    </div>
  );
}
// opts: { title, subtitle, columns:[{key, label, sub}], rows:[{label, sub, cells:{[key]:{code,text}}}],
//         legend:[{code,label}], totals:[{key,value}], filenameBase, codeStyles:{[code]:{bg,fg}} }
function exportScheduleCsv(opts) {
  const { title, subtitle, columns, rows, totals, filenameBase } = opts;
  const lines = [];
  if (title) lines.push(_csvEscape(title));
  if (subtitle) lines.push(_csvEscape(subtitle));
  if (title || subtitle) lines.push("");
  const head = ["EC", "Name", "Role / Status"].concat(columns.map(c => c.label + (c.sub ? " (" + c.sub + ")" : "")));
  lines.push(head.map(_csvEscape).join(","));
  rows.forEach(r => {
    const cells = columns.map(c => {
      const v = r.cells && r.cells[c.key];
      return (v && (v.text || v.code)) || "";
    });
    lines.push([r.ec || "", r.name || "", r.sub || ""].concat(cells).map(_csvEscape).join(","));
  });
  if (totals && totals.length) {
    lines.push("");
    lines.push(["", "", "WORKING TOTAL"].concat(columns.map(c => {
      const t = totals.find(t => t.key === c.key);
      return t ? t.value : "";
    })).map(_csvEscape).join(","));
  }
  lines.push("");
  lines.push(_csvEscape("Generated " + new Date().toLocaleString("en-ZA")));
  _triggerDownload(_safeFile(filenameBase) + ".csv", lines.join("\r\n"), "text/csv");
}
function exportSchedulePdf(opts) {
  const { title, subtitle, columns, rows, totals, legend, filenameBase } = opts;
  const esc = (s) => String(s == null ? "" : s).replace(/[&<>"']/g, ch => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[ch]));
  const dowsAbbr = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
  const moNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

  // ── Group columns into Mon-Sun chunks ──────────────────────────────────
  // The first chunk may be partial (cycle starts mid-week). A new chunk
  // begins on every Monday. Each chunk renders a header banner with the
  // week label and date range, plus a thick coloured separator before it.
  const weeks = [];
  let cur = [];
  columns.forEach(c => {
    if (cur.length && c.dow === 1) { weeks.push(cur); cur = []; }
    cur.push(c);
  });
  if (cur.length) weeks.push(cur);

  const fmtDate = (c) => {
    if (!c) return "";
    if (c.year != null && c.monthIdx != null && c.day != null) {
      return c.day + " " + moNames[c.monthIdx];
    }
    // c.key is YYYY-MM-DD when supplied that way
    if (c.key && /^\d{4}-\d{2}-\d{2}$/.test(c.key)) {
      const dt = new Date(c.key + "T00:00:00");
      return dt.getDate() + " " + moNames[dt.getMonth()];
    }
    return c.label || "";
  };

  // Week banner row — colspans across the days in each chunk
  const weekBannerCells = weeks.map((wk, idx) => {
    const first = wk[0], last = wk[wk.length - 1];
    const partial = wk.length < 7 ? " · partial" : "";
    const wkOff = wk.filter(c => c.dow === 0 || c.dow === 6).length;
    const banner = "Week " + (idx + 1) + " — " + fmtDate(first) + " → " + fmtDate(last)
      + " · " + wk.length + " day" + (wk.length === 1 ? "" : "s") + partial;
    return '<th class="wkbn" colspan="' + wk.length + '">' + esc(banner) + '</th>';
  }).join("");

  // Day header cells — Monday opens a thick left border (week separator);
  // Sat/Sun get a tinted background and red accent on the day-of-week label.
  const dayHeaderCells = [];
  weeks.forEach((wk, wi) => {
    wk.forEach((c, ci) => {
      const isWeekStart = wi > 0 && ci === 0;
      const wknd = c.dow === 0 || c.dow === 6;
      const cls = "dh" + (isWeekStart ? " ws" : "") + (wknd ? " wd" : "");
      const dowLabel = c.sub || (c.dow != null ? dowsAbbr[c.dow] : "");
      dayHeaderCells.push(
        '<th class="' + cls + '">' +
        '<div class="d">' + esc(c.label) + '</div>' +
        (dowLabel ? '<div class="s">' + esc(dowLabel) + '</div>' : '') +
        '</th>'
      );
    });
  });

  // Body rows — same week-start markers + a `c-<code>` class so the CSS
  // palette (vivid greens for working, vivid pinks/reds for off, ambers
  // for leave) takes over per cell.
  const bodyRows = rows.map(r => {
    const tds = [];
    weeks.forEach((wk, wi) => {
      wk.forEach((c, ci) => {
        const v = (r.cells && r.cells[c.key]) || {};
        const code = v.code || "";
        const txt = v.text != null ? v.text : code;
        const isWeekStart = wi > 0 && ci === 0;
        const wknd = c.dow === 0 || c.dow === 6;
        const cls = "c c-" + (code || "blank")
          + (isWeekStart ? " ws" : "")
          + (wknd ? " wd" : "");
        tds.push('<td class="' + cls + '">' + esc(txt) + '</td>');
      });
    });
    return '<tr><td class="lbl"><div class="n">' + esc(r.name || r.ec || "") + '</div>'
      + (r.ec ? '<div class="ec">' + esc(r.ec) + '</div>' : '')
      + (r.sub ? '<div class="rsub">' + esc(r.sub) + '</div>' : '')
      + '</td>' + tds.join("") + '</tr>';
  }).join("");

  // Working-total row — also marks week separators
  let totalRow = "";
  if (totals && totals.length) {
    const totalTds = [];
    weeks.forEach((wk, wi) => {
      wk.forEach((c, ci) => {
        const t = totals.find(t => t.key === c.key);
        const isWeekStart = wi > 0 && ci === 0;
        const wknd = c.dow === 0 || c.dow === 6;
        const cls = "tot-c" + (isWeekStart ? " ws" : "") + (wknd ? " wd" : "");
        totalTds.push('<td class="' + cls + '">' + esc(t ? t.value : "") + '</td>');
      });
    });
    totalRow = '<tr class="tot"><td class="lbl">WORKING TOTAL</td>' + totalTds.join("") + '</tr>';
  }

  // Legend — uses the same `c-<code>` palette so legend swatches match cells.
  const legendHtml = (legend && legend.length)
    ? '<div class="legend">' + legend.map(l =>
      '<span class="lg"><i class="c c-' + (l.code || "blank") + '">'
      + esc(l.text || l.code || "") + '</i> ' + esc(l.label) + '</span>'
    ).join("") + '</div>'
    : '';

  const guideHtml =
    '<div class="guide">' +
    '<strong>📅 Reading the schedule:</strong> ' +
    'each <span class="hl">vertical pink line</span> marks the start of a new <strong>Mon-Sun work week</strong>. ' +
    'Weekend columns (Sat / Sun) have a soft pink tint and a red day-of-week label. ' +
    'Working days are <span class="ck c-W">GREEN</span>, off-days are <span class="ck c-O">PINK</span>, ' +
    'requested off-days are <span class="ck c-R">RED</span>, leave is <span class="ck c-L">AMBER</span>, ' +
    'extra/manual offs are <span class="ck c-E">TEAL</span>.' +
    '</div>';

  const html = '<!doctype html><html><head><meta charset="utf-8"><title>' + esc(title || "Schedule") + '</title>'
    + '<style>'
    // ── Print + base ──
    + '@page{size:A4 landscape;margin:8mm}'
    + 'html,body{margin:0;padding:0}'
    + 'body{font-family:"DM Sans",system-ui,sans-serif;color:#111;padding:14px}'
    + '*{-webkit-print-color-adjust:exact;print-color-adjust:exact;color-adjust:exact}'
    + 'h1{font-family:"Playfair Display",serif;font-size:22px;color:#831843;margin:0 0 4px}'
    + '.sub{color:#9F1A4F;font-size:12px;margin-bottom:8px;font-weight:600}'
    // ── Reading guide banner ──
    + '.guide{background:#FDF2F8;border:1px solid #FBCFE8;border-left:4px solid #BE185D;border-radius:6px;padding:8px 12px;margin:6px 0 10px;font-size:10px;color:#374151;line-height:1.55}'
    + '.guide strong{color:#831843}'
    + '.guide .hl{color:#BE185D;font-weight:700}'
    + '.guide .ck{display:inline-block;padding:0 6px;border-radius:3px;font-weight:800;font-size:9px;letter-spacing:0.04em;margin:0 1px}'
    // ── Legend ──
    + '.legend{margin:6px 0 10px;font-size:10px;color:#374151;display:flex;flex-wrap:wrap;gap:10px 16px}'
    + '.legend .lg{display:inline-flex;align-items:center;gap:6px}'
    + '.legend .c{padding:2px 8px;border-radius:4px;font-style:normal;font-weight:800;font-size:10px;border:1px solid rgba(0,0,0,0.08)}'
    // ── Table base ──
    + 'table{border-collapse:collapse;width:100%;font-size:10px;table-layout:fixed}'
    + 'th,td{border:1px solid #FBCFE8;padding:3px 2px;text-align:center;vertical-align:middle;word-break:break-word}'
    + 'th{background:#FCE7F3;color:#831843}'
    // ── Week banner row ──
    + 'th.wkbn{background:#BE185D;color:#fff;font-weight:800;font-size:11px;letter-spacing:0.04em;padding:6px 6px;border:1px solid #831843;border-bottom:2px solid #831843;text-transform:uppercase}'
    + 'th.wkbn + th.wkbn{border-left:3px solid #FBCFE8}'
    // ── Day header cells ──
    + 'th.dh .d{font-weight:800;font-size:12px;color:#831843;line-height:1.1}'
    + 'th.dh .s{font-size:9px;font-weight:700;color:#9F1A4F;letter-spacing:0.05em;text-transform:uppercase;margin-top:2px}'
    + 'th.dh.wd{background:#FBCFE8}'
    + 'th.dh.wd .s{color:#9F1A4F}'
    // ── Week-start separator (thick pink line on Mondays after week 1) ──
    + 'th.ws,td.ws{border-left:3px solid #BE185D !important}'
    // ── Weekend column tint on body rows ──
    + 'td.wd{background-color:rgba(251,207,232,0.18)}'
    // ── Staff label column ──
    + 'td.lbl{text-align:left;font-size:10px;background:#fff;padding:5px 7px}'
    + 'td.lbl .n{font-weight:700;color:#831843;font-size:11px}'
    + 'td.lbl .ec{font-size:9px;color:#BE185D;font-weight:600}'
    + 'td.lbl .rsub{font-size:9px;color:#6b7280;font-style:italic;margin-top:1px}'
    // ── Cell palette: vivid working / off / leave / etc. ──
    + 'td.c{font-weight:800;font-size:11px;letter-spacing:0.02em}'
    + 'td.c-W,.legend .c-W,.guide .c-W{background:#22c55e !important;color:#052e16 !important}'   // working — vivid green
    + 'td.c-WE,.legend .c-WE,.guide .c-WE{background:#4ade80 !important;color:#052e16 !important}'// working early — bright green
    + 'td.c-WL,.legend .c-WL,.guide .c-WL{background:#15803d !important;color:#f0fdf4 !important}'// working late — deeper green
    + 'td.c-O,.legend .c-O,.guide .c-O{background:#fda4af !important;color:#7f1d1d !important}'  // off — soft pink
    + 'td.c-R,.legend .c-R,.guide .c-R{background:#ef4444 !important;color:#fff !important}'      // requested off — vivid red
    + 'td.c-L,.legend .c-L,.guide .c-L{background:#fbbf24 !important;color:#7c2d12 !important}'   // leave — amber
    + 'td.c-E,.legend .c-E,.guide .c-E{background:#5eead4 !important;color:#022c22 !important}'   // extra — teal
    + 'td.c-X,.legend .c-X,.guide .c-X{background:#f3f4f6 !important;color:#9ca3af !important}'   // ghost / not scheduled
    + 'td.c-blank{background:#fafafa !important;color:#d1d5db !important}'
    // Weekend tint should still be visible behind a working cell — soften by overlaying border
    + 'td.c.wd{box-shadow:inset 0 0 0 999px rgba(0,0,0,0)}'
    // ── Totals row ──
    + 'tr.tot td{background:#FDF2F8;color:#831843;font-weight:800;font-size:11px;border-top:2px solid #BE185D}'
    + 'tr.tot td.lbl{background:#FCE7F3;color:#831843;letter-spacing:0.04em}'
    + 'tr.tot td.tot-c.ws{border-left:3px solid #BE185D !important}'
    + 'tr.tot td.tot-c.wd{background:#FBCFE8}'
    // ── UI chrome (hidden on print) ──
    + '.foot{margin-top:8px;font-size:9px;color:#9ca3af}'
    + '@media print{.bar{display:none}.guide{break-inside:avoid}}'
    + '.bar{display:flex;gap:8px;margin-bottom:10px}'
    + '.bar button{padding:8px 18px;background:#BE185D;color:#fff;border:none;border-radius:6px;font-size:13px;cursor:pointer;font-family:inherit;font-weight:700}'
    + '.bar button.sec{background:#fff;color:#831843;border:1px solid #FBCFE8;font-weight:600}'
    + '</style></head><body>'
    + '<div class="bar"><button onclick="window.print()">🖨 Save as PDF / Print</button>'
    + '<button class="sec" onclick="window.close()">Close</button></div>'
    + '<h1>' + esc(title || "Schedule") + '</h1>'
    + (subtitle ? '<div class="sub">' + esc(subtitle) + '</div>' : '')
    + guideHtml
    + legendHtml
    + '<table>'
    + '<thead>'
    + '<tr><th class="lbl" rowspan="2" style="width:150px;text-align:left;background:#FCE7F3">Staff</th>' + weekBannerCells + '</tr>'
    + '<tr>' + dayHeaderCells.join("") + '</tr>'
    + '</thead>'
    + '<tbody>' + bodyRows + '</tbody>'
    + (totalRow ? '<tfoot>' + totalRow + '</tfoot>' : '')
    + '</table>'
    + '<div class="foot">' + esc(filenameBase || "") + ' · generated ' + esc(new Date().toLocaleString("en-ZA")) + '</div>'
    + '<script>setTimeout(function(){window.focus();}, 100);<\/script>'
    + '</body></html>';
  const w = window.open("", "_blank");
  if (!w) { alert("Pop-up blocked. Allow pop-ups for this site to download the PDF."); return; }
  w.document.open(); w.document.write(html); w.document.close();
  try { w.document.title = (filenameBase || "schedule"); } catch (_) { }
}

// ─── SOUTH AFRICAN PUBLIC HOLIDAYS ──────────────────────────────────────────────
// Per the Public Holidays Act, 1994. If a holiday falls on a Sunday, the
// following Monday is also a public holiday ("observed").
function _easterSunday(year) {
  const a = year % 19;
  const b = Math.floor(year / 100);
  const c = year % 100;
  const d = Math.floor(b / 4);
  const e = b % 4;
  const f = Math.floor((b + 8) / 25);
  const g = Math.floor((b - f + 1) / 3);
  const h = (19 * a + b - d - g + 15) % 30;
  const i = Math.floor(c / 4);
  const k = c % 4;
  const l = (32 + 2 * e + 2 * i - h - k) % 7;
  const m = Math.floor((a + 11 * h + 22 * l) / 451);
  const month = Math.floor((h + l - 7 * m + 114) / 31);
  const day = ((h + l - 7 * m + 114) % 31) + 1;
  return new Date(year, month - 1, day);
}
function _dkey(y, m, d) {
  return y + "-" + String(m).padStart(2, "0") + "-" + String(d).padStart(2, "0");
}
const _saHolidayCache = {};
function saHolidays(year) {
  if (_saHolidayCache[year]) return _saHolidayCache[year];
  const out = {};
  const add = (m, d, name) => {
    const dt = new Date(year, m - 1, d);
    out[_dkey(year, m, d)] = name;
    if (dt.getDay() === 0) {
      const dt2 = new Date(year, m - 1, d + 1);
      out[_dkey(dt2.getFullYear(), dt2.getMonth() + 1, dt2.getDate())] = name + " (observed)";
    }
  };
  add(1, 1, "New Year's Day");
  add(3, 21, "Human Rights Day");
  const easter = _easterSunday(year);
  const gf = new Date(easter); gf.setDate(easter.getDate() - 2);
  const fd = new Date(easter); fd.setDate(easter.getDate() + 1);
  out[_dkey(gf.getFullYear(), gf.getMonth() + 1, gf.getDate())] = "Good Friday";
  out[_dkey(fd.getFullYear(), fd.getMonth() + 1, fd.getDate())] = "Family Day";
  add(4, 27, "Freedom Day");
  add(5, 1, "Workers' Day");
  add(6, 16, "Youth Day");
  add(8, 9, "Women's Day");
  add(9, 24, "Heritage Day");
  add(12, 16, "Day of Reconciliation");
  add(12, 25, "Christmas Day");
  add(12, 26, "Day of Goodwill");
  _saHolidayCache[year] = out;
  return out;
}

// ─── TRIAL DOCUMENTS — the checklist HR collects from a trial tech ─────────────
// Collected during the trial; the signed contract is added once they've passed
// and are being onboarded. Stored on the trial record as r.docs = { key: true }.
const TRIAL_DOC_ITEMS = [
  { k: "idPermit", label: "ID / Passport + valid asylum & form (verifiable with Home Affairs) — or a valid work permit" },
  { k: "sars", label: "SARS registration" },
  { k: "particulars", label: "Personal particulars form (completed)" },
  { k: "bank", label: "Proof of bank account" },
  { k: "address", label: "Proof of address" },
  { k: "trialContract", label: "2-week trial contract" }
];
const TRIAL_SIGNED_CONTRACT = { k: "signedContract", label: "Signed contract (after a successful trial)", onboard: true };
// Items applicable to a record now — the signed contract only appears once the
// tech has passed / is being onboarded.
function trialDocList(r) {
  const items = TRIAL_DOC_ITEMS.slice();
  if (r && (r.status === "passed" || r.status === "hired")) items.push(TRIAL_SIGNED_CONTRACT);
  return items;
}
function trialDocsDone(r) { const d = (r && r.docs) || {}; return trialDocList(r).filter(it => !!d[it.k]).length; }
function trialDocsTotal(r) { return trialDocList(r).length; }
function trialDocsComplete(r) { return trialDocsTotal(r) > 0 && trialDocsDone(r) === trialDocsTotal(r); }

// ─── TRIAL OUTCOME: "not_onboarding" ──────────────────────────────────────────
// A candidate who PASSED the trial and then never joined (took another job,
// withdrew, unreachable…). Deliberately NOT modelled as "failed": she met the
// bar, so conflating the two would corrupt the pass/fail reporting the trial
// board exists to produce, and would tell the next HR reader she wasn't good
// enough. The record keeps its evaluations and its pass — only the hire fell
// through — and carries WHY on r.notOnboarding = {reason, note, at, by}.
const NOT_ONBOARDING_REASONS = [
  { key: "other_job", label: "Took another job" },
  { key: "declined", label: "Declined the offer" },
  { key: "no_show", label: "Never started / no-show" },
  { key: "uncontactable", label: "Uncontactable" },
  { key: "relocated", label: "Relocated / too far to travel" },
  { key: "personal", label: "Personal / family reasons" },
  { key: "no_vacancy", label: "No vacancy at the store" },
  { key: "other", label: "Other (add a note)" }
];
const NOT_ONBOARDING_LABEL = {};
NOT_ONBOARDING_REASONS.forEach(r => { NOT_ONBOARDING_LABEL[r.key] = r.label; });
function notOnboardingReasonLabel(r) {
  const key = r && r.notOnboarding && r.notOnboarding.reason;
  return NOT_ONBOARDING_LABEL[key] || (key ? String(key) : "");
}
// Is this trial candidate GONE — a terminal negative outcome, never coming back
// to the floor? "not_onboarding" behaves exactly like "failed" for every
// "is this person still an active trialist" question: schedule ghost rows, the
// Fresha to-do lists, the per-branch active counts.
//
// This exists as ONE predicate on purpose. Those questions are asked in ~12
// places that each hand-list statuses as a DENYLIST (`!== "failed" && !== "hired"`),
// so a new terminal status defaults to *active* and silently leaks a departed
// candidate onto store schedules. Route new terminal statuses through here.
//
// NOT for payroll: the trial-day reports pay every worked day regardless of
// outcome, so they filter on check-ins and must keep including gone candidates.
function trialIsGone(c) {
  const s = String((c && c.status) || "");
  return s === "failed" || s === "not_onboarding";
}


// Maternity used to blank a person's ENTIRE row the instant their status
// flipped to "on maternity". Instead we honour the Maternity tab's start
// date: schedule them normally up to that date and only show 'ML' from it
// onward. Returns { full, fromYmd }:
//   • full=true               → on mat for the whole cycle (no start date on
//                               file, or it began on/before the cycle began)
//                               → the entire row is ML, exactly as before.
//   • full=false, fromYmd set → maternity STARTS mid-cycle on fromYmd: real
//                               working days before it, ML on/after it.
//   • full=false, fromYmd=null→ not on maternity during this cycle (a known
//                               start date that lands after the cycle ends).
// matStart is read from the joined maternity record (person.matRec.matStart)
// with a flat person.matStart fallback for callers that pass it directly.
function matCycleWindow(person, cycleStartYmd, cycleEndYmd) {
  const rec = (person && person.matRec) || null;
  const status = (rec && rec.matStatus) || (person && person.matStatus) || null;
  const onMat = !!(person && (person.onMat || person._onMat));
  const ret = (rec && rec.returnDate) || (person && person.returnDate) || null;
  if (!onMat) {
    // Returned to work. We deliberately do NOT bring someone back onto the
    // schedule automatically while they're still on maternity — only once HR
    // flips their status to "returned". When that return date falls inside
    // this cycle, keep them on ML up to it and only schedule real shifts from
    // the return date onward (untilYmd is exclusive — the first day back).
    if (status === "returned" && ret) {
      if (ret <= cycleStartYmd) return { full: false, fromYmd: null, untilYmd: null }; // back before this cycle → fully active
      if (cycleEndYmd && ret > cycleEndYmd) return { full: true, fromYmd: cycleStartYmd, untilYmd: null }; // not back yet this cycle → ML all
      return { full: false, fromYmd: cycleStartYmd, untilYmd: ret };                   // back mid-cycle
    }
    return { full: false, fromYmd: null, untilYmd: null };
  }
  const ms = (rec && rec.matStart) || (person && person.matStart) || null;
  if (!ms) return { full: true, fromYmd: cycleStartYmd, untilYmd: null };          // date unknown → whole cycle
  if (ms <= cycleStartYmd) return { full: true, fromYmd: cycleStartYmd, untilYmd: null };  // already underway
  if (cycleEndYmd && ms > cycleEndYmd) return { full: false, fromYmd: null, untilYmd: null }; // starts a later cycle
  return { full: false, fromYmd: ms, untilYmd: null };                             // mid-cycle start
}

// Unpaid legal-status leave window for one cycle — parallels matCycleWindow.
// A tech/manager whose Compliance "Unpaid Leave (Legal)" record (status
// on_leave) covers these dates is kept OFF the roster and rendered as unpaid
// emergency leave (EL), exactly like maternity. The record arrives through
// enriched as person.unpaidLegalRec; start/end may be null (open-ended → the
// whole cycle). untilYmd is EXCLUSIVE (the first day back), matching
// matCycleWindow so the render's cell test can be shared.
function legalLeaveWindow(person, cycleStartYmd, cycleEndYmd) {
  const rec = person && person.unpaidLegalRec;
  if (!rec) return { full: false, fromYmd: null, untilYmd: null };
  const start = rec.startDate || null;
  const end = rec.endDate || null;
  if (end && end < cycleStartYmd) return { full: false, fromYmd: null, untilYmd: null };          // ended before this cycle
  if (start && cycleEndYmd && start > cycleEndYmd) return { full: false, fromYmd: null, untilYmd: null }; // starts a later cycle
  const startsBefore = !start || start <= cycleStartYmd;
  const endsAfter = !end || (cycleEndYmd && end >= cycleEndYmd);
  if (startsBefore && endsAfter) return { full: true, fromYmd: cycleStartYmd, untilYmd: null };   // whole cycle
  const fromYmd = startsBefore ? cycleStartYmd : start;
  let untilYmd = null;
  if (!endsAfter && end) {
    const d = new Date(end + "T00:00:00"); d.setDate(d.getDate() + 1);            // exclusive: first day back
    untilYmd = d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0") + "-" + String(d.getDate()).padStart(2, "0");
  }
  return { full: false, fromYmd, untilYmd };
}

// ─── MANAGER SCHEDULE GENERATOR (mgrSched) ────────────────────────────────────────
// Ported 1:1 from the old HR portal HTML (function originally on line 842).
// Generates a per-manager × per-day grid for one branch over a single 25th→24th
// payroll cycle.
//   - SM gets 2 weekend pairs (Sat+Sun) off per cycle. AM gets 1.
//   - Each full ISO week targets 2 off-days per manager.
//   - Day-of-week preference for off-day picking: Mon=6, Tue=5, Wed=4, Sun=3,
//     Thu=1, Fri=0, Sat=0 — managers prefer mid-week and never voluntarily
//     take Fri/Sat off (busy days).
//   - Min 2 managers working per day (hard constraint).
//   - Max 6 consecutive working days (5-pass fix at the end).
// Off-boarding ghosts: post-leftDate cells become "X". Onboarding ghosts:
// pre-startDate cells become "X". Both are computed from the staff record's
// leftDate / startDate fields.
//
// Cell vocabulary: W=working, O=off (auto), L=on leave, R=requested off,
// E=extra off (manual), X=ghost.
//
// Returns { managers, dates, grid, conflicts, dayTotals, branch, cycleStart,
//   cycleEnd, weekOrder, weeksMap }.
function mgrSched(branchName, cycleStartYmd, allManagers, leaveRecs, requests, priorContext) {
  const p2 = z => String(z).padStart(2, "0");
  const fmt = z => z.getFullYear() + "-" + p2(z.getMonth() + 1) + "-" + p2(z.getDate());
  const d0 = new Date(cycleStartYmd + "T00:00:00");
  const dEnd = new Date(d0.getFullYear(), d0.getMonth() + 1, 24);
  const dates = [];
  for (let c = new Date(d0); c <= dEnd; c.setDate(c.getDate() + 1)) {
    dates.push({ d: fmt(new Date(c)), dow: c.getDay() });
  }
  const cycleEnd = dates[dates.length - 1].d;

  // Filter managers for this branch + cycle (skip future-onboarding, skip
  // anyone who left before the cycle started).
  const fAll = allManagers.filter(h => {
    if (h.branch !== branchName) return false;
    if (h._onboarding && h._startDate && h._startDate > cycleEnd) return false;
    if (h.leftDate && h.leftDate < cycleStartYmd) return false;
    return true;
  });
  // Scheduling pool excludes anyone currently on maternity. The grid still
  // renders a row for them (with every cell as 'ML') so the manager team
  // sees who's away, but every shift-assignment / coverage loop below uses
  // `f` and pretends maternity people don't exist.
  const f = fAll.filter(h => !h._onMat);
  if (fAll.length === 0) {
    return {
      managers: [], dates, grid: {}, conflicts: [{ type: "no_managers", msg: "No managers at " + branchName, severity: "high" }],
      dayTotals: {}, branch: branchName, cycleStart: cycleStartYmd, cycleEnd, weekOrder: [], weeksMap: {}
    };
  }
  if (f.length === 0) {
    // Every manager at this branch is on maternity - render an ML-only grid
    // and surface a conflict so the user knows nobody can be scheduled.
    const matGrid = {};
    for (const h of fAll) { matGrid[h.ec] = {}; for (const x of dates) matGrid[h.ec][x.d] = "ML"; }
    return {
      managers: fAll, dates, grid: matGrid, conflicts: [{ type: "no_active_managers", msg: "All managers at " + branchName + " are on maternity leave.", severity: "high" }],
      dayTotals: {}, branch: branchName, cycleStart: cycleStartYmd, cycleEnd, weekOrder: [], weeksMap: {}
    };
  }
  const m = f.length;
  // Small-team coverage threshold (per-day function):
  //   - 3+ managers AVAILABLE that day (none on leave/mat) → require >=2 working.
  //   - 2 or fewer available (true 2-mgr store, OR 3-mgr store where one is
  //     on leave/maternity that day)               → allow 1 working.
  // The 6-consecutive-day cap and 2-off-per-week rule take priority over
  // keeping 2 mgrs on duty when the available team has dropped to 2.
  const _minCoverageFor = (ymd) => {
    const activeToday = m - (W[ymd] && W[ymd].leave ? W[ymd].leave : 0);
    return activeToday >= 3 ? 2 : 1;
  };

  // ISO week mapping
  const wkOf = ymd => {
    const x = new Date(ymd + "T00:00:00");
    const dn = (x.getDay() + 6) % 7;
    x.setDate(x.getDate() - dn + 3);
    const ff = new Date(x.getFullYear(), 0, 4);
    const fdn = (ff.getDay() + 6) % 7;
    ff.setDate(ff.getDate() - fdn + 3);
    const wk = 1 + Math.round((x - ff) / (7 * 86400000));
    return x.getFullYear() + "-W" + p2(wk);
  };
  const wkMap = {}, wkOrder = [];
  for (const x of dates) {
    const w = wkOf(x.d);
    if (!wkMap[w]) { wkMap[w] = []; wkOrder.push(w); }
    wkMap[w].push(x);
  }
  const wkOfDay = {};
  for (const w of wkOrder) for (const x of wkMap[w]) wkOfDay[x.d] = w;

  // Initialise per-manager grid + per-day counters
  const grid = {}, W = {};
  for (const x of dates) W[x.d] = { dow: x.dow, working: 0, off: 0, leave: 0 };
  for (const h of f) { grid[h.ec] = {}; for (const x of dates) grid[h.ec][x.d] = null; }
  // Seed leaves
  for (const lv of leaveRecs || []) {
    if (!grid[lv.ec]) continue;
    for (const x of dates) if (x.d >= lv.startDate && x.d <= lv.endDate) {
      grid[lv.ec][x.d] = "L"; W[x.d].leave++;
    }
  }
  // Seed requested off-days
  for (const r of requests || []) {
    if (grid[r.ec] && grid[r.ec][r.date] == null) {
      grid[r.ec][r.date] = "R"; W[r.date].off++;
    }
  }

  // ── Store-closed days ─────────────────────────────────────────────
  // Some branches are closed on fixed weekdays (e.g. Betty is closed Sun+Mon).
  // Every manager at those branches is off on those days, always. We seed
  // those cells as "O" before the rest of the solver runs so they consume
  // the per-week off budget and block any working-day placement.
  const _salonCfg = (typeof SALONS !== "undefined") ? SALONS.find(s => s && s.name === branchName) : null;
  const closedDow = (_salonCfg && Array.isArray(_salonCfg.closedDow)) ? _salonCfg.closedDow : [];
  if (closedDow.length) {
    const closedSet = new Set(closedDow.map(Number));
    for (const x of dates) {
      if (!closedSet.has(x.dow)) continue;
      for (const h of f) {
        if (grid[h.ec][x.d] == null) {
          grid[h.ec][x.d] = "O"; W[x.d].off++;
        }
      }
    }
  }

  // ── Weekend pairing pass ──────────────────────────────────────────
  const offWk = {};
  for (const h of f) { offWk[h.ec] = {}; for (const w of wkOrder) offWk[h.ec][w] = 0; }
  for (const h of f) for (const x of dates) {
    const v = grid[h.ec][x.d];
    if (v === "L" || v === "R" || v === "O") offWk[h.ec][wkOfDay[x.d]]++;
  }

  // ── Cross-month carry-over (leading partial week) ────────────────
  // Hard rule: no manager may exceed 2 off-days in any Mon–Sun labour
  // week, even when that week straddles two scheduling cycles. If this
  // cycle starts mid-week, the leading week overlaps with the prior
  // cycle's tail. priorContext.priorOffs[ec] holds the count of O/R/L
  // each manager already had on those overlap days. We seed offWk for
  // the leading week with that count so every downstream check
  // (weekend-pair gate, backtracking solver via wkMap[w].length, cross-
  // week swap accounting) naturally honours the cap.
  const leadingWk = wkOrder[0];
  const trailingWk = wkOrder[wkOrder.length - 1];
  const isLeadingPartial = !!(leadingWk && wkMap[leadingWk] && wkMap[leadingWk].length < 7);
  const isTrailingPartial = !!(trailingWk && wkMap[trailingWk] && wkMap[trailingWk].length < 7 && trailingWk !== leadingWk);
  const priorOffs = (priorContext && priorContext.priorOffs) || {};
  const priorMissing = !!(priorContext && priorContext.priorMissing);
  const nextOffs = (priorContext && priorContext.nextOffs) || {};
  const nextMissing = !!(priorContext && priorContext.nextMissing);
  if (isLeadingPartial) {
    for (const h of f) {
      const carry = +priorOffs[h.ec] || 0;
      if (carry > 0) offWk[h.ec][leadingWk] += carry;
    }
  }
  // Trailing partial week — same shared-week problem at the END of the cycle.
  // The trailing partial week of THIS cycle = the leading partial week of the
  // NEXT cycle. If the next cycle exists, count the offs each manager already
  // has on the overlap days (Sat/Sun after our cycleEnd, etc.) and seed
  // offWk[trailingWk] so we don't add a 3rd off into that combined week.
  if (isTrailingPartial) {
    for (const h of f) {
      const carry = +nextOffs[h.ec] || 0;
      if (carry > 0) offWk[h.ec][trailingWk] += carry;
    }
  }
  const wePairs = (h) => {
    let ct = 0;
    for (let i = 0; i < dates.length - 1; i++) {
      if (dates[i].dow === 6 && dates[i + 1].dow === 0) {
        const a = grid[h.ec][dates[i].d], b = grid[h.ec][dates[i + 1].d];
        if ((a === "O" || a === "L" || a === "R") && (b === "O" || b === "L" || b === "R")) ct++;
      }
    }
    return ct;
  };
  const setOff = (ec, day) => {
    if (grid[ec][day] != null) return false;
    grid[ec][day] = "O"; W[day].off++; offWk[ec][wkOfDay[day]]++;
    return true;
  };
  // Locked days = weekend-pair offs that the 7-day-streak fix is NOT allowed
  // to swap away. Without this, the fix happily breaks Sat-Sun pairs to fix
  // long streaks, leaving the manager with 0 weekend pairs (the conflict
  // user reported for Robin P).
  const pairLocked = {};
  for (const h of f) pairLocked[h.ec] = new Set();
  const allWePairs = [];
  for (let i = 0; i < dates.length - 1; i++) {
    if (dates[i].dow === 6 && dates[i + 1].dow === 0) allWePairs.push([dates[i], dates[i + 1]]);
  }
  const _isStoreTier = (r) => r === "SM" || r === "SSM";
  // Branches with fixed closed days (e.g. Betty: Sun+Mon) already give every
  // manager a guaranteed multi-day off-block every week. Skip the Sat+Sun
  // pairing pass entirely — trying to add a Sat+Sun pair would blow the 2-off
  // weekly cap (closed days already consume it).
  const _skipWePair = closedDow.length > 0;
  const ordered = _skipWePair ? [] : [...f].sort((a, b) => (_isStoreTier(a.role) ? 0 : 1) - (_isStoreTier(b.role) ? 0 : 1));
  for (const h of ordered) {
    const need = _isStoreTier(h.role) ? 2 : 1;
    let have = wePairs(h);
    if (have >= need) continue;
    let candidates = allWePairs.filter(([fr, sa]) =>
      grid[h.ec][fr.d] == null && grid[h.ec][sa.d] == null
      && offWk[h.ec][wkOfDay[fr.d]] + 2 <= 2
      && offWk[h.ec][wkOfDay[sa.d]] + (wkOfDay[fr.d] === wkOfDay[sa.d] ? 0 : 2) <= 2
    );
    while (have < need && candidates.length) {
      candidates.sort((a, b) => {
        const wa = m - W[a[0].d].off - W[a[0].d].leave - 1;
        const wa2 = m - W[a[1].d].off - W[a[1].d].leave - 1;
        const wb = m - W[b[0].d].off - W[b[0].d].leave - 1;
        const wb2 = m - W[b[1].d].off - W[b[1].d].leave - 1;
        const adjPen = (pair) => {
          const i0 = dates.indexOf(pair[0]), i1 = dates.indexOf(pair[1]);
          let pen = 0;
          if (i0 > 0) { const prev = grid[h.ec][dates[i0 - 1].d]; if (prev === "O" || prev === "L" || prev === "R") pen -= 300; }
          if (i1 < dates.length - 1) { const nxt = grid[h.ec][dates[i1 + 1].d]; if (nxt === "O" || nxt === "L" || nxt === "R") pen -= 300; }
          return pen;
        };
        const sa = (wa < 2 ? -1000 : 0) + (wa2 < 2 ? -1000 : 0) - (W[a[0].d].off + W[a[1].d].off) + adjPen(a);
        const sb = (wb < 2 ? -1000 : 0) + (wb2 < 2 ? -1000 : 0) - (W[b[0].d].off + W[b[1].d].off) + adjPen(b);
        return sb - sa;
      });
      const pair = candidates.shift(), fr = pair[0], saturday = pair[1];
      setOff(h.ec, fr.d); setOff(h.ec, saturday.d); have++;
      pairLocked[h.ec].add(fr.d); pairLocked[h.ec].add(saturday.d);
      candidates = candidates.filter(([fr2, sa2]) =>
        grid[h.ec][fr2.d] == null && grid[h.ec][sa2.d] == null
        && offWk[h.ec][wkOfDay[fr2.d]] + 2 <= 2
        && offWk[h.ec][wkOfDay[sa2.d]] + (wkOfDay[fr2.d] === wkOfDay[sa2.d] ? 0 : 2) <= 2
      );
    }
  }

  // ── Per-week off-day allocation — BACKTRACKING SOLVER ─────────────
  // Hard rules enforced AT PLACEMENT TIME (not as a post-pass clean-up):
  //   1. 2 off-days per full ISO week
  //   2. Min 2 managers working per day (coverage)
  //   3. Max 6 consecutive working days per manager (the killer rule)
  // For each manager, backtrack through their non-pair weeks placing
  // 2 weekday offs at a time. Skip any candidate that would push this
  // manager's longest W-run ≥ 7. If no candidate satisfies, backtrack
  // to the previous week and try a different placement. Falls back to
  // greedy Mon-Tue if backtracking fails entirely (very rare).
  const dowOrd = { 0: 3, 1: 6, 2: 5, 3: 4, 4: 1, 5: 0, 6: 0 };
  // Helper: max W-gap on either side of the candidate, between candidate
  // and the nearest existing off-day in this manager's grid. Matches OLD's
  // _maxRun(_dy) — local-gap, NOT global-run.
  const maxRunIfOff = (ec, candDay) => {
    const myOffs = [];
    for (let i = 0; i < dates.length; i++) {
      const v = grid[ec][dates[i].d];
      if (v === "O" || v === "L" || v === "R") myOffs.push(i);
    }
    const ix = dates.findIndex(x => x.d === candDay);
    let prev = -2, next = -2;
    for (const o of myOffs) {
      if (o < ix && o > prev) prev = o;
      if (o > ix && (next === -2 || o < next)) next = o;
    }
    const bf = prev >= 0 ? ix - prev - 1 : 0;
    const af = next >= 0 ? next - ix - 1 : 0;
    return Math.max(bf, af);
  };
  // Helper: length of off-streak created by placing candidate as O
  const offStreakIfOff = (ec, candDay) => {
    const idx = dates.findIndex(x => x.d === candDay);
    if (idx < 0) return 1;
    let n = 1;
    for (let j = idx - 1; j >= 0; j--) {
      const v = grid[ec][dates[j].d];
      if (v === "O" || v === "L" || v === "R") n++; else break;
    }
    for (let j = idx + 1; j < dates.length; j++) {
      const v = grid[ec][dates[j].d];
      if (v === "O" || v === "L" || v === "R") n++; else break;
    }
    return n;
  };
  // Helper: spacing in days from candidate to the nearest existing off
  // (or large value if no offs yet)
  const spacingTo = (ec, candDay) => {
    const idx = dates.findIndex(x => x.d === candDay);
    let best = 999;
    for (let j = 0; j < dates.length; j++) {
      if (j === idx) continue;
      const v = grid[ec][dates[j].d];
      if (v === "O" || v === "L" || v === "R") {
        const dist = Math.abs(j - idx);
        if (dist < best) best = dist;
      }
    }
    return best;
  };

  // For each manager, run backtracking solver across all full weeks
  // that need 2 offs (skipping weeks where the weekend pair already
  // contributes 2). Backtracking guarantees max-run ≤ 6 if a solution
  // exists; falls back to greedy if no solution exists.
  for (const h of f) {
    // Build the list of full weeks needing offs (with their target need)
    const weeksToFill = [];
    for (const w of wkOrder) {
      const days = wkMap[w];
      if (days.length < 7) continue;
      const need = 2 - offWk[h.ec][w];
      if (need > 0) weeksToFill.push({ w, days, need });
    }
    if (weeksToFill.length === 0) continue;

    // Compute longest W/null-run for THIS manager only (treats null as W
    // since unfilled weeks would otherwise be working).
    const maxRunForManager = () => {
      let run = 0, mx = 0;
      for (const x of dates) {
        const v = grid[h.ec][x.d];
        if (v === "O" || v === "L" || v === "R") run = 0;
        else { run++; if (run > mx) mx = run; }
      }
      return mx;
    };
    // Best-case max-run: treat NULL as off (we haven't decided yet — they
    // CAN become offs in a later level). Used as the prune check so we
    // don't kill branches that are still solvable.
    const minMaxRunIfNullsBecomeOffs = () => {
      let run = 0, mx = 0;
      for (const x of dates) {
        const v = grid[h.ec][x.d];
        if (v === "O" || v === "L" || v === "R" || v == null) run = 0;
        else { run++; if (run > mx) mx = run; }
      }
      return mx;
    };

    // Backtracking search
    const tryWeek = (i) => {
      if (i >= weeksToFill.length) {
        return maxRunForManager() <= 6;
      }
      const { days, need } = weeksToFill[i];
      // Generate candidate combinations
      // Small-team rule: stores with exactly 2 managers (total) are allowed
      // to run with 1 mgr on duty so the 6-consec cap and 2-off-per-week
      // rule can both be honoured. 3+ manager stores always require >=2
      // working, even when one is on leave (those cases surface as
      // conflicts for manual review).
      const candidates = [];
      if (need === 2) {
        for (let a = 0; a < days.length; a++) {
          if (grid[h.ec][days[a].d] != null) continue;
          if ((m - W[days[a].d].off - W[days[a].d].leave - 1) < _minCoverageFor(days[a].d)) continue;
          for (let b = a + 1; b < days.length; b++) {
            if (grid[h.ec][days[b].d] != null) continue;
            if ((m - W[days[b].d].off - W[days[b].d].leave - 1) < _minCoverageFor(days[b].d)) continue;
            candidates.push([days[a], days[b]]);
          }
        }
      } else {
        for (const d of days) {
          if (grid[h.ec][d.d] != null) continue;
          if ((m - W[d.d].off - W[d.d].leave - 1) < _minCoverageFor(d.d)) continue;
          candidates.push([d]);
        }
      }
      // Score: prefer mid-week (dow weight) + adjacency bonus + late-in-cycle
      // bonus when a weekend pair sits in the next week.
      const scoreCombo = (combo) => {
        let s = 0;
        for (const d of combo) s += (dowOrd[d.dow] || 0) * 10;
        if (combo.length === 2) {
          const idxA = dates.indexOf(combo[0]);
          const idxB = dates.indexOf(combo[1]);
          if (Math.abs(idxA - idxB) === 1) s += 30;     // adjacency bonus
        }
        // Smooth W-coverage: penalise days that already have many offs
        for (const d of combo) s -= W[d.d].off * 5;
        return s;
      };
      candidates.sort((a, b) => scoreCombo(b) - scoreCombo(a));
      // Try each candidate in scored order
      for (const combo of candidates) {
        // Apply
        for (const d of combo) {
          grid[h.ec][d.d] = "O";
          W[d.d].off++;
          offWk[h.ec][wkOfDay[d.d]]++;
        }
        // Prune: max-run check after this placement
        if (maxRunForManager() <= 6) {
          if (tryWeek(i + 1)) return true;
        }
        // Undo
        for (const d of combo) {
          grid[h.ec][d.d] = null;
          W[d.d].off--;
          offWk[h.ec][wkOfDay[d.d]]--;
        }
      }
      return false;
    };

    if (!tryWeek(0)) {
      // Backtracking failed — fall back to greedy Mon-Tue placement
      // for any week still missing offs (will report conflict later).
      for (const wt of weeksToFill) {
        let need = 2 - offWk[h.ec][wt.w];
        for (const d of wt.days) {
          if (need <= 0) break;
          if (grid[h.ec][d.d] != null) continue;
          // Same small-team rule as the backtracker.
          if ((m - W[d.d].off - W[d.d].leave - 1) < _minCoverageFor(d.d)) continue;
          grid[h.ec][d.d] = "O";
          W[d.d].off++;
          offWk[h.ec][wkOfDay[d.d]]++;
          need--;
        }
      }
    }
  }

  // ── Default fill: any remaining null → W ─────────────────────────
  for (const h of f) for (const x of dates) {
    if (grid[h.ec][x.d] == null) { grid[h.ec][x.d] = "W"; W[x.d].working++; }
  }

  // ── 7-consecutive-day fix (1:1 port from old HTML, 5 passes) ──────
  // For each manager: find longest W-run; build _swappable list of off
  // days OUTSIDE the run within the run's ISO weeks (skipping pair-
  // locked weekend offs); for each src in turn, pick the in-run target
  // that yields the smallest new max-run; apply if it improves; first
  // src that yields an improvement wins (no exhaustive search).
  // Coverage check: only the target-day → O transition (target's
  // working count must stay ≥ 2). Run counter only counts "W" (NOT "E").
  for (let pass = 0; pass < 5; pass++) {
    let anyFix = false;
    for (const h of f) {
      let run = 0, rs = -1, maxRun = 0, maxRs = -1, maxRe = -1;
      for (let i = 0; i < dates.length; i++) {
        const v = grid[h.ec][dates[i].d];
        if (v === "W" || v === "WE" || v === "WB" || v === "WM" || v === "WL") {
          if (run === 0) rs = i;
          run++;
          if (run > maxRun) { maxRun = run; maxRs = rs; maxRe = i; }
        } else run = 0;
      }
      if (maxRun < 7) continue;
      const runWks = new Set();
      for (let i = maxRs; i <= maxRe; i++) runWks.add(wkOfDay[dates[i].d]);
      const swappable = [];
      for (let i = 0; i < dates.length; i++) {
        if (grid[h.ec][dates[i].d] !== "O") continue;
        if (!runWks.has(wkOfDay[dates[i].d])) continue;
        if (i >= maxRs && i <= maxRe) continue;            // outside the run
        if (pairLocked[h.ec].has(dates[i].d)) continue;
        swappable.push(i);
      }
      let fixed = false;
      for (const src of swappable) {
        if (fixed) break;
        const srcWk = wkOfDay[dates[src].d];
        let bestIx = -1, bestNew = maxRun;
        for (let ix = maxRs; ix <= maxRe; ix++) {
          // OLD restricts targets to the SAME ISO WEEK as the source-O.
          if (wkOfDay[dates[ix].d] !== srcWk) continue;
          const wb = m - W[dates[ix].d].off - W[dates[ix].d].leave;
          // Small-team rule: 2 or fewer available that day (true 2-mgr
          // store, or 3-mgr store with one on leave) allows 1-mgr days.
          if (wb - 1 < _minCoverageFor(dates[ix].d)) continue;  // target's coverage
          // Try the swap, measure new max run, revert
          const oldSrc = grid[h.ec][dates[src].d];
          const oldTgt = grid[h.ec][dates[ix].d];
          grid[h.ec][dates[src].d] = "W";
          grid[h.ec][dates[ix].d] = "O";
          let nr = 0, nm = 0;
          for (let j = 0; j < dates.length; j++) {
            { const _vv = grid[h.ec][dates[j].d]; if (_vv === "W" || _vv === "WE" || _vv === "WB" || _vv === "WM" || _vv === "WL") { nr++; if (nr > nm) nm = nr; } else nr = 0; }
          }
          grid[h.ec][dates[src].d] = oldSrc;
          grid[h.ec][dates[ix].d] = oldTgt;
          if (nm < bestNew) { bestNew = nm; bestIx = ix; }
        }
        if (bestIx >= 0) {
          // Apply
          grid[h.ec][dates[src].d] = "W";
          W[dates[src].d].off--; W[dates[src].d].working++; offWk[h.ec][wkOfDay[dates[src].d]]--;
          grid[h.ec][dates[bestIx].d] = "O";
          W[dates[bestIx].d].working--; W[dates[bestIx].d].off++; offWk[h.ec][wkOfDay[dates[bestIx].d]]++;
          fixed = true; anyFix = true;
        }
      }
    }
    if (!anyFix) break;
  }

  // ── Partial-week off allocation (pre-fill so HARD max-6 stays compatible
  //    with HARD 2-offs-per-FULL-week) ───────────────────────────────────
  // Full weeks already have their 2 offs from the backtracking solver. The
  // leading and trailing partial weeks were never touched. With 4-manager
  // teams and a mid-week cycle start, that leaves runs that span partial+
  // full+full at 7-10 days. Place offs in the partial weeks now — limited
  // by the cross-month carry — so the HARD max-6 step that follows can rely
  // on swap-only moves and never has to push a full week to 3 offs.
  const isFullWeek = (wk) => wkMap[wk] && wkMap[wk].length === 7;
  const isPartialWeek = (wk) => wkMap[wk] && wkMap[wk].length < 7;
  const partialCarry = (ec, wk) => {
    if (wk === leadingWk && isLeadingPartial) return +priorOffs[ec] || 0;
    if (wk === trailingWk && isTrailingPartial) return +nextOffs[ec] || 0;
    return 0;
  };
  const longestWRun = (ec) => {
    let run = 0, mx = 0;
    for (const x of dates) {
      const v = grid[ec][x.d];
      if (v === "W" || v === "WE" || v === "WB" || v === "WM" || v === "WL" || v === "E") { run++; if (run > mx) mx = run; }
      else if (v === null || v === undefined) { run++; if (run > mx) mx = run; }
      else run = 0;
    }
    return mx;
  };
  for (const h of f) {
    for (const wk of [leadingWk, trailingWk]) {
      if (!isPartialWeek(wk)) continue;
      // offWk already includes the cross-month carry (we seeded it earlier so
      // the weekend-pair gate respects it). So the cap is simply 2 - offWk[wk].
      let capacity = 2 - offWk[h.ec][wk];
      if (capacity <= 0) continue;
      // Aim for proportional offs: roughly weekLen * 2 / 7, but never above capacity
      const weekLen = wkMap[wk].length;
      let want = Math.min(capacity, Math.max(0, Math.round(weekLen * 2 / 7)));
      if (want <= 0 && longestWRun(h.ec) >= 7) want = Math.min(1, capacity);
      // For very short partials with carry already at the cap, still try to
      // place 1 off if the manager would otherwise span the rollover with no
      // off-day on either side. This keeps the rollover week visibly humane
      // even when the carry from the adjacent cycle is positioned far from
      // this end of the week.
      if (want <= 0 && capacity >= 1) {
        // Check if this manager has ANY off in the partial week's days within
        // the current cycle. If not, force-place 1 off here for "seamless flow".
        let hasOff = false;
        for (const dy of wkMap[wk]) {
          const v = grid[h.ec][dy.d];
          if (v === "O" || v === "L" || v === "R") { hasOff = true; break; }
        }
        if (!hasOff) want = 1;
      }
      while (want-- > 0) {
        // Pick the W day in the partial that, when made O, minimises this
        // manager's max-run (and preserves coverage).
        let best = null, bestMax = Infinity;
        for (const dy of wkMap[wk]) {
          const cur = grid[h.ec][dy.d];
          if (cur !== "W") continue;
          if (pairLocked[h.ec].has(dy.d)) continue;
          // Small-team rule applied per-day. Rollover/partial weeks
          // honour the same 2-off cap as full weeks via offWk +
          // partialCarry, so the rules apply uniformly across the
          // cycle boundary.
          if ((m - W[dy.d].off - W[dy.d].leave - 1) < _minCoverageFor(dy.d)) continue;
          grid[h.ec][dy.d] = "O";
          const mx = longestWRun(h.ec);
          grid[h.ec][dy.d] = "W";
          if (mx < bestMax) { bestMax = mx; best = dy; }
        }
        if (!best) break;
        grid[h.ec][best.d] = "O";
        W[best.d].working--;
        W[best.d].off++;
        offWk[h.ec][wk]++;
      }
    }
  }

  // ── HARD max-6 enforcement (labour law) — preserves 2-offs-per-FULL-week
  // Both rules are hard. Strategies allowed:
  //   STEP 1  Same-week swap inside a full week — counts unchanged.
  //   STEP 2  Cross-week swap where the SOURCE is a partial week (no 2-target)
  //           AND the TARGET week stays within its cap (full ≤ 2, partial
  //           ≤ 2 - carry).
  //   STEP 3  Insert in a partial week with remaining capacity (≤ 2-carry).
  //   The cross-week-swap-into-full-week-already-at-2 path is BANNED — that
  //   would push the full week to 3 offs.
  for (const h of f) {
    for (let pass = 0; pass < 30; pass++) {
      let run = 0, rs = -1, maxRun = 0, maxRs = -1, maxRe = -1;
      for (let i = 0; i < dates.length; i++) {
        const v = grid[h.ec][dates[i].d];
        if (v === "W" || v === "WE" || v === "WB" || v === "WM" || v === "WL" || v === "E") {
          if (run === 0) rs = i;
          run++;
          if (run > maxRun) { maxRun = run; maxRs = rs; maxRe = i; }
        } else run = 0;
      }
      if (maxRun <= 6) break;

      // STEPS 1+2 — best swap that respects 2-per-full-week
      let bestSwap = null, bestSwapMax = maxRun;
      for (let src = 0; src < dates.length; src++) {
        const sv = grid[h.ec][dates[src].d];
        if (sv !== "O" && sv !== "E") continue;
        if (pairLocked[h.ec].has(dates[src].d)) continue;
        const srcWk = wkOfDay[dates[src].d];
        for (let ix = maxRs; ix <= maxRe; ix++) {
          const tgtWk = wkOfDay[dates[ix].d];
          const sameWk = srcWk === tgtWk;
          if (!sameWk) {
            // Cross-week swap allowed only when source is partial AND
            // target's cap won't be breached.
            if (!isPartialWeek(srcWk)) continue;
            if (isFullWeek(tgtWk)) {
              // target full week — must already be < 2 offs
              if (offWk[h.ec][tgtWk] >= 2) continue;
            } else if (isPartialWeek(tgtWk)) {
              const carryT = partialCarry(h.ec, tgtWk);
              if (offWk[h.ec][tgtWk] + carryT >= 2) continue;
            }
          }
          const wb = m - W[dates[ix].d].off - W[dates[ix].d].leave;
          // Small-team rule applied per-day.
          if (wb - 1 < _minCoverageFor(dates[ix].d)) continue;
          const oS = grid[h.ec][dates[src].d];
          const oT = grid[h.ec][dates[ix].d];
          grid[h.ec][dates[src].d] = "W";
          grid[h.ec][dates[ix].d] = "O";
          let nr = 0, nm = 0;
          for (let j = 0; j < dates.length; j++) {
            const v2 = grid[h.ec][dates[j].d];
            if (v2 === "W" || v2 === "WE" || v2 === "WB" || v2 === "WM" || v2 === "WL" || v2 === "E") { nr++; if (nr > nm) nm = nr; } else nr = 0;
          }
          grid[h.ec][dates[src].d] = oS;
          grid[h.ec][dates[ix].d] = oT;
          if (nm < bestSwapMax) { bestSwapMax = nm; bestSwap = { src, ix }; }
        }
      }
      if (bestSwap) {
        const { src, ix } = bestSwap;
        grid[h.ec][dates[src].d] = "W";
        W[dates[src].d].off--; W[dates[src].d].working++; offWk[h.ec][wkOfDay[dates[src].d]]--;
        grid[h.ec][dates[ix].d] = "O";
        W[dates[ix].d].working--; W[dates[ix].d].off++; offWk[h.ec][wkOfDay[dates[ix].d]]++;
        continue;
      }

      // STEP 3 — insert in a PARTIAL week with capacity (preserves 2/full-week)
      const insertOrder = [];
      for (let i = maxRs + 6; i <= maxRe; i++) insertOrder.push(i);
      for (let i = maxRs + 5; i >= maxRs; i--) insertOrder.push(i);
      let inserted = false;
      for (const ix of insertOrder) {
        const tgtWk = wkOfDay[dates[ix].d];
        if (!isPartialWeek(tgtWk)) continue;
        const carryT = partialCarry(h.ec, tgtWk);
        if (offWk[h.ec][tgtWk] + carryT >= 2) continue;
        const wb = m - W[dates[ix].d].off - W[dates[ix].d].leave;
        // Small-team rule applied per-day.
        if (wb - 1 < _minCoverageFor(dates[ix].d)) continue;
        grid[h.ec][dates[ix].d] = "O";
        W[dates[ix].d].working--; W[dates[ix].d].off++; offWk[h.ec][wkOfDay[dates[ix].d]]++;
        inserted = true;
        break;
      }
      if (!inserted) break; // unsolvable with hard 2/week + max-6 — surface as conflict
    }
  }

  // ── Day totals + conflicts ────────────────────────────────────────
  const dayTotals = {};
  for (const x of dates) {
    let w = 0, o = 0, l = 0, r = 0;
    for (const h of f) {
      const v = grid[h.ec][x.d];
      // WE / WL are working states too (Sandown early/late split).
      if (v === "W" || v === "WE" || v === "WB" || v === "WM" || v === "WL") w++;
      else if (v === "O") o++;
      else if (v === "L") l++;
      else if (v === "R") { r++; o++; }
    }
    dayTotals[x.d] = { working: w, off: o, leave: l, requested: r };
  }
  const conflicts = [];
  for (const x of dates) {
    const w = dayTotals[x.d].working;
    // Small-team rule applied per-day: a true 2-mgr store, or a 3-mgr store
    // where one is on leave that day, may run with a single mgr — don't
    // flag those as 'solo' conflicts. 3+ mgrs available → require >=2.
    if (w < _minCoverageFor(x.d)) conflicts.push({ type: "solo_or_empty", msg: x.d + ": only " + w + " manager(s) working", severity: "high", date: x.d });
  }
  // Map of managers who submitted off-day requests this cycle. A request
  // can overrule the guaranteed weekend pair (the request takes priority,
  // and we don't surface a "short weekend" conflict for that manager).
  const hasReq = new Set();
  for (const r of (requests || [])) if (r && r.ec) hasReq.add(r.ec);
  for (const h of f) {
    const need = (h.role === "SM" || h.role === "SSM") ? 2 : 1;
    const have = wePairs(h);
    // Skip the Sat+Sun pair conflict on branches with fixed closed days —
    // every manager already has a guaranteed weekly off-block from the
    // store-closed seed (e.g. Betty: Sun+Mon).
    if (!_skipWePair && have < need && !hasReq.has(h.ec)) conflicts.push({ type: "short_weekend", msg: h.name + " has " + have + " weekend(s) off (target " + need + ")", severity: "medium", ec: h.ec });
    for (const w of wkOrder) {
      if (wkMap[w].length < 7) continue;
      if (offWk[h.ec][w] < 2) conflicts.push({ type: "short_off_week", msg: h.name + " has " + offWk[h.ec][w] + " off in " + w + " (target 2)", severity: "medium", ec: h.ec, week: w });
    }
    // Cross-month rollover: leading partial-week effective off-count
    // (in-cycle + prior tail) must still respect the 2-cap.
    if (isLeadingPartial && offWk[h.ec][leadingWk] > 2) {
      const inCycle = offWk[h.ec][leadingWk] - (+priorOffs[h.ec] || 0);
      conflicts.push({ type: "rollover_overlimit", msg: h.name + " has " + offWk[h.ec][leadingWk] + " off-days in the rollover week (" + inCycle + " this cycle + " + (+priorOffs[h.ec] || 0) + " prior) — over the 2-cap", severity: "high", ec: h.ec, week: leadingWk });
    }
    // Trailing partial — same check on the cycle's tail week.
    if (isTrailingPartial && offWk[h.ec][trailingWk] > 2) {
      const inCycle = offWk[h.ec][trailingWk] - (+nextOffs[h.ec] || 0);
      conflicts.push({ type: "rollover_overlimit", msg: h.name + " has " + offWk[h.ec][trailingWk] + " off-days in the closing rollover week (" + inCycle + " this cycle + " + (+nextOffs[h.ec] || 0) + " next) — over the 2-cap", severity: "high", ec: h.ec, week: trailingWk });
    }
    let run = 0, seen7 = false;
    for (const x of dates) {
      const _v = grid[h.ec][x.d];
      if (_v === "W" || _v === "WE" || _v === "WB" || _v === "WM" || _v === "WL") {
        run++;
        if (run >= 7 && !seen7) { conflicts.push({ type: "consecutive", msg: h.name + " " + run + "+ consecutive working days", severity: "high", ec: h.ec }); seen7 = true; }
      } else { run = 0; seen7 = false; }
    }
  }
  // If this cycle starts mid-week but the prior cycle hasn't been
  // generated yet, the cross-month overlap can't be enforced. Surface
  // it as a single info-level conflict so the user knows.
  if (isLeadingPartial && priorMissing) {
    conflicts.push({ type: "prior_missing", msg: "Prior month's manager schedule not generated yet — the leading rollover week's 2-off cap can't be enforced across the boundary. Generate the prior cycle first for full coverage.", severity: "medium" });
  }
  if (isTrailingPartial && nextMissing) {
    conflicts.push({ type: "next_missing", msg: "Next month's manager schedule not generated yet — the closing rollover week's 2-off cap is provisional. When you generate the next cycle, that boundary will be re-checked.", severity: "medium" });
  }
  // Ghost overlay (offboard / onboarding)
  for (const h of f) {
    if (h.leftDate) {
      h._offGhost = true;
      h._offLeftDate = h.leftDate;
      h._offReason = h.offRec ? h.offRec.reason : "";
      if (grid[h.ec]) for (const x of dates) if (x.d > h.leftDate) grid[h.ec][x.d] = "X";
    }
    // Pre-start blanking: a manager only exists on the schedule from their
    // start date. Blank (X → rendered "—") any cell before it so a mid-cycle
    // hire — e.g. a promoted trial AM starting on the 8th — isn't scheduled
    // for the whole month. The onboarding wrapper carries _startDate; a saved
    // or just-promoted manager carries startDate (and no _onboarding flag), so
    // gate on either. Established managers are unaffected — no cycle day falls
    // before a past start date. Done here in the solver (not only in the tab's
    // post-load pass) so the Generate / Sync drafts and the published schedule
    // are blanked too, not just the on-screen view.
    const _startD = h._startDate || h.startDate;
    if (_startD) {
      if (h._onboarding) { h._obStarting = true; h._obStartDate = _startD; }
      if (grid[h.ec]) for (const x of dates) if (x.d < _startD) grid[h.ec][x.d] = "X";
    }
  }
  // Seed grid rows for on-mat managers (they were not in `f` so the
  // grid-init loop above didn't create their row). Every day shows 'ML'
  // so the schedule grid renders a greyed maternity-leave band for them.
  for (const h of fAll) {
    if (!h._onMat) continue;
    if (!grid[h.ec]) grid[h.ec] = {};
    for (const x of dates) grid[h.ec][x.d] = "ML";
  }
  // Return fAll (not f) so on-mat managers appear on the rendered
  // schedule. Their row is greyed via _onMat and every cell reads 'ML'.
  return { managers: fAll, dates, grid, conflicts, dayTotals, branch: branchName, cycleStart: cycleStartYmd, cycleEnd, weekOrder: wkOrder, weeksMap: wkMap };
}

// Manager grids are canonically keyed by YYYY-MM-DD (see mgrSched). A couple
// of writers historically saved day-of-month numeric keys instead, which the
// Schedule-tab overview can't read — it looks every cell up by YYYY-MM-DD, so
// a numeric-keyed row rendered as all-working with no off-days. Re-key any bare
// day-of-month keys to the matching YYYY-MM-DD inside the cycle (25th of the
// start month → 24th of the next), healing those rows on load. YYYY-MM-DD keys
// already present are kept as-is (and win over any duplicate numeric key).
function rekeyMgrGridToYmd(grid, cycleStartYmd) {
  if (!grid || !cycleStartYmd) return grid || {};
  const parts = cycleStartYmd.split("-").map(Number);
  const sy = parts[0], sm = parts[1];                 // start year, start month (1-12)
  if (!sy || !sm) return grid;
  const p2 = n => String(n).padStart(2, "0");
  const out = {};
  for (const ec in grid) {
    const row = grid[ec] || {};
    const conv = {};
    for (const k in row) {
      if (/^\d{4}-\d{2}-\d{2}$/.test(k)) { conv[k] = row[k]; continue; }
      const dom = parseInt(k, 10);
      if (!isNaN(dom) && dom >= 1 && dom <= 31 && String(dom) === String(k).trim()) {
        let y = sy, mo = sm;                           // days 25..31 → start month; 1..24 → next month
        if (dom <= 24) { mo = sm + 1; if (mo > 12) { mo = 1; y = sy + 1; } }
        const ymdKey = y + "-" + p2(mo) + "-" + p2(dom);
        if (!(ymdKey in conv)) conv[ymdKey] = row[k];
      } else {
        conv[k] = row[k];
      }
    }
    out[ec] = conv;
  }
  return out;
}


// ─── CONFIG ──────────────────────────────────────────────────────────────────────
// Each salon carries a `region` key — used by the Locations tab filter and
// any future regional reporting. Values: "wc" (Western Cape), "gauteng",
// "kzn". Custom branches added at runtime default to "wc" if they were
// saved before this field existed.

// ── Reusable searchable staff/manager picker ──────────────────────────────
// Drop-in replacement for the plain <select> dropdowns we use to pick a
// staff member. Filters as you type by name OR EC, shows up to 30 hits,
// closes on outside-click or selection. `formatOption` lets each call site
// control the label (default: "EC · Name").
function StaffPicker({ people, valueEc, onChange, placeholder, formatOption, style, disabled }) {
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState("");
  const containerRef = useRef(null);
  const inputRef = useRef(null);
  useEffect(() => {
    const onDoc = (e) => {
      if (containerRef.current && !containerRef.current.contains(e.target)) {
        setOpen(false);
        setQuery("");
      }
    };
    document.addEventListener("mousedown", onDoc);
    return () => document.removeEventListener("mousedown", onDoc);
  }, []);
  const list = Array.isArray(people) ? people : [];
  const selected = valueEc ? list.find(p => p && p.ec === valueEc) : null;
  const fmt = formatOption || ((p) => (p.ec || "—") + " · " + (p.name || ""));
  const q = (query || "").trim().toLowerCase();
  const matches = q === ""
    ? list.slice(0, 30)
    : list.filter(p =>
      ((p.name || "").toLowerCase().includes(q)) ||
      ((p.ec || "").toLowerCase().includes(q))
    ).slice(0, 30);
  const inputStyle = {
    width: "100%", padding: "7px 10px", borderRadius: 8, border: "1px solid #FBCFE8",
    fontSize: 13, fontFamily: "inherit", background: disabled ? "#f3f4f6" : "#fff",
    boxSizing: "border-box", ...(style || {})
  };
  return (
    <div ref={containerRef} style={{ position: "relative" }}>
      <input
        ref={inputRef}
        type="text"
        disabled={disabled}
        value={open ? query : (selected ? fmt(selected) : "")}
        onFocus={() => { setQuery(""); setOpen(true); }}
        onChange={(e) => { setQuery(e.target.value); setOpen(true); }}
        placeholder={placeholder || ("Search " + list.length + " staff by name or EC…")}
        style={inputStyle}
        autoComplete="off"
      />
      {selected && !open && (
        <button type="button" onMouseDown={(e) => { e.preventDefault(); onChange && onChange(""); setQuery(""); }}
          style={{ position: "absolute", right: 8, top: "50%", transform: "translateY(-50%)", background: "transparent", border: "none", color: "#9ca3af", cursor: "pointer", fontSize: 14, padding: "0 4px" }}
          title="Clear"
        >×</button>
      )}
      {open && (
        <div style={{ position: "absolute", top: "calc(100% + 4px)", left: 0, right: 0, background: "#fff", border: "1px solid #FBCFE8", borderRadius: 8, maxHeight: 260, overflowY: "auto", zIndex: 200, boxShadow: "0 8px 20px rgba(0,0,0,0.12)" }}>
          {matches.length === 0 ? (
            <div style={{ padding: "9px 12px", fontSize: 12, color: "#9ca3af", fontStyle: "italic" }}>No matches</div>
          ) : matches.map((p, i) => (
            <div key={(p.ec || "") + "_" + i}
              onMouseDown={(e) => { e.preventDefault(); onChange && onChange(p.ec); setOpen(false); setQuery(""); }}
              style={{ padding: "8px 12px", cursor: "pointer", fontSize: 13, borderBottom: i < matches.length - 1 ? "1px solid #FCE7F3" : "none", display: "flex", alignItems: "center", gap: 8 }}
              onMouseEnter={(e) => { e.currentTarget.style.background = "#FCE7F3"; }}
              onMouseLeave={(e) => { e.currentTarget.style.background = "#fff"; }}
            >
              <span style={{ fontFamily: "monospace", color: "#9ca3af", fontSize: 11, minWidth: 40 }}>{p.ec || "—"}</span>
              <span style={{ flex: 1, color: "#111827", fontWeight: 600 }}>{p.name || "(no name)"}</span>
              {p.branch && <span style={{ fontSize: 11, color: "#6b7280" }}>📍 {p.branch}</span>}
              {p.role && <span style={{ fontSize: 9, fontWeight: 700, padding: "1px 6px", borderRadius: 99, background: "#FCE7F3", color: "#831843" }}>{p.role}</span>}
              {p.onMat && <span style={{ fontSize: 9, fontWeight: 700, padding: "1px 6px", borderRadius: 99, background: "#FBCFE8", color: "#831843" }}>🤱</span>}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

