// ─── TINY COMPONENTS ─────────────────────────────────────────────────────────────
function Chip({ bg, color, border, children }) {
  return <span style={{ background: bg, color, border: `1px solid ${border}`, borderRadius: 20, padding: "3px 10px", fontSize: 11, fontWeight: 700, whiteSpace: "nowrap", display: "inline-flex", alignItems: "center", gap: 4 }}>{children}</span>;
}
const CompBadge = ({ permit }) => { const c = COMPLIANCE[permit] || COMPLIANCE.z_na; return <Chip bg={c.bg} color={c.color} border={c.border}>{c.icon} {c.label}</Chip>; };
const LevelBadge = ({ level }) => {
  if (!level) return <span style={{ color: "#d1d5db", fontSize: 11 }}>—</span>;
  const m = { One: ["#e0e7ff", "#3730a3"], Two: ["#ede9fe", "#5b21b6"], Three: ["#cffafe", "#155e75"] };
  const [bg, c] = m[level] || ["#f3f4f6", "#374151"];
  return <span style={{ background: bg, color: c, borderRadius: 6, padding: "3px 9px", fontSize: 11, fontWeight: 700 }}>{level}</span>;
};
// BOA Pathways — the programme for unemployed South Africans some staff come
// through. Graduates get a 🎓 cap next to their name (hover for the label).
const BoaPathwaysBadge = ({ size }) => (
  <span title="BOA Pathways graduate" style={{ fontSize: size || 13, cursor: "default" }}>🎓</span>
);
// Bargaining council — staff signed up with the council have a sick-pay fund,
// so the company doesn't pay their sick days (the fund covers it). Members get
// a 🤝 badge next to their name (hover for the label).
const BargainingCouncilBadge = ({ size }) => (
  <span title="Bargaining council member — sick days covered by the council fund (not paid by the company)" style={{ fontSize: size || 13, cursor: "default" }}>🤝</span>
);
function Meter({ current, capacity, goal, lowDemand, projected }) {
  const target = goal || capacity;
  const pct = Math.min(current / target * 100, 100);
  const col = current === 0 ? "#dc2626" : current < target * 0.6 ? "#f97316" : current < target ? "#eab308" : "#16a34a";
  // `projected` is the headcount once all pending transfers settle. Only show
  // the second marker/label when it differs from the live count, so stores
  // with no pending moves keep the original single-number meter.
  const hasProjection = typeof projected === "number" && projected !== current;
  const projPct = hasProjection ? Math.min(projected / target * 100, 100) : 0;
  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", fontSize: 11, fontWeight: 700, marginBottom: 3, color: current >= target ? "#15803d" : "#9a3412" }}>
        <span>{current} / {target} active{lowDemand ? " (target)" : ""}</span>
        <span>{current >= target ? "✓ Sufficient" : `${target - current} needed`}</span>
      </div>
      <div style={{ position: "relative", height: 7, borderRadius: 99, background: "#e5e7eb", overflow: "hidden" }}>
        <div style={{ height: "100%", width: `${pct}%`, background: col, borderRadius: 99, transition: "width .4s" }} />
        {/* Dashed marker for the after-transfers headcount. */}
        {hasProjection && (
          <div title={`After transfers: ${projected} active`} style={{ position: "absolute", top: -1, bottom: -1, left: `calc(${projPct}% - 1px)`, width: 2, background: "#1d4ed8" }} />
        )}
      </div>
      {hasProjection && (
        <div style={{ display: "flex", justifyContent: "space-between", fontSize: 10, fontWeight: 700, marginTop: 3, color: "#1d4ed8" }}>
          <span>🔮 After transfers: {projected} / {target} active</span>
          <span>{projected >= target ? "✓ Sufficient" : `${target - projected} needed`}</span>
        </div>
      )}
    </div>
  );
}

// ─── MATERNITY MODAL ─────────────────────────────────────────────────────────────
function MatModal({ rec, onClose, onSave, onDelete, people }) {
  const [f, setF] = useState({ ...rec });
  const [search, setSearch] = useState("");
  const set = (k, v) => setF(p => ({ ...p, [k]: v }));
  const inp = { width: "100%", padding: "8px 11px", borderRadius: 8, border: "1px solid #FBCFE8", background: "#FCE7F3", fontFamily: "inherit", fontSize: 13, boxSizing: "border-box" };
  const lbl = { display: "block", fontSize: 10, fontWeight: 700, color: "#BE185D", letterSpacing: "0.08em", marginBottom: 4, textTransform: "uppercase" };
  const isNew = !rec._id;
  // Lookup pool for new records: techs + managers. Match by name OR EC, up
  // to 10 results. Picking auto-fills EC, name and branch so the record
  // links back to the existing staff row cleanly.
  const pool = (people || []).filter(p => p && p.ec);
  const q = (search || "").trim().toLowerCase();
  const matches = !q ? [] : pool
    .filter(p => (p.name || "").toLowerCase().includes(q) || (p.ec || "").toLowerCase().includes(q))
    .slice(0, 10);
  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,.55)", zIndex: 300, display: "flex", alignItems: "center", justifyContent: "center", padding: 16 }}
      onClick={e => e.target === e.currentTarget && onClose()}>
      <div style={{ background: "#FFFFFF", borderRadius: 22, width: "min(520px,96vw)", maxHeight: "90vh", overflowY: "auto", padding: "30px 28px", boxShadow: "0 30px 90px rgba(0,0,0,.22)" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 20 }}>
          <h2 style={{ fontFamily: "'Cormorant Garamond',serif", fontSize: 24, color: "#111827", margin: 0 }}>{!rec._id ? "Add Record" : "Edit Maternity Record"}</h2>
          <button onClick={onClose} style={{ background: "none", border: "none", fontSize: 24, cursor: "pointer", color: "#9ca3af" }}>×</button>
        </div>

        {/* Status explanation */}
        <div style={{ background: "#FCE7F3", border: "1px solid #fde68a", borderRadius: 10, padding: "10px 14px", marginBottom: 16, fontSize: 12, color: "#831843", lineHeight: 1.5 }}>
          <strong>🤰 Pregnant</strong> = still working in the store, counts toward staffing.<br />
          <strong>🤱 On Maternity Leave</strong> = not in the store, <em>excluded</em> from the store's active count + the schedule (marked ML).
        </div>

        {/* Staff lookup — only on new records. Searches techs + managers
            and auto-fills EC / name / branch so the record links back to
            the staff row. Manual fields below stay editable. */}
        {isNew && (
          <div style={{ background: "#FFFBEB", border: "1px solid #FDE68A", borderRadius: 10, padding: "12px 14px", marginBottom: 14 }}>
            <label style={{ display: "block", fontSize: 11, fontWeight: 700, color: "#78350F", textTransform: "uppercase", letterSpacing: "0.06em", marginBottom: 6 }}>Pick from existing staff</label>
            <input
              type="text"
              autoFocus
              value={search}
              onChange={e => setSearch(e.target.value)}
              placeholder={"Search " + pool.length + " people by name or EC…"}
              style={{ width: "100%", padding: "9px 11px", border: "1px solid #FDE68A", borderRadius: 8, fontSize: 14, fontFamily: "inherit", boxSizing: "border-box" }}
            />
            {q && (
              <div style={{ marginTop: 8, maxHeight: 220, overflowY: "auto", border: "1px solid #FDE68A", borderRadius: 8, background: "#fff" }}>
                {matches.length === 0 ? (
                  <div style={{ padding: "10px 12px", fontSize: 12, color: "#9ca3af", fontStyle: "italic" }}>No matches.</div>
                ) : matches.map(p => (
                  <div key={(p.ec || "") + "_" + (p.role || "tech")}
                    onClick={() => { setF({ ...f, ec: p.ec, name: p.name || "", branch: p.branch || (SALONS[0] && SALONS[0].name) || "" }); setSearch(""); }}
                    style={{ padding: "8px 12px", borderBottom: "1px solid #FEF3C7", cursor: "pointer", display: "flex", alignItems: "center", gap: 10 }}
                    onMouseEnter={e => e.currentTarget.style.background = "#FEF3C7"}
                    onMouseLeave={e => e.currentTarget.style.background = "#fff"}
                  >
                    <span style={{ fontSize: 11, fontFamily: "monospace", color: "#92400e", fontWeight: 700, minWidth: 42 }}>{p.ec}</span>
                    <span style={{ flex: 1, fontSize: 13, color: "#111827", fontWeight: 600 }}>{p.name}</span>
                    <span style={{ fontSize: 11, color: "#6b7280" }}>📍 {p.branch || "—"}</span>
                    <span style={{ fontSize: 9, fontWeight: 700, padding: "1px 6px", borderRadius: 99, background: p.role === "NT" ? "#FCE7F3" : "#ede9fe", color: p.role === "NT" ? "#831843" : "#7c3aed" }}>{p.role === "NT" ? "Tech" : (p.role || "Mgr")}</span>
                  </div>
                ))}
              </div>
            )}
            {f.ec && !q && (
              <div style={{ marginTop: 8, padding: "8px 12px", background: "#FEF3C7", borderRadius: 8, fontSize: 12, color: "#78350F" }}>
                Selected: <b style={{ fontFamily: "monospace" }}>{f.ec}</b> · {f.name} · 📍 {f.branch}
                <button type="button" onClick={() => { setF({ ...f, ec: "", name: "", branch: (SALONS[0] && SALONS[0].name) || "" }); }}
                  style={{ marginLeft: 10, background: "transparent", border: "none", color: "#92400e", cursor: "pointer", fontWeight: 700, fontSize: 11, textDecoration: "underline" }}
                >clear</button>
              </div>
            )}
          </div>
        )}

        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 13 }}>
          <div><label style={lbl}>EC Code</label><input style={inp} value={f.ec} onChange={e => set("ec", e.target.value)} placeholder="e.g. B585" /></div>
          <div style={{ gridColumn: "1/-1" }}><label style={lbl}>Full Name</label><input style={inp} value={f.name} onChange={e => set("name", e.target.value)} /></div>
          <div>
            <label style={lbl}>Branch</label>
            <select style={inp} value={f.branch} onChange={e => set("branch", e.target.value)}>
              {SALONS.map(s => <option key={s.name}>{s.name}</option>)}
            </select>
          </div>
          <div>
            <label style={lbl}>Status</label>
            <select style={inp} value={f.matStatus} onChange={e => set("matStatus", e.target.value)}>
              <option value="on_mat">🤱 On Maternity Leave (excluded from count)</option>
              <option value="dates_tbc">⏳ Maternity — Dates TBC (excluded; dates pending)</option>
              <option value="pregnant">🤰 Pregnant – Still at Work (counted in)</option>
              <option value="returned">✅ Returned to Work</option>
              <option value="sick_leave">🏥 Sick Leave</option>
            </select>
          </div>
          <div><label style={lbl}>Maternity Start Date</label><input type="date" style={inp} value={f.matStart || ""} onChange={e => set("matStart", e.target.value || null)} /></div>
          <div><label style={lbl}>Maternity End Date</label><input type="date" style={inp} value={f.matEnd || ""} onChange={e => set("matEnd", e.target.value || null)} /></div>
          <div style={{ gridColumn: "1/-1" }}><label style={lbl}>Expected Return to Work</label><input type="date" style={inp} value={f.returnDate || ""} onChange={e => set("returnDate", e.target.value || null)} /></div>
          <div style={{ gridColumn: "1/-1" }}><label style={lbl}>Notes</label><textarea style={{ ...inp, minHeight: 70, resize: "vertical" }} value={f.notes || ""} onChange={e => set("notes", e.target.value)} /></div>
        </div>
        <div style={{ display: "flex", gap: 10, marginTop: 22, justifyContent: "space-between", alignItems: "center" }}>
          {rec._id && <button onClick={() => { if (confirm("Delete this record?")) onDelete(rec._id); }} style={{ padding: "9px 16px", borderRadius: 9, border: "none", background: "#FBCFE8", color: "#BE185D", cursor: "pointer", fontFamily: "inherit", fontSize: 13, fontWeight: 700 }}>Delete</button>}
          <div style={{ display: "flex", gap: 10, marginLeft: "auto" }}>
            <button onClick={onClose} style={{ padding: "9px 20px", borderRadius: 9, border: "1px solid #FBCFE8", background: "#FFFFFF", cursor: "pointer", fontFamily: "inherit", fontSize: 13 }}>Cancel</button>
            <button onClick={() => onSave(f)} style={{ padding: "9px 22px", borderRadius: 9, border: "none", background: "#BE185D", color: "#fff", cursor: "pointer", fontFamily: "inherit", fontSize: 13, fontWeight: 700 }}>Save</button>
          </div>
        </div>
      </div>
    </div>
  );
}

// ─── STAFF MODAL ──────────────────────────────────────────────────────────────────
function StaffModal({ s, onClose, onSave, onTransfer, allStaff, isOwner, onHardDelete }) {
  // Split existing "name" into firstName / surname for the form. New records
  // start blank. Combined back into `name` on save.
  const splitName = (full) => {
    const t = (full || "").trim();
    if (!t) return { firstName: "", surname: "" };
    const i = t.indexOf(" ");
    if (i < 0) return { firstName: t, surname: "" };
    return { firstName: t.slice(0, i), surname: t.slice(i + 1).trim() };
  };
  const initial = splitName(s.name);
  const [f, setF] = useState({ ...s, firstName: initial.firstName, surname: initial.surname, position: s.position || s.level || "" });
  const set = (k, v) => setF(p => ({ ...p, [k]: v }));
  const inp = { width: "100%", padding: "8px 11px", borderRadius: 8, border: "1px solid #FBCFE8", background: "#FCE7F3", fontFamily: "inherit", fontSize: 13, color: "#111827", boxSizing: "border-box" };
  const lbl = { display: "block", fontSize: 10, fontWeight: 700, color: "#BE185D", letterSpacing: "0.08em", marginBottom: 4, textTransform: "uppercase" };

  // Check for duplicate EC in a different record (salon staff/managers in state)
  const _dupSalon = allStaff.find(x =>
    x.ec.trim().toUpperCase() === f.ec.trim().toUpperCase() && x._id !== f._id
  );
  // Head Office staff are a separate population (never in allStaff), so also
  // block reusing an EC that belongs to an HO employee. There is NO DB unique
  // constraint on employee_code, so this client guard is the only defence.
  const _fEcU = String(f.ec || "").trim().toUpperCase();
  const _dupHeadOffice = !_dupSalon && !!_fEcU && isHeadOfficeEc(f.ec)
    && String((s && s.ec) || "").trim().toUpperCase() !== _fEcU;
  const dupInOtherBranch = _dupSalon || (_dupHeadOffice ? { name: "a Head Office employee", branch: HEAD_OFFICE } : null);

  // Required-field validation
  const missing = [];
  if (!(f.firstName || "").trim()) missing.push("First name");
  if (!(f.surname || "").trim()) missing.push("Surname");
  if (!(f.startDate || "").trim()) missing.push("Start date");
  if (!(f.position || "").trim()) missing.push("Position");
  const blockSave = !!dupInOtherBranch || missing.length > 0;

  const submit = () => {
    if (blockSave) return;
    const _yw = startDateYearWarning(f.startDate);
    if (_yw && !window.confirm("⚠ The start date (" + f.startDate + ") " + _yw + ".\n\nThat usually means the year was mistyped (e.g. 2006 instead of 2026). Save it anyway?")) return;
    const fullName = (f.firstName.trim() + " " + f.surname.trim()).trim();
    const out = { ...f, name: fullName, level: f.position };
    onSave(out);
  };

  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,.55)", zIndex: 200, display: "flex", alignItems: "center", justifyContent: "center", padding: 16 }}
      onClick={e => e.target === e.currentTarget && onClose()}>
      <div style={{ background: "#FFFFFF", borderRadius: 22, width: "min(520px,96vw)", maxHeight: "90vh", overflowY: "auto", padding: "30px 28px", boxShadow: "0 30px 90px rgba(0,0,0,.22)" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 18 }}>
          <h2 style={{ fontFamily: "'Cormorant Garamond',serif", fontSize: 24, color: "#111827", margin: 0 }}>{!s._id ? "Add Staff" : "Edit Staff"}</h2>
          <button onClick={onClose} style={{ background: "none", border: "none", fontSize: 24, cursor: "pointer", color: "#9ca3af" }}>×</button>
        </div>

        {dupInOtherBranch && (
          <div style={{ background: "#FBCFE8", border: "1px solid #fca5a5", borderRadius: 10, padding: "11px 14px", marginBottom: 14, fontSize: 12, color: "#831843" }}>
            🚫 <strong>Duplicate EC</strong> — <strong>{dupInOtherBranch.name}</strong> already has EC <strong>{f.ec}</strong> at <strong>{dupInOtherBranch.branch}</strong>. Use a different EC code.
          </div>
        )}
        {missing.length > 0 && (
          <div style={{ background: "#fef3c7", border: "1px solid #fbbf24", borderRadius: 10, padding: "11px 14px", marginBottom: 14, fontSize: 12, color: "#78350f" }}>
            ⚠ <strong>Required:</strong> {missing.join(", ")}
          </div>
        )}

        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 13 }}>
          <div><label style={lbl}>EC Code</label>
            <input style={{ ...inp, border: `1px solid ${dupInOtherBranch ? "#fca5a5" : "#d1d5db"}`, background: dupInOtherBranch ? "#FAEEF1" : "#f9fafb" }}
              value={f.ec} onChange={e => set("ec", e.target.value)} /></div>
          <div><label style={lbl}>First Name *</label>
            <input style={inp} value={f.firstName} onChange={e => set("firstName", e.target.value)} placeholder="e.g. Thandi" /></div>
          <div><label style={lbl}>Surname *</label>
            <input style={inp} value={f.surname} onChange={e => set("surname", e.target.value)} placeholder="e.g. Mokoena" /></div>
          <div><label style={lbl}>Branch</label>
            <select style={inp} value={f.branch} onChange={e => set("branch", e.target.value)}>
              {SALONS.map(s => <option key={s.name}>{s.name}</option>)}
            </select>
          </div>
          <div><label style={lbl}>Position *</label>
            <select style={inp} value={f.position || ""} onChange={e => set("position", e.target.value)}>
              <option value="">—</option>
              <option>One</option>
              <option>Two</option>
              <option>Three</option>
              <option>Trainee</option>
            </select>
          </div>
          <div style={{ gridColumn: "1/-1" }}><label style={lbl}>Start Date * {f.startDate && (() => {
            const d = new Date(f.startDate + "T00:00:00");
            const days = Math.floor((Date.now() - d) / 86400000);
            const yrs = (days / 365).toFixed(1);
            return <span style={{ fontWeight: 600, color: "#9ca3af", letterSpacing: 0, textTransform: "none", marginLeft: 8 }}>· {days < 365 ? days + " days" : yrs + " yrs"} tenure</span>;
          })()}</label>
            <input type="date" style={inp} value={f.startDate || ""} onChange={e => set("startDate", e.target.value || null)} />
          </div>
          <div style={{ gridColumn: "1/-1" }}><label style={lbl}>Contract</label>
            <select style={inp} value={f.contract || "NO CONTRACT"} onChange={e => set("contract", e.target.value)}>
              <option>Permanent</option><option>Fixed Term</option><option>3 Month</option><option>NO CONTRACT</option><option>2 Weeks</option><option>Induction</option>
            </select>
          </div>
          <div style={{ gridColumn: "1/-1", background: "#FCE7F3", borderRadius: 12, padding: "14px 16px", border: "1px solid #FBCFE8" }}>
            <div style={{ fontSize: 10, fontWeight: 700, color: "#BE185D", marginBottom: 10, textTransform: "uppercase", letterSpacing: "0.08em" }}>Compliance / Work Status</div>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 7 }}>
              {Object.entries(COMPLIANCE).map(([k, c]) => (
                <label key={k} style={{ display: "flex", alignItems: "center", gap: 8, padding: "7px 11px", borderRadius: 9, border: `2px solid ${f.permit === k ? c.border : "#e5e7eb"}`, background: f.permit === k ? c.bg : "#fff", cursor: "pointer" }}>
                  <input type="radio" checked={f.permit === k} onChange={() => set("permit", k)} style={{ display: "none" }} />
                  <span style={{ fontSize: 16 }}>{c.icon}</span>
                  <span style={{ fontSize: 11, fontWeight: 700, color: f.permit === k ? c.color : "#831843" }}>{c.label}</span>
                </label>
              ))}
            </div>
            {/* Expiry date - only relevant for asylum / work permit. Lets HR
                surface anyone whose doc is about to lapse via the Compliance
                'Expiring soon' panel. */}
            {(f.permit === "asylum" || f.permit === "work_permit") && (
              <div style={{ marginTop: 10 }}>
                <label style={{ display: "block", fontSize: 11, fontWeight: 700, color: "#374151", textTransform: "uppercase", letterSpacing: "0.06em", marginBottom: 4 }}>
                  {f.permit === "asylum" ? "Asylum document expiry" : "Work permit expiry"}
                </label>
                <input type="date" value={f.permitExpiry || ""} onChange={e => set("permitExpiry", e.target.value || null)}
                  style={{ width: "100%", padding: "8px 11px", border: "1px solid #FBCFE8", borderRadius: 8, fontSize: 13, fontFamily: "inherit", background: "#FCE7F3" }} />
              </div>
            )}
          </div>
          {/* BOA Pathways — flags staff recruited through the BOA Pathways
              programme for unemployed South Africans. Drives the 🎓 badge on
              the Employee list and the Locations overview, and the BOA Pathways
              total tile. */}
          <label style={{ gridColumn: "1/-1", display: "flex", alignItems: "center", gap: 10, padding: "12px 16px", borderRadius: 12, border: `2px solid ${f.boaPathways ? "#6EE7B7" : "#e5e7eb"}`, background: f.boaPathways ? "#ECFDF5" : "#fff", cursor: "pointer" }}>
            <input type="checkbox" checked={!!f.boaPathways} onChange={e => set("boaPathways", e.target.checked)} style={{ width: 17, height: 17, accentColor: "#059669", cursor: "pointer" }} />
            <span style={{ fontSize: 18 }}>🎓</span>
            <span>
              <span style={{ display: "block", fontSize: 12, fontWeight: 700, color: f.boaPathways ? "#065F46" : "#374151" }}>BOA Pathways graduate</span>
              <span style={{ display: "block", fontSize: 11, color: "#6b7280" }}>Recruited through the BOA Pathways programme.</span>
            </span>
          </label>
          {/* Bargaining council — members have a sick-pay fund, so the company
              does NOT pay their sick days (even with a note). When ticked, this
              person's "Sick + note" is treated as unpaid on the payroll totals.
              The Payroll → Bargaining Council tab can also tick people in bulk
              by matching them off the council statement. */}
          <label style={{ gridColumn: "1/-1", display: "flex", alignItems: "center", gap: 10, padding: "12px 16px", borderRadius: 12, border: `2px solid ${f.bargainingCouncil ? "#93C5FD" : "#e5e7eb"}`, background: f.bargainingCouncil ? "#EFF6FF" : "#fff", cursor: "pointer" }}>
            <input type="checkbox" checked={!!f.bargainingCouncil} onChange={e => set("bargainingCouncil", e.target.checked)} style={{ width: 17, height: 17, accentColor: "#2563EB", cursor: "pointer" }} />
            <span style={{ fontSize: 18 }}>🤝</span>
            <span>
              <span style={{ display: "block", fontSize: 12, fontWeight: 700, color: f.bargainingCouncil ? "#1E40AF" : "#374151" }}>Signed up with the bargaining council</span>
              <span style={{ display: "block", fontSize: 11, color: "#6b7280" }}>Has a council sick-pay fund — sick days are NOT paid by the company, even with a note.</span>
            </span>
          </label>
        </div>
        <div style={{ display: "flex", gap: 10, marginTop: 22, justifyContent: "space-between", alignItems: "center", flexWrap: "wrap" }}>
          {s._id !== undefined && (
            <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
              <button onClick={() => { onClose(); onTransfer(s); }}
                style={{ padding: "9px 16px", borderRadius: 9, border: "none", background: "#BE185D", color: "#fff", cursor: "pointer", fontFamily: "inherit", fontSize: 12, fontWeight: 700 }}>
                🔄 Transfer Branch
              </button>
              {isOwner && onHardDelete && (
                <button onClick={() => onHardDelete(s)}
                  title="Hard delete — owner only. Removes the record entirely; bypasses off-boarding."
                  style={{ padding: "9px 16px", borderRadius: 9, border: "1px solid #fecaca", background: "#fff", color: "#7f1d1d", cursor: "pointer", fontFamily: "inherit", fontSize: 12, fontWeight: 700 }}>
                  🗑 Delete (owner)
                </button>
              )}
            </div>
          )}
          <div style={{ display: "flex", gap: 10, marginLeft: "auto" }}>
            <button onClick={onClose} style={{ padding: "9px 20px", borderRadius: 9, border: "1px solid #FBCFE8", background: "#FFFFFF", cursor: "pointer", fontFamily: "inherit", fontSize: 13 }}>Cancel</button>
            <button onClick={submit} disabled={blockSave}
              style={{ padding: "9px 22px", borderRadius: 9, border: "none", background: blockSave ? "#d1d5db" : "#b45309", color: "#fff", cursor: blockSave ? "not-allowed" : "pointer", fontFamily: "inherit", fontSize: 13, fontWeight: 700 }}>Save</button>
          </div>
        </div>
      </div>
    </div>
  );
}

// ─── TRANSFER MODAL ───────────────────────────────────────────────────────────────
function TransferModal({ s, onClose, onConfirm, onCancelTransfer }) {
  // If this person already has a pending transfer, pre-fill the form
  const isEditing = !!s.transferring && !s.isShadow;
  const [toBranch, setToBranch] = useState(s.transferTo || SALONS.find(sl => sl.name !== s.branch)?.name || "");
  const [transferDate, setTransferDate] = useState(s.transferDate || "");
  const [note, setNote] = useState(s.transferNote || "");
  const [confirmDelete, setConfirmDelete] = useState(false);
  const inp = { width: "100%", padding: "8px 11px", borderRadius: 8, border: "1px solid #FBCFE8", background: "#FCE7F3", fontFamily: "inherit", fontSize: 13, boxSizing: "border-box" };
  const lbl = { display: "block", fontSize: 10, fontWeight: 700, color: "#BE185D", letterSpacing: "0.08em", marginBottom: 4, textTransform: "uppercase" };
  const isPending = transferDate && new Date(transferDate) > TODAY;

  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,.6)", zIndex: 300, display: "flex", alignItems: "center", justifyContent: "center", padding: 16 }}
      onClick={e => e.target === e.currentTarget && onClose()}>
      <div style={{ background: "#FFFFFF", borderRadius: 22, width: "min(500px,96vw)", padding: "30px 28px", boxShadow: "0 30px 90px rgba(0,0,0,.25)" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 6 }}>
          <h2 style={{ fontFamily: "'Cormorant Garamond',serif", fontSize: 24, color: "#111827", margin: 0 }}>
            {isEditing ? "✏️ Edit Transfer" : "🔄 Branch Transfer"}
          </h2>
          <button onClick={onClose} style={{ background: "none", border: "none", fontSize: 24, cursor: "pointer", color: "#9ca3af" }}>×</button>
        </div>

        {/* Existing transfer banner */}
        {isEditing && (
          <div style={{ background: "#FBCFE8", border: "1px solid #7dd3fc", borderRadius: 10, padding: "10px 14px", marginBottom: 14, fontSize: 12, color: "#0c4a6e" }}>
            ✏️ <strong>Editing existing transfer</strong> — currently scheduled to move to <strong>{s.transferTo}</strong> on <strong>{s.transferDate ? new Date(s.transferDate).toLocaleDateString("en-ZA", { day: "2-digit", month: "short", year: "numeric" }) : "—"}</strong>.<br />
            Update the fields below and save, or delete the transfer entirely.
          </div>
        )}

        {/* Staff summary */}
        <div style={{ background: "#F5E1E7", border: "1px solid #7dd3fc", borderRadius: 10, padding: "12px 14px", marginBottom: 18 }}>
          <div style={{ fontWeight: 700, fontSize: 13, color: "#0c4a6e" }}>{s.name} {s.ec
            ? <span style={{ fontFamily: "monospace", fontSize: 11, color: "#BE185D" }}>({s.ec})</span>
            : <span style={{ background: "#FCD34D", color: "#78350f", fontSize: 9, fontWeight: 800, padding: "1px 7px", borderRadius: 999, letterSpacing: "0.04em" }}>{(s.role || "nt") === "am" ? "AM TRIAL" : "ON TRIAL / INDUCTION"}</span>}</div>
          <div style={{ fontSize: 11, color: "#BE185D", marginTop: 3 }}>Currently at: <strong>{s.branch}</strong></div>
        </div>

        <div style={{ display: "grid", gap: 13 }}>
          <div>
            <label style={lbl}>Transfer To Branch</label>
            <select style={inp} value={toBranch} onChange={e => setToBranch(e.target.value)}>
              {SALONS.filter(sl => sl.name !== s.branch).map(sl => <option key={sl.name}>{sl.name}</option>)}
            </select>
          </div>
          <div>
            <label style={lbl}>Transfer Date</label>
            <input type="date" style={inp} value={transferDate} onChange={e => setTransferDate(e.target.value)} />
            {transferDate && (
              <div style={{ fontSize: 11, marginTop: 5, fontWeight: 700, color: isPending ? "#0369a1" : "#065f46" }}>
                {isPending
                  ? `⏳ Pending — staff member shows on BOTH branches until ${new Date(transferDate).toLocaleDateString("en-ZA", { day: "2-digit", month: "short", year: "numeric" })}`
                  : `✅ Effective immediately — moves to ${toBranch} now`}
              </div>
            )}
          </div>
          <div>
            <label style={lbl}>Notes (optional)</label>
            <input style={inp} value={note} onChange={e => setNote(e.target.value)} placeholder="e.g. covering for maternity leave" />
          </div>
        </div>

        {/* Preview */}
        {toBranch && transferDate && (
          <div style={{ background: isPending ? "#fef3c7" : "#d1fae5", border: `1px solid ${isPending ? "#fde68a" : "#6ee7b7"}`, borderRadius: 10, padding: "11px 14px", marginTop: 14, fontSize: 12, color: isPending ? "#78350f" : "#065f46" }}>
            {isPending ? (
              <>
                <strong>📋 What will happen:</strong><br />
                • <strong>{s.name}</strong> stays visible on <strong>{s.branch}</strong> with a 🔄 "Transferring out" badge<br />
                • Also appears on <strong>{toBranch}</strong> with a 🔄 "Arriving" badge<br />
                • Neither branch counts them toward active headcount during transition
              </>
            ) : (
              <>
                <strong>✅ What will happen:</strong><br />
                • <strong>{s.name}</strong> moves immediately from <strong>{s.branch}</strong> to <strong>{toBranch}</strong><br />
                • They count toward {toBranch}&apos;s active headcount from today
              </>
            )}
          </div>
        )}

        {/* Inline delete confirmation — no window.confirm needed */}
        {isEditing && confirmDelete && (
          <div style={{ background: "#FBCFE8", border: "1px solid #fca5a5", borderRadius: 10, padding: "12px 14px", marginTop: 14, fontSize: 12, color: "#831843" }}>
            <div style={{ fontWeight: 700, marginBottom: 8 }}>⚠️ Are you sure you want to delete this transfer?</div>
            <div style={{ marginBottom: 10 }}>This will remove all transfer badges and keep <strong>{s.name}</strong> at <strong>{s.branch}</strong>.</div>
            <div style={{ display: "flex", gap: 8 }}>
              <button onClick={() => onCancelTransfer(s)}
                style={{ padding: "7px 16px", borderRadius: 8, border: "none", background: "#991b1b", color: "#fff", cursor: "pointer", fontFamily: "inherit", fontSize: 12, fontWeight: 700 }}>
                Yes, Delete Transfer
              </button>
              <button onClick={() => setConfirmDelete(false)}
                style={{ padding: "7px 14px", borderRadius: 8, border: "1px solid #FBCFE8", background: "#FFFFFF", cursor: "pointer", fontFamily: "inherit", fontSize: 12 }}>
                No, Keep It
              </button>
            </div>
          </div>
        )}

        <div style={{ display: "flex", gap: 10, marginTop: 22, justifyContent: "space-between", alignItems: "center" }}>
          {/* Delete transfer button — only shown when editing */}
          {isEditing && !confirmDelete && (
            <button onClick={() => setConfirmDelete(true)}
              style={{ padding: "9px 16px", borderRadius: 9, border: "none", background: "#FBCFE8", color: "#831843", cursor: "pointer", fontFamily: "inherit", fontSize: 12, fontWeight: 700 }}>
              🗑 Delete Transfer
            </button>
          )}
          <div style={{ display: "flex", gap: 10, marginLeft: "auto" }}>
            <button onClick={onClose} style={{ padding: "9px 20px", borderRadius: 9, border: "1px solid #FBCFE8", background: "#FFFFFF", cursor: "pointer", fontFamily: "inherit", fontSize: 13 }}>Cancel</button>
            <button onClick={() => toBranch && transferDate && onConfirm({ staff: s, toBranch, transferDate, note, isPending })}
              disabled={!toBranch || !transferDate}
              style={{ padding: "9px 22px", borderRadius: 9, border: "none", background: !toBranch || !transferDate ? "#d1d5db" : "#0c4a6e", color: "#fff", cursor: !toBranch || !transferDate ? "not-allowed" : "pointer", fontFamily: "inherit", fontSize: 13, fontWeight: 700 }}>
              {isEditing ? "💾 Save Changes" : isPending ? "Schedule Transfer" : "Confirm Transfer Now"}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

// ─── MANAGER MODAL ────────────────────────────────────────────────────────────────
function ManagerModal({ m, pin, onClose, onSave, onDelete, smTrialActive, onStartSmTrial }) {
  const parseName = (t) => {
    if (!t) return { firstName: "", surname: "" };
    const i = t.indexOf(" ");
    if (i < 0) return { firstName: t, surname: "" };
    return { firstName: t.slice(0, i), surname: t.slice(i + 1).trim() };
  };
  const initial = parseName(m.name);
  const [f, setF] = useState({ ...m, firstName: m.firstName || initial.firstName, surname: m.surname || initial.surname });
  // Auto-generate a random 6-digit clock-in PIN for brand-new managers so
  // the owner doesn't have to think one up. Existing managers keep their
  // saved PIN. The PIN is still editable in the input below either way.
  const _randomPin = () => String(Math.floor(100000 + Math.random() * 900000));
  const _initPin = (m && m._id !== undefined) ? (pin || "") : (pin || _randomPin());
  const [pinInput, setPinInput] = useState(_initPin);
  const set = (k, v) => setF(p => ({ ...p, [k]: v }));
  const inp = { width: "100%", padding: "8px 11px", borderRadius: 8, border: "1px solid #FBCFE8", background: "#FCE7F3", fontFamily: "inherit", fontSize: 13, color: "#111827", boxSizing: "border-box" };
  const lbl = { display: "block", fontSize: 10, fontWeight: 700, color: "#BE185D", letterSpacing: "0.08em", marginBottom: 4, textTransform: "uppercase" };
  const isNew = f._id === undefined;
  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,.6)", zIndex: 300, display: "flex", alignItems: "center", justifyContent: "center", padding: 16 }}
      onClick={e => e.target === e.currentTarget && onClose()}>
      <div style={{ background: "#FFFFFF", borderRadius: 22, width: "min(460px,96vw)", maxHeight: "90vh", overflowY: "auto", padding: "28px 26px", boxShadow: "0 30px 90px rgba(0,0,0,.25)" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 20 }}>
          <h2 style={{ fontFamily: "'Playfair Display',serif", fontSize: 22, color: "#8E5570", margin: 0 }}>
            {isNew ? "Add Manager" : "Edit Manager"}
          </h2>
          <button onClick={onClose} style={{ background: "none", border: "none", fontSize: 24, cursor: "pointer", color: "#9ca3af" }}>×</button>
        </div>
        <div style={{ display: "grid", gap: 13 }}>
          <div><label style={lbl}>EC Code</label>
            <input style={inp} value={f.ec} onChange={e => set("ec", e.target.value)} placeholder="e.g. B185M" /></div>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
            <div><label style={lbl}>First Name</label>
              <input style={inp} value={f.firstName || ""} onChange={e => set("firstName", e.target.value)} placeholder="e.g. Thandi" /></div>
            <div><label style={lbl}>Surname</label>
              <input style={inp} value={f.surname || ""} onChange={e => set("surname", e.target.value)} placeholder="e.g. Smith" /></div>
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
            <div><label style={lbl}>Branch</label>
              <select style={inp} value={f.branch} onChange={e => set("branch", e.target.value)}>
                {SALONS.map(s => <option key={s.name}>{s.name}</option>)}
              </select>
            </div>
            <div><label style={lbl}>Role</label>
              {/* Placeholder for a blank/unset role. A bare <select> with an
                  empty value silently displays its first option (SSM) without
                  it being chosen, so a role-less manager looked like an SSM and
                  saved back blank — making her vanish from the Locations tiers.
                  The explicit empty option surfaces the missing role instead. */}
              <select style={inp} value={f.role || ""} onChange={e => set("role", e.target.value)}>
                <option value="" disabled>— Select role —</option>
                <option value="SSM">💎 Senior Store Manager (SSM)</option>
                <option value="SM">👑 Store Manager (SM)</option>
                <option value="AM">⭐ Assistant Manager (AM)</option>
              </select>
            </div>
          </div>

          {/* SM trial tagger — visible for existing AMs (to start a trial) or
              for anyone who's already on an active trial (to surface the
              hint). This lets HR see and correct stale records where the
              manager was marked SM directly without going through the trial.
              Hidden for brand-new records (no _id yet). */}
          {!isNew && (f.role === "AM" || smTrialActive) && typeof onStartSmTrial === "function" && (
            <div style={{ background: smTrialActive ? "#f1f5f9" : "#FFF7ED", border: "1px solid " + (smTrialActive ? "#cbd5e1" : "#FED7AA"), borderRadius: 9, padding: "10px 12px", display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10, flexWrap: "wrap" }}>
              <div style={{ fontSize: 11, color: smTrialActive ? "#475569" : "#9A3412", lineHeight: 1.4 }}>
                {smTrialActive
                  ? <>⭐ <strong>Already on SM trial</strong> — view progress and evaluations in the SM Trials tab.</>
                  : <><strong>⭐ Store Manager trial</strong><br /><span style={{ color: "#9A3412" }}>3-month trial with mid + final evaluations. Outcome auto-promotes to SM.</span></>}
              </div>
              {!smTrialActive && (
                <button type="button"
                  onClick={async () => {
                    const _today = (() => { const d = new Date(); const p = n => String(n).padStart(2, "0"); return d.getFullYear() + "-" + p(d.getMonth() + 1) + "-" + p(d.getDate()); })();
                    const sd = prompt("Start the 3-month SM trial for " + (f.firstName || "") + " " + (f.surname || "") + ".\n\nTrial start date (YYYY-MM-DD):", _today);
                    if (sd === null) return;
                    const trimmed = (sd || "").trim();
                    if (!/^\d{4}-\d{2}-\d{2}$/.test(trimmed)) { alert("Please enter the date as YYYY-MM-DD."); return; }
                    const ok = await onStartSmTrial(f.ec, trimmed);
                    if (ok) {
                      alert("⭐ SM trial started. View it in People → SM Trials.");
                      onClose();
                    }
                  }}
                  style={{ padding: "7px 14px", borderRadius: 8, border: "none", background: "#EA580C", color: "#fff", cursor: "pointer", fontFamily: "inherit", fontSize: 12, fontWeight: 700, whiteSpace: "nowrap" }}>⭐ Start SM Trial</button>
              )}
            </div>
          )}
          <div><label style={lbl}>Notes</label>
            <input style={inp} value={f.notes || ""} onChange={e => set("notes", e.target.value)} placeholder="e.g. Transfer from Sandown, Pregnant..." /></div>

          {/* Compliance / work-permit status. Same options the staff modal
              uses; persists to the same `permit` column on the staff row. */}
          <div>
            <label style={lbl}>Compliance / Work Permit</label>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(140px,1fr))", gap: 8 }}>
              <label style={{ display: "flex", alignItems: "center", gap: 8, padding: "8px 10px", borderRadius: 8, border: `1.5px solid ${!f.permit ? "#F472B6" : "#e5e7eb"}`, background: !f.permit ? "#fdf2f8" : "#f9fafb", cursor: "pointer" }}>
                <input type="radio" checked={!f.permit} onChange={() => set("permit", null)} style={{ display: "none" }} />
                <span style={{ fontSize: 16 }}>❔</span>
                <span style={{ fontSize: 11, fontWeight: 700, color: !f.permit ? "#831843" : "#6b7280" }}>Not set</span>
              </label>
              {Object.entries(COMPLIANCE).map(([k, c]) => (
                <label key={k} style={{ display: "flex", alignItems: "center", gap: 8, padding: "8px 10px", borderRadius: 8, border: `1.5px solid ${f.permit === k ? c.border : "#e5e7eb"}`, background: f.permit === k ? c.bg : "#f9fafb", cursor: "pointer" }}>
                  <input type="radio" checked={f.permit === k} onChange={() => set("permit", k)} style={{ display: "none" }} />
                  <span style={{ fontSize: 16 }}>{c.icon}</span>
                  <span style={{ fontSize: 11, fontWeight: 700, color: f.permit === k ? c.color : "#831843" }}>{c.label}</span>
                </label>
              ))}
            </div>
            {/* Expiry date - only relevant for asylum / work permit. Feeds
                the Compliance tab's 'Expiring soon' panel. */}
            {(f.permit === "asylum" || f.permit === "work_permit") && (
              <div style={{ marginTop: 10 }}>
                <label style={lbl}>{f.permit === "asylum" ? "Asylum document expiry" : "Work permit expiry"}</label>
                <input type="date" value={f.permitExpiry || ""} onChange={e => set("permitExpiry", e.target.value || null)} style={inp} />
              </div>
            )}
          </div>

          {/* BOA Pathways — same flag as the staff modal; shows the 🎓 badge
              next to the manager's name on the Locations overview and lists. */}
          <label style={{ display: "flex", alignItems: "center", gap: 10, padding: "11px 14px", borderRadius: 10, border: `2px solid ${f.boaPathways ? "#6EE7B7" : "#e5e7eb"}`, background: f.boaPathways ? "#ECFDF5" : "#fff", cursor: "pointer" }}>
            <input type="checkbox" checked={!!f.boaPathways} onChange={e => set("boaPathways", e.target.checked)} style={{ width: 17, height: 17, accentColor: "#059669", cursor: "pointer" }} />
            <span style={{ fontSize: 18 }}>🎓</span>
            <span style={{ fontSize: 12, fontWeight: 700, color: f.boaPathways ? "#065F46" : "#374151" }}>BOA Pathways graduate</span>
          </label>

          {/* Bargaining council — same flag as the staff modal. Members have a
              council sick-pay fund, so their sick days are not paid. */}
          <label style={{ display: "flex", alignItems: "center", gap: 10, padding: "11px 14px", borderRadius: 10, border: `2px solid ${f.bargainingCouncil ? "#93C5FD" : "#e5e7eb"}`, background: f.bargainingCouncil ? "#EFF6FF" : "#fff", cursor: "pointer" }}>
            <input type="checkbox" checked={!!f.bargainingCouncil} onChange={e => set("bargainingCouncil", e.target.checked)} style={{ width: 17, height: 17, accentColor: "#2563EB", cursor: "pointer" }} />
            <span style={{ fontSize: 18 }}>🤝</span>
            <span style={{ fontSize: 12, fontWeight: 700, color: f.bargainingCouncil ? "#1E40AF" : "#374151" }}>Bargaining council — sick days not paid (council fund)</span>
          </label>

          <div>
            <label style={lbl}>Personal Clock-in PIN <span style={{ fontWeight: 500, color: "#9CA3AF", letterSpacing: 0, textTransform: "none", marginLeft: 4 }}>(6 digits — used in the check-in app{isNew && pinInput ? " · auto-generated" : ""})</span></label>
            <div style={{ display: "flex", gap: 6 }}>
              <input
                style={{ ...inp, fontFamily: "monospace", letterSpacing: "0.2em", fontSize: 14, flex: 1 }}
                value={pinInput}
                maxLength={6}
                inputMode="numeric"
                placeholder="6-digit PIN"
                onChange={e => setPinInput(e.target.value.replace(/\D/g, "").slice(0, 6))}
              />
              <button type="button" onClick={() => setPinInput(_randomPin())}
                title="Generate a fresh random 6-digit PIN"
                style={{ padding: "0 12px", borderRadius: 8, border: "1px solid #FBCFE8", background: "#FFFFFF", color: "#831843", cursor: "pointer", fontFamily: "inherit", fontSize: 12, fontWeight: 700, whiteSpace: "nowrap" }}
              >🎲 Random</button>
            </div>
            {pinInput && pinInput.length !== 6 && (
              <div style={{ fontSize: 11, color: "#dc2626", marginTop: 4 }}>PIN must be exactly 6 digits (or empty to clear).</div>
            )}
            {isNew && pinInput.length === 6 && (
              <div style={{ fontSize: 11, color: "#92400e", marginTop: 6, background: "#fef3c7", border: "1px solid #fde68a", borderRadius: 6, padding: "6px 10px" }}>
                💡 Share this PIN with the manager — they'll type it into the check-in kiosk to confirm their attendance. Resettable later from Admin → Manager PINs.
              </div>
            )}
          </div>
          <div><label style={lbl}>Start Date {f.startDate && (() => {
            const d = new Date(f.startDate + "T00:00:00");
            const days = Math.floor((Date.now() - d) / 86400000);
            const yrs = (days / 365).toFixed(1);
            return <span style={{ fontWeight: 600, color: "#9ca3af", letterSpacing: 0, textTransform: "none", marginLeft: 8 }}>· {days < 365 ? days + " days" : yrs + " yrs"} tenure</span>;
          })()}</label>
            <input type="date" style={inp} value={f.startDate || ""} onChange={e => set("startDate", e.target.value || null)} />
          </div>
          <div><label style={lbl}>Contract</label>
            <select style={inp} value={f.contract || ""} onChange={e => set("contract", e.target.value)}>
              <option value="">— Not set —</option>
              <option>Permanent</option>
              <option>Fixed Term</option>
              <option>3 Month</option>
              <option value="NO CONTRACT">NO CONTRACT</option>
            </select>
          </div>
          <div style={{ gridColumn: "1/-1" }}>
            <label style={{ ...lbl, marginBottom: 8 }}>Maternity Status</label>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(140px,1fr))", gap: 8, marginBottom: 10 }}>
              {[
                { val: "active", icon: "✅", label: "Active", desc: "Working normally", border: "#86efac", bg: "#f0fdf4", col: "#15803d" },
                { val: "pregnant", icon: "🤰", label: "Pregnant", desc: "Still at work, leave upcoming", border: "#fde68a", bg: "#fffbeb", col: "#92400e" },
                { val: "on_mat", icon: "🤱", label: "On Maternity", desc: "Currently on leave", border: "#fbcfe8", bg: "#fdf4ff", col: "#7A4258" },
                { val: "dates_tbc", icon: "⏳", label: "Dates TBC", desc: "Away, no dates yet", border: "#fde68a", bg: "#fef3c7", col: "#7c2d12" },
              ].map(opt => {
                const selected = (f.matStatus || "active") === opt.val;
                return (
                  <label key={opt.val} style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 4, padding: "10px 8px", borderRadius: 10, border: `2px solid ${selected ? opt.border : "#e5e7eb"}`, background: selected ? opt.bg : "#f9fafb", cursor: "pointer", textAlign: "center" }}>
                    <input type="radio" checked={selected} onChange={() => { set("matStatus", opt.val); if (opt.val === "active") { set("onMat", false); set("pregnant", false); } else if (opt.val === "pregnant") { set("onMat", false); set("pregnant", true); } else { set("onMat", true); set("pregnant", false); } }}
                      style={{ display: "none" }} />
                    <span style={{ fontSize: 20 }}>{opt.icon}</span>
                    <span style={{ fontSize: 11, fontWeight: 700, color: selected ? opt.col : "#374151" }}>{opt.label}</span>
                    <span style={{ fontSize: 9, color: selected ? opt.col : "#9ca3af" }}>{opt.desc}</span>
                  </label>
                );
              })}
            </div>

            {/* Pregnant — show expected leave start date */}
            {(f.matStatus || "active") === "pregnant" && (
              <div style={{ background: "#FFFFFF", border: "1px solid #fde68a", borderRadius: 9, padding: "12px 14px", marginTop: 4 }}>
                <div style={{ fontSize: 11, fontWeight: 700, color: "#8E5570", marginBottom: 8 }}>🤰 Upcoming Maternity Details</div>
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
                  <div><label style={lbl}>Expected Leave Start Date</label>
                    <input type="date" style={inp} value={f.matStart || ""} onChange={e => set("matStart", e.target.value)} /></div>
                  <div><label style={lbl}>Expected Return Date</label>
                    <input type="date" style={inp} value={f.matReturn || ""} onChange={e => set("matReturn", e.target.value)} /></div>
                  <div style={{ gridColumn: "1/-1" }}><label style={lbl}>Notes</label>
                    <input style={inp} value={f.matNotes || ""} onChange={e => set("matNotes", e.target.value)} placeholder="e.g. due mid-July, cover needed from June" /></div>
                </div>
              </div>
            )}

            {/* On maternity — show return date */}
            {(f.matStatus || "active") === "on_mat" && (
              <div style={{ background: "#F5E1E7", border: "1px solid #FBCFE8", borderRadius: 9, padding: "12px 14px", marginTop: 4 }}>
                <div style={{ fontSize: 11, fontWeight: 700, color: "#8E5570", marginBottom: 8 }}>🤱 Maternity Leave Details — greyed out in cards, not counted in coverage</div>
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
                  <div><label style={lbl}>Leave Start Date</label>
                    <input type="date" style={inp} value={f.matStart || ""} onChange={e => set("matStart", e.target.value)} /></div>
                  <div><label style={lbl}>Return Date</label>
                    <input type="date" style={inp} value={f.matReturn || ""} onChange={e => set("matReturn", e.target.value)} /></div>
                  <div style={{ gridColumn: "1/-1" }}><label style={lbl}>Notes</label>
                    <input style={inp} value={f.matNotes || ""} onChange={e => set("matNotes", e.target.value)} placeholder="e.g. expected return June 2026" /></div>
                </div>
              </div>
            )}
          </div>
        </div>
        <div style={{ display: "flex", gap: 10, marginTop: 22, justifyContent: "space-between", alignItems: "center" }}>
          {!isNew && (
            <button onClick={() => onDelete(f._id)}
              style={{ padding: "9px 14px", borderRadius: 9, border: "none", background: "#FBCFE8", color: "#831843", cursor: "pointer", fontFamily: "inherit", fontSize: 12, fontWeight: 700 }}>
              🗑 Remove
            </button>
          )}
          <div style={{ display: "flex", gap: 10, marginLeft: "auto" }}>
            <button onClick={onClose} style={{ padding: "9px 18px", borderRadius: 9, border: "1px solid #FBCFE8", background: "#FFFFFF", cursor: "pointer", fontFamily: "inherit", fontSize: 13 }}>Cancel</button>
            <button onClick={() => {
              const hasName = (f.firstName || "").trim() || (f.surname || "").trim();
              if (!hasName) return;
              if (pinInput && pinInput.length !== 6) { alert("Personal PIN must be exactly 6 digits, or left empty."); return; }
              const _yw = startDateYearWarning(f.startDate);
              if (_yw && !window.confirm("⚠ The start date (" + f.startDate + ") " + _yw + ".\n\nThat usually means the year was mistyped (e.g. 2006 instead of 2026). Save it anyway?")) return;
              const fullName = ((f.firstName || "").trim() + " " + (f.surname || "").trim()).trim();
              const out = { ...f, name: fullName };
              // Pass the PIN value (could be the same as before, a new one, or empty to clear)
              onSave(out, pinInput);
            }}
              disabled={!((f.firstName || "").trim() || (f.surname || "").trim())}
              style={{ padding: "9px 22px", borderRadius: 9, border: "none", background: !((f.firstName || "").trim() || (f.surname || "").trim()) ? "#d1d5db" : "#1e293b", color: "#fff", cursor: !((f.firstName || "").trim() || (f.surname || "").trim()) ? "not-allowed" : "pointer", fontFamily: "inherit", fontSize: 13, fontWeight: 700 }}>
              {isNew ? "Add Manager" : "Save Changes"}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

// ─── OFFICE STAFF MODAL (Head Office / Call Centre & Sales) ────────────────────
// A sibling of ManagerModal rather than a mode of it: both of ManagerModal's
// discriminating fields have to be REPLACED, not extended (its branch select is
// SALONS-only, its role select is SSM/SM/AM), and its SM-trial tagger is
// meaningless here — so parameterising would fork it internally more than a
// sibling costs. StaffModal/ManagerModal already overlap ~70%; this follows
// that precedent.
//
// The single most important rule: office people are stored with
// branch = "Head Office" ALWAYS. "Call Centre & Sales" is NOT a real branch —
// it's derived from role/EC by isCallCentreStaff. Storing it would break the
// Head Office kiosk (its roster query is .eq("branch","Head Office")) and drop
// the person from ccStaff. So `dept` here is a VIEW concept: it picks the role
// list and the label, never the stored branch.
function OfficeStaffModal({ s, pin, dept, onClose, onSave, onDelete }) {
  const parseName = (t) => {
    if (!t) return { firstName: "", surname: "" };
    const i = t.indexOf(" ");
    if (i < 0) return { firstName: t, surname: "" };
    return { firstName: t.slice(0, i), surname: t.slice(i + 1).trim() };
  };
  const initial = parseName(s.name);
  const [f, setF] = useState({ ...s, firstName: s.firstName || initial.firstName, surname: s.surname || initial.surname });
  // Department is editable on an EXISTING record: it's the only way to move
  // someone who was mis-filed (e.g. an office role carrying a -CC code, which
  // the classifier reads as Call Centre & Sales).
  const [d, setD] = useState(dept === "CC" ? "CC" : "HO");
  const _randomPin = () => String(Math.floor(100000 + Math.random() * 900000));
  const _initPin = (s && s._id !== undefined) ? (pin || "") : (pin || _randomPin());
  const [pinInput, setPinInput] = useState(_initPin);
  const set = (k, v) => setF(p => ({ ...p, [k]: v }));
  const inp = { width: "100%", padding: "8px 11px", borderRadius: 8, border: "1px solid #FBCFE8", background: "#FCE7F3", fontFamily: "inherit", fontSize: 13, color: "#111827", boxSizing: "border-box" };
  const lbl = { display: "block", fontSize: 10, fontWeight: 700, color: "#BE185D", letterSpacing: "0.08em", marginBottom: 4, textTransform: "uppercase" };
  const isNew = f._id === undefined;
  const roleOpts = d === "CC" ? CC_ROLES : HO_ROLES;
  const deptLabel = d === "CC" ? CALL_CENTRE : HEAD_OFFICE;
  const _ecU = String(f.ec || "").trim().toUpperCase();
  const _ecIsCc = /-CC$/.test(_ecU);
  // A role the record already carries that isn't in the current department's
  // list (e.g. Jae Lee: -CC code → reads as CC&S, but role EPA is an office
  // role). Surface it as an explicit option instead of letting the select
  // silently show blank and re-pick on save.
  const _roleMismatch = !!(f.role && !roleOpts.some(r => r.key === f.role));
  // Hard block: an office role on a -CC code lands on the CC&S roster/schedule
  // while shift-rules (which reads role only) still pays office hours — the two
  // classifiers disagree and nothing surfaces it.
  const _ecBlocked = d === "HO" && _ecIsCc;
  const _hasName = !!((f.firstName || "").trim() || (f.surname || "").trim());
  // EC is REQUIRED: every downstream system keys on it (schedules, attendance,
  // PINs, HEAD_OFFICE_ECS), and an EC-less row crashes the roster enrichment.
  const _canSave = _hasName && !!f.role && !_ecBlocked && !!_ecU;
  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,.6)", zIndex: 300, display: "flex", alignItems: "center", justifyContent: "center", padding: 16 }}
      onClick={e => e.target === e.currentTarget && onClose()}>
      <div style={{ background: "#FFFFFF", borderRadius: 22, width: "min(460px,96vw)", maxHeight: "90vh", overflowY: "auto", padding: "28px 26px", boxShadow: "0 30px 90px rgba(0,0,0,.25)" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 20 }}>
          <h2 style={{ fontFamily: "'Playfair Display',serif", fontSize: 22, color: "#8E5570", margin: 0 }}>
            {isNew ? (d === "CC" ? "Add Call Centre & Sales Staff" : "Add Head Office Staff") : "Edit Office Staff"}
          </h2>
          <button onClick={onClose} style={{ background: "none", border: "none", fontSize: 24, cursor: "pointer", color: "#9ca3af" }}>×</button>
        </div>
        <div style={{ display: "grid", gap: 13 }}>
          <div><label style={lbl}>EC Code</label>
            <input style={inp} value={f.ec || ""} onChange={e => set("ec", e.target.value)} placeholder={d === "CC" ? "e.g. B891-CC" : "e.g. B206-M"} />
            {_ecBlocked && (
              <div style={{ fontSize: 11, color: "#dc2626", marginTop: 4, lineHeight: 1.45 }}>
                A <strong>-CC</strong> code marks someone as Call Centre &amp; Sales, so this person would show on the CC&amp;S roster and schedule — but still be paid Head Office hours (08:00–17:00), because hours read the <em>role</em>. Use a non-<strong>-CC</strong> code (e.g. <code>{_ecU.replace(/-CC$/, "-M")}</code>), or switch Department to Call Centre &amp; Sales.
              </div>
            )}
            {d === "CC" && f.ec && !_ecIsCc && (
              <div style={{ fontSize: 11, color: "#92400e", marginTop: 4, lineHeight: 1.45 }}>
                Heads-up: Call Centre &amp; Sales codes normally end in <strong>-CC</strong>. This still works — the role below is what files them on the CC&amp;S floor (the Call Centre Manager's own code is B476-M) — but the code won't match the convention.
              </div>
            )}
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
            <div><label style={lbl}>First Name</label>
              <input style={inp} value={f.firstName || ""} onChange={e => set("firstName", e.target.value)} placeholder="e.g. Thandi" /></div>
            <div><label style={lbl}>Surname</label>
              <input style={inp} value={f.surname || ""} onChange={e => set("surname", e.target.value)} placeholder="e.g. Smith" /></div>
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
            <div><label style={lbl}>Department</label>
              <select style={inp} value={d} onChange={e => {
                const nd = e.target.value;
                setD(nd);
                // The role sets are disjoint, so a role from the old department
                // is never valid in the new one. Clear it rather than carry a
                // stale value that would re-file them on save.
                const keep = (nd === "CC" ? CC_ROLES : HO_ROLES).some(r => r.key === f.role);
                if (!keep) set("role", "");
              }}>
                <option value="HO">🏢 {HEAD_OFFICE}</option>
                <option value="CC">📞 {CALL_CENTRE}</option>
              </select>
            </div>
            <div><label style={lbl}>Role</label>
              {/* Explicit empty option — a bare <select> with an empty value
                  silently shows its first option without it being chosen, which
                  is how a role-less manager used to read as an SSM. Role is
                  REQUIRED here: it sets shift hours, trainer status and CC&S
                  membership, and a blank one can't even be cleared later
                  (the write prunes empty values). */}
              <select style={inp} value={f.role || ""} onChange={e => set("role", e.target.value)}>
                <option value="" disabled>— Select role —</option>
                {_roleMismatch && <option value={f.role}>⚠ {OFFICE_ROLE_LABEL[f.role] || f.role} (current — wrong department)</option>}
                {roleOpts.map(r => <option key={r.key} value={r.key}>{r.icon} {r.label} ({r.key})</option>)}
              </select>
            </div>
          </div>
          {_roleMismatch && (
            <div style={{ fontSize: 11, color: "#92400e", background: "#fef3c7", border: "1px solid #fde68a", borderRadius: 6, padding: "8px 10px", lineHeight: 1.45 }}>
              ⚠ <strong>{OFFICE_ROLE_LABEL[f.role] || f.role}</strong> isn't a {deptLabel} role. This person is filed under {deptLabel} but carries a role from the other side — so their roster and their shift hours currently disagree. Pick a {deptLabel} role, or switch Department.
            </div>
          )}
          <div style={{ fontSize: 11, color: "#3730a3", background: "#eef2ff", border: "1px solid #c7d2fe", borderRadius: 6, padding: "8px 10px", lineHeight: 1.45 }}>
            💡 {d === "CC"
              ? <>Call Centre &amp; Sales works a two-shift split — <strong>07:00–16:00</strong>, or <strong>09:00–18:30</strong> on a late (WL) day.</>
              : <>Head Office works a flat <strong>08:00–17:00</strong> day, Monday to Friday.</>} Their department is derived from the role, not stored as a branch — both are saved under <strong>{HEAD_OFFICE}</strong>.
          </div>
          <div><label style={lbl}>Notes</label>
            <input style={inp} value={f.notes || ""} onChange={e => set("notes", e.target.value)} placeholder="e.g. started on the Cape Town desk" /></div>

          {/* Compliance / work-permit status — same options + column as the
              staff and manager modals. */}
          <div>
            <label style={lbl}>Compliance / Work Permit</label>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(140px,1fr))", gap: 8 }}>
              <label style={{ display: "flex", alignItems: "center", gap: 8, padding: "8px 10px", borderRadius: 8, border: `1.5px solid ${!f.permit ? "#F472B6" : "#e5e7eb"}`, background: !f.permit ? "#fdf2f8" : "#f9fafb", cursor: "pointer" }}>
                <input type="radio" checked={!f.permit} onChange={() => set("permit", null)} style={{ display: "none" }} />
                <span style={{ fontSize: 16 }}>❔</span>
                <span style={{ fontSize: 11, fontWeight: 700, color: !f.permit ? "#831843" : "#6b7280" }}>Not set</span>
              </label>
              {Object.entries(COMPLIANCE).map(([k, c]) => (
                <label key={k} style={{ display: "flex", alignItems: "center", gap: 8, padding: "8px 10px", borderRadius: 8, border: `1.5px solid ${f.permit === k ? c.border : "#e5e7eb"}`, background: f.permit === k ? c.bg : "#f9fafb", cursor: "pointer" }}>
                  <input type="radio" checked={f.permit === k} onChange={() => set("permit", k)} style={{ display: "none" }} />
                  <span style={{ fontSize: 16 }}>{c.icon}</span>
                  <span style={{ fontSize: 11, fontWeight: 700, color: f.permit === k ? c.color : "#831843" }}>{c.label}</span>
                </label>
              ))}
            </div>
            {(f.permit === "asylum" || f.permit === "work_permit") && (
              <div style={{ marginTop: 10 }}>
                <label style={lbl}>{f.permit === "asylum" ? "Asylum document expiry" : "Work permit expiry"}</label>
                <input type="date" value={f.permitExpiry || ""} onChange={e => set("permitExpiry", e.target.value || null)} style={inp} />
              </div>
            )}
          </div>

          <label style={{ display: "flex", alignItems: "center", gap: 10, padding: "11px 14px", borderRadius: 10, border: `2px solid ${f.boaPathways ? "#6EE7B7" : "#e5e7eb"}`, background: f.boaPathways ? "#ECFDF5" : "#fff", cursor: "pointer" }}>
            <input type="checkbox" checked={!!f.boaPathways} onChange={e => set("boaPathways", e.target.checked)} style={{ width: 17, height: 17, accentColor: "#059669", cursor: "pointer" }} />
            <span style={{ fontSize: 18 }}>🎓</span>
            <span style={{ fontSize: 12, fontWeight: 700, color: f.boaPathways ? "#065F46" : "#374151" }}>BOA Pathways graduate</span>
          </label>

          <label style={{ display: "flex", alignItems: "center", gap: 10, padding: "11px 14px", borderRadius: 10, border: `2px solid ${f.bargainingCouncil ? "#93C5FD" : "#e5e7eb"}`, background: f.bargainingCouncil ? "#EFF6FF" : "#fff", cursor: "pointer" }}>
            <input type="checkbox" checked={!!f.bargainingCouncil} onChange={e => set("bargainingCouncil", e.target.checked)} style={{ width: 17, height: 17, accentColor: "#2563EB", cursor: "pointer" }} />
            <span style={{ fontSize: 18 }}>🤝</span>
            <span style={{ fontSize: 12, fontWeight: 700, color: f.bargainingCouncil ? "#1E40AF" : "#374151" }}>Bargaining council — sick days not paid (council fund)</span>
          </label>

          <div>
            <label style={lbl}>Personal Clock-in PIN <span style={{ fontWeight: 500, color: "#9CA3AF", letterSpacing: 0, textTransform: "none", marginLeft: 4 }}>(6 digits — used in the check-in app{isNew && pinInput ? " · auto-generated" : ""})</span></label>
            <div style={{ display: "flex", gap: 6 }}>
              <input
                style={{ ...inp, fontFamily: "monospace", letterSpacing: "0.2em", fontSize: 14, flex: 1 }}
                value={pinInput}
                maxLength={6}
                inputMode="numeric"
                placeholder="6-digit PIN"
                onChange={e => setPinInput(e.target.value.replace(/\D/g, "").slice(0, 6))}
              />
              <button type="button" onClick={() => setPinInput(_randomPin())}
                title="Generate a fresh random 6-digit PIN"
                style={{ padding: "0 12px", borderRadius: 8, border: "1px solid #FBCFE8", background: "#FFFFFF", color: "#831843", cursor: "pointer", fontFamily: "inherit", fontSize: 12, fontWeight: 700, whiteSpace: "nowrap" }}
              >🎲 Random</button>
            </div>
            {pinInput && pinInput.length !== 6 && (
              <div style={{ fontSize: 11, color: "#dc2626", marginTop: 4 }}>PIN must be exactly 6 digits (or empty to clear).</div>
            )}
            {isNew && pinInput.length === 6 && (
              <div style={{ fontSize: 11, color: "#92400e", marginTop: 6, background: "#fef3c7", border: "1px solid #fde68a", borderRadius: 6, padding: "6px 10px" }}>
                💡 Share this PIN with them — they'll type it into the check-in kiosk to confirm their attendance. Resettable later from Admin → Manager PINs.
              </div>
            )}
          </div>
          <div><label style={lbl}>Start Date {f.startDate && (() => {
            const dd = new Date(f.startDate + "T00:00:00");
            const days = Math.floor((Date.now() - dd) / 86400000);
            const yrs = (days / 365).toFixed(1);
            return <span style={{ fontWeight: 600, color: "#9ca3af", letterSpacing: 0, textTransform: "none", marginLeft: 8 }}>· {days < 365 ? days + " days" : yrs + " yrs"} tenure</span>;
          })()}</label>
            <input type="date" style={inp} value={f.startDate || ""} onChange={e => set("startDate", e.target.value || null)} />
          </div>
          <div><label style={lbl}>Contract</label>
            <select style={inp} value={f.contract || ""} onChange={e => set("contract", e.target.value)}>
              <option value="">— Not set —</option>
              <option>Permanent</option>
              <option>Fixed Term</option>
              <option>3 Month</option>
              <option value="NO CONTRACT">NO CONTRACT</option>
            </select>
          </div>
          <div style={{ gridColumn: "1/-1" }}>
            <label style={{ ...lbl, marginBottom: 8 }}>Maternity Status</label>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(140px,1fr))", gap: 8, marginBottom: 10 }}>
              {[
                { val: "active", icon: "✅", label: "Active", desc: "Working normally", border: "#86efac", bg: "#f0fdf4", col: "#15803d" },
                { val: "pregnant", icon: "🤰", label: "Pregnant", desc: "Still at work, leave upcoming", border: "#fde68a", bg: "#fffbeb", col: "#92400e" },
                { val: "on_mat", icon: "🤱", label: "On Maternity", desc: "Currently on leave", border: "#fbcfe8", bg: "#fdf4ff", col: "#7A4258" },
                { val: "dates_tbc", icon: "⏳", label: "Dates TBC", desc: "Away, no dates yet", border: "#fde68a", bg: "#fef3c7", col: "#7c2d12" },
              ].map(opt => {
                const selected = (f.matStatus || "active") === opt.val;
                return (
                  <label key={opt.val} style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 4, padding: "10px 8px", borderRadius: 10, border: `2px solid ${selected ? opt.border : "#e5e7eb"}`, background: selected ? opt.bg : "#f9fafb", cursor: "pointer", textAlign: "center" }}>
                    <input type="radio" checked={selected} onChange={() => { set("matStatus", opt.val); if (opt.val === "active") { set("onMat", false); set("pregnant", false); } else if (opt.val === "pregnant") { set("onMat", false); set("pregnant", true); } else { set("onMat", true); set("pregnant", false); } }}
                      style={{ display: "none" }} />
                    <span style={{ fontSize: 20 }}>{opt.icon}</span>
                    <span style={{ fontSize: 11, fontWeight: 700, color: selected ? opt.col : "#374151" }}>{opt.label}</span>
                    <span style={{ fontSize: 9, color: selected ? opt.col : "#9ca3af" }}>{opt.desc}</span>
                  </label>
                );
              })}
            </div>
            {(f.matStatus || "active") === "pregnant" && (
              <div style={{ background: "#FFFFFF", border: "1px solid #fde68a", borderRadius: 9, padding: "12px 14px", marginTop: 4 }}>
                <div style={{ fontSize: 11, fontWeight: 700, color: "#8E5570", marginBottom: 8 }}>🤰 Upcoming Maternity Details</div>
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
                  <div><label style={lbl}>Expected Leave Start Date</label>
                    <input type="date" style={inp} value={f.matStart || ""} onChange={e => set("matStart", e.target.value)} /></div>
                  <div><label style={lbl}>Expected Return Date</label>
                    <input type="date" style={inp} value={f.matReturn || ""} onChange={e => set("matReturn", e.target.value)} /></div>
                  <div style={{ gridColumn: "1/-1" }}><label style={lbl}>Notes</label>
                    <input style={inp} value={f.matNotes || ""} onChange={e => set("matNotes", e.target.value)} placeholder="e.g. due mid-July, cover needed from June" /></div>
                </div>
              </div>
            )}
            {(f.matStatus || "active") === "on_mat" && (
              <div style={{ background: "#F5E1E7", border: "1px solid #FBCFE8", borderRadius: 9, padding: "12px 14px", marginTop: 4 }}>
                <div style={{ fontSize: 11, fontWeight: 700, color: "#8E5570", marginBottom: 8 }}>🤱 Maternity Leave Details</div>
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
                  <div><label style={lbl}>Leave Start Date</label>
                    <input type="date" style={inp} value={f.matStart || ""} onChange={e => set("matStart", e.target.value)} /></div>
                  <div><label style={lbl}>Return Date</label>
                    <input type="date" style={inp} value={f.matReturn || ""} onChange={e => set("matReturn", e.target.value)} /></div>
                  <div style={{ gridColumn: "1/-1" }}><label style={lbl}>Notes</label>
                    <input style={inp} value={f.matNotes || ""} onChange={e => set("matNotes", e.target.value)} placeholder="e.g. expected return June 2026" /></div>
                </div>
              </div>
            )}
          </div>
        </div>
        <div style={{ display: "flex", gap: 10, marginTop: 22, justifyContent: "space-between", alignItems: "center" }}>
          {!isNew && onDelete && (
            <button onClick={() => onDelete(f._id)}
              style={{ padding: "9px 14px", borderRadius: 9, border: "none", background: "#FBCFE8", color: "#831843", cursor: "pointer", fontFamily: "inherit", fontSize: 12, fontWeight: 700 }}>
              🗑 Remove
            </button>
          )}
          <div style={{ display: "flex", gap: 10, marginLeft: "auto" }}>
            <button onClick={onClose} style={{ padding: "9px 18px", borderRadius: 9, border: "1px solid #FBCFE8", background: "#FFFFFF", cursor: "pointer", fontFamily: "inherit", fontSize: 13 }}>Cancel</button>
            <button onClick={() => {
              if (!_hasName) return;
              if (!_ecU) { alert("An EC Code is required — schedules, attendance, PINs and leave are all keyed on it. Every employee code must be unique and is never reused."); return; }
              if (!f.role) { alert("Pick a role — it sets their shift hours, whether they're a trainer, and whether they sit on the Call Centre & Sales floor."); return; }
              if (_ecBlocked) { alert("A -CC employee code files this person under Call Centre & Sales. Use a non--CC code, or switch Department to Call Centre & Sales."); return; }
              if (pinInput && pinInput.length !== 6) { alert("Personal PIN must be exactly 6 digits, or left empty."); return; }
              const _yw = startDateYearWarning(f.startDate);
              if (_yw && !window.confirm("⚠ The start date (" + f.startDate + ") " + _yw + ".\n\nThat usually means the year was mistyped (e.g. 2006 instead of 2026). Save it anyway?")) return;
              const fullName = ((f.firstName || "").trim() + " " + (f.surname || "").trim()).trim();
              // branch is ALWAYS Head Office — see the header note. The dept is
              // re-derived from role/EC by isCallCentreStaff on read.
              const out = { ...f, name: fullName, branch: HEAD_OFFICE, role: f.role };
              onSave(out, pinInput);
            }}
              disabled={!_canSave}
              style={{ padding: "9px 22px", borderRadius: 9, border: "none", background: !_canSave ? "#d1d5db" : "#1e293b", color: "#fff", cursor: !_canSave ? "not-allowed" : "pointer", fontFamily: "inherit", fontSize: 13, fontWeight: 700 }}>
              {isNew ? "Add" : "Save Changes"}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

// ─── SCHEDULE EDITOR (Phase 2a — manual editing, save to Supabase) ──────────────
function Schedule({ allStaff, trialList, techRequests, onTechRequestsChange, leaveRecs, obList, techLoans, onTechLoansChange, initialBranch, isOwner, branchList, requestStore }) {
  // requestStore (optional, "ho" | "cc") names the persistence target for
  // off-day request edits — default is the nail-tech key. The Head Office
  // scheduler passes "ho" (boa_ho_requests_v1) and the Call Centre & Sales
  // scheduler passes "cc" (boa_cc_requests_v1) so neither ever touches the
  // shared tech key. Resolved by NAME at call time and hard-fails if the saver
  // is missing: a function-reference prop would silently be undefined on a
  // stale-cached data.js and fall back to saveTechRequests — overwriting every
  // salon tech request with the HO/CC array. Failing loudly is the only safe
  // degradation.
  const _saveReqs = (arr) => {
    if (requestStore === "ho") {
      if (!window.BOA_DB.saveHoRequests) throw new Error("This portal build can't save Head Office requests yet — refresh the page to load the latest data.js.");
      return window.BOA_DB.saveHoRequests(arr);
    }
    if (requestStore === "cc") {
      if (!window.BOA_DB.saveCcRequests) throw new Error("This portal build can't save Call Centre & Sales requests yet — refresh the page to load the latest data.js.");
      return window.BOA_DB.saveCcRequests(arr);
    }
    return window.BOA_DB.saveTechRequests(arr);
  };
  // branchList (optional) locks the branch picker to an explicit set — used by
  // the Head Office scheduling sub-tab so HO gets a tech-style grid without
  // "Head Office" ever entering SALONS (which would leak it into ~15 salon
  // surfaces). Defaults to the full salon list.
  const _branchOptions = (branchList && branchList.length) ? branchList : SALONS.map(s => s.name);
  const [branch, setBranch] = useState(initialBranch || _branchOptions[0]);
  // The store a staff row SCHEDULES under. Call Centre & Sales people carry
  // branch "Head Office" in the staff table (the split is derived, never
  // stored), but they schedule under the CALL_CENTRE store — so every roster /
  // leave-stamp filter in this component must compare against this, not the
  // raw s.branch, or the CC&S mount matches nobody. Identity for salon rows.
  const _schedBranchOf = (s) => (s && isHeadOfficeBranch(s.branch) && isCallCentreStaff(s)) ? CALL_CENTRE : (s && s.branch);
  // Head Office has no mani/pedi stations, so autoFill's station-capacity math
  // computes capacity 0 and generates a schedule with everyone off — the
  // feature is meaningless there (HO is a simple M–F pattern, filled by hand).
  const _isHoSchedule = branch === HEAD_OFFICE;
  const [ym, setYm] = useState(window.BOA_DB ? window.BOA_DB.currentSchedYm() : "2026-05");
  const [grid, setGrid] = useState({});
  const [savedAt, setSavedAt] = useState(null);
  const [dirty, setDirty] = useState(false);
  const [saving, setSaving] = useState(false);
  const [loading, setLoading] = useState(false);
  // Saved "final versions" list for this (branch, ym). Loaded on mount + on
  // branch/ym change so the count badge on 📋 Versions is accurate.
  const [versions, setVersions] = useState([]);
  const [versionsOpen, setVersionsOpen] = useState(false);
  const [techReqModal, setTechReqModal] = useState(null); // {ec, date, note} draft
  // Drag-and-drop state — { ec, day, value, weekIdx } when a cell is being dragged
  const [dragSource, setDragSource] = useState(null);
  // Version history modal state
  const [historyOpen, setHistoryOpen] = useState(false);
  const [historyVersions, setHistoryVersions] = useState([]);
  const [historyLoading, setHistoryLoading] = useState(false);
  // Auto-fill diagnostics — populated whenever auto-fill or staff-sync runs.
  // unhonouredRequests: [{ec, name, date, dayNum, reason}] — request-off days
  // we couldn't apply without breaking a hard rule (2-off/week is the main
  // one). Surfaced as a warning banner above the grid.
  const [unhonouredRequests, setUnhonouredRequests] = useState([]);
  // One-level undo for bulk grid actions (Auto-fill / Clear period / Sync
  // staff). Snapshots the grid right before the action so a misfire can be
  // rolled back in the editor. Like the actions themselves, the rollback isn't
  // saved until you click Save. Reset on branch/cycle change so undo only ever
  // applies to the schedule you're looking at (i.e. per branch + period).
  const [undoSnap, setUndoSnap] = useState(null);  // { grid, label } | null

  async function openHistory() {
    setHistoryOpen(true);
    setHistoryLoading(true);
    try {
      const v = await window.BOA_DB.loadScheduleHistory(branch, ym, false);
      setHistoryVersions(Array.isArray(v) ? v : []);
    } catch (e) {
      console.error("loadScheduleHistory:", e);
      setHistoryVersions([]);
    } finally { setHistoryLoading(false); }
  }
  async function restoreVersion(idx) {
    const v = historyVersions[idx];
    if (!v) return;
    const ts = v.savedAt ? new Date(v.savedAt).toLocaleString() : "this snapshot";
    if (!confirm(
      "Restore the version saved on " + ts + "?\n\n" +
      "Your current schedule will be backed up to history first, then this older version will replace it on screen. " +
      "You'll still need to click Save to commit the restored version."
    )) return;
    setGrid(v.grid || {});
    setDirty(true);
    setHistoryOpen(false);
  }

  useEffect(() => {
    if (!window.BOA_DB || !window.BOA_DB.isReady) return;
    setLoading(true);
    window.BOA_DB.loadSchedule(branch, ym, false).then((d) => {
      setGrid((d && d.grid) || {});
      setSavedAt((d && d.savedAt) || null);
      setDirty(false);
      setUnhonouredRequests([]);
      setUndoSnap(null);                 // undo only applies to the loaded branch + period
      setLoading(false);
    });
  }, [branch, ym]);

  // Heal grid rows keyed by a DRIFTED employee code — stray whitespace or a
  // case difference between the saved row key and the current staff record's
  // ec (e.g. after the code was edited on the staff record). The grid render
  // and the staff-sync diff both look up rows by the EXACT staff ec, so a
  // drifted row renders as a blank row, the person is flagged "+ Add" (an
  // autofilled duplicate), and her REAL row shows as a stale row to remove —
  // syncing would wipe a hand-made schedule. Re-key drifted rows to the staff
  // ec as soon as both the grid and the staff list are here; when a row also
  // exists under the exact key, the exact row's cells win and the drifted row
  // only fills its blanks. Marks the schedule dirty so Save persists the
  // healed keys (the kiosk + My BOA viewers read the saved grid).
  useEffect(() => {
    if (loading) return;
    const byNorm = {};
    (allStaff || []).forEach(s => { if (s && s.ec) byNorm[String(s.ec).trim().toUpperCase()] = s.ec; });
    const keys = Object.keys(grid || {});
    const isDrifted = (k) => { const c = byNorm[String(k).trim().toUpperCase()]; return !!c && c !== k; };
    if (!keys.some(isDrifted)) return;
    const healed = {};
    // Drifted rows first, exact-key rows second, so real exact cells override.
    keys.filter(isDrifted).forEach(k => {
      const canon = byNorm[String(k).trim().toUpperCase()];
      healed[canon] = Object.assign({}, healed[canon], grid[k]);
    });
    keys.filter(k => !isDrifted(k)).forEach(k => {
      healed[k] = Object.assign({}, healed[k], grid[k]);
    });
    setGrid(healed);
    setDirty(true);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [grid, allStaff, loading]);

  const days = window.BOA_DB ? window.BOA_DB.periodDays(ym) : [];

  // Auto-stamp 'R' on cells with a pending off-day request — runs after each
  // schedule load and whenever techRequests changes (e.g. a new request comes
  // in from the check-in app). Empty cells become R; cells the user has set
  // to anything else are preserved. If anything was added, the schedule goes
  // dirty so the user knows to Save.
  // ECs of the staff actually rendered on THIS grid. A shared request key
  // (boa_ho_requests_v1) can hold records for people who schedule elsewhere —
  // after the Call Centre & Sales split, CC people's originals stay in the HO
  // key (Supabase rows are never deleted) but they schedule on the CC&S tab.
  // Scoping every request consumer to this set stops a foreign record from
  // stamping a phantom row into (and being saved back onto) this grid.
  const _gridEcSet = useMemo(() => new Set((allStaff || []).map(s => String(s.ec || "").trim().toUpperCase())), [allStaff]);
  const _inGrid = (ec) => _gridEcSet.has(String(ec || "").trim().toUpperCase());
  useEffect(() => {
    if (loading) return;
    if (!techRequests || techRequests.length === 0) return;
    if (!days || days.length === 0) return;
    let changed = false;
    const next = JSON.parse(JSON.stringify(grid || {}));
    for (const r of techRequests) {
      if (!r || r.branch !== branch || !r.date) continue;
      if (!_inGrid(r.ec)) continue;
      const dt = new Date(r.date + "T00:00:00");
      if (isNaN(dt.getTime())) continue;
      const inPeriod = days.some(d => d.year === dt.getFullYear() && d.monthIdx === dt.getMonth() && d.d === dt.getDate());
      if (!inPeriod) continue;
      const dayNum = dt.getDate();
      if (!next[r.ec]) next[r.ec] = {};
      if (!next[r.ec][dayNum]) {
        next[r.ec][dayNum] = "R";
        changed = true;
      }
    }
    if (changed) {
      setGrid(next);
      setDirty(true);
    }
    // Intentionally not depending on `grid` to avoid an infinite re-stamp loop;
    // the effect re-runs when techRequests/branch/ym/loading change.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [techRequests, branch, ym, loading]);

  // Auto-stamp 'L' on cells that fall within an approved leave record. Runs
  // after each schedule load and whenever the leave list changes (e.g. the
  // user just added a new leave row in the Leave Planner). Leave overrides
  // W / WL / O / R cells because the tech is genuinely off; X (ghost cells
  // for staff who haven't started or have left) is preserved. Existing L
  // cells stay L. The schedule is marked dirty so the user knows to Save.
  useEffect(() => {
    if (loading) return;
    if (!leaveRecs || leaveRecs.length === 0) return;
    if (!days || days.length === 0) return;
    // Match leave records to staff by TRIMMED ec (the attendance overlay does
    // the same) and stamp the "L" under the staff row's exact ec key — the
    // render reads grid[s.ec], so a leave record whose ec carries stray
    // whitespace / a different format must resolve back to that row's key.
    // Previously we gated on (and keyed by) the raw leaveRec ec, so such a
    // record was skipped or written under a key no row reads, leaving the
    // tech's whole row blank on the schedule.
    const ecByTrim = {};
    allStaff.filter(s => _schedBranchOf(s) === branch).forEach(s => { ecByTrim[String(s.ec).trim()] = s.ec; });
    let changed = false;
    const next = JSON.parse(JSON.stringify(grid || {}));
    for (const lv of leaveRecs) {
      if (!lv || !lv.ec || !lv.startDate || !lv.endDate) continue;
      const ec = ecByTrim[String(lv.ec).trim()];
      if (!ec) continue;
      const sd = new Date(lv.startDate + "T00:00:00");
      const ed = new Date(lv.endDate + "T00:00:00");
      if (isNaN(sd.getTime()) || isNaN(ed.getTime())) continue;
      for (const d of days) {
        const dt = new Date(d.year, d.monthIdx, d.d);
        if (dt < sd || dt > ed) continue;
        if (!next[ec]) next[ec] = {};
        const cur = next[ec][d.d];
        if (cur === "X") continue;                  // preserve ghost cells
        if (cur === "L") continue;                  // already on leave
        if (cur === "O" || cur === "R") continue;   // already scheduled OFF — an off day inside the leave window stays an off day, it doesn't become a leave day
        next[ec][d.d] = "L";
        changed = true;
      }
    }
    if (changed) {
      setGrid(next);
      // AUTO-SAVE the stamped leave cells. The on-screen stamp made the tab
      // look correct while the SAVED grid — the only thing the kiosk schedule
      // and the My BOA viewer read — stayed unchanged until someone clicked
      // Save, which is easy to forget. Persist the leave cells immediately
      // with a per-cell read-merge-write (publishLeaveToSchedule skips days
      // already O/R/X/ML and only saves when something actually changes, so
      // re-opening the tab is idempotent and never clobbers other edits).
      // Scoped to records overlapping the VISIBLE cycle, and clamped to it,
      // so historical leave records don't trigger writes to old schedules.
      // This also self-heals leave approved before publishing existed, the
      // first time anyone opens the affected schedule. setDirty is NOT set
      // for leave stamps anymore — they are saved, not pending.
      const _isoOf = (d) => d.year + "-" + String(d.monthIdx + 1).padStart(2, "0") + "-" + String(d.d).padStart(2, "0");
      const cycStartIso = _isoOf(days[0]);
      const cycEndIso = _isoOf(days[days.length - 1]);
      (async () => {
        for (const lv of leaveRecs) {
          if (!lv || !lv.ec || !lv.startDate || !lv.endDate) continue;
          if (lv.startDate > cycEndIso || lv.endDate < cycStartIso) continue;
          const ec = ecByTrim[String(lv.ec).trim()];
          if (!ec) continue;
          const from = lv.startDate > cycStartIso ? lv.startDate : cycStartIso;
          const to = lv.endDate < cycEndIso ? lv.endDate : cycEndIso;
          try { await publishLeaveToSchedule(ec, branch, from, to); }
          catch (e) { console.error("leave auto-save:", e); }
        }
      })();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [leaveRecs, branch, ym, loading, allStaff]);
  const periodLbl = window.BOA_DB ? window.BOA_DB.periodLabel(ym) : "";

  // All scheduled staff at this branch — actively-working first (sorted by EC),
  // then on-maternity-leave at the bottom (also sorted by EC). On-mat staff
  // remain visible so the manager can see who's away, but they're greyed out
  // and excluded from the auto-fill algorithm.
  // Period start ymd derived from `days` so we can decide visibility for
  // leaving staff (kept in this month if their leftDate is on/after period
  // start; dropped completely from the next month onward).
  const _periodStartYmdForTechs = useMemo(() => {
    if (!days || days.length === 0) return null;
    const f = days[0];
    return f.year + "-" + String(f.monthIdx + 1).padStart(2, "0") + "-" + String(f.d).padStart(2, "0");
  }, [ym]);
  const techs = useMemo(() => {
    // Regular techs at this branch. Records currently transferring OUT
    // stay here — their post-transferDate cells are greyed at render
    // time so the manager can still see what they're scheduled for up
    // to the move date.
    const regularTechs = allStaff
      .filter(s => _schedBranchOf(s) === branch && !s.isShadow)
      // Off-boarding visibility rule: a tech with a leftDate stays on the
      // grid for the cycle they leave in (greyed-out row + X cells after
      // leftDate, handled at render and in PHASE 18). From the next cycle
      // onward — once their leftDate falls strictly before the period
      // start — they vanish from the schedule entirely.
      .filter(s => !s.leftDate || !_periodStartYmdForTechs || s.leftDate >= _periodStartYmdForTechs);
    // Arriving techs — derived from any real record whose transferring
    // flag points HERE. Derivation (rather than relying on the local
    // shadow record handleTransfer creates) means the arriving row
    // survives a page refresh: shadows live in React state only, but
    // the underlying transferring/transferTo/transferDate fields are
    // persisted on the source record so we can recompute the shadow.
    const seenArrivingEcs = new Set();
    const arrivingTechs = allStaff
      .filter(s => !s.isShadow && s.transferring && s.transferTo === branch && s.transferDate)
      .filter(s => !seenArrivingEcs.has(s.ec) && (seenArrivingEcs.add(s.ec), true))
      .map(s => ({
        ...s,
        _id: "shadow-" + s.ec,
        branch,
        transferFrom: s.branch,
        transferTo: branch,
        isShadow: true,
      }));

    return [...regularTechs, ...arrivingTechs].sort((a, b) => {
      // Arriving shadows render below all real techs.
      if (!!a.isShadow !== !!b.isShadow) return a.isShadow ? 1 : -1;
      const am = a.onMat ? 1 : 0;
      const bm = b.onMat ? 1 : 0;
      if (am !== bm) return am - bm;                       // active before on-mat
      return (a.ec || "").localeCompare(b.ec || "");
    });
  }, [allStaff, branch, _periodStartYmdForTechs]);

  // Set of "ec|dayOfMonth" combos that have a pending off-day request in the
  // active branch + cycle. Used to render a small dot on the schedule cell so
  // managers can see which cells should still get marked as off / R.
  const requestedSet = useMemo(() => {
    const out = new Set();
    for (const r of (techRequests || [])) {
      if (!r || r.branch !== branch || !r.date) continue;
      if (!_inGrid(r.ec)) continue;
      const dt = new Date(r.date + "T00:00:00");
      // Only honour requests whose ymd falls in the current period.
      const inPeriod = days.some(d => d.year === dt.getFullYear() && d.monthIdx === dt.getMonth() && d.d === dt.getDate());
      if (!inPeriod) continue;
      out.add(r.ec + "|" + dt.getDate());
    }
    return out;
  }, [techRequests, branch, days]);

  // Emergency (unpaid) leave days for the visible staff. The saved grid stores a
  // generic "L" for ALL leave, so we cross-reference the Leave Planner records to
  // paint emergency leave distinctly (orange "EL") instead of the same grey "L"
  // used for paid annual leave. Render-only — the grid still stores "L".
  const emergencyLeaveSet = useMemo(() => {
    const set = new Set();
    (leaveRecs || []).forEach(lv => {
      if (!lv || !lv.emergency || !lv.ec || !lv.startDate || !lv.endDate) return;
      const sd = new Date(lv.startDate + "T00:00:00"), ed = new Date(lv.endDate + "T00:00:00");
      if (isNaN(sd.getTime()) || isNaN(ed.getTime())) return;
      for (let cur = new Date(sd); cur <= ed; cur.setDate(cur.getDate() + 1)) {
        const ymd = cur.getFullYear() + "-" + String(cur.getMonth() + 1).padStart(2, "0") + "-" + String(cur.getDate()).padStart(2, "0");
        set.add(String(lv.ec).trim() + "|" + ymd);
      }
    });
    return set;
  }, [leaveRecs]);
  // ALL Leave-Planner days (annual + emergency), trimmed-ec|ymd. Drives a live
  // display overlay so leave shows on the schedule the moment it's in the planner
  // — even if the saved grid wasn't re-stamped yet (the auto-stamp effect only
  // fires while THIS branch/cycle is open, so a tech's freshly-approved leave
  // could otherwise read blank/working until someone re-opened their schedule).
  const plannerLeaveSet = useMemo(() => {
    const set = new Set();
    (leaveRecs || []).forEach(lv => {
      if (!lv || !lv.ec || !lv.startDate || !lv.endDate) return;
      const sd = new Date(lv.startDate + "T00:00:00"), ed = new Date(lv.endDate + "T00:00:00");
      if (isNaN(sd.getTime()) || isNaN(ed.getTime())) return;
      for (let cur = new Date(sd); cur <= ed; cur.setDate(cur.getDate() + 1)) {
        const ymd = cur.getFullYear() + "-" + String(cur.getMonth() + 1).padStart(2, "0") + "-" + String(cur.getDate()).padStart(2, "0");
        set.add(String(lv.ec).trim() + "|" + ymd);
      }
    });
    return set;
  }, [leaveRecs]);

  const cycle = ["W", "WE", "WL", "O", "R", "L", "E", "X", "trial", ""];
  const cellStyle = (z) => {
    if (z === "W") return { background: "#dcfce7", color: "#14532d" };
    if (z === "WE") return { background: "#a7f3d0", color: "#064e3b" };
    if (z === "WL") return { background: "#86efac", color: "#14532d" };
    if (z === "O") return { background: "#fee2e2", color: "#991b1b" };
    if (z === "R") return { background: "#fca5a5", color: "#7f1d1d" };
    if (z === "L") return { background: "#cbd5e1", color: "#475569" };
    if (z === "ML") return { background: "#ede9fe", color: "#6b21a8", fontStyle: "italic", fontWeight: 700 };
    if (z === "E") return { background: "#6ee7b7", color: "#064e3b" };
    if (z === "X") return { background: "#f3f4f6", color: "#9ca3af", fontStyle: "italic", fontWeight: 500 };
    if (z === "trial") return { background: "#fef08a", color: "#854d0e", fontWeight: 700 };
    return { background: "#fff", color: "#9ca3af" };
  };

  function setCell(ec, day, val) {
    setGrid(g => {
      const next = { ...g };
      const ecRow = { ...(next[ec] || {}) };
      if (val) ecRow[day] = val; else delete ecRow[day];
      if (Object.keys(ecRow).length === 0) delete next[ec]; else next[ec] = ecRow;
      return next;
    });
    setDirty(true);
  }
  function cycleCell(ec, day) {
    const cur = (grid[ec] || {})[day] || "";
    const idx = cycle.indexOf(cur);
    const nxt = cycle[(idx + 1) % cycle.length];
    setCell(ec, day, nxt);
  }
  function clearAll() {
    if (!confirm("Clear all entries for this period? Cannot be undone after Save.")) return;
    setUndoSnap({ grid: JSON.parse(JSON.stringify(grid || {})), label: "Clear period" });
    setGrid({}); setDirty(true);
  }

  // ── Auto-fill: greedy scheduler implementing the full BOA rule set ────
  // Rules encoded (in order of application):
  //  1. Sunday rotation HARD — every staff off every second Sunday (A/B 50/50)
  //  2. Min-staffing per day  — Fri/Sat ≈85%, Wed/Thu/Sun ≈60%, Mon/Tue ≈45%, +5% in busy period
  //  3. Sunday min ≈40% of headcount (rotation respected even if dips coverage)
  //  4. Station capacity HARD — techs/day ≤ (mani + pedi) physical stations (extras get pushed off)
  //  5. 2 off-days/week (HARD), exactly 1 off-day in the staff's designated 6-day busy week
  //  6. Off-day preference: Mon/Tue → Wed/Thu → Sun, avoid Fri/Sat where coverage permits
  //  7. Weekday flexibility: short of off-days? Fill from Mon-Thu, NEVER Sunday
  //  8. Day-off requests HARD — applied as R, override everything else
  async function autoFill() {
    if (Object.keys(grid).length > 0 && !confirm("Replace existing schedule with auto-generated one? Day-off requests will be honoured. Existing manual entries will be lost.")) return;
    // Snapshot the pre-fill grid so the whole auto-fill can be rolled back.
    setUndoSnap({ grid: JSON.parse(JSON.stringify(grid || {})), label: "Auto-fill" });

    // Fetch day-off requests for this branch/period
    let dayRequests = [];
    try {
      const r = await window.BOA_DB.sb.from("app_state").select("value").eq("key", "boa_offreq_" + branch + "_" + ym).maybeSingle();
      dayRequests = (r.data && r.data.value) || [];
    } catch (e) { console.warn("Could not load day requests:", e); }

    const salon = salonForBranch;
    // HARD station cap = mani + pedi stations physically available at the salon.
    // We never schedule more techs working than there are stations to seat them.
    const capacity = (salon.mani || 0) + (salon.pedi || 0);

    // Group weeks (Mon-Sun)
    const weeks = [];
    let cur = [];
    days.forEach(d => {
      cur.push(d);
      if (d.dow === 0) { weeks.push(cur); cur = []; }
    });
    if (cur.length) weeks.push(cur);

    // Maternity windows for this cycle. Someone on mat for the WHOLE cycle is
    // excluded from scheduling (as before). Someone whose maternity STARTS
    // mid-cycle is scheduled normally — we overlay 'ML' on their on/after-start
    // days at the very end, so their real working days up to the start date
    // are preserved instead of the whole row being blanked.
    const _cycStartYmd = days.length ? days[0].year + "-" + String(days[0].monthIdx + 1).padStart(2, "0") + "-" + String(days[0].d).padStart(2, "0") : "";
    const _cycEndYmd = days.length ? days[days.length - 1].year + "-" + String(days[days.length - 1].monthIdx + 1).padStart(2, "0") + "-" + String(days[days.length - 1].d).padStart(2, "0") : "";
    const matWin = {};
    techs.forEach(t => { matWin[t.ec] = matCycleWindow(t, _cycStartYmd, _cycEndYmd); });
    // Unpaid legal-status leave windows — handled exactly like maternity:
    // a tech on legal leave for the whole cycle is kept off the roster, and a
    // mid-cycle window is overlaid as leave on its days. Maternity wins when
    // someone is on both.
    const legalWin = {};
    techs.forEach(t => { legalWin[t.ec] = matWin[t.ec].full ? { full: false, fromYmd: null, untilYmd: null } : legalLeaveWindow(t, _cycStartYmd, _cycEndYmd); });
    // Active techs = everyone not on maternity OR legal leave for the full cycle
    // (a mid-cycle mat/legal tech is active here so they get real days before
    // their window starts).
    const allActive = [...techs].filter(t => !matWin[t.ec].full && !legalWin[t.ec].full);
    const sortedTechs = allActive
      .sort((a, b) => (a.ec || "").localeCompare(b.ec || ""));
    const onMatTechs = techs.filter(t => matWin[t.ec].full);
    const onLegalTechs = techs.filter(t => !matWin[t.ec].full && legalWin[t.ec].full);
    const totalStaff = sortedTechs.length;
    const sundayGroup = {};
    sortedTechs.forEach((s, i) => { sundayGroup[s.ec] = (i % 2 === 0) ? "A" : "B"; });

    // Identify busy-period weeks (full weeks that contain prev-month-25→6 of current)
    const ymP = ym.split("-").map(Number);
    const curMonth = ymP[1], prevMonth = (curMonth === 1) ? 12 : curMonth - 1;
    const isBusyDay = (d) => {
      const m = d.monthIdx + 1;
      if (m === prevMonth && d.d >= 25) return true;
      if (m === curMonth && d.d <= 6) return true;
      return false;
    };
    // Designation candidates — preference order:
    //   1. Full weeks that overlap the busy period (25th–6th, peak revenue)
    //   2. Otherwise the earliest full weeks (later weeks = less revenue, avoid)
    const fullWeekMeta = weeks
      .map((w, i) => ({ i, full: w.length === 7, hasBusy: w.some(isBusyDay) }))
      .filter(x => x.full);
    const busyWeekIndices = fullWeekMeta.filter(x => x.hasBusy).map(x => x.i);
    const fallbackWeekIndices = fullWeekMeta.filter(x => !x.hasBusy).sort((a, b) => a.i - b.i).map(x => x.i);
    const designatedCandidates = busyWeekIndices.length > 0 ? busyWeekIndices : fallbackWeekIndices;

    // 6-day week designation — EXACT match to the original `c1`.
    // KEY: pool is ALL FULL WEEKS (sorted by busy-day count DESC), NOT only
    // busy weeks. Some techs naturally fall through to non-busy weeks when
    // the busy ones hit the 35% per-week cap. This is what allows "some
    // people to work their 6-day week later in the month, not just during
    // busy period." Branches that opt out entirely: Table Bay, Sandown.
    // Branches that opt out of the 6-day busy-week designation. Betty is
    // closed Sun+Mon (5 working days/week max), so no tech ever works 6.
    const NO_SIX_DAY_BRANCHES = new Set(["Table Bay", "Sandown", "Betty"]);
    const designatedBusyWeek = {};
    if (!NO_SIX_DAY_BRANCHES.has(branch)) {
      const allFullWeeks = weeks.map((w, i) => ({ w, i })).filter(x => x.w.length >= 7).map(x => x.i);
      const busyDayCount = (wIdx) => weeks[wIdx].filter(d => isBusyDay(d)).length;
      const wkCount = {};
      const perWeekCap = Math.max(2, Math.ceil(sortedTechs.length * 0.35));
      sortedTechs.forEach((s) => {
        if (allFullWeeks.length === 0) { designatedBusyWeek[s.ec] = -1; return; }
        const grp = sundayGroup[s.ec];
        // Eligible: weeks where this tech WORKS the Sunday — Sunday parity
        // is anchored to the Sunday's calendar date so the rotation stays
        // consistent across cycle boundaries.
        let eligible = allFullWeeks.filter(wIdx => weekSundayOffGroup(weeks[wIdx]) !== grp);
        // Transfer-aware narrowing: a tech mid-transfer isn't actually at
        // this branch for the whole cycle, so picking their +1 W week
        // before/after they're here means the extra W lands on days they
        // don't work here at all. Restrict eligible weeks to ones that
        // overlap their active window on THIS branch.
        if (s.transferDate) {
          const _ymd = (dy) => dy.year + "-" + String(dy.monthIdx + 1).padStart(2, "0") + "-" + String(dy.d).padStart(2, "0");
          if (s.isShadow && s.transferTo === branch) {
            // Arriving: only weeks with at least one day on/after transferDate.
            const _post = allFullWeeks.filter(wIdx =>
              weeks[wIdx].some(dy => _ymd(dy) >= s.transferDate)
              && (weekSundayOffGroup(weeks[wIdx]) !== grp)
            );
            if (_post.length > 0) eligible = _post;
          } else if (!s.isShadow && s.transferring && s.transferTo && s.transferTo !== branch) {
            // Outgoing: only weeks with at least one day before transferDate.
            const _pre = allFullWeeks.filter(wIdx =>
              weeks[wIdx].some(dy => _ymd(dy) < s.transferDate)
              && (weekSundayOffGroup(weeks[wIdx]) !== grp)
            );
            if (_pre.length > 0) eligible = _pre;
          }
        }
        if (eligible.length === 0) return;                      // skip; no designation
        // Sort by busy-day-count DESC — busy weeks tried first
        const sorted = [...eligible].sort((a, b) => busyDayCount(b) - busyDayCount(a));
        let picked = null;
        for (const wIdx of sorted) {
          if (!wkCount[wIdx]) wkCount[wIdx] = 0;
          if (wkCount[wIdx] < perWeekCap) { picked = wIdx; break; }
        }
        if (picked == null) {
          // All capped — pick least-loaded
          let least = sorted[0];
          for (const wIdx of sorted) {
            if ((wkCount[wIdx] || 0) < (wkCount[least] || 0)) least = wIdx;
          }
          picked = least;
        }
        wkCount[picked] = (wkCount[picked] || 0) + 1;
        designatedBusyWeek[s.ec] = picked;
      });
    }

    // Coverage targets per day-of-week — ascending gradient from Mon (least
    // staff) to Sat (full occupancy):
    //   Mon — fewest. Quietest day, biggest off-day sink.
    //   Tue — slightly more.
    //   Wed — slightly more.
    //   Thu — more.
    //   Fri/Sat — IDEAL FULL OCCUPANCY (100% of active staff, capped at station count).
    //   Sun — rotation rule (~half team, capped to staff/2).
    // Coverage gradient ported from the original bundle's `c1` function.
    // Steeper Mon→Thu progression than my v2 had, gives a cleaner Mon<Tue<Wed<Thu separation.
    const dayTargetPct = (dow, busyPeriod) => {
      let base;
      if (dow === 5 || dow === 6) base = 1.00; // Fri/Sat — full
      else if (dow === 4) base = 0.70; // Thu
      else if (dow === 3) base = 0.60; // Wed
      else if (dow === 2) base = 0.50; // Tue
      else if (dow === 1) base = 0.40; // Mon — fewest
      else if (dow === 0) base = 0.40; // Sun rotation
      else base = 0.60;
      if (busyPeriod) base += 0.05;
      return Math.min(base, 1.0);
    };
    // Original uses Math.round (not ceil) — matches the working bundle.
    const minWorkingFor = (d) => {
      const capRem = Math.max(1, capacity);
      const target = Math.max(1, Math.round(dayTargetPct(d.dow, isBusyDay(d)) * allActive.length));
      return totalStaff <= 2 ? 1 : Math.min(capRem, target);
    };

    const newGrid = {};
    sortedTechs.forEach(s => { newGrid[s.ec] = {}; });

    // ── Store-closed days (e.g. Betty closes Sun+Mon) ───────────────────
    // Pre-seed every closed-DOW cell as 'O' for every active tech. The
    // FIRST closed Sunday in the cycle stays as a normal work day — Betty
    // techs work in another store that day (half at Bree, half at Green
    // Point); the banner above the schedule shows the split.
    const _closedDow = Array.isArray(salon.closedDow) ? salon.closedDow.map(Number) : [];
    if (_closedDow.length) {
      const _closedSet = new Set(_closedDow);
      const _firstSunday = _closedSet.has(0) ? days.find(d => d.dow === 0) : null;
      for (const d of days) {
        if (!_closedSet.has(d.dow)) continue;
        if (_firstSunday && d.year === _firstSunday.year && d.monthIdx === _firstSunday.monthIdx && d.d === _firstSunday.d) continue;
        for (const s of sortedTechs) {
          if (newGrid[s.ec][d.d] == null) newGrid[s.ec][d.d] = "O";
        }
      }
    }

    // ── Cross-month carry-over for the leading partial week ─────────────
    // A schedule period (25th–24th) can begin mid-week. The Mon-Sun labour
    // week containing the period's first days extends back into the prior
    // month's schedule. To keep the labour-week off quota capped at 2, we
    // load the prior month's schedule and count any off-days each tech
    // already has on the days of that shared labour week. The leading
    // partial's quota is then reduced by that count.
    // ── Cross-month STRICT 2-off-per-week constraint ────────────────────
    // Hard rule: no tech may ever have more than 2 off-days within any
    // single Mon-Sun labour week, even if those days span two scheduling
    // periods. The leading partial week of this period overlaps with the
    // tail of the previous month's schedule. We load the prior schedule
    // and count how many off-days each tech already has in those overlap
    // days; that count is added to the in-period off-count for this
    // tech's wIdx=0 week, so the existing 2-cap check naturally enforces
    // the cross-month boundary.
    let priorOffsLeading = {};                 // ec → number of offs already in prior month's days (Mon-Sat span before period start)
    const leadingWeekRef = weeks[0];
    const isLeadingPartial = leadingWeekRef && leadingWeekRef.length < 7;
    let priorMonthMissing = false;             // true when leading partial exists but prior schedule has no data
    if (isLeadingPartial) {
      try {
        const priorYm = window.BOA_DB.shiftYm(ym, -1);
        const priorSched = await window.BOA_DB.loadSchedule(branch, priorYm, false);
        const priorGrid = (priorSched && priorSched.grid) || {};
        const priorIsEmpty = !priorSched || !priorSched.grid || Object.keys(priorSched.grid).length === 0;
        priorMonthMissing = priorIsEmpty;
        const firstDay = leadingWeekRef[0];
        const firstDow = firstDay.dow;
        const firstDate = new Date(firstDay.year, firstDay.monthIdx, firstDay.d);
        const daysBack = (firstDow === 0) ? 6 : firstDow - 1;
        const priorDays = [];
        for (let k = daysBack; k > 0; k--) {
          const dt = new Date(firstDate); dt.setDate(firstDate.getDate() - k);
          priorDays.push(dt.getDate());
        }
        sortedTechs.forEach(s => {
          const row = priorGrid[s.ec] || {};
          let n = 0;
          priorDays.forEach(dnum => {
            const v = row[dnum];
            if (v === "O" || v === "R" || v === "L") n++;
          });
          priorOffsLeading[s.ec] = n;
        });
      } catch (e) {
        console.warn("Could not load prior schedule for carry-over:", e);
        priorMonthMissing = true;
        sortedTechs.forEach(s => { priorOffsLeading[s.ec] = 0; });
      }
    }
    // Option A — if the prior month hasn't been generated yet, the
    // cross-month 2-off-per-week constraint can't be enforced for the
    // leading partial week. Surface this and let the user decide.
    if (isLeadingPartial && priorMonthMissing) {
      const priorYm = window.BOA_DB.shiftYm(ym, -1);
      const [py, pm] = priorYm.split("-").map(Number);
      const priorLabel = new Date(py, pm - 1, 1).toLocaleString("en-US", { month: "long", year: "numeric" });
      const ok = confirm(
        "The schedule for " + priorLabel + " hasn't been generated yet.\n\n" +
        "This month starts mid-week, so the first labour week (Mon-Sun) overlaps with " + priorLabel + ". " +
        "Without that month's schedule, the strict 2-off-per-week rule can't be enforced across the boundary — " +
        "a tech might end up with more than 2 off-days in that combined week once " + priorLabel + " is generated later.\n\n" +
        "Recommended: cancel, generate " + priorLabel + " first, then return here.\n\n" +
        "Click OK to continue anyway, or Cancel to stop."
      );
      if (!ok) return;
    }
    // Trailing-partial cross-month carry — mirror of the leading carry.
    // When this cycle ends mid-week, the labour week containing the trailing
    // days extends INTO the next cycle. Without a reservation, PHASE 4 fills
    // the trailing partial to the full 2-cap (e.g. 2 offs in a Mon-Wed tail)
    // — leaving zero room in the next cycle's leading partial for the same
    // labour week, which over-staffs the new cycle's Thu-Sat days. Reserve
    // 1 off-slot here for EVERY tech, regardless of Sunday-rotation group:
    //   • off-group techs spend their reserved slot on the next cycle's
    //     Sunday (stamped by PASS A using `sundayDateParity`),
    //   • on-group techs spend theirs on a Thu-Sat coverage off placed by
    //     the next cycle's PHASE 4.
    // Splitting 1 off per cycle-side keeps the labour-week 2-cap intact and
    // distributes coverage evenly across the cross-month boundary instead
    // of bunching all the offs in one cycle's tail.
    const trailingWeekRef = weeks.length > 0 ? weeks[weeks.length - 1] : null;
    const isTrailingPartial = !!(trailingWeekRef && trailingWeekRef.length < 7 && weeks.length > 1);
    const futureOffsTrailing = {};
    sortedTechs.forEach(s => { futureOffsTrailing[s.ec] = 0; });
    if (isTrailingPartial) {
      sortedTechs.forEach(s => { futureOffsTrailing[s.ec] = 1; });
    }
    const trailingWeekIdx = weeks.length - 1;
    const isCarryWeek = (wIdx) =>
      (isLeadingPartial && wIdx === 0) ||
      (isTrailingPartial && wIdx === trailingWeekIdx);
    // Helper: how many off-days each tech "carries in/out" of the period
    // for a given week index. The leading partial (wIdx=0 when the cycle
    // starts mid-week) carries IN from the prior month's tail; the
    // trailing partial (wIdx=last when the cycle ends mid-week) carries
    // OUT a reserved slot for the next month's Sunday rotation. Every
    // other week returns 0 so the existing in-period count stands alone.
    const _carryFor = (ec, wIdx) => {
      if (isLeadingPartial && wIdx === 0) return priorOffsLeading[ec] || 0;
      if (isTrailingPartial && wIdx === trailingWeekIdx) return futureOffsTrailing[ec] || 0;
      return 0;
    };

    // PHASE E — max-6-consecutive enforcement, ported from the original `c1`.
    // For each tech, find their longest streak ≥ 7 and try to break it by
    // swapping an existing off-day (in any week the streak spans) onto a
    // day inside the streak. The original was much more lenient than my v2:
    //   • allows Mon/Fri/Sat as swap candidates (just not Sun)
    //   • accepts a swap if the new max-streak is SHORTER than the old one
    //     (doesn't require complete elimination)
    //   • picks the swap that minimises the resulting max-streak
    //   • up to 10 attempts per tech
    // This is what made the original schedule labour-law compliant in
    // practice — my over-strict v2 left too many violations unresolved.
    function enforceMaxSixConsecutive(g, allDays, weekChunks, ecList) {
      let totalSwaps = 0, unresolved = 0;
      const dayToWk = new Map();
      weekChunks.forEach((w, i) => w.forEach(d => dayToWk.set(d.d, i)));

      const findLongestRun = (ec) => {
        let cu = 0, rs = -1, maxRun = 0, maxRs = -1, maxRe = -1;
        for (let i = 0; i < allDays.length; i++) {
          const v = g[ec] && g[ec][allDays[i].d];
          if (v === "W" || v === "WE" || v === "WB" || v === "WM" || v === "WL" || v === "E") {
            if (cu === 0) rs = i;
            cu++;
            if (cu > maxRun) { maxRun = cu; maxRs = rs; maxRe = i; }
          } else { cu = 0; rs = -1; }
        }
        return { maxRun, maxRs, maxRe };
      };
      const wkOffsCount = (ec, wIdx) => {
        const wk = weekChunks[wIdx];
        if (!wk) return 0;
        return wk.reduce((n, d) => {
          const v = g[ec] && g[ec][d.d];
          return n + ((v === "O" || v === "R" || v === "L") ? 1 : 0);
        }, 0);
      };
      const dayWorking = (d) => ecList.reduce((n, e2) => {
        const v = g[e2] && g[e2][d.d];
        return n + ((v === "W" || v === "WE" || v === "WB" || v === "WM" || v === "WL" || v === "E") ? 1 : 0);
      }, 0);

      ecList.forEach(ec => {
        for (let attempt = 0; attempt < 40; attempt++) {
          const { maxRun, maxRs, maxRe } = findLongestRun(ec);
          if (maxRun < 7) break;

          // Weeks the run spans
          const runWks = new Set();
          for (let i = maxRs; i <= maxRe; i++) runWks.add(dayToWk.get(allDays[i].d));

          // Off-day candidates for the swap source: tech's existing Os (not Sun)
          // in any week the run spans, OUTSIDE the run itself.
          const swapSources = [];
          for (let i = 0; i < allDays.length; i++) {
            const d = allDays[i];
            if (d.dow === 0) continue;
            if (g[ec][d.d] !== "O") continue;
            if (!runWks.has(dayToWk.get(d.d))) continue;
            if (i >= maxRs && i <= maxRe) continue;
            swapSources.push(i);
          }

          // STEP 1: try swap (preserves tech's off-count) — pick the swap
          // that minimises the new max-streak. Only cap check; no minW check
          // (other passes handle under-coverage). Allows Mon/Fri/Sat as swap.
          let bestSwap = null;
          let bestNewMax = maxRun;
          for (const src of swapSources) {
            const srcWk = dayToWk.get(allDays[src].d);
            const srcWorking = dayWorking(allDays[src]);
            if (srcWorking + 1 > capacity) continue;          // cap: src would over-cap on flip
            for (let ix = maxRs; ix <= maxRe; ix++) {
              const tgt = allDays[ix];
              if (tgt.dow === 0) continue;
              if (dayToWk.get(tgt.d) !== srcWk) continue;     // same week as src
              g[ec][allDays[src].d] = "W";
              g[ec][tgt.d] = "O";
              const { maxRun: newMax } = findLongestRun(ec);
              g[ec][allDays[src].d] = "O";
              g[ec][tgt.d] = "W";
              if (newMax < bestNewMax) {
                bestNewMax = newMax;
                bestSwap = { src, tgt };
              }
            }
          }

          if (bestSwap) {
            g[ec][allDays[bestSwap.src].d] = "W";
            g[ec][bestSwap.tgt.d] = "O";
            totalSwaps++;
            if (bestNewMax < 7) break;
            continue;
          }

          // STEP 2 — fallback: PLACE A NEW OFF in the streak on a day where
          // the tech still has off-quota left in that week (me < we). This
          // matches the original bundle's escape valve. Adds an off-day,
          // doesn't remove one — but only within the tech's per-week target.
          let placed = null;
          let placedScore = -Infinity;
          for (let ix = maxRs; ix <= maxRe; ix++) {
            const tgt = allDays[ix];
            if (tgt.dow === 0) continue;
            if (g[ec][tgt.d] !== "W" && g[ec][tgt.d] !== "WE" && g[ec][tgt.d] !== "WL") continue;
            const wIdx = dayToWk.get(tgt.d);
            if (wIdx == null) continue;
            const wk = weekChunks[wIdx];
            const wkLen = wk.length;
            // Per-week target. For partials we allow up to 2 (matches the
            // earlier wkMaxOffs logic in Phase C).
            let target;
            if (wkLen < 7) target = 2;
            else target = (designatedBusyWeek[ec] === wIdx) ? 1 : 2;
            if (wkOffsCount(ec, wIdx) >= target) continue;     // tech already at target for this week
            // Prefer Mon/Tue (high score), avoid Thu/Fri/Sat
            const sc = (tgt.dow === 1 ? 60 : tgt.dow === 2 ? 40 :
              tgt.dow === 3 ? 20 : tgt.dow === 4 ? -40 :
                (tgt.dow === 5 || tgt.dow === 6) ? -45 : 15);
            if (sc > placedScore) { placedScore = sc; placed = tgt; }
          }
          if (placed) {
            g[ec][placed.d] = "O";
            totalSwaps++;
            const { maxRun: m2 } = findLongestRun(ec);
            if (m2 < 7) break;
            continue;
          }

          unresolved++;
          break;
        }
      });
      return { totalSwaps, unresolved };
    }

    // ── Build a unified request list from BOTH sources ──────────────────
    //   • dayRequests  — legacy boa_offreq_<branch>_<ym>: { ec, days:[d,...] }
    //   • techRequests — new boa_tech_requests_v1:        { ec, branch, date }
    // We dedupe by (ec, day-of-month) and keep the date string so we can
    // give a precise warning when a request can't be honoured.
    const reqByEcDay = new Map();
    const _addReq = (ec, dayNum, date, source, note) => {
      if (!ec || !dayNum) return;
      const k = ec + "|" + dayNum;
      if (reqByEcDay.has(k)) return;
      reqByEcDay.set(k, { ec, day: dayNum, date: date || "", source: source || "", note: note || "" });
    };
    dayRequests.forEach(req => {
      if (!req.ec) return;
      (req.days || []).forEach(dnum => {
        const dd = days.find(x => x.d === dnum);
        const date = dd ? (dd.year + "-" + String(dd.monthIdx + 1).padStart(2, "0") + "-" + String(dnum).padStart(2, "0")) : "";
        _addReq(req.ec, dnum, date, req.source || "legacy", req.note || "");
      });
    });
    (techRequests || []).forEach(r => {
      if (!r || !r.ec || !r.date) return;
      if (r.branch && r.branch !== branch) return;
      if (!_inGrid(r.ec)) return;
      const dt = new Date(r.date + "T00:00:00");
      if (isNaN(dt.getTime())) return;
      const inPeriod = days.some(d => d.year === dt.getFullYear() && d.monthIdx === dt.getMonth() && d.d === dt.getDate());
      if (!inPeriod) return;
      _addReq(r.ec, dt.getDate(), r.date, r.source || "request", r.note || "");
    });
    const consolidatedReqs = Array.from(reqByEcDay.values());
    const requestedDays = {};
    consolidatedReqs.forEach(r => {
      requestedDays[r.ec] = requestedDays[r.ec] || new Set();
      requestedDays[r.ec].add(r.day);
    });

    // Track requests we couldn't apply (and why) so we can warn the user
    // above the grid. Each entry: {ec, name, date, dayNum, reason, source, note}.
    const unhonouredList = [];
    const techByEc = {};
    sortedTechs.forEach(t => { techByEc[t.ec] = t; });
    onMatTechs.forEach(t => { techByEc[t.ec] = t; });
    onLegalTechs.forEach(t => { techByEc[t.ec] = t; });
    const dayToWeekIdx = new Map();
    weeks.forEach((wk, wIdx) => wk.forEach(d => dayToWeekIdx.set(d.d, wIdx)));
    const _logUnhonoured = (req, reason) => {
      const t = techByEc[req.ec];
      unhonouredList.push({
        ec: req.ec,
        name: (t && t.name) || req.ec,
        date: req.date,
        dayNum: req.day,
        reason,
        source: req.source,
        note: req.note
      });
    };

    // PASS A — Sun rotation across ALL weeks first (matches original PHASE 1
    // which uses `K.forEach(...)` outside the per-week PHASE 4 loop). This
    // ensures PHASE 4's adjacency check can see Sundays of OTHER weeks too.
    //
    // The Sunday is ALWAYS stamped for the off-group, even when the cycle
    // starts with a partial leading week and the prior month's tail already
    // carries 2 offs into the rollover labour week. The visible "one off /
    // one on" alternation that staff see each week is the user-facing
    // contract; skipping the Sunday to satisfy a strict cross-month 2-cap
    // breaks that contract on the leading-partial Sunday. The trailing-
    // carry reservation above prevents the prior cycle from over-stuffing
    // the rollover week in the first place when both months are generated
    // under the new logic, so the cap is upheld in normal operation. If a
    // legacy prior grid was generated before this fix and the rollover
    // week ends up with 3 offs, that overage is surfaced as a soft
    // conflict rather than silently breaking the rotation.
    weeks.forEach((week, wIdx) => {
      const sundayDay = week.find(d => d.dow === 0);
      if (!sundayDay) return;
      // Skip the Sunday rotation entirely on closed Sundays — the
      // closedDow pre-seed has already stamped everyone O on every
      // Sunday EXCEPT the first one (which is the cross-store loan day
      // and must stay W for all techs). Running the rotation here
      // would otherwise mark half the team Sun=O on the first Sunday,
      // contradicting the loan-day rule.
      if (_closedDow.indexOf(0) !== -1) return;
      const sundayOffGroup = sundayDateParity(sundayDay);
      sortedTechs.forEach(s => {
        if (sundayGroup[s.ec] === sundayOffGroup) {
          newGrid[s.ec][sundayDay.d] = "O";
        }
      });
    });

    // ── Apply day-off requests, with the 2-off-per-week cap as a hard rule.
    // Sundays have already been stamped by PASS A, so we count them in the
    // per-week off-tally before placing R. If placing an R would push the
    // tech to >2 offs in any single Mon-Sun labour week (incl. cross-month
    // carry from the prior cycle for the leading partial), we skip the
    // request and log it for the warning banner. The remaining auto-fill
    // phases protect R cells, so a stamped R won't be removed later.
    consolidatedReqs.sort((a, b) => (a.ec === b.ec ? a.day - b.day : a.ec.localeCompare(b.ec)));
    consolidatedReqs.forEach(req => {
      const ec = req.ec;
      if (!newGrid[ec]) {
        _logUnhonoured(req, "tech is not in the active scheduling roster (on leave, terminated, or not at this branch)");
        return;
      }
      const wIdx = dayToWeekIdx.get(req.day);
      if (wIdx == null) {
        _logUnhonoured(req, "date is outside this scheduling cycle");
        return;
      }
      const wk = weeks[wIdx];
      const existing = newGrid[ec][req.day];
      if (existing === "L") { _logUnhonoured(req, "tech is on leave that day"); return; }
      if (existing === "X") { _logUnhonoured(req, "outside tech's employment dates"); return; }
      // Count existing offs in the labour week, EXCLUDING the request day
      // itself (we may be replacing an O there with R, which doesn't change
      // the count). Then add 1 for the new R if existing isn't already off.
      let curOffOther = 0;
      for (const dd of wk) {
        if (dd.d === req.day) continue;
        const v = newGrid[ec][dd.d];
        if (v === "O" || v === "R" || v === "L") curOffOther++;
      }
      const carry = _carryFor(ec, wIdx);
      const wouldAddOff = (existing === "O" || existing === "R") ? 0 : 1;
      if (curOffOther + wouldAddOff + carry > 2) {
        const reason = "would put " + (curOffOther + wouldAddOff + carry) +
          " off-days in that Mon-Sun labour week (max 2 allowed" +
          (carry > 0 ? "; " + carry + " carried over from the prior cycle" : "") + ")";
        _logUnhonoured(req, reason);
        return;
      }
      // Safe to place — upgrade O→R or stamp empty cell as R.
      newGrid[ec][req.day] = "R";
    });

    // Pre-compute global per-day W counters and helpers used by PHASE 4.
    const _W4 = {};
    days.forEach(d => {
      const minW = minWorkingFor(d);
      const off = sortedTechs.filter(s => {
        const v = newGrid[s.ec][d.d]; return v === "O" || v === "R" || v === "L";
      }).length;
      _W4[d.d] = { minNeeded: minW, maxOff: Math.max(0, totalStaff - minW), currentOff: off, dow: d.dow };
    });
    const _isPreHol4 = (d) => {
      const dt = new Date(d.year, d.monthIdx, d.d + 1);
      const ymd = dt.getFullYear() + "-" + String(dt.getMonth() + 1).padStart(2, "0") + "-" + String(dt.getDate()).padStart(2, "0");
      return holidayLookup && !!holidayLookup[ymd];
    };
    const _slackOk4 = (dnum) => _W4[dnum].currentOff < _W4[dnum].maxOff;
    const _tt4 = (s, d) => {
      if (newGrid[s.ec][d.d] || !_slackOk4(d.d)) return -9999;
      let score = 0;
      if (d.dow === 1) score += 60;
      else if (d.dow === 2) score += 40;
      else if (d.dow === 3) score += 20;
      else if (d.dow === 4) score -= 40;
      else if (d.dow === 0) score += 15;
      else if (d.dow === 5 || d.dow === 6) score -= 45;
      if (_isPreHol4(d)) score -= 8;
      const myOffs = days.filter(z => newGrid[s.ec][z.d] && newGrid[s.ec][z.d] !== "W" && z.d !== d.d).map(z => z.d);
      if (myOffs.length > 0) {
        const minD = Math.min(...myOffs.map(od => Math.abs(od - d.d)));
        if (minD <= 1) score -= 50;
        else if (minD === 2) score -= 20;
        else if (minD === 3 || minD === 4) score += 25;
      }
      score += (_W4[d.d].maxOff - _W4[d.d].currentOff) * 5;
      return score;
    };
    const _placeOff4 = (ec, dnum) => {
      if (!newGrid[ec][dnum]) {
        newGrid[ec][dnum] = "O";
        if (_W4[dnum]) _W4[dnum].currentOff++;
      }
    };
    // Cross-month carry-aware: when wIdx is the leading partial week, add
    // priorOffsLeading[ec] so this tech's effective per-week off count
    // reflects offs already used in the prior month's tail of the same
    // Mon-Sun labour week. The hard 2-cap then applies cross-month.
    const _wkOffs4 = (ec, week, wIdx) => {
      const inWk = week.reduce((n, d) => {
        const v = newGrid[ec][d.d]; return n + ((v && v !== "W") ? 1 : 0);
      }, 0);
      return inWk + (typeof wIdx === "number" ? _carryFor(ec, wIdx) : 0);
    };
    const _wkTarget4 = (ec, wIdx) => (designatedBusyWeek[ec] === wIdx) ? 1 : 2;
    const _isAllLeave4 = (ec, week) => week.every(d => newGrid[ec][d.d] === "L");

    // PASS B — PHASE 4: per-week off-day fill using `_tt4` scoring.
    // Now Sundays for ALL weeks are already set, so adjacency calculations
    // include cross-week Sundays — matches the original.
    weeks.forEach((week, wIdx) => {
      for (let pass = 0; pass < 200; pass++) {
        const undertarget = sortedTechs
          .filter(s => !_isAllLeave4(s.ec, week) && _wkOffs4(s.ec, week, wIdx) < _wkTarget4(s.ec, wIdx))
          .map(s => ({ s, off: _wkOffs4(s.ec, week, wIdx) }))
          .sort((a, b) => a.off - b.off);
        if (undertarget.length === 0) break;
        let placed = false;
        for (const { s } of undertarget) {
          const opts = week.filter(d => !newGrid[s.ec][d.d] && _slackOk4(d.d) && d.dow !== 0);
          if (opts.length === 0) continue;
          opts.sort((a, b) => _tt4(s, b) - _tt4(s, a));
          _placeOff4(s.ec, opts[0].d);
          placed = true;
          break;
        }
        if (!placed) break;
      }
    });

    // PHASE 5 — fill any remaining cells as W (across ALL weeks at once,
    // matching the original `for(let h of f)for(let M of p)d[h.ec][M.d]||(d[h.ec][M.d]="W")`).
    sortedTechs.forEach(s => days.forEach(d => { if (!newGrid[s.ec][d.d]) newGrid[s.ec][d.d] = "W"; }));

    // Build the global W (per-day off counters) AFTER PHASE 5 so PHASE 6's
    // streak detection and cap calculations see the full populated grid.
    const _W6 = {};
    days.forEach(d => {
      const off = sortedTechs.filter(s => { const v = newGrid[s.ec][d.d]; return v === "O" || v === "R" || v === "L"; }).length;
      _W6[d.d] = { currentOff: off, dow: d.dow };
    });
    const _dayToWk6 = new Map();
    weekChunks.forEach((wk, i) => wk.forEach(d => _dayToWk6.set(d.d, i)));

    // PHASE 6 — per-day STATION CAP enforcement with streak protection.
    // Iterates ALL non-Sunday days. For each over-cap day, finds a tech
    // working that day with a same-week O on a higher-priority day (with
    // headroom), swaps. Reverts if swap creates a 7-day streak.
    days.forEach(d => {
      if (d.dow === 0) return;
      let needed = (totalStaff - _W6[d.d].currentOff) - capacity;
      if (needed <= 0) return;
      const dWk = _dayToWk6.get(d.d);
      let safetyC = 0;
      while (needed > 0 && safetyC++ < 50) {
        const workers = sortedTechs.filter(s => newGrid[s.ec][d.d] === "W");
        let any = false;
        for (const cand of workers) {
          const swapDays = days.filter(B => {
            if (B.d === d.d || newGrid[cand.ec][B.d] !== "O" || B.dow === 0) return false;
            if (_dayToWk6.get(B.d) !== dWk) return false;            // SAME WEEK as d
            return (totalStaff - _W6[B.d].currentOff) < capacity;     // B has headroom
          });
          if (swapDays.length === 0) continue;
          swapDays.sort((a, b) => {
            const pri = x => x.dow === 1 ? 3 : x.dow === 2 ? 2 : x.dow === 3 ? 1 : 0;
            if (pri(a) !== pri(b)) return pri(b) - pri(a);
            const aHead = capacity - (totalStaff - _W6[a.d].currentOff);
            const bHead = capacity - (totalStaff - _W6[b.d].currentOff);
            return bHead - aHead;
          });
          const sw = swapDays[0];
          newGrid[cand.ec][d.d] = "O"; _W6[d.d].currentOff++;
          newGrid[cand.ec][sw.d] = "W"; _W6[sw.d].currentOff--;
          // Streak check across the FULL period (this is now correct because
          // PHASE 5 has filled all empty cells as W).
          let run = 0, viol = false;
          for (const dd of days) {
            const v = newGrid[cand.ec][dd.d];
            if (v === "W" || v === "WE" || v === "WB" || v === "WM" || v === "WL" || v === "E") {
              run++;
              if (run >= 7) { viol = true; break; }
            } else run = 0;
          }
          if (viol) {
            newGrid[cand.ec][d.d] = "W"; _W6[d.d].currentOff--;
            newGrid[cand.ec][sw.d] = "O"; _W6[sw.d].currentOff++;
            continue;
          }
          needed--; any = true;
          break;
        }
        if (!any) break;
      }
    });

    // ─── Cross-week streak/coverage passes (ported from original `c1`) ───
    const W = {};
    const _isPreHolFn = (d) => {
      const dt = new Date(d.year, d.monthIdx, d.d + 1);
      const ymd = dt.getFullYear() + "-" + String(dt.getMonth() + 1).padStart(2, "0") + "-" + String(dt.getDate()).padStart(2, "0");
      return holidayLookup && !!holidayLookup[ymd];
    };
    days.forEach(d => {
      const minW = minWorkingFor(d, sortedTechs.length);
      const off = sortedTechs.filter(s => { const v = newGrid[s.ec][d.d]; return v === "O" || v === "R" || v === "L"; }).length;
      W[d.d] = { dd: d, minNeeded: minW, maxOff: Math.max(0, sortedTechs.length - minW), currentOff: off, dow: d.dow, isPreHol: _isPreHolFn(d) };
    });
    const ecList = sortedTechs.map(s => s.ec);
    const dayToWk = new Map();
    weekChunks.forEach((wk, idx) => wk.forEach(d => dayToWk.set(d.d, idx)));
    // Cross-month carry-aware: leading partial week gets prior-month tail
    // offs added so the strict 2-cap is enforced across the boundary by
    // every later phase (7, 8, 9, 10, 11, 13) that consults this counter.
    const techWkOffs = (ec, wkIdx) => {
      const wk = weekChunks[wkIdx]; if (!wk) return 0;
      const inWk = wk.reduce((n, d) => {
        const v = newGrid[ec][d.d]; return n + ((v && v !== "W" && v !== "WE" && v !== "WB" && v !== "WM" && v !== "WL" && v !== "E") ? 1 : 0);
      }, 0);
      return inWk + _carryFor(ec, wkIdx);
    };
    // Matches original An(h, M): 1 if designated for week wkIdx, else 2.
    const techTarget = (ec, wkIdx) => (designatedBusyWeek[ec] === wkIdx) ? 1 : 2;
    const findFirst7 = (ec) => {
      let cnt = 0, start = null, end = null;
      for (const d of days) {
        const v = newGrid[ec][d.d];
        if (v === "W" || v === "WE" || v === "WB" || v === "WM" || v === "WL" || v === "E") {
          if (cnt === 0) start = d.d;
          cnt++; end = d.d;
          if (cnt >= 7) return { start, end };
        } else cnt = 0;
      }
      return null;
    };

    // PHASE 7 — per-tech streak fix (up to 40 attempts).
    sortedTechs.forEach(s => {
      const ec = s.ec;
      for (let attempt = 0; attempt < 40; attempt++) {
        const j = findFirst7(ec);
        if (!j) break;
        const inRun = (dd) => dd.d >= j.start && dd.d <= j.end;
        const V = days.filter(B => inRun(B) && newGrid[ec][B.d] === "W" && B.dow !== 0);
        const Z = (j.start + j.end) / 2;
        const baseScore = (B) => (B.dow === 1 ? 60 : B.dow === 2 ? 40 : B.dow === 3 ? 20 : B.dow === 4 ? -40 : B.dow === 0 ? 10 : -45);
        const pA = days.filter(B => newGrid[ec][B.d] === "O" && B.dow !== 0 && !inRun(B));
        // Sort streak working-days by score (higher = better off-target)
        const EA = [...V].sort((B, eA) => {
          const sa = (W[B.d].currentOff < W[B.d].maxOff ? 200 : 0) + baseScore(B) - Math.abs(B.d - Z) * 0.8;
          const sb = (W[eA.d].currentOff < W[eA.d].maxOff ? 200 : 0) + baseScore(eA) - Math.abs(eA.d - Z) * 0.8;
          return sb - sa;
        });
        // Sort outside off-days by adjacency cluster score
        const oA = pA.map(B => {
          const others = days.filter(y => newGrid[ec][y.d] && newGrid[ec][y.d] !== "W" && y.d !== B.d).map(y => y.d);
          const minD = others.length > 0 ? Math.min(...others.map(y => Math.abs(y - B.d))) : 99;
          return { src: B, clusterScore: minD <= 2 ? 100 : minD <= 4 ? 30 : 0 };
        }).sort((a, b) => b.clusterScore - a.clusterScore);
        let fixed = false;
        for (const B of EA) {
          for (const { src: eA } of oA) {
            if (dayToWk.get(eA.d) !== dayToWk.get(B.d)) continue;
            // Try swap
            newGrid[ec][eA.d] = "W"; W[eA.d].currentOff--;
            newGrid[ec][B.d] = "O"; W[B.d].currentOff++;
            const newJ = findFirst7(ec);
            // Cap check on eA
            const eaWorking = totalStaff - W[eA.d].currentOff;
            if (eaWorking <= capacity && (!newJ || (newJ.end - newJ.start) < (j.end - j.start) || newJ.start > j.start)) {
              fixed = true;
              break;
            }
            // Revert
            newGrid[ec][B.d] = "W"; W[B.d].currentOff--;
            newGrid[ec][eA.d] = "O"; W[eA.d].currentOff++;
          }
          if (fixed) break;
        }
        if (fixed) continue;
        // Fallback 1: place new off in streak where tech is under target
        const HA = V.filter(B => techWkOffs(ec, dayToWk.get(B.d)) < techTarget(ec, dayToWk.get(B.d)));
        if (HA.length > 0) {
          HA.sort((B, eA) => {
            const sa = (W[B.d].currentOff < W[B.d].maxOff ? 200 : 0) + baseScore(B) - Math.abs(B.d - Z) * 0.8;
            const sb = (W[eA.d].currentOff < W[eA.d].maxOff ? 200 : 0) + baseScore(eA) - Math.abs(eA.d - Z) * 0.8;
            return sb - sa;
          });
          newGrid[ec][HA[0].d] = "O"; W[HA[0].d].currentOff++;
          continue;
        }
        // Fallback 2: same logic, mark as loose (tracked in zq for later trim protection)
        if (HA.length === 0) break;
      }
    });
    const zq = new Set();    // loose offs (placeholder — would normally be filled by HA fallback when target exceeded)

    // PHASE 8 — if total staff > station cap, force more offs to bring working ≤ cap.
    if (totalStaff > capacity) {
      days.forEach(h => {
        if (h.dow === 0) return;
        const wkH = dayToWk.get(h.d);
        const need = totalStaff - capacity;
        while (W[h.d].currentOff < need) {
          let bestS = null, bestSc = -999;
          for (const s of sortedTechs) {
            if (newGrid[s.ec][h.d]) continue;
            const o2 = techWkOffs(s.ec, wkH);
            const tg = techTarget(s.ec, wkH);
            const sc = tg - o2;
            if (sc > bestSc) { bestS = s; bestSc = sc; }
          }
          if (!bestS || bestSc <= 0) break;
          newGrid[bestS.ec][h.d] = "O"; W[h.d].currentOff++;
        }
      });
    }

    // PHASE 9 — top-up under-target weeks.
    weekChunks.forEach((wk, wkIdx) => {
      if (wk.length < 7) return;
      sortedTechs.forEach(s => {
        const ec = s.ec;
        const target = techTarget(ec, wkIdx);
        let cur = techWkOffs(ec, wkIdx);
        for (let iter = 0; iter < 14 && cur < target; iter++) {
          const opts = wk.filter(d => newGrid[ec][d.d] === "W" && d.dow !== 0);
          if (opts.length === 0) break;
          const score = (d) => {
            let s2 = 0;
            if (d.dow === 1 || d.dow === 2) s2 += 55;
            else if (d.dow === 3) s2 += 40;
            else if (d.dow === 4) s2 -= 15;
            else if (d.dow === 0) s2 += 15;
            else if (d.dow === 5 || d.dow === 6) s2 -= 45;
            if (W[d.d] && W[d.d].isPreHol) s2 -= 8;
            const r = W[d.d].maxOff - W[d.d].currentOff;
            s2 += r > 0 ? r * 8 : (r - 1) * 40;
            s2 -= Math.max(0, W[d.d].currentOff - 1) * 50;
            return s2;
          };
          opts.sort((a, b) => score(b) - score(a));
          newGrid[ec][opts[0].d] = "O"; W[opts[0].d].currentOff++; cur++;
        }
      });
    });

    // PHASE 10 — trim excess offs (over target).
    weekChunks.forEach((wk, wkIdx) => {
      if (wk.length < 7) return;
      sortedTechs.forEach(s => {
        const ec = s.ec;
        const target = techTarget(ec, wkIdx);
        const offDays = wk.filter(d => {
          const v = newGrid[ec][d.d];
          return (v === "O" || v === "R" || v === "L");
        });
        if (offDays.length <= target) return;
        let excess = offDays.length - target;
        const candidates = offDays.filter(d => {
          const v = newGrid[ec][d.d];
          return v === "O" && d.dow !== 0 && !zq.has(ec + "-" + d.d);
        });
        candidates.sort((a, b) => {
          const pri = (x) => (x.dow === 5 || x.dow === 6) ? 3 : (x.dow === 3 || x.dow === 4) ? 2 : 1;
          return pri(b) - pri(a);
        });
        for (const d of candidates) {
          if (excess <= 0) break;
          newGrid[ec][d.d] = "W"; W[d.d].currentOff--; excess--;
        }
      });
    });

    // PHASE 11 — per-day cap/floor enforcement.
    days.forEach(h => {
      if (h.dow === 0) return;
      const wkH = dayToWk.get(h.d);
      // Reduce excess offs (currentOff > maxOff)
      while (W[h.d].currentOff > W[h.d].maxOff) {
        let cand = null, best = -999;
        for (const s of sortedTechs) {
          if (newGrid[s.ec][h.d] !== "O") continue;
          const sc = techWkOffs(s.ec, wkH) - techTarget(s.ec, wkH);
          if (sc > best) { cand = s; best = sc; }
        }
        if (!cand || best <= 0) break;
        newGrid[cand.ec][h.d] = "W"; W[h.d].currentOff--;
      }
      // Push more off if working over station cap
      while ((totalStaff - W[h.d].currentOff) > capacity) {
        let cand = null, bestLow = 999;
        for (const s of sortedTechs) {
          if (newGrid[s.ec][h.d] !== "W") continue;
          const oc = techWkOffs(s.ec, wkH);
          if (oc >= techTarget(s.ec, wkH)) continue;
          if (oc < bestLow) { cand = s; bestLow = oc; }
        }
        if (!cand) break;
        newGrid[cand.ec][h.d] = "O"; W[h.d].currentOff++;
      }
    });

    // PHASE 12 — final safety pass for max-6-consecutive.
    let totalSwaps = 0, unresolved = 0;
    sortedTechs.forEach(s => {
      const ec = s.ec;
      for (let safIter = 0; safIter < 10; safIter++) {
        let cu = 0, rs = -1, maxRun = 0, maxRs = -1, maxRe = -1;
        for (let i = 0; i < days.length; i++) {
          const v = newGrid[ec][days[i].d];
          if (v === "W" || v === "WE" || v === "WB" || v === "WM" || v === "WL" || v === "E") {
            if (cu === 0) rs = i;
            cu++;
            if (cu > maxRun) { maxRun = cu; maxRs = rs; maxRe = i; }
          } else { cu = 0; rs = -1; }
        }
        if (maxRun < 7) break;
        const runWks = new Set();
        for (let i = maxRs; i <= maxRe; i++) runWks.add(dayToWk.get(days[i].d));
        const swp = [];
        for (let i = 0; i < days.length; i++) {
          const dd = days[i];
          if (newGrid[ec][dd.d] !== "O" || dd.dow === 0) continue;
          if (!runWks.has(dayToWk.get(dd.d))) continue;
          if (i >= maxRs && i <= maxRe) continue;
          swp.push(i);
        }
        let fixed = false;
        for (const src of swp) {
          if (fixed) break;
          const srcWk = dayToWk.get(days[src].d);
          let bestIx = -1, bestNew = maxRun;
          for (let ix = maxRs; ix <= maxRe; ix++) {
            if (dayToWk.get(days[ix].d) !== srcWk) continue;
            if (days[ix].dow === 0) continue;
            if (W[days[ix].d].currentOff >= W[days[ix].d].maxOff) continue;
            newGrid[ec][days[src].d] = "W";
            newGrid[ec][days[ix].d] = "O";
            let nr = 0, nm = 0;
            for (const dd of days) {
              const v = newGrid[ec][dd.d];
              if (v === "W" || v === "WE" || v === "WB" || v === "WM" || v === "WL" || v === "E") { nr++; if (nr > nm) nm = nr; } else nr = 0;
            }
            newGrid[ec][days[src].d] = "O";
            newGrid[ec][days[ix].d] = "W";
            if (nm < bestNew) { bestNew = nm; bestIx = ix; }
          }
          if (bestIx >= 0) {
            newGrid[ec][days[src].d] = "W"; W[days[src].d].currentOff--;
            newGrid[ec][days[bestIx].d] = "O"; W[days[bestIx].d].currentOff++;
            fixed = true;
            totalSwaps++;
          }
        }
        if (!fixed) { unresolved++; break; }
      }
    });

    // PHASE 13 — final fill to target across full weeks.
    weekChunks.forEach((wk, wkIdx) => {
      if (wk.length < 7) return;
      sortedTechs.forEach(s => {
        const ec = s.ec;
        let oc = techWkOffs(ec, wkIdx);
        const tg = techTarget(ec, wkIdx);
        if (oc >= tg) return;
        for (const wD of [1, 2, 3, 4, 0, 5, 6]) {
          if (oc >= tg) break;
          for (const dy of wk) {
            if (dy.dow !== wD || newGrid[ec][dy.d] !== "W") continue;
            newGrid[ec][dy.d] = "O"; W[dy.d].currentOff++; oc++;
            break;
          }
        }
      });
    });

    // PHASE 15 — balancing pass. Even out same-DOW off-totals across the cycle.
    for (let balIter = 0; balIter < 6; balIter++) {
      let changed = false;
      const byDow = {};
      days.forEach(d => { (byDow[d.dow] = byDow[d.dow] || []).push(d); });
      for (const dow of [1, 2, 3, 4]) {
        const ds = byDow[dow] || [];
        if (ds.length < 2) continue;
        ds.sort((u, v) => W[v.d].currentOff - W[u.d].currentOff);
        const heavy = ds[0], light = ds[ds.length - 1];
        const gap = W[heavy.d].currentOff - W[light.d].currentOff;
        if (gap <= 2) continue;
        for (const tech of sortedTechs) {
          if (newGrid[tech.ec][heavy.d] !== "O") continue;
          if (newGrid[tech.ec][light.d] !== "W") continue;
          newGrid[tech.ec][heavy.d] = "W";
          newGrid[tech.ec][light.d] = "O";
          let ok = true, run = 0;
          for (const d of days) {
            const v = newGrid[tech.ec][d.d];
            if (v === "W" || v === "WE" || v === "WB" || v === "WM" || v === "WL" || v === "E") { run++; if (run >= 7) { ok = false; break; } } else run = 0;
          }
          if (!ok) {
            newGrid[tech.ec][heavy.d] = "O"; newGrid[tech.ec][light.d] = "W";
            continue;
          }
          const wkHeavy = dayToWk.get(heavy.d), wkLight = dayToWk.get(light.d);
          // Use techWkOffs so cross-month carry is included for the leading
          // partial week — the strict 2-cap must hold even when balancing.
          const heavyOffs = techWkOffs(tech.ec, wkHeavy);
          const lightOffs = techWkOffs(tech.ec, wkLight);
          const heavyQuota = techTarget(tech.ec, wkHeavy);
          const lightQuota = techTarget(tech.ec, wkLight);
          // Strict cross-month guard: if light is a partial week with
          // cross-month carry (leading or trailing) and would now exceed
          // 2 offs (in-period + carry), revert.
          const lightHardCap = isCarryWeek(wkLight) ? 2 : (lightQuota + 1);
          if (heavyOffs < heavyQuota || lightOffs > lightHardCap) {
            newGrid[tech.ec][heavy.d] = "O"; newGrid[tech.ec][light.d] = "W";
            continue;
          }
          W[heavy.d].currentOff--; W[light.d].currentOff++;
          changed = true;
          break;
        }
      }
      if (!changed) break;
    }

    // PHASE 16 — additional safety pass for max-6-consecutive (mid-streak insertion).
    for (let safIter = 0; safIter < 10; safIter++) {
      let fixedAny = false;
      for (const tech of sortedTechs) {
        const ec = tech.ec;
        let run = 0, runStart = -1;
        const runs = [];
        for (let i = 0; i < days.length; i++) {
          const v = newGrid[ec][days[i].d];
          if (v === "W" || v === "WE" || v === "WB" || v === "WM" || v === "WL" || v === "E") {
            if (run === 0) runStart = i;
            run++;
          } else {
            if (run >= 7) runs.push({ start: runStart, len: run });
            run = 0; runStart = -1;
          }
        }
        if (run >= 7) runs.push({ start: runStart, len: run });
        if (runs.length === 0) continue;
        let broke = false;
        for (const ri of runs) {
          if (broke) break;
          for (let ki = ri.start + 1; ki < ri.start + ri.len - 1 && !broke; ki++) {
            const newOffD = days[ki];
            if (newOffD.dow === 0) continue;
            for (let j = 0; j < days.length; j++) {
              if (j >= ri.start && j < ri.start + ri.len) continue;
              const cd = days[j];
              if (newGrid[ec][cd.d] !== "O" || cd.dow === 0) continue;
              newGrid[ec][newOffD.d] = "O"; newGrid[ec][cd.d] = "W";
              let ok = true, r2 = 0;
              for (const dd2 of days) {
                const v = newGrid[ec][dd2.d];
                if (v === "W" || v === "WE" || v === "WB" || v === "WM" || v === "WL" || v === "E") { r2++; if (r2 >= 7) { ok = false; break; } } else r2 = 0;
              }
              // Cross-month strict 2-cap: if newOffD lands in a partial
              // week with cross-month carry (leading or trailing) and
              // the tech now exceeds 2 for that Mon-Sun week
              // (carry + in-period), revert.
              const newWk = dayToWk.get(newOffD.d);
              if (ok && isCarryWeek(newWk) && techWkOffs(ec, newWk) > 2) ok = false;
              if (ok) {
                W[newOffD.d].currentOff++; W[cd.d].currentOff--;
                fixedAny = true; broke = true;
                break;
              } else {
                newGrid[ec][newOffD.d] = "W"; newGrid[ec][cd.d] = "O";
              }
            }
          }
        }
        if (fixedAny) break;
      }
      if (!fixedAny) break;
    }

    // PHASE 17 — Late-shift assignment per store.
    //   Table Bay: designate up to 3 working techs per non-Sunday as "WL"
    //              (work late). Existing rule, unchanged.
    //   Sandown:   split working techs 50/50 each non-Sunday between
    //              "WE" (work early, 08:00–17:30) and "WL" (work late,
    //              11:00–20:00). Both cells render green; the WE/WL text
    //              labels who is on which shift. With an odd headcount,
    //              WE gets the extra (more morning coverage).
    //   Fourways / Mall of the South / Ballito:
    //              designate up to 4 working techs per non-Sunday as "WL"
    //              (aim for 4, accept 3 if only 3 are working). Sundays
    //              are left as plain "W" so everyone works the same
    //              single shift — per HR's request for these stores.
    // Distribution uses a per-tech `lateShiftCount` so the same techs
    // don't always end up on the late shift.
    const lateShiftCount = {};
    if (branch === "Table Bay") {
      sortedTechs.forEach(s => { lateShiftCount[s.ec] = 0; });
      days.forEach(dy => {
        if (dy.dow === 0) return;
        const workers = sortedTechs.filter(s => newGrid[s.ec][dy.d] === "W");
        workers.sort((a, b) =>
          (lateShiftCount[a.ec] - lateShiftCount[b.ec]) ||
          a.ec.localeCompare(b.ec)
        );
        const need = Math.min(3, workers.length);
        for (let i = 0; i < need; i++) {
          newGrid[workers[i].ec][dy.d] = "WL";
          lateShiftCount[workers[i].ec]++;
        }
      });
    } else if (branch === "Sandown") {
      sortedTechs.forEach(s => { lateShiftCount[s.ec] = 0; });
      days.forEach(dy => {
        if (dy.dow === 0) return;
        const workers = sortedTechs.filter(s => newGrid[s.ec][dy.d] === "W");
        // Sort so techs who've been on late shift least often go to WL
        // first — keeps the late shift fairly rotated across the cycle.
        workers.sort((a, b) =>
          (lateShiftCount[a.ec] - lateShiftCount[b.ec]) ||
          a.ec.localeCompare(b.ec)
        );
        const lateCount = Math.floor(workers.length / 2);
        for (let i = 0; i < workers.length; i++) {
          const code = i < lateCount ? "WL" : "WE";
          newGrid[workers[i].ec][dy.d] = code;
          if (code === "WL") lateShiftCount[workers[i].ec]++;
        }
      });
    } else if (branch === "Fourways") {
      // Fourways: 4 late workers Mon–Sat, 2-3 late on Sundays (Sunday is
      // still a trading day with extended hours per HR). The Sunday count
      // alternates between 2 and 3 by Sunday-date parity so consecutive
      // Sundays don't sit at the same staffing level. Falls back to fewer
      // when there aren't enough techs scheduled to work that day.
      // Mall of the South and Ballito share the Mon–Sat-only variant below.
      sortedTechs.forEach(s => { lateShiftCount[s.ec] = 0; });
      days.forEach(dy => {
        const workers = sortedTechs.filter(s => newGrid[s.ec][dy.d] === "W");
        workers.sort((a, b) =>
          (lateShiftCount[a.ec] - lateShiftCount[b.ec]) ||
          a.ec.localeCompare(b.ec)
        );
        const cap = dy.dow === 0 ? (sundayDateParity(dy.d) === "A" ? 3 : 2) : 4;
        const need = Math.min(cap, workers.length);
        for (let i = 0; i < need; i++) {
          newGrid[workers[i].ec][dy.d] = "WL";
          lateShiftCount[workers[i].ec]++;
        }
      });
    } else if (branch === "Mall of the South" || branch === "Ballito") {
      // 4 late workers per non-Sunday, fall back to whatever's available
      // if fewer techs are working. Sundays untouched → everyone stays on
      // plain "W" (single shift).
      sortedTechs.forEach(s => { lateShiftCount[s.ec] = 0; });
      days.forEach(dy => {
        if (dy.dow === 0) return;
        const workers = sortedTechs.filter(s => newGrid[s.ec][dy.d] === "W");
        workers.sort((a, b) =>
          (lateShiftCount[a.ec] - lateShiftCount[b.ec]) ||
          a.ec.localeCompare(b.ec)
        );
        const need = Math.min(4, workers.length);
        for (let i = 0; i < need; i++) {
          newGrid[workers[i].ec][dy.d] = "WL";
          lateShiftCount[workers[i].ec]++;
        }
      });
    } else if (branch === "Riverlands") {
      // Riverlands works a tighter cadence: 3 late workers per weekday
      // (Mon–Fri only). Saturday and Sunday everyone stays on plain "W"
      // — the store runs a single shift on weekends.
      sortedTechs.forEach(s => { lateShiftCount[s.ec] = 0; });
      days.forEach(dy => {
        if (dy.dow === 0 || dy.dow === 6) return;
        const workers = sortedTechs.filter(s => newGrid[s.ec][dy.d] === "W");
        workers.sort((a, b) =>
          (lateShiftCount[a.ec] - lateShiftCount[b.ec]) ||
          a.ec.localeCompare(b.ec)
        );
        const need = Math.min(3, workers.length);
        for (let i = 0; i < need; i++) {
          newGrid[workers[i].ec][dy.d] = "WL";
          lateShiftCount[workers[i].ec]++;
        }
      });
    }

    // PHASE 18 — Onboarding & offboarding ghost cells.
    // Days BEFORE a tech's start date (onboarding) → "X" (pre-start marker).
    // Days AFTER a tech's left date (offboarding) → "X" (post-departure).
    sortedTechs.forEach(s => {
      const startDate = s.startDate || s._startDate;
      if (s._onboarding && startDate) {
        days.forEach(d => {
          const ymd = d.year + "-" + String(d.monthIdx + 1).padStart(2, "0") + "-" + String(d.d).padStart(2, "0");
          if (ymd < startDate) newGrid[s.ec][d.d] = "X";
        });
      }
      if (s.leftDate) {
        days.forEach(d => {
          const ymd = d.year + "-" + String(d.monthIdx + 1).padStart(2, "0") + "-" + String(d.d).padStart(2, "0");
          if (ymd > s.leftDate) newGrid[s.ec][d.d] = "X";
        });
      }
    });

    // Full-cycle maternity staff: mark every day as L (Leave). They were
    // excluded from the algorithm above. (Mid-cycle mat techs are handled by
    // the ML overlay at the very end of this function — they keep real working
    // days up to their start date.)
    onMatTechs.forEach(t => {
      newGrid[t.ec] = newGrid[t.ec] || {};
      days.forEach(d => { newGrid[t.ec][d.d] = "L"; });
    });
    // Full-cycle legal-leave staff: same treatment — every day Leave. The cell
    // render overlays these as unpaid emergency leave (EL); maternity already
    // claimed anyone on both, so there's no overlap here.
    onLegalTechs.forEach(t => {
      newGrid[t.ec] = newGrid[t.ec] || {};
      days.forEach(d => { newGrid[t.ec][d.d] = "L"; });
    });

    // Annual-leave stamping — for any tech who is still employed (active
    // row in the grid) and has a leave record on the calendar that
    // overlaps the cycle, stamp those days as L right here in the auto-
    // fill so the schedule reflects the calendar without waiting for the
    // post-render auto-stamp effect (which doesn't re-fire after a fresh
    // auto-fill resets the grid). Ghost (X) cells are preserved so that
    // post-leftDate days don't get overwritten with L.
    if (leaveRecs && leaveRecs.length > 0) {
      const branchEcs = new Set(allStaff.filter(s => _schedBranchOf(s) === branch).map(s => s.ec));
      for (const lv of leaveRecs) {
        if (!lv || !lv.ec || !lv.startDate || !lv.endDate) continue;
        if (!branchEcs.has(lv.ec)) continue;
        if (!newGrid[lv.ec]) continue;
        const sd = new Date(lv.startDate + "T00:00:00");
        const ed = new Date(lv.endDate + "T00:00:00");
        if (isNaN(sd.getTime()) || isNaN(ed.getTime())) continue;
        for (const d of days) {
          const dt = new Date(d.year, d.monthIdx, d.d);
          if (dt < sd || dt > ed) continue;
          if (newGrid[lv.ec][d.d] === "X") continue;     // preserve ghost cells
          newGrid[lv.ec][d.d] = "L";
        }
      }
    }

    // ── Rescue pass for requests skipped by the 2-cap pre-pass ────────────
    // For each unhonoured-because-of-week-cap request, try a same-week swap:
    // turn an existing O (in the SAME Mon-Sun week, not Sunday) into W and
    // stamp the request day as R. The week's total off-count stays at 2,
    // so the per-week rule is preserved. We only accept the swap if it
    // doesn't violate any other hard rule:
    //   • capacity on the day made W (working ≤ stations)
    //   • min-coverage on the day made R (working ≥ minWorkingFor)
    //   • max-6-consecutive working days for that tech across the period
    // If no valid swap exists, the request stays unhonoured.
    const stillUnhonoured = [];
    const liveStreak7 = (ec) => {
      let run = 0;
      for (const dd of days) {
        const v = newGrid[ec][dd.d];
        if (v === "W" || v === "WE" || v === "WB" || v === "WM" || v === "WL" || v === "E") { run++; if (run >= 7) return true; }
        else run = 0;
      }
      return false;
    };
    const dayWorking = (dnum) => sortedTechs.reduce((n, s) => {
      const v = newGrid[s.ec][dnum]; return n + ((v === "W" || v === "WE" || v === "WB" || v === "WM" || v === "WL" || v === "E") ? 1 : 0);
    }, 0);
    unhonouredList.forEach(u => {
      // Only attempt rescue for the week-cap reason; other reasons (leave,
      // ghost, outside cycle, not-in-roster) can't be rescued by swapping.
      if (!u.reason || u.reason.indexOf("would put") !== 0) {
        stillUnhonoured.push(u); return;
      }
      const ec = u.ec;
      if (!newGrid[ec]) { stillUnhonoured.push(u); return; }
      const wIdx = dayToWeekIdx.get(u.dayNum);
      if (wIdx == null) { stillUnhonoured.push(u); return; }
      const wk = weeks[wIdx];
      const dDay = days.find(x => x.d === u.dayNum);
      if (!dDay) { stillUnhonoured.push(u); return; }
      // Min-coverage on the request day after R: working drops by 1.
      const reqDayMin = minWorkingFor(dDay);
      const reqDayWorkingAfter = dayWorking(u.dayNum) - ((newGrid[ec][u.dayNum] === "W" || newGrid[ec][u.dayNum] === "WE" || newGrid[ec][u.dayNum] === "WL" || newGrid[ec][u.dayNum] === "E") ? 1 : 0);
      if (reqDayWorkingAfter < reqDayMin) {
        u.reason = "would drop coverage on " + (u.date || u.dayNum) + " below the minimum (" + reqDayWorkingAfter + " < " + reqDayMin + ")";
        stillUnhonoured.push(u); return;
      }
      // Find an O in the same week (not Sunday, not the request day).
      const offCells = wk.filter(d =>
        d.d !== u.dayNum && d.dow !== 0 && newGrid[ec][d.d] === "O"
      );
      let swapped = false;
      for (const cand of offCells) {
        // Capacity check on cand if it becomes W
        const candWorkingAfter = dayWorking(cand.d) + 1;
        if (candWorkingAfter > capacity) continue;
        // Try the swap
        const origCand = newGrid[ec][cand.d];
        const origReq = newGrid[ec][u.dayNum];
        newGrid[ec][cand.d] = "W";
        newGrid[ec][u.dayNum] = "R";
        if (liveStreak7(ec)) {
          newGrid[ec][cand.d] = origCand;
          newGrid[ec][u.dayNum] = origReq;
          continue;
        }
        swapped = true;
        break;
      }
      if (!swapped) {
        // Sharpen the reason: nothing to swap with.
        if (offCells.length === 0) {
          u.reason = "no swappable off-day in the same Mon-Sun week (only Sundays / leave / requests in that week)";
        }
        stillUnhonoured.push(u);
      }
    });

    // ── Closed-day branches: enforce the "off-days ONLY on closed DOWs" rule
    // User rule for Betty (closedDow: [0, 1]): nail-tech off-days can ONLY
    // fall on Sun or Mon — never Tue-Sat. The various autoFill phases above
    // place O on other weekdays when they think a tech needs more rest or
    // when coverage exceeds capacity. Sweep those back to W so the final
    // schedule respects the rule, regardless of which phase placed them.
    // Sunday cells stay untouched (the first-Sunday week intentionally
    // leaves Sun blank → loaned out → set to W here).
    if (_closedDow.length > 0) {
      const _closedDowSetFinal = new Set(_closedDow);
      for (const ec of Object.keys(newGrid)) {
        for (const d of days) {
          if (_closedDowSetFinal.has(d.dow)) continue;
          if (newGrid[ec][d.d] === "O") newGrid[ec][d.d] = "W";
        }
      }
    }

    // Mid-cycle maternity overlay — runs LAST so nothing overwrites it. For
    // any tech whose maternity starts partway through this cycle, stamp 'ML'
    // on every day on/after the start date; days before it keep the real
    // shift the generator just assigned. (Full-cycle mat techs were already
    // filled above.) A returner (status flipped to "returned") has the window
    // bounded by untilYmd — their return date — so ML covers only the days
    // BEFORE they're back and real shifts from the return date stay.
    techs.forEach(t => {
      const w = matWin[t.ec];
      if (!w || w.full || !w.fromYmd) return;
      newGrid[t.ec] = newGrid[t.ec] || {};
      days.forEach(d => {
        const dy = d.year + "-" + String(d.monthIdx + 1).padStart(2, "0") + "-" + String(d.d).padStart(2, "0");
        if (dy >= w.fromYmd && (!w.untilYmd || dy < w.untilYmd)) newGrid[t.ec][d.d] = "ML";
      });
    });
    // Mid-cycle legal-leave overlay — same idea, stamping plain 'L' (the cell
    // render paints it as unpaid emergency leave). Maternity already owns any
    // overlapping day (its overlay ran just above and we skip ML cells here).
    techs.forEach(t => {
      const w = legalWin[t.ec];
      if (!w || w.full || !w.fromYmd) return;
      newGrid[t.ec] = newGrid[t.ec] || {};
      days.forEach(d => {
        const dy = d.year + "-" + String(d.monthIdx + 1).padStart(2, "0") + "-" + String(d.d).padStart(2, "0");
        if (dy >= w.fromYmd && (!w.untilYmd || dy < w.untilYmd) && newGrid[t.ec][d.d] !== "ML") newGrid[t.ec][d.d] = "L";
      });
    });

    // Re-apply approved extra days (E) — runs LAST, like the overlays above. A
    // full regenerate wipes the grid, and UNLIKE leave/maternity nothing else
    // restores approved extra-day requests onto a fresh grid. Without this an
    // approved extra day silently vanishes from the roster after a regenerate:
    // the tech then shows "Off" on My BOA / kiosk and may not come in (this bit
    // a Kuils River tech on 2026-06-28). Mirrors applyExtraDayToSchedule's "E".
    // Never overrides a leave / maternity / ghost cell. Fails safe — on any
    // load error nothing is stamped and behaviour is exactly as before.
    try {
      const approvedExtras = (window.BOA_DB && window.BOA_DB.loadExtraDayRequests)
        ? (await window.BOA_DB.loadExtraDayRequests()) : [];
      const KEEP_EXTRA = { ML: 1, L: 1, X: 1 };
      (approvedExtras || []).forEach(r => {
        if (!r || r.status !== "approved" || !r.ec || !r.work_date) return;
        if (String(r.store || "").trim() !== branch) return;             // belongs to another store
        const wd = String(r.work_date).slice(0, 10);
        const day = days.find(d => (d.year + "-" + String(d.monthIdx + 1).padStart(2, "0") + "-" + String(d.d).padStart(2, "0")) === wd);
        if (!day) return;                                                // not in this cycle's days
        const ecKey = Object.keys(newGrid).find(k => String(k).trim().toUpperCase() === String(r.ec).trim().toUpperCase());
        if (!ecKey) return;                                              // tech not on this branch's roster
        if (KEEP_EXTRA[newGrid[ecKey][day.d]]) return;                   // don't clobber leave / maternity / ghost
        newGrid[ecKey][day.d] = "E";
      });
    } catch (e) { console.warn("autoFill: re-stamp approved extra days failed (continuing):", e); }

    setGrid(newGrid);
    setDirty(true);
    setUnhonouredRequests(stillUnhonoured);

    // ── Betty: auto-create first-Sunday cross-store loan records ─────────
    // Half of the active techs (alphabetical by EC) go to Bree, the other
    // half go to Green Point. Pre-existing auto-loans (fromBranch=Betty
    // → Bree/Green Point) for that date are replaced; any other loans
    // for the same tech/date are left alone.
    if (_closedDow.includes(0) && onTechLoansChange) {
      const _firstSun = days.find(d => d.dow === 0);
      if (_firstSun && sortedTechs.length > 0) {
        const _firstSunYmd = _firstSun.year + "-" + String(_firstSun.monthIdx + 1).padStart(2, "0") + "-" + String(_firstSun.d).padStart(2, "0");
        const _activeAlpha = [...sortedTechs].sort((a, b) => (a.ec || "").localeCompare(b.ec || ""));
        const _half = Math.ceil(_activeAlpha.length / 2);
        const _assignFor = (idx) => idx < _half ? "Bree" : "Green Point";
        const _existing = (techLoans || []).filter(l => !(l && l.date === _firstSunYmd && l.fromBranch === branch && (l.toBranch === "Bree" || l.toBranch === "Green Point")));
        const _newAuto = _activeAlpha.map((s, idx) => ({
          _id: "ln_betty_auto_" + _firstSunYmd + "_" + s.ec,
          ec: s.ec,
          name: s.name || "",
          date: _firstSunYmd,
          fromBranch: branch,
          toBranch: _assignFor(idx),
          note: "Auto: Betty first-Sunday cross-store rotation",
          createdBy: "auto",
          createdAt: new Date().toISOString()
        }));
        try { await onTechLoansChange([..._existing, ..._newAuto]); }
        catch (e) { console.error("Betty auto-loans:", e); }
      }
    }

    const totalReqs = consolidatedReqs.length;
    const honouredReqs = totalReqs - stillUnhonoured.length;
    const skippedNote = stillUnhonoured.length > 0
      ? " — " + stillUnhonoured.length + " skipped (see warning above the grid)"
      : "";
    alert(
      "Schedule auto-filled.\n\n" +
      "• Total staff: " + totalStaff + "  (Group A: " + sortedTechs.filter(s => sundayGroup[s.ec] === 'A').length +
      ", Group B: " + sortedTechs.filter(s => sundayGroup[s.ec] === 'B').length + ")\n" +
      "• Weeks in period: " + weeks.length + "  (busy weeks: " + busyWeekIndices.length +
      (isLeadingPartial ? ", leading partial carries from prior month" : "") +
      (isTrailingPartial ? ", trailing partial reserves a slot for next month's leading partial" : "") + ")\n" +
      "• Day-requests: " + honouredReqs + " of " + totalReqs + " honoured" + skippedNote + "\n" +
      "• Station cap: " + capacity + " techs/day  (Mani " + (salon.mani || 0) + " + Pedi " + (salon.pedi || 0) + ")\n" +
      "• Max-6-consecutive: " + (totalSwaps > 0 ? totalSwaps + " off-days shifted to comply" : "no shifts needed") +
      (unresolved > 0 ? " — ⚠ " + unresolved + " unresolved" : "") + "\n\n" +
      "Review the grid + summary table below, then click Save."
    );
  }
  // Build the column / row payload shared by the CSV and PDF exports.
  function buildExportPayload(opts) {
    opts = opts || {};
    // sourceGrid lets callers print a different snapshot (e.g. the
    // last approved/published version) without mutating editor state.
    // Falls back to the live working grid.
    const sourceGrid = opts.sourceGrid || grid;
    const sourceSavedAt = opts.savedAt || savedAt;
    const titleSuffix = opts.titleSuffix || "";
    const subtitleSuffix = opts.subtitleSuffix || "";
    const filenameSuffix = opts.filenameSuffix || "";
    const monthAbbr = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    const dowAbbr = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
    const cellInfo = {
      W: { text: "W", bg: "#dcfce7", fg: "#14532d" },
      WE: { text: "WE", bg: "#a7f3d0", fg: "#064e3b" },
      WL: { text: "WL", bg: "#86efac", fg: "#14532d" },
      O: { text: "OFF", bg: "#fee2e2", fg: "#991b1b" },
      R: { text: "REQ", bg: "#fca5a5", fg: "#7f1d1d" },
      L: { text: "LV", bg: "#cbd5e1", fg: "#475569" },
      E: { text: "EXT", bg: "#6ee7b7", fg: "#064e3b" },
      X: { text: "—", bg: "#f3f4f6", fg: "#9ca3af" }
    };
    const columns = days.map(d => ({
      key: d.year + "-" + String(d.monthIdx + 1).padStart(2, "0") + "-" + String(d.d).padStart(2, "0"),
      label: d.d + " " + monthAbbr[d.monthIdx],
      sub: dowAbbr[d.dow],
      day: d.d,
      dow: d.dow,
      year: d.year,
      monthIdx: d.monthIdx
    }));
    const rows = techs.filter(t => {
      // Direction-aware transfer filter. Two cases on the source branch:
      //   • OUTGOING (t.transferring && transferTo !== branch): tech is
      //     leaving us. If transferDate is before this period's start,
      //     they're already gone — hide from this branch's PDF.
      //   • INCOMING (t.isShadow with transferFrom === some other store,
      //     OR an arriving shadow whose transferTo === branch): they're
      //     joining us. Always keep them on the destination PDF — the
      //     transferDate filter from above would wrongly exclude
      //     arrivals before the cycle start (they're already here).
      if (t.transferring && t.transferTo && t.transferTo !== branch && t.transferDate && _periodStartYmdForTechs) {
        if (t.transferDate < _periodStartYmdForTechs) return false;
      }
      return true;
    }).map(t => {
      const cells = {};
      const row = sourceGrid[t.ec] || {};
      // Direction-aware cell blanking, mirrors the schedule editor:
      //   • Outgoing transfer (original record, transferTo !== branch):
      //     cells on/after transferDate are blank — tech is at the new
      //     branch from that day.
      //   • Incoming transfer (shadow arrival, transferTo === branch):
      //     cells BEFORE transferDate are blank — tech is at the
      //     source branch up to that day.
      const _xferDate = t.transferring && t.transferDate ? t.transferDate : null;
      const _outgoing = !!_xferDate && !t.isShadow && t.transferTo && t.transferTo !== branch;
      const _incoming = !!_xferDate && t.isShadow && t.transferTo === branch;
      columns.forEach(c => {
        if (_outgoing && c.key >= _xferDate) {
          cells[c.key] = { code: "", text: "" };
          return;
        }
        if (_incoming && c.key < _xferDate) {
          cells[c.key] = { code: "", text: "" };
          return;
        }
        const code = row[c.day] || "";
        const info = cellInfo[code];
        cells[c.key] = { code, text: info ? info.text : "" };
      });
      const _xferSub = _outgoing
        ? ("Transferring to " + (t.transferTo || "—") + " on " + _xferDate)
        : _incoming
          ? ("Arriving from " + (t.transferFrom || "—") + " on " + _xferDate)
          : null;
      return {
        ec: t.ec,
        name: t.name,
        sub: _xferSub || (t.onMat ? "On maternity leave" : "Nail tech"),
        cells
      };
    });
    // Working-total counts honour the same direction-aware rules so
    // the bottom row reflects who is actually here on each day.
    const totals = columns.map(c => {
      let w = 0;
      techs.forEach(t => {
        // Skip outgoing transfers fully gone before this period.
        if (t.transferring && t.transferTo && t.transferTo !== branch && t.transferDate && _periodStartYmdForTechs && t.transferDate < _periodStartYmdForTechs) return;
        const _xferDate = t.transferring && t.transferDate ? t.transferDate : null;
        const _outgoing = !!_xferDate && !t.isShadow && t.transferTo && t.transferTo !== branch;
        const _incoming = !!_xferDate && t.isShadow && t.transferTo === branch;
        if (_outgoing && c.key >= _xferDate) return;
        if (_incoming && c.key < _xferDate) return;
        const v = (sourceGrid[t.ec] || {})[c.day];
        if (v === "W" || v === "WE" || v === "WB" || v === "WM" || v === "WL" || v === "E") w++;
      });
      return { key: c.key, value: w };
    });
    const codeStyles = {};
    Object.keys(cellInfo).forEach(k => { codeStyles[k] = { bg: cellInfo[k].bg, fg: cellInfo[k].fg }; });
    const legend = [
      { code: "W", text: "W", label: "Working" },
      { code: "WE", text: "WE", label: "Working early shift" },
      { code: "WL", text: "WL", label: "Working late shift" },
      { code: "O", text: "OFF", label: "Off" },
      { code: "R", text: "REQ", label: "Requested off" },
      { code: "L", text: "LV", label: "Leave" },
      { code: "E", text: "EXT", label: "Extra off" },
      { code: "X", text: "—", label: "Not scheduled" }
    ];
    return {
      title: "BOA Nail Tech Schedule — " + branch + titleSuffix,
      subtitle: periodLbl + (sourceSavedAt ? " · saved " + new Date(sourceSavedAt).toLocaleString("en-ZA") : "") + subtitleSuffix,
      filenameBase: "BOA_tech_schedule_" + branch + "_" + ym + filenameSuffix,
      columns, rows, totals, legend, codeStyles
    };
  }
  function downloadCsv() {
    if (dirty) {
      if (!confirm("You have unsaved changes — they won't appear in the saved version. Download the current view anyway?")) return;
    } else if (!savedAt && Object.keys(grid).length === 0) {
      alert("Nothing to download — generate or save a schedule first.");
      return;
    }
    exportScheduleCsv(buildExportPayload());
  }
  // PDF: roster = whatever is on the live schedule right now (so techs
  // transferring in/out, new joiners and people leaving show up just
  // like they do in the editor). Cell DATA prefers the last approved
  // + published snapshot — that's the "official" schedule HR signed
  // off on. For techs whose EC isn't in the approved snapshot (they
  // joined / transferred in after approval), we fall back to their
  // live cells so the row isn't blank.
  async function downloadPdf() {
    let approved = null;
    try {
      const list = await window.BOA_DB.loadApprovedSchedules(branch, ym, false);
      approved = Array.isArray(list) && list.length > 0 ? list[0] : null;
    } catch (e) {
      alert("Could not load the approved schedule: " + (e.message || e));
      return;
    }
    if (!approved) {
      if (!savedAt && Object.keys(grid).length === 0) {
        alert("Nothing to download — no approved version has been published yet, and the editor is empty. Generate, save, then click 📌 Approve & Publish first.");
        return;
      }
      const proceed = confirm("No approved version has been published yet for " + branch + " · " + periodLbl + ".\n\nClick OK to download the current editor view (marked as DRAFT), or Cancel to go back and Approve & Publish first.");
      if (!proceed) return;
      exportSchedulePdf(buildExportPayload({
        titleSuffix: " (DRAFT)",
        subtitleSuffix: " · DRAFT — not yet approved",
        filenameSuffix: "_DRAFT"
      }));
      return;
    }
    // Merge: approved cells win per EC; ECs only present in the live
    // grid (e.g. a tech who transferred in after approval) keep their
    // live cells so the PDF still shows them rostered.
    const mergedGrid = {};
    techs.forEach(t => {
      const ec = t.ec;
      if (approved.grid && approved.grid[ec] && Object.keys(approved.grid[ec]).length > 0) {
        mergedGrid[ec] = approved.grid[ec];
      } else {
        mergedGrid[ec] = grid[ec] || {};
      }
    });
    const approvedLabel = (approved.name || "Approved") +
      (approved.approvedBy ? " · approved by " + approved.approvedBy : "") +
      (approved.savedAt ? " · " + new Date(approved.savedAt).toLocaleString("en-ZA") : "");
    exportSchedulePdf(buildExportPayload({
      sourceGrid: mergedGrid,
      savedAt: approved.savedAt,
      subtitleSuffix: " · " + approvedLabel,
      filenameSuffix: "_approved"
    }));
  }

  async function save() {
    // Strengthened overwrite confirmation. If a saved schedule already
    // exists, surface its last-saved time and remind the manager that the
    // previous version will be backed up to history (up to 5 versions
    // kept). Skips the prompt for first-time saves.
    try {
      const existing = await window.BOA_DB.loadSchedule(branch, ym, false);
      const hasExisting = existing && existing.grid && Object.keys(existing.grid).length > 0;
      if (hasExisting) {
        const ts = existing.savedAt ? new Date(existing.savedAt).toLocaleString() : "an earlier session";
        const ok = confirm(
          "⚠ You're about to OVERWRITE the saved schedule for this period.\n\n" +
          "Last saved: " + ts + "\n\n" +
          "The current saved version will be backed up to Version History (last 5 are kept) " +
          "so you can restore it later if needed.\n\n" +
          "Click OK to overwrite, or Cancel to keep the existing schedule."
        );
        if (!ok) return;
      }
    } catch (peekErr) {
      console.warn("Could not peek existing schedule before save:", peekErr);
    }
    setSaving(true);
    try {
      const v = await window.BOA_DB.saveSchedule(branch, ym, grid, false);
      setSavedAt(v.savedAt); setDirty(false);
      if (window.BOA_LOG_ACTIVITY) {
        window.BOA_LOG_ACTIVITY("Saved tech schedule", branch + " · " + ym, "");
      }
    } catch (e) { alert("Could not save: " + (e.message || e)); }
    finally { setSaving(false); }
  }

  // Save a named "final version" snapshot of the current grid alongside
  // who made it + who approved it. Stored in app_state under
  // boa_schedapproved_<branch>_<ym> via window.BOA_DB.saveApprovedSchedule.
  // Refresh the saved-versions list whenever the (branch, ym) the user
  // is looking at changes.
  useEffect(() => {
    let cancelled = false;
    (async () => {
      if (!window.BOA_DB || !window.BOA_DB.loadApprovedSchedules) { setVersions([]); return; }
      try {
        const list = await window.BOA_DB.loadApprovedSchedules(branch, ym, false);
        if (!cancelled) setVersions(list || []);
      } catch (_) { if (!cancelled) setVersions([]); }
    })();
    return () => { cancelled = true; };
  }, [branch, ym]);

  // Restore a saved version's grid into the current draft. The user still
  // has to click Save to persist it as the live schedule — restoring just
  // pulls the snapshot into the editable grid.
  function restoreVersion(v) {
    if (!v || !v.grid) return;
    if (dirty && !window.confirm("You have unsaved changes in the current grid. Restore version \"" + v.name + "\" and discard those edits?")) return;
    if (!dirty && !window.confirm("Restore version \"" + v.name + "\" into the editor? (Click Save afterwards to make it the live schedule.)")) return;
    setGrid(JSON.parse(JSON.stringify(v.grid)));
    setDirty(true);
    setVersionsOpen(false);
    if (window.BOA_LOG_ACTIVITY) {
      window.BOA_LOG_ACTIVITY("Restored final tech schedule version", branch + " · " + ym + " · " + v.name,
        "Loaded snapshot saved " + new Date(v.savedAt).toLocaleString("en-ZA"), "Schedule");
    }
  }

  async function deleteVersion(v) {
    if (!v) return;
    if (!window.confirm("Delete saved version \"" + v.name + "\"?\n\nThis cannot be undone.")) return;
    try {
      const next = await window.BOA_DB.deleteApprovedSchedule(branch, ym, false, v.id);
      setVersions(next || []);
      if (window.BOA_LOG_ACTIVITY) {
        window.BOA_LOG_ACTIVITY("Deleted final tech schedule version", branch + " · " + ym + " · " + v.name,
          "Made by " + (v.madeBy || "—") + " · approved by " + (v.approvedBy || "—"), "Schedule");
      }
    } catch (e) { alert("Could not delete: " + (e.message || e)); }
  }

  async function saveFinalVersion() {
    // Visible-without-DevTools diagnostic. Reports exactly which check
    // fails (API missing / empty grid / cancel / save error / persisted-
    // but-not-found) via an alert chain so we don't have to chase a
    // silent failure in the browser console.
    if (!window.BOA_DB) {
      alert("DIAG: window.BOA_DB is missing — data layer hasn't loaded. Hard-refresh the page (Cmd-Shift-R / Ctrl-Shift-F5).");
      return;
    }
    if (!window.BOA_DB.saveApprovedSchedule) {
      alert("DIAG: window.BOA_DB exists but .saveApprovedSchedule is missing — this deploy hasn't got the new code yet. Has PR #55 actually been merged into main and Netlify redeployed?");
      return;
    }
    if (!grid || Object.keys(grid).length === 0) {
      alert("Nothing to save — the schedule is empty for this period.");
      return;
    }
    // Phase 3.1: show per-person what STAFF WILL SEE change vs the live
    // published[0] before committing. Fails open — a preview error never
    // blocks the publish. (Tech snapshots carry no baked hours: code-only diff.)
    try {
      const _prevList = window.BOA_DB.loadApprovedSchedules
        ? await window.BOA_DB.loadApprovedSchedules(branch, ym, false)
        : [];
      const _prev = (_prevList && _prevList[0]) || null;
      const _diff = computePublishDiff(_prev && _prev.grid, _prev && _prev.hours, grid, null, _prev && _prev.names);
      const _proceed = await showPublishDiffDialog({ kind: "Nail tech schedule", branch, ym, diff: _diff });
      if (!_proceed) return;
    } catch (_pd) { console.error("[saveFinal] tech — publish diff preview failed (continuing):", _pd); }
    const name = window.prompt("Name this version (e.g. \"Final v1\", \"After Theresa review\"):", "");
    if (name === null) return;
    if (!name.trim()) { alert("Cancelled — a name is required."); return; }
    const madeBy = window.prompt("Who made this schedule? (manager / scheduler name)", "");
    if (madeBy === null) return;
    const approvedBy = window.prompt("Who approved it?", "");
    if (approvedBy === null) return;
    const note = window.prompt("Optional note (anything else worth recording):", "");
    if (note === null) return;
    setSaving(true);
    const ecCount = Object.keys(grid).length;
    console.log("[saveFinal] tech — saving", { branch, ym, ecCount, name: name.trim(), madeBy: madeBy.trim(), approvedBy: approvedBy.trim() });
    try {
      const u = window.BOA_CURRENT_USER || {};
      const saved = await window.BOA_DB.saveApprovedSchedule(branch, ym, false, {
        name: name.trim(),
        grid: JSON.parse(JSON.stringify(grid)),
        madeBy: madeBy.trim(),
        approvedBy: approvedBy.trim(),
        note: note.trim(),
        savedBy: u.name || ""
      });
      console.log("[saveFinal] tech — saveApprovedSchedule returned", saved);
      // Verify by listing — if the save silently failed (RLS, network) the
      // returned record won't be in the persisted list.
      const after = window.BOA_DB.loadApprovedSchedules
        ? await window.BOA_DB.loadApprovedSchedules(branch, ym, false)
        : [];
      console.log("[saveFinal] tech — list after save (" + after.length + " versions)", after);
      const persisted = saved && after.some(x => x && x.id === saved.id);
      if (!persisted) {
        alert("⚠ Save returned but the version wasn't found in storage after re-reading.\n\n" +
          "This usually means Supabase Row-Level-Security blocked the write to app_state.\n\n" +
          "Open DevTools → Console for the [saveFinal] log lines and paste them back.");
        return;
      }
      setVersions(after);
      // Save Final supersedes Save — also publish the snapshot as the live
      // schedule so the rest of the system (attendance, leave, kiosk, etc.)
      // immediately sees the approved version. Failure here is logged and
      // shown, but the archive entry already persisted.
      let publishedLive = false;
      try {
        const live = await window.BOA_DB.saveSchedule(branch, ym, grid, false);
        setSavedAt(live.savedAt); setDirty(false);
        publishedLive = true;
      } catch (publishErr) {
        console.error("[saveFinal] tech — archive saved but publish-to-live failed:", publishErr);
      }
      if (window.BOA_LOG_ACTIVITY) {
        window.BOA_LOG_ACTIVITY("Approved tech schedule", branch + " · " + ym + " · " + (saved && saved.name || name),
          "Made by " + (madeBy || "—") + " · approved by " + (approvedBy || "—") + (publishedLive ? "" : " · ⚠ archive saved but live-schedule publish failed"), "Schedule");
      }
      alert("✓ Approved + published: " + (saved.name || name) + "\n\n" +
        after.length + " final version" + (after.length === 1 ? "" : "s") + " on file for " + branch + " · " + ym +
        (publishedLive ? "" : "\n\n⚠ NOTE: the snapshot was archived but writing it to the live schedule failed. Try the regular Save button to publish."));
    } catch (e) {
      console.error("[saveFinal] tech — failed", e);
      alert("Could not save final version: " + (e.message || e) + "\n\nSee DevTools → Console for details.");
    } finally { setSaving(false); }
  }

  const monthAbbr = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  const dowAbbr = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

  function rowCounts(ec) {
    const row = grid[ec] || {};
    let w = 0, off = 0;
    days.forEach(d => {
      const v = row[d.d];
      if (v === "W" || v === "WE" || v === "WB" || v === "WM" || v === "WL" || v === "E") w++;
      if (v === "O" || v === "R" || v === "L") off++;
    });
    return { w, off };
  }

  // ── Conflict detection: max 2 off-days per week per staff ──────────────
  // Groups the period into Mon-Sun weeks and flags any staff who has more
  // than 2 off-days (O / R / L combined) in any single week.
  const weekChunks = useMemo(() => {
    const out = []; let cur = [];
    days.forEach(d => { cur.push(d); if (d.dow === 0) { out.push(cur); cur = []; } });
    if (cur.length) out.push(cur);
    return out;
  }, [days]);

  // Map day-number → week index, for fast same-week checks during drag-drop
  const dayWeekMap = useMemo(() => {
    const map = {};
    weekChunks.forEach((w, idx) => w.forEach(d => { map[d.d] = idx; }));
    return map;
  }, [weekChunks]);

  // Drag-and-drop handlers — swap a cell's value with another cell's value
  // within the same staff row AND the same Mon-Sun week. Click-to-cycle
  // remains available; the browser only initiates a drag on mousedown+move.
  const handleDragStart = (e, ec, day, value, isOnMat) => {
    if (isOnMat) { e.preventDefault(); return; }
    setDragSource({ ec, day, value, weekIdx: dayWeekMap[day] });
    if (e.dataTransfer) {
      e.dataTransfer.effectAllowed = "move";
      try { e.dataTransfer.setData("text/plain", ec + ":" + day); } catch (_) { }
    }
  };
  const isValidDropTarget = (ec, day) => {
    if (!dragSource) return false;
    if (dragSource.ec !== ec) return false;
    if (dragSource.day === day) return false;
    if (dayWeekMap[day] !== dragSource.weekIdx) return false;
    return true;
  };
  const handleDragOver = (e, ec, day) => {
    if (!isValidDropTarget(ec, day)) return;
    e.preventDefault();
    if (e.dataTransfer) e.dataTransfer.dropEffect = "move";
  };
  const handleDrop = (e, ec, day) => {
    e.preventDefault();
    if (!isValidDropTarget(ec, day)) { setDragSource(null); return; }
    const targetValue = (grid[ec] || {})[day] || "";
    setGrid(g => {
      const row = { ...(g[ec] || {}) };
      row[dragSource.day] = targetValue;
      row[day] = dragSource.value;
      return { ...g, [ec]: row };
    });
    setDirty(true);
    setDragSource(null);
  };
  const handleDragEnd = () => setDragSource(null);

  const monthAbbr0 = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  // Coverage / capacity helpers reused by both auto-fill and the bottom-row stats
  const salonForBranch = useMemo(() => SALONS.find(s => s.name === branch) || { capacity: 999 }, [branch]);

  // Identify busy-period weeks (full weeks containing prev-25 → cur-6)
  const ymParts = ym.split("-").map(Number);
  const isBusyDay = (d) => {
    const m = d.monthIdx + 1;
    const curMonth = ymParts[1], prevMonth = (curMonth === 1) ? 12 : curMonth - 1;
    if (m === prevMonth && d.d >= 25) return true;
    if (m === curMonth && d.d <= 6) return true;
    return false;
  };
  const dayTargetPct = (dow, busyPeriod) => {
    let base;
    if (dow === 5 || dow === 6) base = 1.00; // Fri/Sat full
    else if (dow === 4) base = 0.70; // Thu
    else if (dow === 3) base = 0.60; // Wed
    else if (dow === 2) base = 0.50; // Tue
    else if (dow === 1) base = 0.40; // Mon — fewest
    else base = 0.40; // Sun
    if (busyPeriod) base += 0.05;
    return Math.min(base, 1.0);
  };
  // Station cap = mani + pedi stations (hard physical limit).
  const stationCap = (salonForBranch.mani || 0) + (salonForBranch.pedi || 0);
  // Original uses Math.round, not ceil.
  const minWorkingFor = (d, totalStaff) => totalStaff <= 2 ? 1
    : Math.min(stationCap, Math.max(1, Math.round(dayTargetPct(d.dow, isBusyDay(d)) * totalStaff)));

  // SA public holidays for every year covered by the visible period
  const holidayLookup = useMemo(() => {
    const years = new Set(days.map(d => d.year));
    const out = {};
    years.forEach(y => Object.assign(out, saHolidays(y)));
    return out;
  }, [days]);
  const _hkey = (d) => d.year + "-" + String(d.monthIdx + 1).padStart(2, "0") + "-" + String(d.d).padStart(2, "0");
  const isHoliday = (d) => !!holidayLookup[_hkey(d)];
  const holidayName = (d) => holidayLookup[_hkey(d)] || "";

  // Trial nail techs shown as read-only YELLOW GHOST rows on the schedule.
  // They have no employee code and aren't in the saved grid, so this is a
  // pure render overlay — nothing here is ever written to boa_sched. Each
  // trial runs 10 WORKING days from its start date: Monday–Friday only,
  // skipping weekends and SA public holidays. We expose the set of trial-day
  // dates (YYYY-MM-DD) so the grid can paint just those cells.
  const trialGhostRows = useMemo(() => {
    const active = (trialList || []).filter(c =>
      c && c.branch === branch &&
      String(c.role || "nt").toLowerCase() === "nt" &&   // nail techs only (excludes AM/SM/managers, any case)
      c.status !== "passed" && !trialIsGone(c) && c.status !== "hired" &&
      c.startDate
    );
    const _pad = (n) => String(n).padStart(2, "0");
    return active.map(c => {
      // Walk forward from the start date collecting 10 Mon–Fri non-holiday
      // days. Cap the scan so a bad/edge date can never loop unbounded.
      const daySet = new Set();
      const start = new Date(c.startDate + "T12:00:00");
      let firstYmd = null, lastYmd = null;
      if (!isNaN(start)) {
        const cur = new Date(start);
        for (let guard = 0; guard < 60 && daySet.size < 10; guard++) {
          const y = cur.getFullYear(), m = cur.getMonth() + 1, dd = cur.getDate();
          const ymd = y + "-" + _pad(m) + "-" + _pad(dd);
          const dow = cur.getDay();
          const isHol = !!(saHolidays(y) || {})[ymd];
          if (dow !== 0 && dow !== 6 && !isHol) {
            daySet.add(ymd);
            if (!firstYmd) firstYmd = ymd;
            lastYmd = ymd;
          }
          cur.setDate(cur.getDate() + 1);
        }
      }
      return {
        _id: "trial-" + c._id,
        name: c.name || "Trial tech",
        _trial: true,
        _trialStartDate: c.startDate,
        _trialDaySet: daySet,
        _trialFirstYmd: firstYmd,
        _trialLastYmd: lastYmd,
        _trialStatus: c.status
      };
    });
  }, [trialList, branch]);

  // 7+ consecutive working days violations (HARD — labour law). Skip on-mat staff.
  const longStreaks = useMemo(() => {
    const out = [];
    techs.filter(t => !t.onMat).forEach(s => {
      let streak = 0, startIdx = -1;
      for (let i = 0; i < days.length; i++) {
        const v = (grid[s.ec] || {})[days[i].d];
        if (v === "W" || v === "WE" || v === "WB" || v === "WM" || v === "WL" || v === "E") {
          if (streak === 0) startIdx = i;
          streak++;
        } else {
          if (streak >= 7) {
            const a = days[startIdx], b = days[i - 1];
            out.push({
              ec: s.ec, name: s.name, count: streak,
              range: a.d + " " + ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"][a.monthIdx] + " – " + b.d + " " + ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"][b.monthIdx]
            });
          }
          streak = 0; startIdx = -1;
        }
      }
      if (streak >= 7) {
        const a = days[startIdx], b = days[days.length - 1];
        out.push({
          ec: s.ec, name: s.name, count: streak,
          range: a.d + " " + ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"][a.monthIdx] + " – " + b.d + " " + ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"][b.monthIdx]
        });
      }
    });
    return out;
  }, [grid, techs, days]);

  const tooManyOff = useMemo(() => {
    const out = [];
    techs.filter(t => !t.onMat).forEach(s => {
      const row = grid[s.ec] || {};
      weekChunks.forEach((week, wIdx) => {
        const offDays = week.filter(d => {
          const v = row[d.d];
          return v === "O" || v === "R" || v === "L";
        });
        if (offDays.length > 2) {
          const first = week[0], last = week[week.length - 1];
          out.push({
            ec: s.ec,
            name: s.name,
            weekIdx: wIdx + 1,
            range: first.d + " " + monthAbbr0[first.monthIdx] + " – " + last.d + " " + monthAbbr0[last.monthIdx],
            count: offDays.length,
            offCells: offDays.map(d => d.d + " " + monthAbbr0[d.monthIdx]).join(", ")
          });
        }
      });
    });
    return out;
  }, [grid, techs, weekChunks]);

  // ── Selective staff sync ─────────────────────────────────────────────
  // When a tech joins / leaves AFTER a schedule has been generated, we
  // don't want a full regen (manual edits would be lost). Instead we
  // surface a banner with a "Sync staff" button that adds rows for new
  // joins and cleans up rows for departures, without touching anyone
  // else's row.
  const gridHasData = useMemo(
    () => Object.keys(grid || {}).some(ec => grid[ec] && Object.keys(grid[ec]).length > 0),
    [grid]
  );
  const periodEndYmd = useMemo(() => {
    if (!days || days.length === 0) return null;
    const last = days[days.length - 1];
    return last.year + "-" + String(last.monthIdx + 1).padStart(2, "0") + "-" + String(last.d).padStart(2, "0");
  }, [days]);
  const periodStartYmd = useMemo(() => {
    if (!days || days.length === 0) return null;
    const first = days[0];
    return first.year + "-" + String(first.monthIdx + 1).padStart(2, "0") + "-" + String(first.d).padStart(2, "0");
  }, [days]);
  // Active techs that don't have a scheduled row yet — almost always new
  // joiners whose start date lands inside or just before the cycle. Excludes
  // people whose start date is AFTER the cycle ends (no working days here).
  // EC comparisons are by TRIMMED, case-folded code — a saved row whose key
  // carries formatting drift still belongs to the person (the load-time heal
  // re-keys it; this keeps the diff honest even before that runs), so she is
  // neither flagged "+ Add" nor her real row flagged stale for removal.
  const missingTechs = useMemo(() => {
    if (!gridHasData) return [];
    const _norm = (x) => String(x == null ? "" : x).trim().toUpperCase();
    const rowsByNorm = {};
    Object.keys(grid).forEach(k => { if (grid[k] && Object.keys(grid[k]).length > 0) rowsByNorm[_norm(k)] = true; });
    return techs.filter(t => {
      if (rowsByNorm[_norm(t.ec)]) return false;
      const startDate = t.startDate || t._startDate;
      if (startDate && periodEndYmd && startDate > periodEndYmd) return false;
      return true;
    });
  }, [techs, grid, gridHasData, periodEndYmd]);
  // Rows in the grid for ec's that aren't in the active techs list — usually
  // terminated staff (leftDate set) or staff who moved branches. Pair each
  // with the underlying staff record (looked up in allStaff) so syncStaff
  // can decide whether to mark X cells (leftDate within cycle) or drop the
  // row entirely (leftDate before cycle / record gone).
  const staleStaff = useMemo(() => {
    if (!gridHasData) return [];
    const _norm = (x) => String(x == null ? "" : x).trim().toUpperCase();
    const activeEcs = new Set(techs.map(t => _norm(t.ec)));
    return Object.keys(grid).filter(ec => !activeEcs.has(_norm(ec))).map(ec => ({
      ec,
      staff: allStaff.find(s => _norm(s.ec) === _norm(ec)) || null
    }));
  }, [techs, grid, allStaff, gridHasData]);

  // Per-tech mini-scheduler. Only fills cells for `tech.ec` and never
  // mutates other rows. Honours the same hard rules the bulk auto-fill
  // enforces:
  //   • startDate / leftDate ghost cells (X)
  //   • on-maternity-leave full leave (L)
  //   • Sunday A/B rotation — group inferred from existing techs to keep
  //     the per-Sunday split balanced
  //   • request days within the 2-off-per-week cap (any rejected request
  //     is returned in `unhonored` for the warning banner)
  //   • per-day station capacity — if existing techs already fill the
  //     stations on a day, this tech is forced off that day (counts as
  //     one of their 2 weekly offs)
  //   • max-6-consecutive working days (insert an off in any 7+ streak,
  //     within the 2-cap; otherwise the streak is left for manual review)
  function fillRowForTech(tech, existingGrid) {
    const ec = tech.ec;
    const row = {};
    const unhonored = [];
    const _ymd = (d) => d.year + "-" + String(d.monthIdx + 1).padStart(2, "0") + "-" + String(d.d).padStart(2, "0");
    // Maternity: a full-cycle mat blanks the whole row (Leave). A mid-cycle
    // start is scheduled normally below and gets an 'ML' overlay on/after the
    // start date just before we return — so real working days are kept.
    const _matCycStart = days.length ? _ymd(days[0]) : "";
    const _matCycEndF = days.length ? _ymd(days[days.length - 1]) : "";
    const _techMatWin = matCycleWindow(tech, _matCycStart, _matCycEndF);
    if (_techMatWin.full) {
      days.forEach(d => { row[d.d] = "L"; });
      return { row, unhonored };
    }
    const startDate = tech.startDate || tech._startDate;
    const isOnboarding = tech._onboarding && startDate;
    const leftDate = tech.leftDate;
    days.forEach(d => {
      const ymd = _ymd(d);
      if (isOnboarding && ymd < startDate) row[d.d] = "X";
      if (leftDate && ymd > leftDate) row[d.d] = "X";
    });
    // Infer Sunday A/B group counts from existing techs so the new tech
    // joins the smaller group.
    let aCount = 0, bCount = 0;
    techs.forEach(t => {
      if (t.ec === ec) return;
      const er = existingGrid[t.ec];
      if (!er) return;
      let aOffs = 0, bOffs = 0;
      weekChunks.forEach((wk) => {
        const sun = wk.find(d => d.dow === 0);
        if (!sun) return;
        const v = er[sun.d];
        if (v === "O" || v === "R") {
          // Date-anchored parity — same convention used by the bulk
          // auto-fill above, so the inference matches what the algorithm
          // would produce.
          if (sundayDateParity(sun) === "A") aOffs++;
          else bOffs++;
        }
      });
      if (aOffs > bOffs) aCount++;
      else if (bOffs > aOffs) bCount++;
    });
    const myGroup = aCount <= bCount ? "A" : "B";
    // Tech's request days within this cycle
    const myReqs = new Set();
    const reqMeta = {};                                  // dayNum → {date, note, source}
    (techRequests || []).forEach(r => {
      if (!r || r.ec !== ec) return;
      if (r.branch && r.branch !== branch) return;
      const dt = new Date(r.date + "T00:00:00");
      if (isNaN(dt.getTime())) return;
      const inP = days.some(d => d.year === dt.getFullYear() && d.monthIdx === dt.getMonth() && d.d === dt.getDate());
      if (!inP) return;
      const dn = dt.getDate();
      myReqs.add(dn);
      reqMeta[dn] = { date: r.date, note: r.note || "", source: r.source || "request" };
    });
    const capacity = (salonForBranch.mani || 0) + (salonForBranch.pedi || 0);
    // Current working count on a day from EXISTING rows (not this tech).
    const dayWorkingExisting = (dnum) => {
      let n = 0;
      Object.keys(existingGrid).forEach(otherEc => {
        if (otherEc === ec) return;
        const v = existingGrid[otherEc] && existingGrid[otherEc][dnum];
        if (v === "W" || v === "WE" || v === "WB" || v === "WM" || v === "WL" || v === "E") n++;
      });
      return n;
    };
    const weekOffCount = (wk) => wk.reduce((n, d) => {
      const v = row[d.d];
      return n + ((v === "O" || v === "R" || v === "L") ? 1 : 0);
    }, 0);

    weekChunks.forEach((wk, wIdx) => {
      const avail = wk.filter(d => row[d.d] !== "X");
      if (avail.length === 0) return;

      // Per-week off-target.
      //  - Default branches: 2 off-days (Mon-Sun rotation).
      //  - Closed-day branches (e.g. Betty closes Sun+Mon): the only
      //    off-days are the pre-seeded closed-DOW cells. So the target
      //    is exactly the count of closed-DOW days in this chunk that
      //    were pre-seeded as O. That gives:
      //      • 2 for a normal full week (Sun=O + Mon=O),
      //      • 1 for the first-Sunday week (only Mon=O; Sun is left
      //        blank because techs are loaned to Bree / Green Point),
      //      • 0 for a leading partial that doesn't include Monday
      //        (the labour week's Monday-off lives in the prior cycle).
      //    User rule: Betty staff can ONLY ever be off on Sun or Mon —
      //    deriving the target from the pre-seed stops autoFill from
      //    adding a Tue-Sat off-day under any week shape.
      const _closedDowForRow = Array.isArray(salonForBranch.closedDow) ? salonForBranch.closedDow.map(Number) : [];
      const _closedDowSet = new Set(_closedDowForRow);
      const _isClosedBranch = _closedDowSet.size > 0;
      const offTarget = _isClosedBranch
        ? wk.filter(d => _closedDowSet.has(d.dow) && row[d.d] === "O").length
        : 2;

      // Sunday rotation — date-anchored so the alternation continues
      // correctly across cycle boundaries.
      const sundayDay = avail.find(d => d.dow === 0);
      if (sundayDay && myGroup === sundayDateParity(sundayDay) && !row[sundayDay.d]) {
        row[sundayDay.d] = "O";
      }

      // Apply requested off-days first, with the per-week cap
      const reqDays = avail.filter(d => myReqs.has(d.d));
      for (const reqD of reqDays) {
        const meta = reqMeta[reqD.d] || {};
        const dt = meta.date || _ymd(reqD);
        const cur = row[reqD.d];
        if (cur === "L") {
          unhonored.push({ ec, name: tech.name, date: dt, dayNum: reqD.d, reason: "tech is on leave that day", source: meta.source, note: meta.note });
          continue;
        }
        if (cur === "X") {
          unhonored.push({ ec, name: tech.name, date: dt, dayNum: reqD.d, reason: "outside tech's employment dates", source: meta.source, note: meta.note });
          continue;
        }
        if (cur === "O") { row[reqD.d] = "R"; continue; }
        if (cur === "R") continue;
        const off = weekOffCount(wk);
        if (off >= offTarget) {
          unhonored.push({ ec, name: tech.name, date: dt, dayNum: reqD.d, reason: "would put " + (offTarget + 1) + " off-days in that Mon-Sun labour week (max " + offTarget + " allowed)", source: meta.source, note: meta.note });
          continue;
        }
        row[reqD.d] = "R";
      }

      // Top up to per-week off-target (full weeks only). Prefer Mon→Tue→Wed
      // and days where the existing schedule is already at capacity (so this
      // tech being off relieves the pressure rather than creating excess).
      if (avail.length >= 7) {
        let safety = 0;
        while (weekOffCount(wk) < offTarget && safety++ < 10) {
          const candidates = avail.filter(d => !row[d.d] && d.dow !== 0);
          if (candidates.length === 0) break;
          candidates.sort((a, b) => {
            const sc = (x) => {
              let s = 0;
              if (x.dow === 1) s += 60;
              else if (x.dow === 2) s += 40;
              else if (x.dow === 3) s += 20;
              else if (x.dow === 4) s -= 40;
              else if (x.dow === 5 || x.dow === 6) s -= 45;
              if (dayWorkingExisting(x.d) >= capacity) s += 100;
              return s;
            };
            return sc(b) - sc(a);
          });
          row[candidates[0].d] = "O";
        }
      }

      // Fill remaining cells. If a day is already at capacity in the
      // existing schedule, mark this tech off there (within per-week
      // cap); else mark them as W.
      avail.forEach(d => {
        if (row[d.d]) return;
        if (d.dow !== 0 && dayWorkingExisting(d.d) >= capacity && weekOffCount(wk) < offTarget) {
          row[d.d] = "O";
        } else {
          row[d.d] = "W";
        }
      });
    });

    // Max-6-consecutive: try to insert an off inside any 7+ streak,
    // respecting the per-week off-cap. Bail when no valid insertion exists.
    const _closedDowForStreak = Array.isArray(salonForBranch.closedDow) ? salonForBranch.closedDow.map(Number) : [];
    const _closedDowSetStreak = new Set(_closedDowForStreak);
    const _isClosedBranchStreak = _closedDowSetStreak.size > 0;
    for (let attempt = 0; attempt < 10; attempt++) {
      let run = 0, runStart = -1;
      let longestRun = 0, longestStart = -1, longestEnd = -1;
      for (let i = 0; i < days.length; i++) {
        const v = row[days[i].d];
        if (v === "W" || v === "WE" || v === "WB" || v === "WM" || v === "WL" || v === "E") {
          if (run === 0) runStart = i;
          run++;
          if (run > longestRun) { longestRun = run; longestStart = runStart; longestEnd = i; }
        } else { run = 0; }
      }
      if (longestRun < 7) break;
      let inserted = false;
      for (let ix = longestStart + 1; ix < longestEnd; ix++) {
        const d = days[ix];
        if (d.dow === 0) continue;
        if (row[d.d] !== "W" && row[d.d] !== "WE" && row[d.d] !== "WL") continue;
        const wIdx = weekChunks.findIndex(wk => wk.some(x => x.d === d.d));
        if (wIdx < 0) continue;
        // Respect the per-week off-target. Closed-day branches cap at
        // the number of closed-DOW cells in that chunk (1 in the
        // first-Sunday week, 2 in normal weeks, 0 in some partials);
        // everyone else caps at 2.
        const _wkForStreak = weekChunks[wIdx];
        const targetForThisWeek = _isClosedBranchStreak
          ? _wkForStreak.filter(d => _closedDowSetStreak.has(d.dow) && row[d.d] === "O").length
          : 2;
        if (weekOffCount(_wkForStreak) >= targetForThisWeek) continue;
        // For closed-day branches, the insertion must land on a closed
        // DOW (Sun/Mon for Betty) — never Tue-Sat. The cell is currently
        // a W (we only inserted if it's W/WL), so this guard prevents
        // adding an out-of-policy mid-week off when breaking a streak.
        if (_isClosedBranchStreak && !_closedDowSetStreak.has(d.dow)) continue;
        row[d.d] = "O";
        inserted = true;
        break;
      }
      if (!inserted) break;
    }

    // Mid-cycle maternity overlay — stamp ML on/after the start date, keeping
    // the real shifts the fill just assigned for the days before it. For a
    // returner the window is bounded by untilYmd (the return date), so ML only
    // covers the days before they're back.
    if (_techMatWin.fromYmd) {
      days.forEach(d => { const _dy = _ymd(d); if (_dy >= _techMatWin.fromYmd && (!_techMatWin.untilYmd || _dy < _techMatWin.untilYmd)) row[d.d] = "ML"; });
    }

    return { row, unhonored };
  }

  async function syncStaff() {
    const addCount = missingTechs.length;
    const staleCount = staleStaff.length;
    if (addCount === 0 && staleCount === 0) {
      alert("No staff changes to sync — every active tech already has a row, and there are no stale rows.");
      return;
    }
    const lines = [];
    if (addCount > 0) {
      lines.push("Add " + addCount + " new tech row" + (addCount === 1 ? "" : "s") + ":");
      missingTechs.forEach(t => lines.push("  + " + t.name + " (" + t.ec + ")" + (t.startDate ? " · starts " + t.startDate : "")));
    }
    if (staleCount > 0) {
      lines.push((addCount > 0 ? "\n" : "") + "Clean up " + staleCount + " stale row" + (staleCount === 1 ? "" : "s") + ":");
      staleStaff.forEach(s => {
        const sf = s.staff;
        if (sf && sf.leftDate && sf.leftDate >= (periodStartYmd || "") && sf.leftDate <= (periodEndYmd || "")) {
          lines.push("  − " + (sf.name || s.ec) + " (" + s.ec + ") · left " + sf.leftDate + " — cells after that date marked X");
        } else if (sf && sf.leftDate) {
          lines.push("  − " + (sf.name || s.ec) + " (" + s.ec + ") · left " + sf.leftDate + " — row removed");
        } else {
          lines.push("  − " + (sf ? (sf.name || s.ec) : s.ec) + " (" + s.ec + ") · no longer at this branch — row removed");
        }
      });
    }
    if (!confirm(
      "Sync staff changes?\n\n" +
      lines.join("\n") + "\n\n" +
      "Existing rows for unaffected staff will be left untouched. " +
      "New rows are filled per the schedule rules (2 off-days/week, Sunday rotation, request days where they fit). " +
      "After syncing, click Save to commit."
    )) return;

    // Snapshot the pre-sync grid so the staff sync can be rolled back.
    setUndoSnap({ grid: JSON.parse(JSON.stringify(grid || {})), label: "Sync staff" });
    const newGrid = JSON.parse(JSON.stringify(grid || {}));
    const allUnh = [];

    missingTechs.forEach(t => {
      const { row, unhonored } = fillRowForTech(t, newGrid);
      newGrid[t.ec] = row;
      allUnh.push(...unhonored);
    });

    staleStaff.forEach(s => {
      const ec = s.ec;
      const staff = s.staff;
      if (staff && staff.leftDate) {
        // Mark cells AFTER leftDate as X. Keep cells on/before leftDate
        // as-is — those days the tech actually worked.
        const _ymd = (d) => d.year + "-" + String(d.monthIdx + 1).padStart(2, "0") + "-" + String(d.d).padStart(2, "0");
        let everPre = false;
        days.forEach(d => {
          if (_ymd(d) > staff.leftDate) {
            newGrid[ec] = newGrid[ec] || {};
            newGrid[ec][d.d] = "X";
          } else {
            everPre = true;
          }
        });
        if (!everPre) delete newGrid[ec];
      } else {
        delete newGrid[ec];
      }
    });

    setGrid(newGrid);
    setDirty(true);
    setUnhonouredRequests(allUnh);

    const unhCnt = allUnh.length;
    alert(
      "Staff sync complete.\n\n" +
      (addCount > 0 ? "• Added " + addCount + " new tech row" + (addCount === 1 ? "" : "s") + " (rule-compliant fill).\n" : "") +
      (staleCount > 0 ? "• Cleaned up " + staleCount + " stale row" + (staleCount === 1 ? "" : "s") + ".\n" : "") +
      (unhCnt > 0 ? "• ⚠ " + unhCnt + " request day" + (unhCnt === 1 ? "" : "s") + " not honoured (see warning above).\n" : "") +
      "\nReview the grid, then click Save to commit."
    );
  }

  return (
    <div style={{ padding: "0 24px" }}>
      <div style={{ display: "flex", gap: 12, alignItems: "center", flexWrap: "wrap", marginBottom: 14 }}>
        <div style={{ fontFamily: "'Playfair Display',serif", fontSize: 24, fontWeight: 700, color: "#831843" }}>📅 Schedule Editor</div>
        <select value={branch} onChange={e => { if (dirty && !confirm("You have unsaved changes. Discard?")) return; setBranch(e.target.value); }}
          style={{ padding: "8px 12px", borderRadius: 9, border: "1px solid #FBCFE8", background: "#fff", fontFamily: "inherit", fontSize: 14, color: "#831843", fontWeight: 600 }}>
          {_branchOptions.map(n => <option key={n} value={n}>{n}</option>)}
        </select>
        <div style={{ display: "flex", alignItems: "center", gap: 6, background: "#fff", border: "1px solid #FBCFE8", borderRadius: 9, padding: "4px" }}>
          <button onClick={() => { if (dirty && !confirm("Discard unsaved changes?")) return; setYm(window.BOA_DB.shiftYm(ym, -1)); }} style={{ background: "none", border: "none", fontSize: 18, cursor: "pointer", color: "#BE185D", padding: "0 8px", lineHeight: 1 }}>‹</button>
          <span style={{ fontSize: 13, fontWeight: 600, color: "#831843", padding: "0 6px" }}>{periodLbl}</span>
          <button onClick={() => { if (dirty && !confirm("Discard unsaved changes?")) return; setYm(window.BOA_DB.shiftYm(ym, +1)); }} style={{ background: "none", border: "none", fontSize: 18, cursor: "pointer", color: "#BE185D", padding: "0 8px", lineHeight: 1 }}>›</button>
        </div>
        {(() => {
          const active = techs.filter(t => !t.onMat).length;
          const onMat = techs.filter(t => t.onMat).length;
          const cap = (salonForBranch.mani || 0) + (salonForBranch.pedi || 0);
          return (
            <div style={{ display: "flex", alignItems: "center", gap: 8, background: "#FFFFFF", border: "1px solid #FBCFE8", borderRadius: 9, padding: "6px 12px", fontSize: 11, color: "#831843" }}>
              <span style={{ fontWeight: 700, fontSize: 13 }}>{active}</span>
              <span style={{ color: "#9CA3AF" }}>active</span>
              {onMat > 0 && <span style={{ background: "#e5e7eb", color: "#374151", padding: "1px 6px", borderRadius: 4, fontSize: 10, fontWeight: 700 }}>+{onMat} 🤱</span>}
              <span style={{ color: "#9CA3AF" }}>·</span>
              <span style={{ color: "#9CA3AF" }}>cap</span>
              <span style={{ fontWeight: 700 }}>{cap}</span>
            </div>
          );
        })()}
        <div style={{ flex: 1 }} />
        {savedAt && !dirty && <span style={{ fontSize: 11, color: "#15803d", fontStyle: "italic" }}>✓ Saved {new Date(savedAt).toLocaleString()}</span>}
        {dirty && <span style={{ fontSize: 11, color: "#b45309", fontWeight: 600 }}>● Unsaved changes</span>}
        {!_isHoSchedule && <button onClick={autoFill} style={{ padding: "8px 14px", borderRadius: 9, border: "1px solid #BE185D", background: "#FCE7F3", color: "#831843", cursor: "pointer", fontFamily: "inherit", fontSize: 13, fontWeight: 700 }}>✨ Auto-fill</button>}
        {undoSnap && (
          <button onClick={() => { setGrid(undoSnap.grid); setDirty(true); setUndoSnap(null); }}
            title={"Undo " + undoSnap.label + " — restores the schedule to just before it (click Save to keep the rollback)"}
            style={{ padding: "8px 14px", borderRadius: 9, border: "1px solid #fbbf24", background: "#fef3c7", color: "#78350f", cursor: "pointer", fontFamily: "inherit", fontSize: 13, fontWeight: 700 }}>↶ Undo {undoSnap.label}</button>
        )}
        <button onClick={openHistory} style={{ padding: "8px 14px", borderRadius: 9, border: "1px solid #FBCFE8", background: "#FFFFFF", color: "#BE185D", cursor: "pointer", fontFamily: "inherit", fontSize: 13, fontWeight: 600 }}>🕒 History</button>
        {(() => {
          const canDownload = !!savedAt && !dirty && Object.keys(grid).length > 0;
          const tip = canDownload ? "" : (dirty ? "Save the schedule first to download a clean copy" : "Nothing saved to download yet");
          return (
            <>
              <button onClick={downloadCsv} disabled={!canDownload} title={tip || "Download CSV"} style={{ padding: "8px 12px", borderRadius: 9, border: "1px solid #FBCFE8", background: canDownload ? "#FFFFFF" : "#F9FAFB", color: canDownload ? "#BE185D" : "#9CA3AF", cursor: canDownload ? "pointer" : "not-allowed", fontFamily: "inherit", fontSize: 13, fontWeight: 600 }}>⬇ CSV</button>
              <button onClick={downloadPdf} disabled={!canDownload} title={tip || "Download PDF"} style={{ padding: "8px 12px", borderRadius: 9, border: "1px solid #FBCFE8", background: canDownload ? "#FFFFFF" : "#F9FAFB", color: canDownload ? "#BE185D" : "#9CA3AF", cursor: canDownload ? "pointer" : "not-allowed", fontFamily: "inherit", fontSize: 13, fontWeight: 600 }}>⬇ PDF</button>
            </>
          );
        })()}
        <button onClick={clearAll} style={{ padding: "8px 14px", borderRadius: 9, border: "1px solid #FBCFE8", background: "#FFFFFF", color: "#BE185D", cursor: "pointer", fontFamily: "inherit", fontSize: 13, fontWeight: 600 }}>Clear period</button>
        <button onClick={save} disabled={saving || !dirty} title="Save current edits as the live schedule. Use this for work-in-progress; the prior version is backed up to history."
          style={{ padding: "8px 18px", borderRadius: 9, border: "none", background: dirty ? "#BE185D" : "#FBCFE8", color: dirty ? "#fff" : "#9F1A4F", cursor: dirty ? "pointer" : "not-allowed", fontFamily: "inherit", fontSize: 13, fontWeight: 700 }}>{saving ? "Saving…" : "Save Draft"}</button>
        <button onClick={saveFinalVersion} disabled={saving}
          title="Publish the current grid as the approved schedule for this cycle. Writes it as the live schedule AND archives a named snapshot with who made + approved it. Use this on the 15th of each month for the next month's schedule."
          style={{ padding: "8px 14px", borderRadius: 9, border: "1px solid #15803d", background: "#dcfce7", color: "#14532d", cursor: saving ? "not-allowed" : "pointer", fontFamily: "inherit", fontSize: 13, fontWeight: 700 }}>
          📌 Approve &amp; Publish
        </button>
        <button onClick={() => setVersionsOpen(o => !o)} title="View, restore or delete previously saved final versions for this branch + cycle."
          style={{ padding: "8px 14px", borderRadius: 9, border: "1px solid #15803d", background: versionsOpen ? "#86efac" : "#FFFFFF", color: "#14532d", cursor: "pointer", fontFamily: "inherit", fontSize: 13, fontWeight: 700 }}>
          📋 Versions ({versions.length}) {versionsOpen ? "▾" : "▸"}
        </button>
      </div>
      {versionsOpen && (
        <div style={{ marginTop: 10, padding: "12px 16px", background: "#FFFFFF", border: "1px solid #15803d", borderRadius: 10 }}>
          <div style={{ fontSize: 13, fontWeight: 700, color: "#14532d", marginBottom: 10 }}>Final versions for {branch} · {ym}</div>
          {versions.length === 0 && (
            <div style={{ fontSize: 12, color: "#6b7280", fontStyle: "italic" }}>No versions saved yet. Click 📌 Save Final to snapshot the current grid.</div>
          )}
          {versions.length > 0 && (
            <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12 }}>
              <thead>
                <tr style={{ background: "#dcfce7", color: "#14532d" }}>
                  <th style={{ padding: "6px 10px", textAlign: "left", fontWeight: 700, borderBottom: "1px solid #86efac" }}>Name</th>
                  <th style={{ padding: "6px 10px", textAlign: "left", fontWeight: 700, borderBottom: "1px solid #86efac" }}>Made by</th>
                  <th style={{ padding: "6px 10px", textAlign: "left", fontWeight: 700, borderBottom: "1px solid #86efac" }}>Approved by</th>
                  <th style={{ padding: "6px 10px", textAlign: "left", fontWeight: 700, borderBottom: "1px solid #86efac" }}>Saved at</th>
                  <th style={{ padding: "6px 10px", textAlign: "left", fontWeight: 700, borderBottom: "1px solid #86efac" }}>Note</th>
                  <th style={{ padding: "6px 10px", textAlign: "right", fontWeight: 700, borderBottom: "1px solid #86efac" }}></th>
                </tr>
              </thead>
              <tbody>
                {versions.map(v => (
                  <tr key={v.id} style={{ borderTop: "1px solid #f0fdf4" }}>
                    <td style={{ padding: "6px 10px", color: "#14532d", fontWeight: 600 }}>{v.name}</td>
                    <td style={{ padding: "6px 10px", color: "#14532d" }}>{v.madeBy || "—"}</td>
                    <td style={{ padding: "6px 10px", color: "#14532d" }}>{v.approvedBy || "—"}</td>
                    <td style={{ padding: "6px 10px", color: "#374151", fontSize: 11, whiteSpace: "nowrap" }}>{v.savedAt ? new Date(v.savedAt).toLocaleString("en-ZA", { day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit" }) : "—"}</td>
                    <td style={{ padding: "6px 10px", color: "#374151", fontSize: 11, fontStyle: v.note ? "normal" : "italic" }}>{v.note || "—"}</td>
                    <td style={{ padding: "6px 10px", textAlign: "right", whiteSpace: "nowrap" }}>
                      <button onClick={() => restoreVersion(v)} title="Load this version into the editor (you still need to click Save to make it the live schedule)"
                        style={{ background: "#dcfce7", color: "#14532d", border: "1px solid #86efac", borderRadius: 6, padding: "3px 9px", cursor: "pointer", fontSize: 11, fontWeight: 700, marginRight: 4 }}>↺ Restore</button>
                      <button onClick={() => deleteVersion(v)} title="Permanently delete this saved version"
                        style={{ background: "#fee2e2", color: "#7f1d1d", border: "1px solid #fca5a5", borderRadius: 6, padding: "3px 9px", cursor: "pointer", fontSize: 11, fontWeight: 700 }}>🗑</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      )}

      {/* ── Off-day requests for nail techs ── mirrors the manager planner panel.
          Linked to the same `boa_tech_requests_v1` row the check-in app's manager
          dashboard writes to, so requests submitted there appear here. */}
      {(() => {
        const allReqs = techRequests || [];
        const norm = (s) => (s || "").toString().toLowerCase().trim();
        const branchKey = norm(branch);
        const cycleYmds = new Set((days || []).map(d => d.year + "-" + String(d.monthIdx + 1).padStart(2, "0") + "-" + String(d.d).padStart(2, "0")));
        // Branch-aware list (in cycle) and a count of requests sitting outside
        // the current cycle so we can surface them as a hint instead of silently
        // dropping them.
        const branchReqs = allReqs.filter(r => r && r.date && norm(r.branch) === branchKey && _inGrid(r.ec));
        const cycleReqs = branchReqs.filter(r => cycleYmds.has(r.date));
        const otherCycle = branchReqs.length - cycleReqs.length;
        const otherBranch = allReqs.filter(r => r && r.date && norm(r.branch) !== branchKey && _inGrid(r.ec)).length;
        const dowAbbrLocal = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
        const techsActive = techs.filter(t => !t.onMat);
        const persist = async (next) => {
          try {
            await _saveReqs(next);
            if (onTechRequestsChange) onTechRequestsChange(next);
          } catch (e) { alert("Could not save: " + (e.message || e)); }
        };
        const removeReq = async (id) => {
          if (!window.confirm("Remove this off-day request?")) return;
          await persist(allReqs.filter(x => x.id !== id));
        };
        // Note: requests auto-stamp R on the grid via a useEffect; no manual
        // "Apply to grid" step needed.
        return (
          <div style={{ background: "#FFFFFF", border: "1px solid #FBCFE8", borderRadius: 11, padding: "12px 14px", marginBottom: 14 }}>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: cycleReqs.length ? 10 : 0, gap: 12, flexWrap: "wrap" }}>
              <div>
                <div style={{ fontSize: 13, fontWeight: 700, color: "#831843" }}>📝 Off-day requests for this cycle</div>
                <div style={{ fontSize: 11, color: "#9ca3af", marginTop: 2 }}>Submitted from the check-in app or here. Each request auto-fills its day on the grid as <strong>R</strong>; the schedule still needs <em>Save</em> to persist.</div>
              </div>
              <div style={{ display: "flex", gap: 8 }}>
                <button onClick={async () => {
                  if (!window.BOA_DB || !window.BOA_DB.listRequestKeys) { alert("Diagnostic not available — re-deploy after the latest data.js update."); return; }
                  try {
                    const keys = await window.BOA_DB.listRequestKeys();
                    const tables = window.BOA_DB.probeRequestTables ? await window.BOA_DB.probeRequestTables() : [];
                    const parts = [];
                    if (keys.length === 0) {
                      parts.push("app_state: no request-shaped rows found.");
                    } else {
                      parts.push("app_state keys:\n" + keys.map(k => "  • " + k.key + " — " + k.count + " entr" + (k.count === 1 ? "y" : "ies") + (k.sample ? "\n      sample: " + JSON.stringify(k.sample).slice(0, 180) : "")).join("\n"));
                    }
                    if (tables.length === 0) {
                      parts.push("\nSupabase tables probed: none of the candidate names exist or returned data.");
                    } else {
                      parts.push("\nSupabase tables found:\n" + tables.map(t => "  • " + t.table + " — " + (t.error ? "error: " + t.error : (t.rows + " row" + (t.rows === 1 ? "" : "s") + (t.sample ? "\n      sample: " + JSON.stringify(t.sample).slice(0, 200) : "")))).join("\n"));
                    }
                    parts.push("\n\nPortal currently reads:\n  • boa_tech_requests_v1 (techs)\n  • boa_mgr_requests_v1 (managers)\n\nShare the location the check-in app actually writes to and I'll align them.");
                    console.log("[BOA] Request diagnostic — keys:", keys, "tables:", tables);
                    alert(parts.join("\n"));
                  } catch (e) { alert("Diagnostic failed: " + (e.message || e)); }
                }}
                  title="List every request-shaped row in app_state — helps find where the check-in app saves day-off requests"
                  style={{ padding: "7px 14px", background: "#FFFFFF", color: "#831843", border: "1px solid #FBCFE8", borderRadius: 8, cursor: "pointer", fontFamily: "inherit", fontSize: 12, fontWeight: 600 }}>
                  🔍 Diagnose
                </button>
                <button onClick={() => setTechReqModal({ ec: (techsActive[0] && techsActive[0].ec) || "", dates: [], date: (days && days[0] ? (days[0].year + "-" + String(days[0].monthIdx + 1).padStart(2, "0") + "-" + String(days[0].d).padStart(2, "0")) : ""), note: "" })}
                  disabled={techsActive.length === 0}
                  style={{ padding: "7px 14px", background: techsActive.length ? "#BE185D" : "#FBCFE8", color: techsActive.length ? "#fff" : "#9F1A4F", border: "none", borderRadius: 8, cursor: techsActive.length ? "pointer" : "not-allowed", fontFamily: "inherit", fontSize: 12, fontWeight: 700 }}>
                  + Request day off
                </button>
              </div>
            </div>
            {cycleReqs.length === 0 && (
              <div style={{ marginTop: 8, fontSize: 11, color: "#9ca3af", fontStyle: "italic" }}>
                No off-day requests for {branch} in this cycle yet.
                {(otherCycle > 0 || otherBranch > 0) && (
                  <span style={{ marginLeft: 6, color: "#9F1A4F", fontStyle: "normal", fontWeight: 600 }}>
                    ({otherCycle > 0 && `${otherCycle} for ${branch} on other dates`}{otherCycle > 0 && otherBranch > 0 && " · "}{otherBranch > 0 && `${otherBranch} for other branches`})
                  </span>
                )}
              </div>
            )}
            {cycleReqs.length > 0 && (() => {
              // Friendly label for the source field. Requests submitted from the
              // check-in app's manager dashboard typically set source: "checkin_app";
              // requests added in this portal use source: "portal".
              const sourceLabel = (s) => {
                const k = (s || "").toString().toLowerCase();
                if (k === "portal" || k === "hr_portal" || k === "hr-portal") return "HR portal";
                if (k === "checkin_app" || k === "check_in_app" || k === "checkin" || k === "check-in" ||
                  k === "manager_app" || k === "manager-app" || k === "manager") return "check-in app";
                if (!k) return null;
                return s; // unknown — surface the raw string so we can spot bad data
              };
              // Decorate + split into pending vs honoured.
              const decorated = cycleReqs.map(r => {
                const tx = techs.find(t => t.ec === r.ec);
                const dt = new Date(r.date + "T00:00:00");
                const dayNum = parseInt(r.date.slice(8, 10), 10);
                const cellVal = (grid[r.ec] || {})[dayNum];
                const onGrid = cellVal === "R" || cellVal === "O";
                return {
                  r,
                  nm: (tx && tx.name) || r.name || r.ec,
                  dt,
                  dayNum,
                  onGrid,
                  src: sourceLabel(r.source),
                  addedAt: r.addedAt ? new Date(r.addedAt) : null
                };
              }).sort((a, b) => a.r.date.localeCompare(b.r.date));
              const pillBase = {
                display: "inline-flex", alignItems: "center", gap: 8,
                background: "#FCE7F3", border: "1px solid #FBCFE8",
                borderRadius: 20, padding: "5px 12px", fontSize: 11
              };
              return (
                <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
                  {decorated.map(d => (
                    <div key={d.r.id} style={pillBase} title={d.addedAt ? "Added " + d.addedAt.toLocaleString("en-ZA") : ""}>
                      <span style={{ fontWeight: 700, color: "#831843" }}>{d.nm}</span>
                      <span style={{ color: "#831843" }}>· {d.r.date} ({dowAbbrLocal[d.dt.getDay()]})</span>
                      {d.src && (
                        <span style={{ fontSize: 10, fontWeight: 700, color: "#0369a1", background: "#e0f2fe", border: "1px solid #bae6fd", borderRadius: 5, padding: "0 5px", letterSpacing: "0.02em" }}>from {d.src}</span>
                      )}
                      {d.r.note && <span style={{ color: "#9ca3af", fontStyle: "italic" }}>· "{d.r.note}"</span>}
                      <button onClick={() => removeReq(d.r.id)} title="Remove this request"
                        style={{ background: "transparent", border: "none", color: "#9F1A4F", cursor: "pointer", fontSize: 14, fontWeight: 700, lineHeight: 1, padding: "0 4px" }}>×</button>
                    </div>
                  ))}
                </div>
              );
            })()}
          </div>
        );
      })()}

      {/* Tech off-day request modal */}
      {techReqModal && (
        <div onClick={() => setTechReqModal(null)} style={{ position: "fixed", inset: 0, background: "rgba(131,24,67,0.35)", zIndex: 9000, display: "flex", alignItems: "center", justifyContent: "center", padding: "40px 20px" }}>
          <div onClick={e => e.stopPropagation()} style={{ background: "#fff", borderRadius: 13, padding: "22px 24px", width: "min(440px, 100%)", border: "1px solid #FBCFE8" }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 14 }}>
              <div style={{ fontFamily: "'Outfit',system-ui,sans-serif", fontSize: 18, fontWeight: 700, color: "#831843" }}>Request day off · {branch}</div>
              <button onClick={() => setTechReqModal(null)} style={{ background: "transparent", border: "none", color: "#9F1A4F", cursor: "pointer", fontSize: 18, fontWeight: 700, lineHeight: 1 }}>×</button>
            </div>
            <div style={{ display: "grid", gap: 10, fontSize: 13 }}>
              <label style={{ display: "flex", flexDirection: "column", gap: 4 }}>
                <span style={{ fontSize: 11, fontWeight: 700, color: "#BE185D", letterSpacing: "0.04em" }}>NAIL TECH</span>
                <StaffPicker
                  people={techs.filter(t => !t.onMat)}
                  valueEc={techReqModal.ec}
                  onChange={(ec) => setTechReqModal({ ...techReqModal, ec })}
                  placeholder="Search nail techs…"
                  formatOption={(t) => t.name + " (" + t.ec + ")"}
                />
              </label>
              <label style={{ display: "flex", flexDirection: "column", gap: 4 }}>
                <span style={{ fontSize: 11, fontWeight: 700, color: "#BE185D", letterSpacing: "0.04em" }}>DATES <span style={{ fontWeight: 600, color: "#9F1A4F" }}>(pick one or more)</span></span>
                <div style={{ display: "flex", gap: 6, alignItems: "center", flexWrap: "wrap" }}>
                  <input type="date" value={techReqModal.date || ""}
                    onChange={(e) => setTechReqModal({ ...techReqModal, date: e.target.value })}
                    style={{ padding: "7px 10px", borderRadius: 8, border: "1px solid #FBCFE8", fontSize: 13, flex: "1 1 160px" }} />
                  <button type="button"
                    onClick={() => {
                      const dt = (techReqModal.date || "").trim();
                      if (!dt) return;
                      const cur = Array.isArray(techReqModal.dates) ? techReqModal.dates : [];
                      if (cur.includes(dt)) return;
                      setTechReqModal({ ...techReqModal, dates: [...cur, dt].sort(), date: "" });
                    }}
                    style={{ padding: "7px 12px", background: "#FCE7F3", color: "#BE185D", border: "1px solid #FBCFE8", borderRadius: 8, cursor: "pointer", fontFamily: "inherit", fontSize: 12, fontWeight: 700 }}>+ Add</button>
                </div>
                {Array.isArray(techReqModal.dates) && techReqModal.dates.length > 0 && (
                  <div style={{ display: "flex", flexWrap: "wrap", gap: 5, marginTop: 4 }}>
                    {techReqModal.dates.map(d => (
                      <span key={d} style={{ display: "inline-flex", alignItems: "center", gap: 4, background: "#FCE7F3", color: "#831843", border: "1px solid #FBCFE8", borderRadius: 999, padding: "3px 9px", fontSize: 11, fontWeight: 700 }}>
                        {new Date(d + "T00:00:00").toLocaleDateString("en-ZA", { weekday: "short", day: "2-digit", month: "short" })}
                        <button type="button"
                          onClick={() => setTechReqModal({ ...techReqModal, dates: techReqModal.dates.filter(x => x !== d) })}
                          style={{ background: "transparent", border: "none", color: "#9F1A4F", cursor: "pointer", fontWeight: 800, padding: 0, lineHeight: 1, fontSize: 13 }}>×</button>
                      </span>
                    ))}
                  </div>
                )}
              </label>
              <label style={{ display: "flex", flexDirection: "column", gap: 4 }}>
                <span style={{ fontSize: 11, fontWeight: 700, color: "#BE185D", letterSpacing: "0.04em" }}>NOTE (optional)</span>
                <input type="text" value={techReqModal.note}
                  onChange={(e) => setTechReqModal({ ...techReqModal, note: e.target.value })}
                  placeholder="e.g. doctor's appointment"
                  style={{ padding: "7px 10px", borderRadius: 8, border: "1px solid #FBCFE8", fontSize: 13 }} />
              </label>
            </div>
            <div style={{ display: "flex", gap: 8, justifyContent: "flex-end", marginTop: 16 }}>
              <button onClick={() => setTechReqModal(null)}
                style={{ padding: "8px 14px", background: "#fff", color: "#831843", border: "1px solid #FBCFE8", borderRadius: 8, cursor: "pointer", fontFamily: "inherit", fontSize: 13 }}>Cancel</button>
              <button onClick={async () => {
                if (!techReqModal.ec) { alert("Pick a nail tech."); return; }
                // Combine the dates-chip list with the lone date input so a
                // user who just typed one date and clicked Save (without
                // pressing + Add) still gets it captured.
                const dateList = Array.isArray(techReqModal.dates) ? techReqModal.dates.slice() : [];
                const single = (techReqModal.date || "").trim();
                if (single && !dateList.includes(single)) dateList.push(single);
                if (dateList.length === 0) { alert("Pick at least one date."); return; }
                const dupes = dateList.filter(d => (techRequests || []).some(r => r.ec === techReqModal.ec && r.date === d));
                if (dupes.length > 0) {
                  if (!confirm(dupes.length + " of those date(s) are already requested for this tech. Skip the duplicates and save the rest?")) return;
                }
                const datesToSave = dateList.filter(d => !dupes.includes(d));
                if (datesToSave.length === 0) { setTechReqModal(null); return; }
                const tx = techs.find(t => t.ec === techReqModal.ec);
                const stamp = new Date().toISOString();
                const note = techReqModal.note || "";
                const newReqs = datesToSave.map(d => ({
                  id: "tr_" + Date.now().toString(36) + "_" + d.replace(/-/g, "") + "_" + Math.random().toString(36).slice(2, 5),
                  ec: techReqModal.ec,
                  name: (tx && tx.name) || "",
                  branch,
                  date: d,
                  note,
                  addedAt: stamp,
                  source: "portal"
                }));
                const next = [...(techRequests || []), ...newReqs];
                try {
                  await _saveReqs(next);
                  if (onTechRequestsChange) onTechRequestsChange(next);
                  setTechReqModal(null);
                } catch (e) { alert("Could not save: " + (e.message || e)); }
              }}
                style={{ padding: "8px 14px", background: "#BE185D", color: "#fff", border: "none", borderRadius: 8, cursor: "pointer", fontFamily: "inherit", fontSize: 13, fontWeight: 700 }}>Save request</button>
            </div>
          </div>
        </div>
      )}

      {/* Version History modal — shows last 5 backups for this branch+period */}
      {historyOpen && (
        <div onClick={() => setHistoryOpen(false)} style={{ position: "fixed", inset: 0, background: "rgba(131,24,67,0.35)", zIndex: 9000, display: "flex", alignItems: "center", justifyContent: "center", padding: "40px 20px" }}>
          <div onClick={(e) => e.stopPropagation()} style={{ background: "#fff", borderRadius: 14, maxWidth: 640, width: "100%", maxHeight: "80vh", overflow: "auto", padding: "22px 26px", boxShadow: "0 20px 50px rgba(131,24,67,0.25)" }}>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 14 }}>
              <div style={{ fontFamily: "'Playfair Display',serif", fontSize: 20, fontWeight: 700, color: "#831843" }}>🕒 Version History</div>
              <button onClick={() => setHistoryOpen(false)} style={{ background: "none", border: "none", fontSize: 22, color: "#BE185D", cursor: "pointer", lineHeight: 1 }}>×</button>
            </div>
            <div style={{ fontSize: 12, color: "#831843", marginBottom: 14, lineHeight: 1.5 }}>
              {branch} · {periodLbl}<br />
              The last 5 saved versions of this schedule are kept here. Restoring will load that older version onto the editor — you'll still need to click Save to commit it (and the current schedule gets backed up automatically).
            </div>
            {historyLoading ? (
              <div style={{ padding: "24px 0", textAlign: "center", color: "#9CA3AF", fontStyle: "italic" }}>Loading history…</div>
            ) : historyVersions.length === 0 ? (
              <div style={{ padding: "24px 12px", textAlign: "center", color: "#9CA3AF", fontStyle: "italic", border: "1px dashed #FBCFE8", borderRadius: 10 }}>
                No previous versions yet.<br />
                <span style={{ fontSize: 11 }}>A snapshot is taken every time a saved schedule is overwritten.</span>
              </div>
            ) : (
              <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                {historyVersions.map((v, i) => {
                  const ts = v.savedAt ? new Date(v.savedAt).toLocaleString() : "(unknown time)";
                  const techCount = v.grid ? Object.keys(v.grid).length : 0;
                  let offCount = 0, workCount = 0;
                  if (v.grid) {
                    Object.values(v.grid).forEach(row => Object.values(row || {}).forEach(cell => {
                      if (cell === "O" || cell === "R" || cell === "L") offCount++;
                      else if (cell === "W" || cell === "WE" || cell === "WB" || cell === "WM" || cell === "WL" || cell === "E") workCount++;
                    }));
                  }
                  return (
                    <div key={i} style={{ border: "1px solid #FBCFE8", borderRadius: 10, padding: "12px 14px", display: "flex", alignItems: "center", gap: 12, background: i === 0 ? "#FDF2F8" : "#fff" }}>
                      <div style={{ flex: 1 }}>
                        <div style={{ fontSize: 13, fontWeight: 700, color: "#831843" }}>{ts}{i === 0 ? " · most recent backup" : ""}</div>
                        <div style={{ fontSize: 11, color: "#9CA3AF", marginTop: 3 }}>{techCount} techs · {workCount} working cells · {offCount} off cells</div>
                      </div>
                      <button onClick={() => restoreVersion(i)} style={{ padding: "6px 14px", borderRadius: 8, border: "1px solid #BE185D", background: "#FCE7F3", color: "#831843", cursor: "pointer", fontFamily: "inherit", fontSize: 12, fontWeight: 700 }}>Restore</button>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </div>
      )}

      <div style={{ fontSize: 12, color: "#831843", marginBottom: 10, lineHeight: 1.5 }}>
        Click a cell to cycle through statuses: <strong>W</strong> → WL → O → R → L → E → X → empty. Save commits the period to Supabase. Auto-fill applies BOA rules (Sunday rotation, day requests, 5-day weeks).
      </div>

      {/* Conflicts panel — too many consecutive working days (labour law) */}
      {longStreaks.length > 0 && (
        <div style={{ background: "#fee2e2", border: "1px solid #fca5a5", borderRadius: 10, padding: "12px 14px", marginBottom: 14, color: "#7f1d1d", fontSize: 12, lineHeight: 1.5 }}>
          <div style={{ fontWeight: 700, marginBottom: 6, fontSize: 13 }}>
            ⚠ Labour law: {longStreaks.length} staff with 7+ consecutive working days
          </div>
          <ul style={{ margin: 0, paddingLeft: 20 }}>
            {longStreaks.map((c, i) => (
              <li key={i}>
                <strong>{c.name}</strong> ({c.ec}) · <strong>{c.count} consecutive working days</strong> ({c.range}) — must include an off-day before day 7.
              </li>
            ))}
          </ul>
        </div>
      )}

      {/* Conflicts panel — too many off-days per week */}
      {tooManyOff.length > 0 && (
        <div style={{ background: "#fef3c7", border: "1px solid #fcd34d", borderRadius: 10, padding: "12px 14px", marginBottom: 14, color: "#92400e", fontSize: 12, lineHeight: 1.5 }}>
          <div style={{ fontWeight: 700, marginBottom: 6, fontSize: 13 }}>
            ⚠ {tooManyOff.length} week{tooManyOff.length > 1 ? 's' : ''} over the 2-off-days-per-week limit
          </div>
          <ul style={{ margin: 0, paddingLeft: 20 }}>
            {tooManyOff.map((c, i) => (
              <li key={i}>
                <strong>{c.name}</strong> ({c.ec}) · Week {c.weekIdx} ({c.range}): <strong>{c.count} off-days</strong> ({c.offCells})
              </li>
            ))}
          </ul>
        </div>
      )}

      {/* Auto-fill / sync diagnostic — request days that couldn't be honoured
          without breaking a hard rule (mainly 2 off-days per week). */}
      {unhonouredRequests.length > 0 && (
        <div style={{ background: "#fef3c7", border: "1px solid #fcd34d", borderRadius: 10, padding: "12px 14px", marginBottom: 14, color: "#92400e", fontSize: 12, lineHeight: 1.5 }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 6, gap: 12 }}>
            <div style={{ fontWeight: 700, fontSize: 13 }}>
              ⚠ {unhonouredRequests.length} request day{unhonouredRequests.length > 1 ? 's' : ''} could not be applied without violating a schedule rule
            </div>
            <button onClick={() => setUnhonouredRequests([])}
              title="Dismiss this warning"
              style={{ background: "transparent", border: "none", color: "#92400e", cursor: "pointer", fontSize: 14, fontWeight: 700, lineHeight: 1, padding: "0 4px" }}>×</button>
          </div>
          <div style={{ fontSize: 11, color: "#92400e", marginBottom: 6, fontStyle: "italic" }}>
            Request off-days never override schedule rules. Re-run auto-fill after adjusting the schedule, or place the off-day manually if a rule can flex.
          </div>
          <ul style={{ margin: 0, paddingLeft: 20 }}>
            {unhonouredRequests.map((u, i) => (
              <li key={i}>
                <strong>{u.name}</strong> ({u.ec}) · <strong>{u.date || u.dayNum}</strong> — {u.reason}
                {u.note ? <span style={{ fontStyle: "italic", color: "#7c2d12" }}> · "{u.note}"</span> : null}
              </li>
            ))}
          </ul>
        </div>
      )}

      {/* Selective staff-sync prompt — surfaces when a tech was added or
          terminated AFTER a schedule was generated. Saves a full regen. */}
      {(missingTechs.length > 0 || staleStaff.length > 0) && !loading && (
        <div style={{ background: "#eff6ff", border: "1px solid #93c5fd", borderRadius: 10, padding: "12px 14px", marginBottom: 14, color: "#1e3a8a", fontSize: 12, lineHeight: 1.5 }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 12, flexWrap: "wrap", marginBottom: 6 }}>
            <div style={{ fontWeight: 700, fontSize: 13 }}>
              👥 Staff changes detected — sync without regenerating the whole schedule
            </div>
            <button onClick={syncStaff}
              style={{ padding: "7px 14px", background: "#1e3a8a", color: "#fff", border: "none", borderRadius: 8, cursor: "pointer", fontFamily: "inherit", fontSize: 12, fontWeight: 700 }}>
              Sync staff now
            </button>
          </div>
          <div style={{ fontSize: 11, color: "#1e3a8a", marginBottom: 6, fontStyle: "italic" }}>
            Existing rows are left untouched. New rows are filled per the schedule rules; departures keep pre-leftDate cells and mark post-leftDate cells as X.
          </div>
          <ul style={{ margin: 0, paddingLeft: 20 }}>
            {missingTechs.map(t => (
              <li key={"add-" + t.ec}>
                <strong style={{ color: "#15803d" }}>＋ Add</strong> <strong>{t.name}</strong> ({t.ec})
                {(t.startDate || t._startDate) ? <> · starts <strong>{t.startDate || t._startDate}</strong></> : null}
                {t.onMat ? <> · <em>on maternity leave (will be filled as L)</em></> : null}
              </li>
            ))}
            {staleStaff.map(s => {
              const sf = s.staff;
              const inCycle = sf && sf.leftDate && periodStartYmd && periodEndYmd
                && sf.leftDate >= periodStartYmd && sf.leftDate <= periodEndYmd;
              return (
                <li key={"rm-" + s.ec}>
                  <strong style={{ color: "#9F1A4F" }}>− Remove</strong> <strong>{(sf && sf.name) || s.ec}</strong> ({s.ec})
                  {sf && sf.leftDate
                    ? (inCycle
                      ? <> · left <strong>{sf.leftDate}</strong> — cells after will be marked X</>
                      : <> · left <strong>{sf.leftDate}</strong> — row will be removed</>)
                    : <> · no longer at this branch — row will be removed</>}
                </li>
              );
            })}
          </ul>
        </div>
      )}

      {/* Betty: store closed Sun + Mon. On the first Sunday of the cycle
          all techs work in another store — half at Bree, half at Green
          Point. Split is deterministic by EC (alphabetical first half
          → Bree, second half → Green Point). */}
      {Array.isArray(salonForBranch.closedDow) && salonForBranch.closedDow.includes(0) && (() => {
        const firstSun = days.find(d => d.dow === 0);
        if (!firstSun) return null;
        const active = techs.filter(t => !t.onMat).sort((a, b) => (a.ec || "").localeCompare(b.ec || ""));
        if (active.length === 0) return null;
        const half = Math.ceil(active.length / 2);
        const breeTechs = active.slice(0, half);
        const gpTechs = active.slice(half);
        const dayLabel = firstSun.d + " " + (["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"][firstSun.monthIdx]);
        return (
          <div style={{ background: "#fef3c7", border: "1px solid #fde68a", borderRadius: 10, padding: "12px 16px", marginBottom: 12 }}>
            <div style={{ fontSize: 13, fontWeight: 800, color: "#7c2d12", marginBottom: 6 }}>
              📍 Betty rule — first Sunday of cycle ({dayLabel})
            </div>
            <div style={{ fontSize: 11, color: "#7c2d12", marginBottom: 8, lineHeight: 1.4 }}>
              Betty closes every Sun + Mon. On the first Sunday of the cycle all techs work at another store. Half go to <strong>Bree</strong>, half go to <strong>Green Point</strong>.
            </div>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
              <div>
                <div style={{ fontSize: 10, fontWeight: 800, color: "#7c2d12", letterSpacing: "0.06em", marginBottom: 4 }}>→ BREE ({breeTechs.length})</div>
                {breeTechs.length === 0 ? <div style={{ fontSize: 11, color: "#9ca3af", fontStyle: "italic" }}>—</div> :
                  <div style={{ display: "flex", flexWrap: "wrap", gap: 4 }}>
                    {breeTechs.map(t => <span key={t.ec} style={{ background: "#FFFFFF", border: "1px solid #fde68a", borderRadius: 6, padding: "2px 8px", fontSize: 11, fontWeight: 700, color: "#7c2d12" }}>{t.name}</span>)}
                  </div>}
              </div>
              <div>
                <div style={{ fontSize: 10, fontWeight: 800, color: "#7c2d12", letterSpacing: "0.06em", marginBottom: 4 }}>→ GREEN POINT ({gpTechs.length})</div>
                {gpTechs.length === 0 ? <div style={{ fontSize: 11, color: "#9ca3af", fontStyle: "italic" }}>—</div> :
                  <div style={{ display: "flex", flexWrap: "wrap", gap: 4 }}>
                    {gpTechs.map(t => <span key={t.ec} style={{ background: "#FFFFFF", border: "1px solid #fde68a", borderRadius: 6, padding: "2px 8px", fontSize: 11, fontWeight: 700, color: "#7c2d12" }}>{t.name}</span>)}
                  </div>}
              </div>
            </div>
          </div>
        );
      })()}

      {techs.length === 0 ? (
        <div style={{ padding: 24, background: "#FCE7F3", borderRadius: 10, color: "#831843" }}>No staff at <strong>{branch}</strong>.</div>
      ) : loading ? (
        <div style={{ padding: 24, color: "#831843", fontStyle: "italic" }}>Loading schedule…</div>
      ) : (
        <>
          {/* Per-store shift-time info banners — display the exact start/end
            times that the WE / WL cells correspond to. The schedule grid
            only carries the WE/WL label; the actual hours live here. */}
          {branch === "Sandown" && (
            <div style={{ background: "#ecfdf5", border: "1px solid #a7f3d0", borderRadius: 10, padding: "10px 14px", marginBottom: 10, fontSize: 12, color: "#065f46", display: "flex", flexWrap: "wrap", gap: 14, alignItems: "center" }}>
              <span style={{ fontSize: 11, fontWeight: 800, color: "#065f46", letterSpacing: "0.08em", textTransform: "uppercase" }}>🕐 Sandown shift times</span>
              <span><strong>Mon–Fri</strong> · WE 08:00–17:30 · WL 11:00–20:00</span>
              <span><strong>Saturday</strong> · WE 08:00–17:30 · WL 10:00–19:00</span>
              <span><strong>Sunday</strong> · all shifts 09:00–18:00 (no early/late split)</span>
            </div>
          )}
          {branch === "Table Bay" && (
            <div style={{ background: "#ecfdf5", border: "1px solid #a7f3d0", borderRadius: 10, padding: "10px 14px", marginBottom: 10, fontSize: 12, color: "#065f46", display: "flex", flexWrap: "wrap", gap: 14, alignItems: "center" }}>
              <span style={{ fontSize: 11, fontWeight: 800, color: "#065f46", letterSpacing: "0.08em", textTransform: "uppercase" }}>🕐 Table Bay shift times</span>
              <span>Up to 3 nail techs per day on the late shift (WL).</span>
            </div>
          )}
          {branch === "Fourways" && (
            <div style={{ background: "#ecfdf5", border: "1px solid #a7f3d0", borderRadius: 10, padding: "10px 14px", marginBottom: 10, fontSize: 12, color: "#065f46", display: "flex", flexWrap: "wrap", gap: 14, alignItems: "center" }}>
              <span style={{ fontSize: 11, fontWeight: 800, color: "#065f46", letterSpacing: "0.08em", textTransform: "uppercase" }}>🕐 Fourways shift times</span>
              <span><strong>Mon–Fri</strong> · W 09:30–18:30 · WL 11:00–20:00 (4 techs)</span>
              <span><strong>Saturday</strong> · W 09:00–18:00 · WL 11:00–20:00 (4 techs)</span>
              <span><strong>Sunday</strong> · W 09:00–18:00 · WL 10:00–19:00 (2–3 techs, alternates by parity)</span>
            </div>
          )}
          <div style={{ overflowX: "auto", border: "1px solid #FBCFE8", borderRadius: 10, background: "#fff" }}>
            <table style={{ borderCollapse: "separate", borderSpacing: 0, minWidth: "100%", fontSize: 11 }}>
              <thead>
                <tr>
                  <th style={{ position: "sticky", left: 0, background: "#FCE7F3", padding: "8px 10px", textAlign: "left", borderBottom: "1px solid #FBCFE8", color: "#831843", minWidth: 180, zIndex: 2 }}>Staff</th>
                  {days.map(d => {
                    const wknd = d.dow === 0 || d.dow === 6;
                    const weekEnd = d.dow === 0;
                    const busy = isBusyDay(d);
                    const hol = isHoliday(d);
                    // SA public holiday → lavender (overrides busy yellow).
                    // Otherwise uniform yellow for busy days (25th–6th — peak revenue).
                    const headerBg = d.isToday ? "#FBCFE8"
                      : hol ? "#ede9fe"
                        : busy ? "#fef3c7"
                          : "#FCE7F3";
                    const titleParts = [];
                    if (hol) titleParts.push("🇿🇦 " + holidayName(d));
                    if (busy) titleParts.push("Busy day (25th–6th — peak revenue)");
                    return (
                      <th key={d.year + '-' + d.monthIdx + '-' + d.d} title={titleParts.join(" · ")} style={{ padding: "4px 2px", borderBottom: "1px solid #FBCFE8", borderLeft: "1px solid #FCE7F3", borderRight: weekEnd ? "3px solid #BE185D" : "none", background: headerBg, color: hol ? "#5b21b6" : "#831843", minWidth: 34, textAlign: "center", fontWeight: 600 }}>
                        <div style={{ fontSize: 13, lineHeight: 1 }}>{d.d}</div>
                        <div style={{ fontSize: 8, fontWeight: 500, color: hol ? "#5b21b6" : busy ? "#92400e" : "#BE185D", lineHeight: 1, marginTop: 2 }}>{monthAbbr[d.monthIdx]}</div>
                        <div style={{ fontSize: 8, fontWeight: 700, color: hol ? "#5b21b6" : wknd ? "#BE185D" : "#9CA3AF", lineHeight: 1, marginTop: 2, textTransform: "uppercase", letterSpacing: "0.04em" }}>{dowAbbr[d.dow]}</div>
                        {hol && <div style={{ fontSize: 7, fontWeight: 800, color: "#5b21b6", lineHeight: 1, marginTop: 2, letterSpacing: "0.05em" }}>HOL</div>}
                      </th>
                    );
                  })}
                  <th style={{ padding: "6px 8px", background: "#FCE7F3", borderBottom: "1px solid #FBCFE8", borderLeft: "2px solid #FBCFE8", color: "#831843", fontSize: 10, textTransform: "uppercase", letterSpacing: "0.06em" }}>W</th>
                  <th style={{ padding: "6px 8px", background: "#FCE7F3", borderBottom: "1px solid #FBCFE8", color: "#831843", fontSize: 10, textTransform: "uppercase", letterSpacing: "0.06em" }}>Off</th>
                </tr>
              </thead>
              <tbody>
                {techs.map(s => {
                  const counts = rowCounts(s.ec);
                  // Maternity window for this cycle. fullMat = on mat the whole
                  // cycle (whole row ML, greyed, as before). matFromYmd = a
                  // mid-cycle start date — the row stays a normal working row
                  // and only the days on/after that date read 'ML'.
                  const _cycStartYmd = days.length ? days[0].year + "-" + String(days[0].monthIdx + 1).padStart(2, "0") + "-" + String(days[0].d).padStart(2, "0") : "";
                  const _cycEndYmd = days.length ? days[days.length - 1].year + "-" + String(days[days.length - 1].monthIdx + 1).padStart(2, "0") + "-" + String(days[days.length - 1].d).padStart(2, "0") : "";
                  const _matWin = matCycleWindow(s, _cycStartYmd, _cycEndYmd);
                  const fullMat = _matWin.full;
                  const matFromYmd = _matWin.fromYmd;
                  // Returner: ML only up to the return date (exclusive); real
                  // shifts show from the return date onward.
                  const matUntilYmd = _matWin.untilYmd;
                  // Unpaid legal-status leave window — same shape as maternity.
                  // Maternity wins when someone is on both (matWin checked first).
                  const _legalWin = fullMat ? { full: false, fromYmd: null, untilYmd: null } : legalLeaveWindow(s, _cycStartYmd, _cycEndYmd);
                  const fullLegal = _legalWin.full;
                  const legalFromYmd = _legalWin.fromYmd;
                  const legalUntilYmd = _legalWin.untilYmd;
                  // Off-boarding visibility: row is greyed-out for the
                  // entire cycle they leave in. Cells on/before leftDate
                  // remain editable (real schedule for the days worked);
                  // cells after leftDate are stamped X by PHASE 18 / sync.
                  const isLeaving = !!s.leftDate;
                  // Only a FULL-cycle maternity / legal leave greys the whole
                  // row; a mid-cycle start keeps the row readable so the worked
                  // days show.
                  const rowOpacity = (fullMat || fullLegal) ? 0.55 : (isLeaving ? 0.7 : 1);
                  const nameBg = (fullMat || fullLegal) ? "#f3f4f6" : (isLeaving ? "#f9fafb" : "#fff");
                  const nameColor = (fullMat || fullLegal) ? "#6b7280" : (isLeaving ? "#6b7280" : "#831843");
                  return (
                    <tr key={s.ec} style={{ opacity: rowOpacity }}>
                      <td style={{ position: "sticky", left: 0, background: nameBg, padding: "6px 10px", borderBottom: "1px solid #FCE7F3", color: nameColor, fontWeight: 600, fontSize: 12, zIndex: 1 }}>
                        <div style={{ display: "flex", alignItems: "center", gap: 6, flexWrap: "wrap" }}>
                          <span>{s.name}</span>
                          {isOwner && !s.isShadow && (
                            <button type="button" title={"Regenerate only " + s.name + "'s row — keeps everyone else (and custom movements) as-is"} onClick={() => {
                              if (!window.confirm("Regenerate only " + s.name + "'s row for this cycle?\n\nIt rebuilds just their cells from the current rules (start date, maternity, leave). Everyone else — and any custom movements — stays exactly as-is. Click Save afterwards to keep it.")) return;
                              const _r = fillRowForTech(s, grid);
                              setGrid(g => Object.assign({}, g, { [s.ec]: _r.row }));
                              setDirty(true);
                            }} style={{ border: "1px solid #FBCFE8", background: "#fff", color: "#BE185D", borderRadius: 6, padding: "0 6px", fontSize: 11, lineHeight: "18px", height: 20, cursor: "pointer", fontWeight: 700 }}>↻</button>
                          )}
                          {fullMat && <span style={{ background: "#e5e7eb", color: "#374151", padding: "1px 6px", borderRadius: 4, fontSize: 9, fontWeight: 700, letterSpacing: "0.04em" }}>🤱 ON MAT</span>}
                          {!fullMat && matFromYmd && <span style={{ background: "#ede9fe", color: "#6b21a8", padding: "1px 6px", borderRadius: 4, fontSize: 9, fontWeight: 700, letterSpacing: "0.04em" }}>🤱 {matUntilYmd ? "BACK " + new Date(matUntilYmd + "T12:00:00").toLocaleDateString("en-ZA", { day: "2-digit", month: "short" }) : "ML FROM " + new Date(matFromYmd + "T12:00:00").toLocaleDateString("en-ZA", { day: "2-digit", month: "short" })}</span>}
                          {!fullMat && isLeaving && <span style={{ background: "#fee2e2", color: "#991b1b", padding: "1px 6px", borderRadius: 4, fontSize: 9, fontWeight: 700, letterSpacing: "0.04em" }}>👋 LEFT {s.leftDate}</span>}
                          {fullLegal && <span style={{ background: "#ffedd5", color: "#9a3412", padding: "1px 6px", borderRadius: 4, fontSize: 9, fontWeight: 700, letterSpacing: "0.04em" }}>⏸ LEGAL UNPAID</span>}
                          {!fullLegal && legalFromYmd && <span style={{ background: "#ffedd5", color: "#9a3412", padding: "1px 6px", borderRadius: 4, fontSize: 9, fontWeight: 700, letterSpacing: "0.04em" }}>⏸ {legalUntilYmd ? "BACK " + new Date(legalUntilYmd + "T12:00:00").toLocaleDateString("en-ZA", { day: "2-digit", month: "short" }) : "EL FROM " + new Date(legalFromYmd + "T12:00:00").toLocaleDateString("en-ZA", { day: "2-digit", month: "short" })}</span>}
                          {/* Transfer chips — surface mid-month moves so the
                            manager sees the cross-over at a glance. */}
                          {s.isShadow && s.transferFrom && <span style={{ background: "#dbeafe", color: "#1e40af", padding: "1px 6px", borderRadius: 4, fontSize: 9, fontWeight: 700, letterSpacing: "0.04em" }}>🔄 FROM {s.transferFrom}{s.transferDate ? " · " + new Date(s.transferDate).toLocaleDateString("en-ZA", { day: "2-digit", month: "short" }) : ""}</span>}
                          {!s.isShadow && s.transferring && s.transferTo && <span style={{ background: "#fef3c7", color: "#92400e", padding: "1px 6px", borderRadius: 4, fontSize: 9, fontWeight: 700, letterSpacing: "0.04em" }}>🔄 → {s.transferTo}{s.transferDate ? " · " + new Date(s.transferDate).toLocaleDateString("en-ZA", { day: "2-digit", month: "short" }) : ""}</span>}
                        </div>
                        <div style={{ fontSize: 10, color: "#9CA3AF", marginTop: 1, letterSpacing: "0.04em" }}>{s.ec}</div>
                      </td>
                      {days.map(d => {
                        const dYmd = d.year + "-" + String(d.monthIdx + 1).padStart(2, "0") + "-" + String(d.d).padStart(2, "0");
                        let v = (grid[s.ec] || {})[d.d] || "";
                        // Live Leave-Planner overlay — a planner leave day reads as
                        // "L" even when the saved grid wasn't (re)stamped yet, so
                        // leave added after the schedule was generated still shows.
                        // A scheduled OFF / ghost / maternity day inside the window
                        // stays as-is (matches the auto-stamp + attendance — you
                        // don't take leave on a day off).
                        if (v !== "O" && v !== "R" && v !== "X" && v !== "ML" && v !== "L"
                          && plannerLeaveSet.has(String(s.ec).trim() + "|" + dYmd)) v = "L";
                        const weekEnd = d.dow === 0;
                        const requested = requestedSet.has(s.ec + "|" + d.d);
                        const requestUnapplied = requested && v !== "R" && v !== "O";
                        // Off-boarding: cells AFTER leftDate render flat grey
                        // and locked, regardless of whatever value is sitting
                        // in the saved grid. This way the moment leftDate is
                        // set, the post-departure days visibly disappear from
                        // the schedule without waiting for an auto-fill or
                        // sync pass to stamp X.
                        // Emergency (unpaid) leave: the grid stores a generic "L"
                        // for all leave, so flag days inside an emergency Leave
                        // Planner record to paint them orange "EL" (vs grey "L").
                        const isEmergLeave = v === "L" && emergencyLeaveSet.has(String(s.ec).trim() + "|" + dYmd);
                        const isPastLeft = isLeaving && dYmd > s.leftDate;
                        // Pre-start: a tech only appears on the schedule from
                        // their start date. Days before it render as a locked
                        // grey "—" (like post-departure days) so a mid-cycle
                        // starter doesn't look like they're working the whole
                        // month before they've started.
                        const isPreStart = !!s.startDate && dYmd < s.startDate;
                        // Maternity cell: lavender 'ML' from the start date on.
                        // A full-cycle mat means every cell; a mid-cycle start
                        // means only days on/after it — days before stay the
                        // real worked shift.
                        const cellMat = fullMat || (!!matFromYmd && dYmd >= matFromYmd && (!matUntilYmd || dYmd < matUntilYmd));
                        // Legal-leave cell: orange 'EL' (unpaid emergency leave)
                        // across the covered window. Maternity wins, so this
                        // never fires on a maternity cell.
                        const cellLegal = !cellMat && (fullLegal || (!!legalFromYmd && dYmd >= legalFromYmd && (!legalUntilYmd || dYmd < legalUntilYmd)));
                        // Transfer-edge: for a mid-month branch move, cells
                        // on the wrong side of transferDate render as locked,
                        // greyed placeholders showing where they're moving
                        // to (original record) or coming from (shadow).
                        //   • original record (transferring=true) at the
                        //     source branch → days >= transferDate are 'out'
                        //   • shadow (isShadow=true) at the destination
                        //     branch → days <  transferDate are 'in'
                        const _xferDate = s.transferDate || null;
                        const transferEdge = !_xferDate ? null
                          : (s.isShadow && dYmd < _xferDate) ? "in"
                            : (!s.isShadow && s.transferring && dYmd >= _xferDate) ? "out"
                              : null;
                        const transferOtherBranch = transferEdge === "in" ? (s.transferFrom || "")
                          : transferEdge === "out" ? (s.transferTo || "")
                            : null;
                        const cellLocked = cellMat || cellLegal || isPastLeft || isPreStart || !!transferEdge;
                        // Cross-store loan: if this tech has a same-day loan FROM
                        // this branch, the cell is tinted teal and shows the
                        // destination store (e.g. Betty's first-Sunday Bree/GP
                        // split, or any manually-logged movement).
                        // EC compared TRIMMED: staff rows can carry padded codes
                        // (e.g. "B620-M ") while loan/visit records emit trimmed
                        // ones — strict === silently drops the marker.
                        const _outgoingLoan = (techLoans || []).find(l => l && String(l.ec || "").trim() === String(s.ec || "").trim() && l.date === dYmd && l.fromBranch === branch);
                        const _loanCell = _outgoingLoan && !cellMat && !cellLegal && !isPastLeft
                          ? (_outgoingLoan.toBranch === "Bree" ? { background: "#cffafe", color: "#155e75" }
                            : _outgoingLoan.toBranch === "Green Point" ? { background: "#fce7f3", color: "#9d174d" }
                              : { background: "#e0e7ff", color: "#3730a3" })
                          : null;
                        // Maternity leave cells: distinct lavender tint so
                        // ML reads differently from a regular L (annual
                        // leave) and from a post-departure ghost cell.
                        // Legal-leave + emergency-leave cells share the orange
                        // unpaid-leave tint (EL).
                        const matCell = cellMat
                          ? { background: "#ede9fe", color: "#6b21a8" }
                          : (isPastLeft || isPreStart)
                            ? { background: "#e5e7eb", color: "#9ca3af" }
                            : transferEdge === "out"
                              ? { background: "#fef3c7", color: "#92400e" }   // amber — moving out
                              : transferEdge === "in"
                                ? { background: "#dbeafe", color: "#1e40af" }   // blue — coming in
                                : _loanCell || ((isEmergLeave || cellLegal) ? { background: "#fed7aa", color: "#9a3412", fontWeight: 700 } : cellStyle(v));
                        // Drag-drop visual states
                        const isSrc = dragSource && dragSource.ec === s.ec && dragSource.day === d.d;
                        const isValidDrop = !cellLocked && isValidDropTarget(s.ec, d.d);
                        const dropOutline = isValidDrop ? "2px solid #15803d"
                          : isSrc ? "2px dashed #BE185D"
                            : d.isToday ? "1px dashed rgba(190,24,93,0.45)"
                              : "none";
                        const dragCursor = cellLocked ? "default" : (v ? "grab" : "pointer");
                        const cellTitle = cellMat
                          ? `${s.name} · on maternity leave${matFromYmd && !fullMat ? " (from " + matFromYmd + ")" : ""}`
                          : cellLegal
                            ? `${s.name} · ${d.d} ${monthAbbr[d.monthIdx]} · unpaid legal leave (shown as Emergency / unpaid)`
                            : isPreStart
                              ? `${s.name} · starts ${s.startDate} — not on the schedule until then`
                              : isPastLeft
                                ? `${s.name} · left ${s.leftDate} — no longer scheduled`
                                : transferEdge === "out"
                                  ? `${s.name} · ${d.d} ${monthAbbr[d.monthIdx]} · transferring to ${transferOtherBranch} on ${_xferDate} — fill remaining days on the destination schedule`
                                  : transferEdge === "in"
                                    ? `${s.name} · ${d.d} ${monthAbbr[d.monthIdx]} · arriving from ${transferOtherBranch} on ${_xferDate} — pre-transfer days are still on the source schedule`
                                    : _loanCell
                                      ? `${s.name} · ${d.d} ${monthAbbr[d.monthIdx]} · working at ${_outgoingLoan.toBranch} (cross-store)`
                                      : isEmergLeave
                                        ? `${s.name} · ${d.d} ${monthAbbr[d.monthIdx]} · Emergency leave (unpaid)`
                                        : `${s.name} · ${d.d} ${monthAbbr[d.monthIdx]} · click to cycle, drag to swap within the week${requested ? ' · 📝 day-off requested' + (requestUnapplied ? ' (not yet on grid)' : '') : ''}`;
                        return (
                          <td key={s.ec + '-' + d.d}
                            draggable={!cellLocked && !!v}
                            onDragStart={e => handleDragStart(e, s.ec, d.d, v, cellLocked)}
                            onDragOver={e => handleDragOver(e, s.ec, d.d)}
                            onDrop={e => handleDrop(e, s.ec, d.d)}
                            onDragEnd={handleDragEnd}
                            onClick={cellLocked ? undefined : () => cycleCell(s.ec, d.d)}
                            title={cellTitle}
                            style={{ ...matCell, padding: 0, height: 30, textAlign: "center", borderBottom: "1px solid #FCE7F3", borderLeft: "1px solid #FCE7F3", borderRight: weekEnd ? "3px solid #BE185D" : "none", cursor: dragCursor, fontSize: 11, fontWeight: 700, userSelect: "none", outline: dropOutline, outlineOffset: -1, opacity: isSrc ? 0.4 : undefined, position: "relative" }}>
                            {cellMat ? "ML"
                              : cellLegal ? "EL"
                                : (isPastLeft || isPreStart) ? "—"
                                  : transferEdge === "out" ? (
                                    <span style={{ fontSize: 9, fontWeight: 800, letterSpacing: "0.04em" }}>
                                      →{transferOtherBranch === "Green Point" ? "GP" : transferOtherBranch.slice(0, 4)}
                                    </span>
                                  )
                                    : transferEdge === "in" ? (
                                      <span style={{ fontSize: 9, fontWeight: 800, letterSpacing: "0.04em" }}>
                                        ←{transferOtherBranch === "Green Point" ? "GP" : transferOtherBranch.slice(0, 4)}
                                      </span>
                                    )
                                      : _loanCell ? (
                                        <span style={{ fontSize: 9, fontWeight: 800, letterSpacing: "0.04em" }}>
                                          →{_outgoingLoan.toBranch === "Green Point" ? "GP" : _outgoingLoan.toBranch.slice(0, 4)}
                                        </span>
                                      )
                                        : isEmergLeave ? "EL" : v}
                            {requestUnapplied && !cellLocked && (
                              <span style={{ position: "absolute", top: 1, right: 2, fontSize: 8, lineHeight: 1, color: "#BE185D", pointerEvents: "none" }}>📝</span>
                            )}
                          </td>
                        );
                      })}
                      <td style={{ padding: "6px 8px", borderLeft: "2px solid #FBCFE8", borderBottom: "1px solid #FCE7F3", textAlign: "center", color: (fullMat || fullLegal) ? "#9ca3af" : "#15803d", fontSize: 11, fontWeight: 700 }}>{(fullMat || fullLegal) ? "—" : counts.w}</td>
                      <td style={{ padding: "6px 8px", borderBottom: "1px solid #FCE7F3", textAlign: "center", color: (fullMat || fullLegal) ? "#9ca3af" : "#991b1b", fontSize: 11, fontWeight: 700 }}>{(fullMat || fullLegal) ? "—" : counts.off}</td>
                    </tr>
                  );
                })}
                {/* Trial nail techs — read-only yellow ghost rows. Not in the
                    saved grid, never editable, never counted in coverage. */}
                {trialGhostRows.map(t => {
                  const trialDaysInCycle = days.filter(d => t._trialDaySet.has(d.year + "-" + String(d.monthIdx + 1).padStart(2, "0") + "-" + String(d.d).padStart(2, "0"))).length;
                  if (trialDaysInCycle === 0) return null;   // no trial days this cycle — don't clutter the grid
                  const startLbl = t._trialStartDate ? new Date(t._trialStartDate + "T12:00:00").toLocaleDateString("en-ZA", { day: "2-digit", month: "short" }) : "";
                  return (
                    <tr key={t._id} style={{ opacity: 0.92 }}>
                      <td style={{ position: "sticky", left: 0, background: "#fefce8", padding: "6px 10px", borderBottom: "1px solid #FCE7F3", color: "#854d0e", fontWeight: 600, fontSize: 12, zIndex: 1 }}>
                        <div style={{ display: "flex", alignItems: "center", gap: 6, flexWrap: "wrap" }}>
                          <span>{t.name}</span>
                          <span style={{ background: "#fef08a", color: "#854d0e", padding: "1px 6px", borderRadius: 4, fontSize: 9, fontWeight: 800, letterSpacing: "0.04em" }}>🧪 TRIAL</span>
                        </div>
                        <div style={{ fontSize: 10, color: "#a16207", marginTop: 1, letterSpacing: "0.02em", fontStyle: "italic" }}>10-day trial · started {startLbl} · not yet on payroll</div>
                      </td>
                      {days.map(d => {
                        const dYmd = d.year + "-" + String(d.monthIdx + 1).padStart(2, "0") + "-" + String(d.d).padStart(2, "0");
                        const weekEnd = d.dow === 0;
                        // Pre-start days grey out (X); trial working days are
                        // yellow (T); weekends & public holidays that fall
                        // inside the trial window read as off (O). Days after
                        // the 10th trial day stay blank.
                        let code = "", cs = { background: "#fff", color: "#e5e7eb" }, title = `${t.name} · on trial`;
                        if (t._trialStartDate && dYmd < t._trialStartDate) {
                          code = "X"; cs = cellStyle("X");
                          title = `${t.name} · not started yet — joins ${startLbl}`;
                        } else if (t._trialDaySet.has(dYmd)) {
                          code = "T"; cs = cellStyle("trial");
                          title = `${t.name} · ${d.d} ${monthAbbr[d.monthIdx]} · trial working day (Mon–Fri, excludes weekends & public holidays)`;
                        } else if (t._trialLastYmd && dYmd <= t._trialLastYmd) {
                          code = "O"; cs = cellStyle("O");
                          title = `${t.name} · ${d.d} ${monthAbbr[d.monthIdx]} · off (${isHoliday(d) ? holidayName(d) : "weekend"} during trial)`;
                        }
                        return (
                          <td key={t._id + "-" + d.d} title={title}
                            style={{ ...cs, padding: 0, height: 30, textAlign: "center", borderBottom: "1px solid #FCE7F3", borderLeft: "1px solid #FCE7F3", borderRight: weekEnd ? "3px solid #BE185D" : "none", fontSize: 11, fontWeight: 700, userSelect: "none", cursor: "default" }}>
                            {code}
                          </td>
                        );
                      })}
                      <td style={{ padding: "6px 8px", borderLeft: "2px solid #FBCFE8", borderBottom: "1px solid #FCE7F3", textAlign: "center", color: "#a16207", fontSize: 11, fontWeight: 700 }}>{trialDaysInCycle || "—"}</td>
                      <td style={{ padding: "6px 8px", borderBottom: "1px solid #FCE7F3", textAlign: "center", color: "#9ca3af", fontSize: 11, fontWeight: 700 }}>—</td>
                    </tr>
                  );
                })}
              </tbody>
              <tfoot>
                <tr>
                  <td style={{ position: "sticky", left: 0, background: "#831843", padding: "12px 10px", borderTop: "3px solid #831843", borderBottom: "3px solid #831843", color: "#FFFFFF", fontSize: 11, fontWeight: 800, letterSpacing: "0.08em", textTransform: "uppercase", zIndex: 2 }}>Working / Needed</td>
                  {(() => {
                    const activeTechs = techs.filter(t => !t.onMat); return days.map(d => {
                      const _dYmd = d.year + "-" + String(d.monthIdx + 1).padStart(2, "0") + "-" + String(d.d).padStart(2, "0");
                      // Count ONLY people actually on THIS store's floor that day.
                      // Annual leave (L) and maternity (ML / on-mat) are already
                      // non-work cells; on top of that we drop anyone whose shift
                      // isn't here — permanently transferred out, or loaned out to
                      // another store for the day.
                      const working = activeTechs.filter(s => {
                        const v = (grid[s.ec] || {})[d.d];
                        if (!(v === "W" || v === "WE" || v === "WB" || v === "WM" || v === "WL" || v === "E")) return false;
                        const _xd = s.transferDate || null;
                        if (_xd && !s.isShadow && s.transferring && _dYmd >= _xd) return false;   // permanently transferred out
                        if ((techLoans || []).some(l => l && String(l.ec || "").trim() === String(s.ec || "").trim() && l.date === _dYmd && l.fromBranch === branch)) return false;   // loaned out to another store today (EC trimmed — padded codes exist)
                        return true;
                      }).length;
                      const needed = minWorkingFor(d, activeTechs.length);
                      const ok = working >= needed;
                      const weekEnd = d.dow === 0;
                      const wknd = d.dow === 0 || d.dow === 6;
                      const busy = isBusyDay(d);
                      const hol = isHoliday(d);
                      const footBg = hol ? "#ede9fe" : busy ? "#fef3c7" : "#FCE7F3";
                      return (
                        <td key={'foot-' + d.year + '-' + d.monthIdx + '-' + d.d}
                          style={{ padding: "10px 2px", borderTop: "3px solid #831843", borderBottom: "3px solid #831843", borderLeft: "1px solid #FBCFE8", borderRight: weekEnd ? "3px solid #BE185D" : "none", textAlign: "center", background: footBg }}>
                          <div style={{ display: "inline-block", padding: "5px 10px", borderRadius: 10, background: ok ? "#15803d" : "#dc2626", color: "#FFFFFF", fontWeight: 900, fontSize: 14, lineHeight: 1, minWidth: 24, boxShadow: ok ? "0 2px 6px rgba(21,128,61,0.32)" : "0 2px 6px rgba(220,38,38,0.40)" }}>
                            {working}
                          </div>
                          <div style={{ fontSize: 11, color: "#831843", marginTop: 4, lineHeight: 1, fontWeight: 700, letterSpacing: "0.04em" }}>/ {needed}</div>
                        </td>
                      );
                    });
                  })()}
                  <td style={{ padding: "12px 8px", borderTop: "3px solid #831843", borderBottom: "3px solid #831843", borderLeft: "2px solid #FBCFE8", background: "#831843" }}></td>
                  <td style={{ padding: "12px 8px", borderTop: "3px solid #831843", borderBottom: "3px solid #831843", background: "#831843" }}></td>
                </tr>
              </tfoot>
            </table>
          </div>
        </>
      )}

      <div style={{ display: "flex", gap: 14, flexWrap: "wrap", marginTop: 14, fontSize: 11, color: "#831843", alignItems: "center" }}>
        <strong>Legend:</strong>
        {["W", "WE", "WL", "O", "R", "L", "ML", "E", "X"].map(c => (
          <span key={c} style={{ display: "inline-flex", alignItems: "center", gap: 6 }}>
            <span style={{ ...(c === "ML" ? { background: "#ede9fe", color: "#6b21a8" } : cellStyle(c)), padding: "2px 7px", borderRadius: 4, fontWeight: 700, minWidth: 22, textAlign: "center" }}>{c}</span>
            {c === "W" ? "Work" : c === "WE" ? "Work early" : c === "WL" ? "Work late" : c === "O" ? "Off" : c === "R" ? "Requested off" : c === "L" ? "Leave" : c === "ML" ? "Maternity leave" : c === "E" ? "Extra cover" : "Pre-start"}
          </span>
        ))}
        <span style={{ display: "inline-flex", alignItems: "center", gap: 6, marginLeft: 8 }}>
          <span style={{ background: "#fef3c7", color: "#92400e", padding: "2px 7px", borderRadius: 4, fontWeight: 700, fontSize: 10 }}>BUSY</span>
          25th–6th — peak revenue period (yellow header)
        </span>
        <span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}>
          <span style={{ background: "#ede9fe", color: "#5b21b6", padding: "2px 7px", borderRadius: 4, fontWeight: 700, fontSize: 10 }}>HOL</span>
          🇿🇦 SA public holiday (lavender header — hover for name)
        </span>
      </div>

      {/* ─── Off-Days Per Week summary table ─────────────────────────── */}
      {techs.length > 0 && (() => {
        // Determine Sunday Group A/B by deterministic alphabetical sort (matches auto-fill)
        const sortedTechs = [...techs].sort((a, b) => (a.ec || "").localeCompare(b.ec || ""));
        const sundayGroup = {};
        sortedTechs.forEach((s, i) => { sundayGroup[s.ec] = (i % 2 === 0) ? "A" : "B"; });

        // Identify busy-period weeks: any FULL week that contains 25-31 of prev month or 1-6 of current month
        const ymP = ym.split("-").map(Number);
        const curMonth = ymP[1], prevMonth = (curMonth === 1) ? 12 : curMonth - 1;
        const isBusyDay = (d) => {
          const m = d.monthIdx + 1;
          if (m === prevMonth && d.d >= 25) return true;
          if (m === curMonth && d.d <= 6) return true;
          return false;
        };
        // Match auto-fill: prefer busy weeks; fall back to earliest full weeks otherwise
        const fullWeekMeta = weekChunks
          .map((w, i) => ({ i, full: w.length === 7, hasBusy: w.some(isBusyDay) }))
          .filter(x => x.full);
        const busyWeekIndices = fullWeekMeta.filter(x => x.hasBusy).map(x => x.i);
        const fallbackWeekIndices = fullWeekMeta.filter(x => !x.hasBusy).sort((a, b) => a.i - b.i).map(x => x.i);
        const designatedCandidates = busyWeekIndices.length > 0 ? busyWeekIndices : fallbackWeekIndices;

        // Each staff gets exactly ONE designated 6-day week per month
        function designatedBusyWeek(staffIdx) {
          if (designatedCandidates.length === 0) return -1;
          return designatedCandidates[staffIdx % designatedCandidates.length];
        }

        // Range label for a week's header (e.g. "27 – 3")
        const rangeLabel = (w) => {
          if (!w.length) return "";
          const first = w[0], last = w[w.length - 1];
          const partial = w.length < 7 ? " (partial)" : "";
          if (first.monthIdx === last.monthIdx)
            return first.d + "–" + last.d + partial;
          return first.d + "–" + last.d + partial;
        };

        // Sunday counters
        const sundaysInPeriod = days.filter(d => d.dow === 0);

        // Status pill style
        const pill = (txt, status, isDesig) => {
          const bgs = { on: "#dcfce7", under: "#fee2e2", over: "#fef3c7", neutral: "#e0f2fe" };
          const fgs = { on: "#15803d", under: "#991b1b", over: "#92400e", neutral: "#075985" };
          return (
            <span style={{ display: "inline-block", padding: "3px 10px", borderRadius: 14, background: bgs[status], color: fgs[status], fontWeight: 700, fontSize: 11, minWidth: 30, textAlign: "center" }}>
              {txt}{isDesig ? "*" : ""}
            </span>
          );
        };

        const dotStyle = (color) => ({ display: "inline-block", width: 10, height: 10, borderRadius: "50%", background: color, marginRight: 4, verticalAlign: "middle" });

        return (
          <div style={{ marginTop: 24, background: "#fff", border: "1px solid #FBCFE8", borderRadius: 14, padding: "18px 20px" }}>
            <div style={{ fontFamily: "'Playfair Display',serif", fontSize: 20, fontWeight: 700, color: "#831843" }}>Off-Days Per Week</div>
            <div style={{ fontSize: 12, color: "#BE185D", marginTop: 4, marginBottom: 14, lineHeight: 1.5 }}>
              Target: <strong>2 off</strong> per week. <strong>*</strong> = the staff's designated 6-day week (target: 1 off).
              <span style={dotStyle("#15803d")}></span>on target ·
              <span style={{ ...dotStyle("#991b1b"), marginLeft: 8 }}></span>under ·
              <span style={{ ...dotStyle("#eab308"), marginLeft: 8 }}></span>over (likely leave/requests).
              &nbsp;&nbsp;<strong>Sundays</strong> shows off-Sundays / total.
            </div>

            <div style={{ overflowX: "auto" }}>
              <table style={{ borderCollapse: "collapse", width: "100%", fontSize: 12 }}>
                <thead>
                  <tr style={{ borderBottom: "2px solid #FBCFE8" }}>
                    <th style={{ padding: "8px 10px", textAlign: "left", color: "#BE185D", fontSize: 10, letterSpacing: "0.06em", textTransform: "uppercase", fontWeight: 700 }}>Staff</th>
                    <th style={{ padding: "8px 10px", color: "#BE185D", fontSize: 10, letterSpacing: "0.06em", textTransform: "uppercase", fontWeight: 700 }}>Grp</th>
                    {weekChunks.map((w, wi) => (
                      <th key={wi} style={{ padding: "8px 8px", color: "#BE185D", fontSize: 10, letterSpacing: "0.06em", textTransform: "uppercase", fontWeight: 700, textAlign: "center", borderRight: wi < weekChunks.length - 1 ? "1px solid #FCE7F3" : "none" }}>
                        Wk {wi + 1}<br />
                        <span style={{ fontSize: 9, fontWeight: 500, color: "#F472B6", textTransform: "none", letterSpacing: "normal" }}>{rangeLabel(w)}</span>
                      </th>
                    ))}
                    <th style={{ padding: "8px 10px", color: "#BE185D", fontSize: 10, letterSpacing: "0.06em", textTransform: "uppercase", fontWeight: 700, textAlign: "center", borderLeft: "2px solid #FBCFE8" }}>Total</th>
                    <th style={{ padding: "8px 10px", color: "#BE185D", fontSize: 10, letterSpacing: "0.06em", textTransform: "uppercase", fontWeight: 700, textAlign: "center" }}>Sundays<br /><span style={{ fontSize: 9, fontWeight: 500, textTransform: "none", letterSpacing: "normal" }}>off / total</span></th>
                  </tr>
                </thead>
                <tbody>
                  {sortedTechs.map((s, sIdx) => {
                    const row = grid[s.ec] || {};
                    const designatedWk = designatedBusyWeek(sIdx);
                    let total = 0, sundaysOff = 0, sundaysWorked = 0;
                    sundaysInPeriod.forEach(d => {
                      const v = row[d.d];
                      if (v === "O" || v === "R" || v === "L") sundaysOff++;
                      else if (v === "W" || v === "WE" || v === "WB" || v === "WM" || v === "WL" || v === "E") sundaysWorked++;
                    });
                    return (
                      <tr key={s.ec} style={{ borderBottom: "1px solid #FCE7F3" }}>
                        <td style={{ padding: "8px 10px" }}>
                          <div style={{ fontWeight: 700, color: "#831843", fontSize: 13 }}>{s.name}</div>
                          <div style={{ fontSize: 10, color: "#9CA3AF", letterSpacing: "0.04em" }}>{s.ec}</div>
                        </td>
                        <td style={{ padding: "8px 10px", textAlign: "center" }}>
                          <span style={{ display: "inline-block", padding: "2px 8px", borderRadius: 10, background: sundayGroup[s.ec] === 'A' ? "#dbeafe" : "#fce7f3", color: sundayGroup[s.ec] === 'A' ? "#1e3a8a" : "#9d174d", fontWeight: 700, fontSize: 11 }}>
                            {sundayGroup[s.ec]}
                          </span>
                        </td>
                        {weekChunks.map((w, wi) => {
                          const offCount = w.filter(d => {
                            const v = row[d.d];
                            return v === "O" || v === "R" || v === "L";
                          }).length;
                          total += offCount;
                          const isDesig = wi === designatedWk;
                          const target = isDesig ? 1 : 2;
                          const isPartial = w.length < 7;
                          let status = "on";
                          if (isPartial) status = "neutral";
                          else if (offCount > target) status = "over";
                          else if (offCount < target) status = "under";
                          return (
                            <td key={wi} style={{ padding: "8px 6px", textAlign: "center", borderRight: wi < weekChunks.length - 1 ? "1px solid #FCE7F3" : "none" }}>
                              {pill(offCount, status, isDesig)}
                            </td>
                          );
                        })}
                        <td style={{ padding: "8px 10px", textAlign: "center", borderLeft: "2px solid #FBCFE8" }}>
                          <span style={{ display: "inline-block", padding: "3px 12px", borderRadius: 14, background: "#e0f2fe", color: "#075985", fontWeight: 800, fontSize: 12 }}>{total}</span>
                        </td>
                        <td style={{ padding: "8px 10px", textAlign: "center" }}>
                          <span style={{ display: "inline-block", padding: "3px 10px", borderRadius: 14, background: "#fdf2f8", color: "#831843", fontWeight: 700, fontSize: 11 }}>
                            {sundaysOff} / {sundaysInPeriod.length}
                          </span>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>

            {/* Designated 6-day weeks summary */}
            {designatedCandidates.length > 0 && (
              <div style={{ marginTop: 18, background: "#FCE7F3", border: "1px solid #FBCFE8", borderRadius: 10, padding: "12px 14px", fontSize: 12, color: "#831843" }}>
                <div style={{ fontWeight: 700, marginBottom: 6 }}>
                  📌 Designated 6-day weeks
                  {busyWeekIndices.length > 0
                    ? <span> (preferring busy period <strong>{prevMonth}/25 – {curMonth}/6</strong>):</span>
                    : <span style={{ color: "#92400e" }}> (no busy-period weeks in this period — falling back to earliest full week):</span>}
                </div>
                <ul style={{ margin: 0, paddingLeft: 20, lineHeight: 1.6 }}>
                  {designatedCandidates.map(wIdx => {
                    const staffOnThisWeek = sortedTechs.filter((_, i) => designatedBusyWeek(i) === wIdx);
                    const isBusyWk = busyWeekIndices.includes(wIdx);
                    return (
                      <li key={wIdx}>
                        <strong>Wk {wIdx + 1}</strong> ({rangeLabel(weekChunks[wIdx])})
                        {isBusyWk ? <span style={{ background: "#fef3c7", color: "#92400e", padding: "1px 6px", borderRadius: 4, fontSize: 10, marginLeft: 6, fontWeight: 700 }}>BUSY</span> : <span style={{ background: "#e5e7eb", color: "#475569", padding: "1px 6px", borderRadius: 4, fontSize: 10, marginLeft: 6, fontWeight: 700 }}>FALLBACK</span>}
                        &nbsp;— {staffOnThisWeek.length} staff:&nbsp;{staffOnThisWeek.map(s => s.name.split(" ")[0]).join(", ")}
                      </li>
                    );
                  })}
                </ul>
              </div>
            )}
          </div>
        );
      })()}
    </div>
  );
}

// ─── PIN LOGIN SCREEN ─────────────────────────────────────────────────────────
// Gates the whole app behind a 4-digit personal PIN so the activity log can
// attribute every edit / transfer / off-board / schedule save to a specific
// staff member. Session is stored in sessionStorage (cleared on tab close).
function PinLogin(props) {
  const { onUnlock } = props;
  const [pin, setPin] = useState("");
  const [error, setError] = useState("");

  const submit = (e) => {
    if (e && e.preventDefault) e.preventDefault();
    const store = (props && props.users) || window.__BOA_APP_USERS || STAFF_USERS;
    const u = store[pin] || STAFF_USERS[pin];
    if (!u) {
      setError("Wrong PIN. Please try again.");
      setPin("");
      return;
    }
    const session = { pin, name: u.name, role: u.role, demo: !!u.demo, isOwner: !!u.isOwner, voucherEntryOnly: !!u.voucherEntryOnly, ccOnly: !!u.ccOnly, hideCategories: u.hideCategories || [], hideTabs: u.hideTabs || [], showTabs: u.showTabs || [], readOnlyTabs: u.readOnlyTabs || [], stores: Array.isArray(u.stores) ? u.stores.slice() : [], signedInAt: new Date().toISOString() };
    try { sessionStorage.setItem(PIN_SESSION_KEY, JSON.stringify(session)); } catch (_) { }
    window.BOA_CURRENT_USER = session;
    onUnlock(session);
  };

  return (
    <div style={{ minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center", background: "linear-gradient(180deg,#FCE7F3 0%,#FFFFFF 50%)", fontFamily: "'DM Sans',sans-serif" }}>
      <form onSubmit={submit} style={{ background: "#fff", padding: "36px 40px", borderRadius: 18, border: "1px solid #FBCFE8", boxShadow: "0 10px 30px rgba(190,24,93,0.15)", width: 340, textAlign: "center" }}>
        <div style={{ fontFamily: "'Playfair Display',serif", fontSize: 28, color: "#831843", fontWeight: 700, marginBottom: 6 }}>BOA HR</div>
        <div style={{ fontSize: 12, color: "#BE185D", letterSpacing: "0.16em", textTransform: "uppercase", fontWeight: 700, marginBottom: 22 }}>Staff Sign-In</div>
        <label style={{ display: "block", fontSize: 11, fontWeight: 700, color: "#831843", letterSpacing: "0.08em", textAlign: "left", marginBottom: 6 }}>ENTER YOUR 4-DIGIT PIN</label>
        <input
          type="password"
          inputMode="numeric"
          pattern="[0-9]*"
          maxLength={4}
          value={pin}
          autoFocus
          onChange={e => { setPin(e.target.value.replace(/\D/g, "").slice(0, 4)); setError(""); }}
          style={{ width: "100%", padding: "12px 14px", fontSize: 22, letterSpacing: "0.5em", textAlign: "center", border: "1px solid #FBCFE8", borderRadius: 10, fontFamily: "inherit", color: "#831843" }}
          placeholder="••••"
        />
        {error && <div style={{ color: "#dc2626", fontSize: 12, marginTop: 10, fontWeight: 600 }}>{error}</div>}
        <button type="submit" disabled={pin.length !== 4}
          style={{ marginTop: 18, width: "100%", padding: "11px 14px", background: pin.length === 4 ? "#BE185D" : "#FBCFE8", color: pin.length === 4 ? "#fff" : "#9F1A4F", border: "none", borderRadius: 10, cursor: pin.length === 4 ? "pointer" : "not-allowed", fontFamily: "inherit", fontSize: 13, fontWeight: 700, letterSpacing: "0.06em" }}>
          UNLOCK
        </button>
        <div style={{ fontSize: 10, color: "#9CA3AF", marginTop: 14 }}>Each action you take is logged with your name.</div>
      </form>
    </div>
  );
}

// ─── VOUCHER ENTRY (restricted PIN) ─────────────────────────────────────────
// Bare, stripped view for the "Voucher Entry" login (PIN 6666). No nav, tabs or
// categories — just a spreadsheet-style grid for capturing Shopify→Fresha
// vouchers, which bulk-insert into the Supabase `vouchers` table. The same
// table is read by the kiosk manager voucher lookup.
const VOUCHER_BLANK_ROWS = 25;
function blankVoucherRow() { return { last4: "", fresha: "", amount: "", expiry: "", order: "" }; }
function makeBlankVoucherRows(n) {
  const rows = [];
  for (let i = 0; i < n; i++) rows.push(blankVoucherRow());
  return rows;
}

// ─── Shared Voucher-Admin styling tokens ────────────────────────────────────
// Modern "soft-glow + bold" look reused across VoucherEntryGrid / VoucherAdmin /
