// ─── INSTALL TO DEVICE (PWA) ────────────────────────────────────────────────
// "Install to Device" pill for the header. The browser's install prompt is
// captured before React mounts (see index.html → __BOA_HR_INSTALL_PROMPT);
// this component reads it and listens for the custom installable/installed
// events. It renders nothing once the app is installed / running standalone,
// or when the browser can't offer an install (and it isn't iOS Safari).
function InstallButton() {
  const isStandalone = (window.matchMedia && window.matchMedia('(display-mode: standalone)').matches) || window.navigator.standalone === true;
  const isIos = /iPad|iPhone|iPod/.test(navigator.userAgent) && !window.MSStream;
  const [promptEvt, setPromptEvt] = React.useState(window.__BOA_HR_INSTALL_PROMPT || null);
  const [installed, setInstalled] = React.useState(false);
  const [iosHelp, setIosHelp] = React.useState(false);

  React.useEffect(() => {
    const onAvail = () => setPromptEvt(window.__BOA_HR_INSTALL_PROMPT || null);
    const onInstalled = () => { setInstalled(true); setPromptEvt(null); };
    window.addEventListener('boa-hr-installable', onAvail);
    window.addEventListener('boa-hr-installed', onInstalled);
    window.addEventListener('appinstalled', onInstalled);
    return () => {
      window.removeEventListener('boa-hr-installable', onAvail);
      window.removeEventListener('boa-hr-installed', onInstalled);
      window.removeEventListener('appinstalled', onInstalled);
    };
  }, []);

  // Already installed / launched from home screen → nothing to show.
  if (installed || isStandalone) return null;
  // Chrome/Edge/Android only show the button once the prompt is available.
  // iOS Safari never fires the prompt, so show it there with manual steps.
  if (!promptEvt && !isIos) return null;

  const onClick = async () => {
    if (isIos && !promptEvt) {
      setIosHelp(true);
      return;
    }
    if (!promptEvt) return;
    promptEvt.prompt();
    try { await promptEvt.userChoice; } catch (_) { }
    window.__BOA_HR_INSTALL_PROMPT = null;
    setPromptEvt(null);
  };

  return (
    <>
      <button onClick={onClick} title="Install BOA HR to this device"
        style={{ display: "inline-flex", alignItems: "center", gap: 6, background: "#fff", color: "#BE185D", border: "1px solid rgba(255,255,255,0.7)", borderRadius: 9, padding: "8px 14px", cursor: "pointer", fontFamily: "inherit", fontWeight: 700, fontSize: 12, boxShadow: "0 1px 4px rgba(131,24,67,0.18)" }}>
        <span>⬇️</span> Install to Device
      </button>
      {iosHelp && (
        <div onClick={() => setIosHelp(false)}
          style={{ position: "fixed", inset: 0, background: "rgba(76,5,25,0.45)", backdropFilter: "blur(3px)", zIndex: 100000, display: "flex", alignItems: "center", justifyContent: "center", padding: 20, fontFamily: "'Outfit',system-ui,sans-serif" }}>
          <div onClick={(e) => e.stopPropagation()}
            style={{ background: "#fff", borderRadius: 18, padding: "26px 24px", maxWidth: 360, width: "100%", textAlign: "center", boxShadow: "0 25px 50px -12px rgba(0,0,0,0.35)", color: "#111827" }}>
            <div style={{ fontSize: 38, marginBottom: 8 }}>📲</div>
            <div style={{ fontFamily: "'Playfair Display',serif", fontSize: 20, fontWeight: 800, color: "#9f1239", marginBottom: 6 }}>Install BOA HR</div>
            <div style={{ fontSize: 13, color: "#4b5563", lineHeight: 1.55, marginBottom: 16 }}>
              Add the app to your Home Screen for a full-screen, app-like experience.
            </div>
            <div style={{ textAlign: "left", fontSize: 13, color: "#374151", lineHeight: 1.7, background: "#FCF5F7", border: "1px solid #FBCFE8", borderRadius: 12, padding: "12px 14px", marginBottom: 16 }}>
              <div>1. Tap the <strong>Share</strong> button <span style={{ fontSize: 15 }}>􀈂</span> (the square with an up arrow) at the bottom of Safari.</div>
              <div style={{ marginTop: 6 }}>2. Scroll down and choose <strong>“Add to Home Screen”</strong> ➕.</div>
              <div style={{ marginTop: 6 }}>3. Tap <strong>Add</strong> — the BOA icon appears on your Home Screen.</div>
            </div>
            <button onClick={() => setIosHelp(false)}
              style={{ width: "100%", background: "#BE185D", color: "#fff", border: "none", borderRadius: 10, padding: "11px", fontWeight: 700, fontSize: 13, fontFamily: "inherit", cursor: "pointer" }}>Got it</button>
          </div>
        </div>
      )}
    </>
  );
}

// ─── VOUCHER ADMIN (Owner / Master Admin) ───────────────────────────────────
// Upload the Fresha "Gift Card Transactions" CSV → store in Supabase and
// refresh each voucher's remaining balance + transaction history. Re-uploads
// are deduped by transaction ID, so only new transactions are added.

// Minimal RFC-4180-ish CSV parser (handles quoted fields / embedded commas).
function parseCsvRows(text) {
  const rows = [];
  let row = [], field = "", inQ = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQ) {
      if (c === '"') { if (text[i + 1] === '"') { field += '"'; i++; } else inQ = false; }
      else field += c;
    } else if (c === '"') { inQ = true; }
    else if (c === ',') { row.push(field); field = ""; }
    else if (c === '\n') { row.push(field); rows.push(row); row = []; field = ""; }
    else if (c === '\r') { /* ignore */ }
    else field += c;
  }
  if (field.length || row.length) { row.push(field); rows.push(row); }
  return rows;
}
function parseCsvObjects(text) {
  text = String(text || "").replace(/^﻿/, ""); // strip UTF-8 BOM if present
  const rows = parseCsvRows(text).filter(r => r.length > 1 || (r[0] || "").trim() !== "");
  if (!rows.length) return [];
  const headers = rows[0].map(h => String(h || "").trim().toLowerCase());
  return rows.slice(1).map(r => {
    const o = {};
    headers.forEach((h, i) => { o[h] = r[i] != null ? r[i] : ""; });
    return o;
  });
}

function VoucherAdmin({ currentUser }) {
  const [sub, setSub] = React.useState("uploads");      // "uploads" | "entry"
  const [busy, setBusy] = React.useState(false);
  const [progress, setProgress] = React.useState(null); // { phase, done, total }
  const [result, setResult] = React.useState(null);     // { ok, msg }
  const [stats, setStats] = React.useState(null);       // { count, lastPaymentDate }
  const [vUpload, setVUpload] = React.useState(null);   // { createdAt, orderNumber, count }
  const fileRef = React.useRef(null);

  const loadStats = React.useCallback(async () => {
    try {
      if (window.BOA_DB && window.BOA_DB.giftCardTxnStats) setStats(await window.BOA_DB.giftCardTxnStats());
    } catch (_) { /* table may not exist yet */ }
    try {
      if (window.BOA_DB && window.BOA_DB.latestVoucherUpload) setVUpload(await window.BOA_DB.latestVoucherUpload());
    } catch (_) { /* non-fatal */ }
  }, []);
  React.useEffect(() => { loadStats(); }, [loadStats]);
  // Refresh when returning from the Voucher Entry sub-tab (new batch may have been entered).
  React.useEffect(() => { if (sub === "uploads") loadStats(); }, [sub, loadStats]);

  const onFile = async (e) => {
    const file = e.target.files && e.target.files[0];
    if (e.target) e.target.value = ""; // allow re-selecting the same file
    if (!file) return;
    if (!window.BOA_DB || !window.BOA_DB.importGiftCardTransactions) {
      setResult({ ok: false, msg: "Database not ready. Reload and try again." });
      return;
    }
    setBusy(true); setResult(null); setProgress({ phase: "Reading file…", done: 0, total: 0 });
    try {
      const text = await file.text();
      const objs = parseCsvObjects(text);
      if (!objs.length) throw new Error("No rows found in that CSV.");
      const mapped = objs.map(r => ({
        id: r["id"], gift_card: r["gift card"], payment_date: r["payment date"],
        location: r["location"], amount: r["amount"], txn_type: r["transaction type"],
        client_name: r["client name"], appointment_ref: r["appointment ref"]
      }));
      setProgress({ phase: "Uploading transactions…", done: 0, total: mapped.length });
      const imp = await window.BOA_DB.importGiftCardTransactions(mapped, (done, total) => setProgress({ phase: "Uploading transactions…", done, total }));
      setProgress({ phase: "Updating voucher balances…", done: 0, total: 0 });
      const rec = await window.BOA_DB.recomputeVoucherBalancesForCodes(imp.codes, (done, total) => setProgress({ phase: "Updating voucher balances…", done, total }));
      setResult({ ok: true, msg: imp.saved.toLocaleString() + " transactions imported · balances updated for " + rec.vouchers + " voucher" + (rec.vouchers === 1 ? "" : "s") + "." });
      loadStats();
    } catch (err) {
      setResult({ ok: false, msg: "Import failed: " + ((err && err.message) || String(err)) });
    } finally {
      setBusy(false); setProgress(null);
    }
  };

  const recomputeAll = async () => {
    if (busy || !window.BOA_DB || !window.BOA_DB.recomputeAllVoucherBalances) return;
    setBusy(true); setResult(null); setProgress({ phase: "Recomputing all balances…", done: 0, total: 0 });
    try {
      const rec = await window.BOA_DB.recomputeAllVoucherBalances((done, total) => setProgress({ phase: "Recomputing all balances…", done, total }));
      setResult({ ok: true, msg: "Recomputed balances for " + rec.vouchers + " voucher" + (rec.vouchers === 1 ? "" : "s") + "." });
    } catch (err) {
      setResult({ ok: false, msg: "Recompute failed: " + ((err && err.message) || String(err)) });
    } finally {
      setBusy(false); setProgress(null);
    }
  };

  const pct = progress && progress.total ? Math.round((progress.done / progress.total) * 100) : null;
  const fmtUp = (d) => d ? new Date(d).toLocaleDateString(undefined, { day: "2-digit", month: "short", year: "numeric" }) : "—";
  const fmtUpAt = (d) => {
    if (!d) return "—";
    const x = new Date(d);
    if (isNaN(x.getTime())) return "—";
    return x.toLocaleDateString(undefined, { day: "2-digit", month: "short", year: "numeric" }) +
      " · " + x.toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit" });
  };

  return (
    <div className="va-root" style={{ fontFamily: "'Outfit',system-ui,sans-serif", color: "#831843", width: "100%" }}>
      <style>{VA_STYLE}</style>

      <div style={VA.hero}>
        <div style={VA.heroBadge}>💳</div>
        <div style={{ minWidth: 0 }}>
          <div style={{ fontFamily: "'Playfair Display',serif", fontSize: 25, fontWeight: 700, color: VA.ink, lineHeight: 1.1 }}>Voucher Admin</div>
          <div style={{ fontSize: 13, color: "#9D7387", marginTop: 3 }}>Codes · transaction uploads · lookup audits</div>
        </div>
      </div>

      {(stats || vUpload) && (
        <div style={{ display: "flex", gap: 12, flexWrap: "wrap", marginBottom: 16 }}>
          {stats && (
            <div style={VA.statTile}>
              <div style={{ fontSize: 11, fontWeight: 800, color: "#B86A8B", textTransform: "uppercase", letterSpacing: "0.05em" }}>Transactions stored</div>
              <div style={{ fontFamily: "'Outfit',sans-serif", fontSize: 23, fontWeight: 800, color: VA.accent, marginTop: 3 }}>{(stats.count || 0).toLocaleString()}</div>
            </div>
          )}
          {stats && (
            <div style={VA.statTile}>
              <div style={{ fontSize: 11, fontWeight: 800, color: "#B86A8B", textTransform: "uppercase", letterSpacing: "0.05em" }}>Latest transaction</div>
              <div style={{ fontFamily: "'Outfit',sans-serif", fontSize: 23, fontWeight: 800, color: VA.accent, marginTop: 3 }}>{fmtUp(stats.lastPaymentDate)}</div>
            </div>
          )}
          {vUpload && (
            <div style={VA.statTile}>
              <div style={{ fontSize: 11, fontWeight: 800, color: "#B86A8B", textTransform: "uppercase", letterSpacing: "0.05em" }}>Latest voucher upload</div>
              <div style={{ fontFamily: "'Outfit',sans-serif", fontSize: 17, fontWeight: 800, color: VA.accent, marginTop: 3 }}>{vUpload.createdAt ? fmtUpAt(vUpload.createdAt) : "—"}</div>
              <div style={{ fontSize: 12, color: "#9D7387", marginTop: 3 }}>
                {vUpload.orderNumber ? <>Order <span style={VA.codeChip}>{vUpload.orderNumber}</span></> : "No vouchers entered yet"}
                {vUpload.count ? <> · {vUpload.count.toLocaleString()} stored</> : null}
              </div>
            </div>
          )}
        </div>
      )}

      <div style={{ display: "flex", gap: 8, marginBottom: 18, flexWrap: "wrap" }}>
        <button className="va-tab" onClick={() => setSub("uploads")} style={VA.tab(sub === "uploads")}>📤 Transaction Uploads</button>
        <button className="va-tab" onClick={() => setSub("entry")} style={VA.tab(sub === "entry")}>🎟️ Voucher Entry</button>
        {currentUser?.isOwner && (
          <button className="va-tab" onClick={() => setSub("audit")} style={VA.tab(sub === "audit")}>🔍 Audit</button>
        )}
      </div>

      {sub === "audit" && currentUser?.isOwner && (
        <VoucherAuditPanel />
      )}

      {sub === "entry" && (
        <VoucherEntryGrid />
      )}

      {sub === "uploads" && (<>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(360px, 1fr))", gap: 16, marginBottom: 16, alignItems: "start" }}>
          <div style={{ ...VA.card, marginBottom: 0 }}>
            <VaSectionHead icon="📤" title="Upload Gift Card Transactions" sub="Keep voucher balances up to date" g1="#FCE7F3" g2="#FBCFE8" />
            <div style={{ fontSize: 12.5, color: "#9D7387", marginBottom: 14, lineHeight: 1.5 }}>
              Export from Fresha → Gift Card Transactions, then choose the CSV here. Existing transactions are skipped automatically — re-uploads only add new rows.
            </div>
            <label className="va-drop" style={{ display: "flex", alignItems: "center", gap: 12, padding: "14px 16px", border: "1.5px dashed #F4A8CC", borderRadius: 13, background: "#FFF7FB", cursor: busy ? "not-allowed" : "pointer", transition: "all .15s" }}>
              <span style={VA.badge("#FCE7F3", "#FBCFE8")}>⬆️</span>
              <span style={{ fontSize: 13, fontWeight: 700, color: VA.ink }}>{busy ? "Working…" : "Choose CSV file…"}</span>
              <input ref={fileRef} type="file" accept=".csv,text/csv" disabled={busy} onChange={onFile} style={{ display: "none" }} />
            </label>
            {stats && (
              <div style={{ fontSize: 12, color: "#9D7387", marginTop: 12 }}>
                Stored <strong style={{ color: VA.ink }}>{(stats.count || 0).toLocaleString()}</strong> transactions
                {stats.lastPaymentDate ? <> · latest payment <strong style={{ color: VA.ink }}>{fmtUp(stats.lastPaymentDate)}</strong></> : null}
              </div>
            )}
          </div>

          <div style={{ ...VA.card, marginBottom: 0 }}>
            <VaSectionHead icon="♻️" title="Recompute balances" g1="#FCE7F3" g2="#FBCFE8" />
            <div style={{ fontSize: 12.5, color: "#9D7387", marginBottom: 14, lineHeight: 1.5 }}>
              Balances refresh automatically on upload and when vouchers are entered. Use this only if you need to rebuild every voucher's balance from scratch.
            </div>
            <button className="va-btn" onClick={recomputeAll} disabled={busy} style={VA.ghostBtn}>
              Recompute all balances
            </button>
          </div>
        </div>

        {progress && (
          <div style={VA.card}>
            <div style={{ fontSize: 13, fontWeight: 700, marginBottom: 10, color: VA.ink }}>{progress.phase}{pct != null ? " · " + pct + "%" : ""}</div>
            <div style={{ height: 10, background: "#FCE7F3", borderRadius: 999, overflow: "hidden" }}>
              <div style={{ height: "100%", width: (pct != null ? pct : 100) + "%", background: "linear-gradient(90deg,#BE185D,#F472B6)", borderRadius: 999, transition: "width 0.2s", opacity: pct != null ? 1 : 0.5 }} />
            </div>
            {progress.total ? <div style={{ fontSize: 11, color: "#B86A8B", marginTop: 7 }}>{progress.done.toLocaleString()} / {progress.total.toLocaleString()}</div> : null}
          </div>
        )}

        {result && (
          <div style={{
            display: "inline-flex", alignItems: "center", gap: 8, padding: "11px 16px", borderRadius: 12, fontSize: 13, fontWeight: 700,
            background: result.ok ? "#ECFDF5" : "#FEF2F2", border: "1px solid " + (result.ok ? "#A7F3D0" : "#FECACA"),
            color: result.ok ? "#15803D" : "#B91C1C"
          }}>
            {result.ok ? "✓ " : "⚠️ "}{result.msg}
          </div>
        )}
      </>)}
    </div>
  );
}

// Owner-only audit of kiosk voucher lookups (Voucher Admin → Audit sub-tab).
// Joins the voucher_lookups log to gift_card_transactions to answer, over a
// chosen window: was each looked-up card redeemed, and on the SAME day? Plus a
// flagged list (padded/shortcut entries + same-card/different-full-code). All
// reads go through window.BOA_DB helpers; results are only as fresh as the last
// Gift Card Transactions upload (surfaced as a caveat).
function VoucherAuditPanel() {
  const todayYmd = () => { const n = new Date(); return n.getFullYear() + "-" + String(n.getMonth() + 1).padStart(2, "0") + "-" + String(n.getDate()).padStart(2, "0"); };
  const daysAgoYmd = (n) => { const d = new Date(); d.setDate(d.getDate() - n); return d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0") + "-" + String(d.getDate()).padStart(2, "0"); };
  const [fromYmd, setFromYmd] = React.useState(daysAgoYmd(30));
  const [toYmd, setToYmd] = React.useState(todayYmd());
  const [busy, setBusy] = React.useState("");           // which action is running
  const [error, setError] = React.useState(null);
  const [dayMatch, setDayMatch] = React.useState(null);
  const [unredeemed, setUnredeemed] = React.useState(null);
  const [flagged, setFlagged] = React.useState(null);

  const card = VA.card;
  const fmtMoney = (x) => { const n = Number(String(x == null ? "" : x).replace(/[^0-9.\-]/g, "")); return isNaN(n) ? "—" : "R" + n.toFixed(2); };
  const fmtDate = (x) => x ? new Date(x).toLocaleDateString(undefined, { day: "2-digit", month: "short", year: "numeric" }) : "—";
  const fmtDateTime = (x) => x ? new Date(x).toLocaleString(undefined, { day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit" }) : "—";
  const setPreset = (n) => { setFromYmd(daysAgoYmd(n)); setToYmd(todayYmd()); };

  const runDayMatch = async () => {
    if (!(window.BOA_DB && window.BOA_DB.auditVoucherDayMatch)) { setError("Database not ready."); return; }
    setBusy("daymatch"); setError(null);
    try { setDayMatch(await window.BOA_DB.auditVoucherDayMatch({ fromYmd, toYmd })); }
    catch (e) { setError("Audit failed: " + ((e && e.message) || e)); }
    finally { setBusy(""); }
  };
  const runUnredeemed = async () => {
    if (!(window.BOA_DB && window.BOA_DB.auditUnredeemedLookups)) { setError("Database not ready."); return; }
    setBusy("unredeemed"); setError(null);
    try { setUnredeemed(await window.BOA_DB.auditUnredeemedLookups({ fromYmd, toYmd })); }
    catch (e) { setError("Audit failed: " + ((e && e.message) || e)); }
    finally { setBusy(""); }
  };
  const runFlagged = async () => {
    if (!(window.BOA_DB && window.BOA_DB.listVoucherLookups)) { setError("Database not ready."); return; }
    setBusy("flagged"); setError(null);
    try {
      const all = await window.BOA_DB.listVoucherLookups({ fromYmd, toYmd });
      const padded = all.filter(l => l.suspicious_pad);
      // Same card, different full code: group lookups by fresha_code, flag any
      // card seen with more than one distinct typed code.
      const byCode = {};
      all.forEach(l => {
        if (!l.fresha_code || !l.typed_code) return;
        const k = String(l.fresha_code).toUpperCase();
        (byCode[k] = byCode[k] || new Set()).add(l.typed_code);
      });
      const mismatches = Object.keys(byCode).filter(k => byCode[k].size > 1).map(k => ({
        fresha_code: k, codes: Array.from(byCode[k]),
        lookups: all.filter(l => String(l.fresha_code).toUpperCase() === k)
      }));
      setFlagged({ padded, mismatches });
    } catch (e) { setError("Audit failed: " + ((e && e.message) || e)); }
    finally { setBusy(""); }
  };

  const th = { ...VA.th, padding: "9px 10px" };
  const td = { ...VA.td };
  const tableWrap = { overflowX: "auto", borderRadius: 12, border: "1px solid #FBCFE8", background: "linear-gradient(180deg,#ffffff,#fffafc)", boxShadow: "0 4px 14px rgba(190,24,93,0.05)" };
  const theadRow = { background: "linear-gradient(180deg,#FDEAF3,#FCE7F3)" };

  return (
    <div style={{ width: "100%" }}>
      <div style={{ fontSize: 12.5, color: "#9D7387", marginBottom: 14, lineHeight: 1.5 }}>
        Audit kiosk gift-card lookups against Fresha redemptions. Results are only as fresh as the latest Gift Card Transactions upload.
      </div>

      <div style={card}>
        <VaSectionHead icon="🗓️" title="Lookup window" g1="#FCE7F3" g2="#FBCFE8" />
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 14 }}>
          {[{ n: 1, l: "Today" }, { n: 7, l: "7 days" }, { n: 30, l: "30 days" }, { n: 90, l: "90 days" }, { n: 365, l: "1 year" }].map(p => {
            const active = toYmd === todayYmd() && fromYmd === daysAgoYmd(p.n);
            return <button key={p.n} className="va-tab" onClick={() => setPreset(p.n)} style={VA.tab(active)}>{p.l}</button>;
          })}
        </div>
        <div style={{ display: "flex", gap: 14, flexWrap: "wrap", alignItems: "flex-end" }}>
          <label style={{ fontSize: 11, fontWeight: 800, color: "#B86A8B", textTransform: "uppercase", letterSpacing: "0.05em" }}>From<br />
            <input className="va-input" type="date" value={fromYmd} max={toYmd} onChange={e => setFromYmd(e.target.value)} style={{ ...VA.input, width: "auto", marginTop: 5 }} />
          </label>
          <label style={{ fontSize: 11, fontWeight: 800, color: "#B86A8B", textTransform: "uppercase", letterSpacing: "0.05em" }}>To<br />
            <input className="va-input" type="date" value={toYmd} min={fromYmd} max={todayYmd()} onChange={e => setToYmd(e.target.value)} style={{ ...VA.input, width: "auto", marginTop: 5 }} />
          </label>
        </div>
      </div>

      {error && (<div style={{ ...VA.pill("red"), padding: "11px 16px", borderRadius: 12, fontSize: 13, marginBottom: 16 }}>⚠️ {error}</div>)}

      <div style={card}>
        <VaSectionHead icon="🗓️" title="Looked up vs redeemed — day mismatch" sub="Redeemed on a different day than the lookup" g1="#FCE7F3" g2="#FBCFE8" />
        <div style={{ fontSize: 12.5, color: "#9D7387", marginBottom: 14, lineHeight: 1.5 }}>Cards looked up in the window that were redeemed on a <strong style={{ color: VA.ink }}>different day</strong> than the lookup. Returns the affected cards and their full transactions.</div>
        <button className="va-btn" onClick={runDayMatch} disabled={!!busy} style={VA.primaryBtn(!!busy)}>{busy === "daymatch" ? "Auditing…" : "Run day-match audit"}</button>
        {dayMatch && (
          <div style={{ marginTop: 16 }}>
            <div style={{ marginBottom: 10 }}><span style={VA.pill(dayMatch.mismatches.length ? "red" : "green")}>{dayMatch.mismatches.length} mismatch{dayMatch.mismatches.length === 1 ? "" : "es"}</span> <span style={{ fontSize: 12, color: "#9D7387", marginLeft: 6 }}>transactions latest {fmtDate(dayMatch.lastPaymentDate)}</span></div>
            {dayMatch.mismatches.length === 0 ? <div style={{ fontSize: 13, color: "#15803D", fontWeight: 600 }}>✓ No day mismatches in this window.</div> : dayMatch.mismatches.map((m, i) => (
              <div key={i} style={{ border: "1px solid #FCE7F3", borderRadius: 12, padding: 12, marginBottom: 10, background: "#FFFCFE" }}>
                <div style={{ fontSize: 13, fontWeight: 700, color: VA.ink, marginBottom: 2 }}>•••• {m.lookup.last4} · {fmtMoney(m.lookup.amount)} · <span style={VA.codeChip}>{m.lookup.fresha_code}</span></div>
                <div style={{ fontSize: 12, color: "#9D7387", marginBottom: 8 }}>Looked up {fmtDateTime(m.lookup.looked_up_at)} by <strong style={{ color: VA.ink }}>{m.lookup.manager_name || "—"}</strong> @ {m.lookup.branch || "—"}</div>
                <div style={tableWrap}>
                  <table style={{ width: "100%", borderCollapse: "collapse" }}>
                    <thead><tr style={theadRow}><th style={th}>Redeemed</th><th style={th}>Branch</th><th style={th}>Client</th><th style={th}>Appt</th><th style={{ ...th, textAlign: "right" }}>Amount</th></tr></thead>
                    <tbody>{m.txns.map((t, j) => (
                      <tr key={j} className="va-row"><td style={td}>{fmtDateTime(t.payment_date)}</td><td style={td}>{t.location || "—"}</td><td style={td}>{t.client_name || "—"}</td><td style={td}><span style={VA.codeChip}>{t.appointment_ref || "—"}</span></td><td style={{ ...td, textAlign: "right", fontWeight: 700, color: VA.ink }}>{fmtMoney(t.amount)}</td></tr>
                    ))}</tbody>
                  </table>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      <div style={card}>
        <VaSectionHead icon="🚦" title="Looked up but not redeemed" sub="No redemption on or after the lookup day" g1="#FCE7F3" g2="#FBCFE8" />
        <div style={{ fontSize: 12.5, color: "#9D7387", marginBottom: 14, lineHeight: 1.5 }}>Cards looked up in the window with <strong style={{ color: VA.ink }}>no redemption</strong> on or after the lookup day. Repeated lookups of the same unused card show as a count.</div>
        <button className="va-btn" onClick={runUnredeemed} disabled={!!busy} style={VA.primaryBtn(!!busy)}>{busy === "unredeemed" ? "Auditing…" : "Find unredeemed lookups"}</button>
        {unredeemed && (
          <div style={{ marginTop: 16 }}>
            <div style={{ ...VA.pill("amber"), marginBottom: 10, fontWeight: 600 }}>⚠️ Accurate to the latest upload — transactions last updated {fmtDate(unredeemed.lastPaymentDate)}. A card may simply not be in the latest CSV yet.</div>
            {unredeemed.cards.length === 0 ? <div style={{ fontSize: 13, color: "#15803D", fontWeight: 600 }}>✓ Every looked-up card has a following redemption.</div> : (
              <div style={tableWrap}>
                <table style={{ width: "100%", borderCollapse: "collapse" }}>
                  <thead><tr style={theadRow}><th style={th}>Card</th><th style={th}>Amount</th><th style={{ ...th, textAlign: "center" }}>Lookups</th><th style={th}>Last looked up</th><th style={th}>By</th><th style={th}>Branch</th></tr></thead>
                  <tbody>{unredeemed.cards.map((c, i) => (
                    <tr key={i} className="va-row"><td style={td}>•••• {c.last4} · <span style={VA.codeChip}>{c.fresha_code}</span></td><td style={td}>{fmtMoney(c.amount)}</td><td style={{ ...td, textAlign: "center", fontWeight: 800, color: c.lookupCount > 1 ? "#B91C1C" : VA.ink }}>{c.lookupCount}</td><td style={td}>{fmtDateTime(c.lastLookupAt)}</td><td style={td}>{c.lastBy || "—"}</td><td style={td}>{c.branch || "—"}</td></tr>
                  ))}</tbody>
                </table>
              </div>
            )}
          </div>
        )}
      </div>

      <div style={card}>
        <VaSectionHead icon="⚑" title="Flagged lookups" sub="Padded entries + same card, different code" g1="#FCE7F3" g2="#FBCFE8" />
        <div style={{ fontSize: 12.5, color: "#9D7387", marginBottom: 14, lineHeight: 1.5 }}>Shortcut/padded entries (the characters before the last 4 are all the same) and cards looked up with more than one distinct full code.</div>
        <button className="va-btn" onClick={runFlagged} disabled={!!busy} style={VA.primaryBtn(!!busy)}>{busy === "flagged" ? "Checking…" : "Show flagged lookups"}</button>
        {flagged && (
          <div style={{ marginTop: 16 }}>
            <div style={{ fontSize: 13, fontWeight: 800, color: VA.ink, marginBottom: 8, display: "flex", alignItems: "center", gap: 8 }}>Padded / shortcut entries <span style={VA.pill(flagged.padded.length ? "red" : "green")}>{flagged.padded.length}</span></div>
            {flagged.padded.length === 0 ? <div style={{ fontSize: 12.5, color: "#15803D", marginBottom: 14, fontWeight: 600 }}>✓ None.</div> : (
              <div style={{ ...tableWrap, marginBottom: 16 }}>
                <table style={{ width: "100%", borderCollapse: "collapse" }}>
                  <thead><tr style={theadRow}><th style={th}>When</th><th style={th}>By</th><th style={th}>Branch</th><th style={th}>Typed code</th><th style={th}>Amount</th><th style={{ ...th, textAlign: "center" }}>Found</th></tr></thead>
                  <tbody>{flagged.padded.map((l, i) => (
                    <tr key={i} className="va-row"><td style={td}>{fmtDateTime(l.looked_up_at)}</td><td style={td}>{l.manager_name || "—"}</td><td style={td}>{l.branch || "—"}</td><td style={td}><span style={VA.codeChip}>{l.typed_code}</span></td><td style={td}>{fmtMoney(l.amount)}</td><td style={{ ...td, textAlign: "center" }}>{l.found ? "✓" : "✗"}</td></tr>
                  ))}</tbody>
                </table>
              </div>
            )}
            <div style={{ fontSize: 13, fontWeight: 800, color: VA.ink, marginBottom: 8, display: "flex", alignItems: "center", gap: 8 }}>Same card, different full code <span style={VA.pill(flagged.mismatches.length ? "red" : "green")}>{flagged.mismatches.length}</span></div>
            {flagged.mismatches.length === 0 ? <div style={{ fontSize: 12.5, color: "#15803D", fontWeight: 600 }}>✓ None.</div> : flagged.mismatches.map((m, i) => (
              <div key={i} style={{ border: "1px solid #FCE7F3", borderRadius: 12, padding: 12, marginBottom: 10, background: "#FFFCFE" }}>
                <div style={{ fontSize: 13, fontWeight: 700, color: VA.ink, marginBottom: 8 }}><span style={VA.codeChip}>{m.fresha_code}</span> — {m.codes.length} distinct codes</div>
                <div style={tableWrap}>
                  <table style={{ width: "100%", borderCollapse: "collapse" }}>
                    <thead><tr style={theadRow}><th style={th}>When</th><th style={th}>By</th><th style={th}>Typed code</th></tr></thead>
                    <tbody>{m.lookups.map((l, j) => (
                      <tr key={j} className="va-row"><td style={td}>{fmtDateTime(l.looked_up_at)}</td><td style={td}>{l.manager_name || "—"}</td><td style={td}><span style={VA.codeChip}>{l.typed_code}</span></td></tr>
                    ))}</tbody>
                  </table>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

// ─── BONUS & COMMISSION CONFIG (Owner / Master Admin) ───────────────────────
// Owner-editable rate tables that drive the staff "Bonus & Commission
// Calculator" on the My BOA site (myboa/bonus.js). Stored in
// app_state["boa_bonus_config_v1"] (anon-readable), so the calculator picks up
// changes without a redeploy. Keep this schema in sync with myboa/bonus.js.
const BONUS_CONFIG_DEFAULT = {
  basic: 5500,
  commissionBands: [
    { min: 15000, amount: 600 }, { min: 20000, amount: 1200 }, { min: 25000, amount: 1800 },
    { min: 30000, amount: 2400 }, { min: 35000, amount: 3500 }, { min: 40000, amount: 4100 },
    { min: 45000, amount: 4700 }, { min: 50000, amount: 5300 }
  ],
  commissionExtend: { aboveTurnover: 50000, perStep: 5000, addAmount: 1000 },
  targetBands: [
    { min: 30000, amount: 500 }, { min: 35000, amount: 1000 }, { min: 50000, amount: 3000 }
  ],
  skills: { threshold: 25000, byLevel: { "1": 0, "2": 1000, "3": 2000 } },
  late: { halveAt: 3, zeroAt: 7 }
};
function bonusBandAmount(bands, turnover) {
  let best = null;
  (bands || []).forEach(b => { if (turnover >= b.min && (!best || b.min > best.min)) best = b; });
  return best ? best.amount : 0;
}
function bonusCompute(conf, turnover, level, warning, noShow, late) {
  const t = Math.max(0, Math.round(Number(turnover) || 0));
  const basic = Number(conf.basic) || 0;
  let commission = bonusBandAmount(conf.commissionBands, t);
  const ex = conf.commissionExtend;
  if (ex && ex.perStep > 0 && t > ex.aboveTurnover) {
    commission += Math.floor((t - ex.aboveTurnover) / ex.perStep) * (Number(ex.addAmount) || 0);
  }
  const target = bonusBandAmount(conf.targetBands, t);
  const threshold = (conf.skills && conf.skills.threshold) || 0;
  const skills = t >= threshold ? (Number(conf.skills?.byLevel?.[level]) || 0) : 0;
  const gross = target + skills;
  // A warning or a no-show forfeits the bonus; otherwise it's paid in full.
  // (Lateness no longer factors into the estimate — see the staff disclaimer.)
  const mult = (warning || noShow) ? 0 : 1;
  const net = Math.round(gross * mult);
  return { t, basic, commission, target, skills, gross, mult, net, total: basic + commission + net };
}

function BonusConfig() {
  const PINK = { ink: "#831843", accent: "#BE185D", soft: "#FBCFE8", softer: "#FCE7F3" };
  const [conf, setConf] = React.useState(BONUS_CONFIG_DEFAULT);
  const [loaded, setLoaded] = React.useState(false);
  const [busy, setBusy] = React.useState(false);
  const [result, setResult] = React.useState(null);
  const [pvTurn, setPvTurn] = React.useState("30000");
  const [pvLevel, setPvLevel] = React.useState("2");

  React.useEffect(() => {
    (async () => {
      try {
        const v = window.BOA_DB && window.BOA_DB.loadByKey ? await window.BOA_DB.loadByKey("boa_bonus_config_v1") : null;
        if (v && Array.isArray(v.commissionBands)) {
          setConf({
            basic: (v.basic != null ? v.basic : BONUS_CONFIG_DEFAULT.basic),
            commissionBands: v.commissionBands || BONUS_CONFIG_DEFAULT.commissionBands,
            commissionExtend: v.commissionExtend || BONUS_CONFIG_DEFAULT.commissionExtend,
            targetBands: v.targetBands || BONUS_CONFIG_DEFAULT.targetBands,
            skills: v.skills || BONUS_CONFIG_DEFAULT.skills,
            late: v.late || BONUS_CONFIG_DEFAULT.late
          });
        }
      } catch (_e) { /* keep defaults */ }
      finally { setLoaded(true); }
    })();
  }, []);

  const num = (v) => Math.max(0, Math.round(Number(v) || 0));
  const updateBand = (key, i, field, val) => setConf(c => ({ ...c, [key]: c[key].map((b, idx) => idx === i ? { ...b, [field]: num(val) } : b) }));
  const removeBand = (key, i) => setConf(c => ({ ...c, [key]: c[key].filter((_b, idx) => idx !== i) }));
  const addBand = (key) => setConf(c => ({ ...c, [key]: c[key].concat({ min: 0, amount: 0 }) }));
  const setSkill = (lvl, val) => setConf(c => ({ ...c, skills: { ...c.skills, byLevel: { ...c.skills.byLevel, [lvl]: num(val) } } }));
  const setThreshold = (val) => setConf(c => ({ ...c, skills: { ...c.skills, threshold: num(val) } }));
  const setLate = (field, val) => setConf(c => ({ ...c, late: { ...c.late, [field]: num(val) } }));
  const setBasic = (val) => setConf(c => ({ ...c, basic: num(val) }));
  const setExtend = (field, val) => setConf(c => ({ ...c, commissionExtend: { ...(c.commissionExtend || {}), [field]: num(val) } }));

  const save = async () => {
    if (busy) return;
    setBusy(true); setResult(null);
    try {
      const clean = {
        basic: num(conf.basic),
        commissionBands: [...conf.commissionBands].sort((a, b) => a.min - b.min),
        commissionExtend: conf.commissionExtend || BONUS_CONFIG_DEFAULT.commissionExtend,
        targetBands: [...conf.targetBands].sort((a, b) => a.min - b.min),
        skills: conf.skills, late: conf.late
      };
      await window.BOA_DB.sb.from("app_state").upsert({ key: "boa_bonus_config_v1", value: clean });
      setConf(clean);
      if (window.BOA_LOG_ACTIVITY) window.BOA_LOG_ACTIVITY("Updated bonus & commission rates", "", "Payroll", "Admin");
      setResult({ ok: true, msg: "Saved — the staff calculator will use these rates immediately." });
    } catch (e) {
      setResult({ ok: false, msg: "Could not save: " + ((e && e.message) || e) });
    } finally { setBusy(false); }
  };

  const card = { background: "#fff", border: `1px solid ${PINK.soft}`, borderRadius: 14, padding: "16px 18px", marginBottom: 16 };
  const inp = { width: "100%", padding: "7px 9px", fontSize: 13, border: `1px solid ${PINK.soft}`, borderRadius: 7, fontFamily: "inherit", color: PINK.ink, boxSizing: "border-box" };
  const th = { textAlign: "left", fontSize: 10, fontWeight: 800, color: PINK.ink, textTransform: "uppercase", letterSpacing: "0.05em", padding: "4px 6px" };
  const rand = (n) => "R" + (Number(n) || 0).toLocaleString("en-ZA");
  const pv = bonusCompute(conf, pvTurn, pvLevel, false, false, 0);

  const bandTable = (key, label, hint) => (
    <div style={card}>
      <div style={{ fontWeight: 800, fontSize: 14, marginBottom: 2, color: PINK.ink }}>{label}</div>
      <div style={{ fontSize: 12, color: "#6b7280", marginBottom: 10 }}>{hint}</div>
      <table style={{ borderCollapse: "collapse" }}>
        <thead><tr><th style={th}>Min turnover (R ≥)</th><th style={th}>Amount (R)</th><th style={th}></th></tr></thead>
        <tbody>
          {conf[key].map((b, i) => (
            <tr key={i}>
              <td style={{ padding: "3px 6px" }}><input type="number" value={b.min} onChange={e => updateBand(key, i, "min", e.target.value)} style={{ ...inp, width: 130 }} /></td>
              <td style={{ padding: "3px 6px" }}><input type="number" value={b.amount} onChange={e => updateBand(key, i, "amount", e.target.value)} style={{ ...inp, width: 110 }} /></td>
              <td style={{ padding: "3px 6px" }}><button onClick={() => removeBand(key, i)} style={{ background: "#fef2f2", color: "#991b1b", border: "1px solid #fecaca", borderRadius: 6, padding: "5px 9px", cursor: "pointer", fontSize: 12, fontWeight: 700 }}>×</button></td>
            </tr>
          ))}
        </tbody>
      </table>
      <button onClick={() => addBand(key)} style={{ marginTop: 8, background: PINK.softer, color: PINK.ink, border: `1px solid ${PINK.soft}`, borderRadius: 7, padding: "6px 12px", cursor: "pointer", fontSize: 12, fontWeight: 700 }}>+ Add band</button>
    </div>
  );

  return (
    <div style={{ fontFamily: "'Outfit',system-ui,sans-serif", color: PINK.ink, maxWidth: 760 }}>
      <div style={{ fontFamily: "'Playfair Display',serif", fontSize: 22, fontWeight: 700, marginBottom: 2 }}>🧮 Bonus &amp; Commission</div>
      <div style={{ fontSize: 12, color: "#6b7280", marginBottom: 16 }}>
        These rates drive the staff <strong>Bonus &amp; Commission Calculator</strong> on My BOA. Basic &amp; commission are always paid; bonuses (target + skills) are forfeited by a warning or no-show. {loaded ? "" : "Loading…"}
      </div>

      <div style={card}>
        <div style={{ fontWeight: 800, fontSize: 14, marginBottom: 2, color: PINK.ink }}>Basic salary</div>
        <div style={{ fontSize: 12, color: "#6b7280", marginBottom: 10 }}>Flat monthly basic for everyone — always paid, first line on the payout.</div>
        <label style={{ fontSize: 12, fontWeight: 700 }}>Basic (R / month)<br /><input type="number" value={conf.basic ?? 0} onChange={e => setBasic(e.target.value)} style={{ ...inp, width: 130, marginTop: 4 }} /></label>
      </div>

      {bandTable("commissionBands", "Commission bands", "Turnover ≥ the lowest band's min earns that commission. Highest qualifying band applies (e.g. 34 999 still earns the 30 000 rate).")}

      <div style={card}>
        <div style={{ fontWeight: 800, fontSize: 14, marginBottom: 2, color: PINK.ink }}>Commission above the top band</div>
        <div style={{ fontSize: 12, color: "#6b7280", marginBottom: 10 }}>Above the turnover below, add a fixed amount for every full step of extra turnover (e.g. +R1 000 per R5 000 over R50 000).</div>
        <div style={{ display: "flex", gap: 14, flexWrap: "wrap", alignItems: "flex-end" }}>
          <label style={{ fontSize: 12, fontWeight: 700 }}>Above turnover (R)<br /><input type="number" value={conf.commissionExtend?.aboveTurnover ?? 0} onChange={e => setExtend("aboveTurnover", e.target.value)} style={{ ...inp, width: 120, marginTop: 4 }} /></label>
          <label style={{ fontSize: 12, fontWeight: 700 }}>Per step (R)<br /><input type="number" value={conf.commissionExtend?.perStep ?? 0} onChange={e => setExtend("perStep", e.target.value)} style={{ ...inp, width: 110, marginTop: 4 }} /></label>
          <label style={{ fontSize: 12, fontWeight: 700 }}>Add amount (R)<br /><input type="number" value={conf.commissionExtend?.addAmount ?? 0} onChange={e => setExtend("addAmount", e.target.value)} style={{ ...inp, width: 110, marginTop: 4 }} /></label>
        </div>
      </div>

      {bandTable("targetBands", "Target bonus bands", "A turnover reward, on top of commission. Below the lowest min → no target bonus.")}

      <div style={card}>
        <div style={{ fontWeight: 800, fontSize: 14, marginBottom: 2, color: PINK.ink }}>Skills bonus (by level)</div>
        <div style={{ fontSize: 12, color: "#6b7280", marginBottom: 10 }}>Paid only once turnover reaches the threshold below.</div>
        <div style={{ display: "flex", gap: 14, flexWrap: "wrap", alignItems: "flex-end" }}>
          <label style={{ fontSize: 12, fontWeight: 700 }}>Unlocks at turnover (R ≥)<br /><input type="number" value={conf.skills.threshold} onChange={e => setThreshold(e.target.value)} style={{ ...inp, width: 130, marginTop: 4 }} /></label>
          {["1", "2", "3"].map(l => (
            <label key={l} style={{ fontSize: 12, fontWeight: 700 }}>Level {l} (R)<br /><input type="number" value={conf.skills.byLevel[l] ?? 0} onChange={e => setSkill(l, e.target.value)} style={{ ...inp, width: 100, marginTop: 4 }} /></label>
          ))}
        </div>
      </div>

      <div style={card}>
        <div style={{ fontWeight: 800, fontSize: 14, marginBottom: 2, color: PINK.ink }}>Bonus deductions</div>
        <div style={{ fontSize: 12, color: "#6b7280", marginBottom: 10 }}>A signed <strong>warning</strong> or a <strong>no-show</strong> forfeits the bonus outright (commission is never affected). The calculator doesn't ask about lateness — the threshold below is shown to staff as a reminder in the disclaimer.</div>
        <label style={{ fontSize: 12, fontWeight: 700 }}>Bonus forfeited at (lates ≥)<br /><input type="number" value={conf.late?.zeroAt ?? 7} onChange={e => setLate("zeroAt", e.target.value)} style={{ ...inp, width: 130, marginTop: 4 }} /></label>
      </div>

      <div style={{ ...card, background: PINK.softer }}>
        <div style={{ fontWeight: 800, fontSize: 14, marginBottom: 10, color: PINK.ink }}>Live preview (no incidents)</div>
        <div style={{ display: "flex", gap: 12, flexWrap: "wrap", alignItems: "flex-end", marginBottom: 12 }}>
          <label style={{ fontSize: 12, fontWeight: 700 }}>Turnover (R)<br /><input type="number" value={pvTurn} onChange={e => setPvTurn(e.target.value)} style={{ ...inp, width: 130, marginTop: 4 }} /></label>
          <label style={{ fontSize: 12, fontWeight: 700 }}>Level<br />
            <select value={pvLevel} onChange={e => setPvLevel(e.target.value)} style={{ ...inp, width: 90, marginTop: 4 }}><option value="1">1</option><option value="2">2</option><option value="3">3</option></select>
          </label>
        </div>
        <div style={{ fontSize: 13, color: PINK.ink, lineHeight: 1.7 }}>
          Basic <strong>{rand(pv.basic)}</strong> · Commission <strong>{rand(pv.commission)}</strong> · Target <strong>{rand(pv.target)}</strong> · Skills <strong>{rand(pv.skills)}</strong> →
          <strong style={{ fontSize: 16, color: PINK.accent }}> Total {rand(pv.total)}</strong>
        </div>
      </div>

      <button onClick={save} disabled={busy}
        style={{ background: busy ? PINK.soft : PINK.accent, color: "#fff", border: "none", borderRadius: 9, padding: "11px 22px", cursor: busy ? "not-allowed" : "pointer", fontSize: 14, fontWeight: 700, fontFamily: "inherit" }}>
        {busy ? "Saving…" : "Save rates"}
      </button>

      {result && (
        <div style={{
          marginTop: 14, padding: "11px 14px", borderRadius: 9, fontSize: 13, fontWeight: 600,
          background: result.ok ? "#dcfce7" : "#fef2f2", border: "1px solid " + (result.ok ? "#86efac" : "#fecaca"),
          color: result.ok ? "#14532d" : "#991b1b"
        }}>
          {result.ok ? "✓ " : "⚠️ "}{result.msg}
        </div>
      )}
    </div>
  );
}


// ─── STORE OPENING HOURS CONFIG (Owner / Master Admin) ──────────────────────
// Owner-editable per-branch opening times that feed the recruitment commute
// picker's "leave home by X" calc. Stored in app_state["boa_store_hours_v1"]
// (anon-readable), falling back to STORE_HOURS_DEFAULT / STORE_HOURS_FALLBACK.
function StoreHoursConfig() {
  const PINK = { ink: "#831843", accent: "#BE185D", soft: "#FBCFE8", softer: "#FCE7F3" };
  const [hours, setHours] = React.useState({});
  const [loaded, setLoaded] = React.useState(false);
  const [busy, setBusy] = React.useState(false);
  const [result, setResult] = React.useState(null);

  React.useEffect(() => {
    (async () => {
      try {
        const v = window.BOA_DB && window.BOA_DB.loadByKey ? await window.BOA_DB.loadByKey("boa_store_hours_v1") : null;
        if (v && typeof v === "object") setHours(v);
      } catch (_e) { /* keep empty → defaults */ }
      finally { setLoaded(true); }
    })();
  }, []);

  const branches = (SALONS || []).map(s => s.name);
  const DOW = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
  const getH = (b) => (hours[b] || STORE_HOURS_DEFAULT[b] || STORE_HOURS_FALLBACK);
  const setOpen = (b, val) => setHours(h => ({ ...h, [b]: { ...getH(b), open: val } }));
  const setDow = (b, dow, val) => setHours(h => {
    const cur = getH(b);
    const byDow = { ...(cur.byDow || {}) };
    if (val) byDow[String(dow)] = val; else delete byDow[String(dow)];
    return { ...h, [b]: { ...cur, byDow } };
  });

  const save = async () => {
    if (busy) return;
    setBusy(true); setResult(null);
    try {
      // Persist only branch entries with a usable open time.
      const clean = {};
      branches.forEach(b => {
        const h = getH(b);
        if (h && h.open) clean[b] = { open: h.open, byDow: h.byDow || {} };
      });
      await window.BOA_DB.sb.from("app_state").upsert({ key: "boa_store_hours_v1", value: clean });
      setHours(clean);
      if (window.BOA_LOG_ACTIVITY) window.BOA_LOG_ACTIVITY("Updated store opening hours", "", "Operations", "Admin");
      setResult({ ok: true, msg: "Saved — the recruitment commute picker will use these immediately." });
    } catch (e) {
      setResult({ ok: false, msg: "Could not save: " + ((e && e.message) || e) });
    } finally { setBusy(false); }
  };

  const inp = { padding: "5px 7px", fontSize: 13, border: `1px solid ${PINK.soft}`, borderRadius: 7, fontFamily: "inherit", color: PINK.ink, boxSizing: "border-box" };
  const th = { textAlign: "left", fontSize: 11, fontWeight: 800, color: PINK.accent, textTransform: "uppercase", letterSpacing: 0.4, padding: "6px 8px", borderBottom: `1px solid ${PINK.soft}` };
  const td = { padding: "6px 8px", borderBottom: `1px solid ${PINK.softer}`, verticalAlign: "middle" };

  if (!loaded) return <div style={{ padding: 24, color: "#9ca3af" }}>Loading store hours…</div>;

  return (
    <div style={{ maxWidth: 720 }}>
      <h2 style={{ color: PINK.ink, margin: "4px 0 2px" }}>🕖 Store Opening Hours</h2>
      <p style={{ color: "#6b7280", fontSize: 13, margin: "0 0 14px", lineHeight: 1.5 }}>
        Used by the recruitment <strong>commute picker</strong> to tell a candidate when to leave home to arrive
        <strong> 15 minutes before</strong> their branch opens. Set the normal weekday open time, and optionally a
        different time for <strong>Sunday</strong> / <strong>Saturday</strong>. Closed days are skipped automatically.
      </p>
      <div style={{ background: "#fff", border: `1px solid ${PINK.soft}`, borderRadius: 14, overflow: "hidden" }}>
        <table style={{ width: "100%", borderCollapse: "collapse" }}>
          <thead>
            <tr>
              <th style={th}>Branch</th>
              <th style={th}>Weekday open</th>
              <th style={th}>Sunday</th>
              <th style={th}>Saturday</th>
            </tr>
          </thead>
          <tbody>
            {branches.map(b => {
              const h = getH(b);
              const closed = salonClosedDow(b).map(d => DOW[d]).join(", ");
              return (
                <tr key={b}>
                  <td style={td}>
                    <div style={{ fontWeight: 700, color: PINK.ink, fontSize: 13 }}>{b}</div>
                    {closed && <div style={{ fontSize: 10, color: "#9ca3af" }}>Closed {closed}</div>}
                  </td>
                  <td style={td}><input type="time" value={h.open || ""} onChange={e => setOpen(b, e.target.value)} style={inp} /></td>
                  <td style={td}><input type="time" value={(h.byDow && h.byDow["0"]) || ""} placeholder="—" onChange={e => setDow(b, 0, e.target.value)} style={inp} /></td>
                  <td style={td}><input type="time" value={(h.byDow && h.byDow["6"]) || ""} placeholder="—" onChange={e => setDow(b, 6, e.target.value)} style={inp} /></td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
      <div style={{ display: "flex", alignItems: "center", gap: 14, marginTop: 14 }}>
        <button onClick={save} disabled={busy} style={{ background: PINK.accent, color: "#fff", border: "none", borderRadius: 9, padding: "9px 18px", fontWeight: 800, fontSize: 14, cursor: busy ? "default" : "pointer", opacity: busy ? 0.6 : 1 }}>
          {busy ? "Saving…" : "Save opening hours"}
        </button>
        {result && <span style={{ fontSize: 13, fontWeight: 700, color: result.ok ? "#15803d" : "#b91c1c" }}>{result.msg}</span>}
      </div>
    </div>
  );
}


// ─── APP GATE ─────────────────────────────────────────────────────────────────
// Mounts the PIN sign-in screen until a valid user is set. Once unlocked, the
// real <App/> mounts. Done as a wrapper so <App/>'s hooks always run in the
// same order — putting the PIN check inside <App/> would change hook count.
function AppGate() {
  const [appUsers, setAppUsers] = useState(null);          // dynamic store; null while loading
  const [bootDone, setBootDone] = useState(false);
  const [currentUser, setCurrentUser] = useState(null);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      // Wait for the data layer to wire itself up (BOA_DB.isReady becomes
      // true once the Supabase client + helpers are exposed).
      const waitDB = () => new Promise(res => {
        const tick = () => {
          if (window.BOA_DB && window.BOA_DB.isReady) res();
          else setTimeout(tick, 100);
        };
        tick();
      });
      try { await waitDB(); } catch (_) { }
      if (cancelled) return;

      let dynamic = null;
      let usersReadFailed = false;
      try {
        dynamic = await loadAppUsersFromDb();
      } catch (e) {
        // The users read FAILED (Supabase paused / network blip). Do NOT treat
        // this as "first run" — re-seeding would overwrite the real user list
        // with the built-in defaults (how Settings-added logins got wiped on a
        // Supabase outage). Fall back to in-memory defaults for THIS session
        // only and never persist them; the real users return on the next good read.
        usersReadFailed = true;
        console.error("[BOA] app-users read failed — using in-memory defaults WITHOUT saving (no re-seed):", e);
        dynamic = JSON.parse(JSON.stringify(STAFF_USERS));
      }
      if (usersReadFailed) {
        // Skip seeding + migrations entirely; never write defaults over real data.
      } else if (!dynamic || Object.keys(dynamic).length === 0) {
        // First run — seed Supabase from STAFF_USERS so the Settings tab
        // can edit the original accounts too. Failure to write isn't fatal:
        // we'll fall back to the in-memory copy.
        dynamic = JSON.parse(JSON.stringify(STAFF_USERS));
        try { await saveAppUsersToDb(dynamic); } catch (_) { }
      } else {
        // Make sure any newly-shipped seed user (e.g. Theresa) is present
        // even if the dynamic row was created before they were defined.
        let mutated = false;
        Object.keys(STAFF_USERS).forEach(pin => {
          if (!dynamic[pin]) {
            dynamic[pin] = { ...STAFF_USERS[pin] };
            mutated = true;
          }
        });
        if (mutated) { try { await saveAppUsersToDb(dynamic); } catch (_) { } }

        // One-time migration: hide new Home/Dashboard widgets for all non-owner
        // users. We set `_dashMigrated*` so each migration step only ever runs
        // once per user. The original V1 hid Security Alerts + HR Actions for
        // everyone except the owner. V2 adds the "Manager Absences (Action
        // required)" widget, hidden for everyone except the owner AND ROMs —
        // ROMs are the primary actors on that card, so they see it by default.
        const _dashWidgets = ["dashSecurityAlerts", "dashHrActions"];
        let dashMigrated = false;
        Object.keys(dynamic).forEach(pin => {
          const u = dynamic[pin];
          if (u._dashMigrated) return; // Already migrated, don't force them hidden again

          u._dashMigrated = true;
          dashMigrated = true;

          if (u.isOwner) return; // owners keep full access
          const ht = Array.isArray(u.hideTabs) ? u.hideTabs : [];
          const missing = _dashWidgets.filter(w => !ht.includes(w));
          if (missing.length > 0) {
            u.hideTabs = [...ht, ...missing];
          }
        });
        // V2 migration: introduces the Manager Absences (Action required) widget.
        // Hidden by default for non-owners, EXCEPT ROMs — they're the primary
        // actor on the card so they should see it without an admin step.
        Object.keys(dynamic).forEach(pin => {
          const u = dynamic[pin];
          if (u._dashMigratedV2) return;
          u._dashMigratedV2 = true;
          dashMigrated = true;
          if (u.isOwner) return;
          if (isRomRole(u.role)) return;   // ROMs see it by default
          const ht = Array.isArray(u.hideTabs) ? u.hideTabs : [];
          if (!ht.includes("dashMgrAbsences")) {
            u.hideTabs = [...ht, "dashMgrAbsences"];
          }
        });
        // V3b migration: introduces the Abscond / Absence Warnings widget.
        // HR-sensitive (possible abscondment → disciplinary), so hidden by
        // default for everyone except the owner; admins grant specific people
        // in Settings → Users → Edit (Home/Dashboard › Abscond / Absence
        // Warnings).
        Object.keys(dynamic).forEach(pin => {
          const u = dynamic[pin];
          if (u._dashMigratedAbscond) return;
          u._dashMigratedAbscond = true;
          dashMigrated = true;
          if (u.isOwner) return;
          const ht = Array.isArray(u.hideTabs) ? u.hideTabs : [];
          if (!ht.includes("dashAbscond")) {
            u.hideTabs = [...ht, "dashAbscond"];
          }
        });
        // V3 migration: Rochelle (3030) & Farida (4040) help run the
        // nail-tech trials, so allow-list the Trial Period tab back in for
        // them (Rochelle keeps the rest of People hidden). Runs once each.
        Object.keys(dynamic).forEach(pin => {
          const u = dynamic[pin];
          if (u._trialTabMigrated) return;
          u._trialTabMigrated = true;
          dashMigrated = true;
          if (pin === "3030" || pin === "4040") {
            const st = Array.isArray(u.showTabs) ? u.showTabs : [];
            if (!st.includes("trialPeriod")) u.showTabs = [...st, "trialPeriod"];
          }
        });
        // V3c migration: Rochelle (3030) & Farida (4040) don't just VIEW the
        // Trial Period tab — they run the trials, so they must be able to EDIT
        // it (set start dates, mark the trial days). The earlier grant only
        // made it visible; if the tab is stuck view-only (in readOnlyTabs) or
        // hidden (in hideTabs) for them, the day editor's saves are silently
        // blocked by the read-only guard. Force full edit access. Runs once each.
        Object.keys(dynamic).forEach(pin => {
          const u = dynamic[pin];
          if (u._trialEditMigrated) return;
          u._trialEditMigrated = true;
          dashMigrated = true;
          if (pin === "3030" || pin === "4040") {
            if (Array.isArray(u.readOnlyTabs)) u.readOnlyTabs = u.readOnlyTabs.filter(t => t !== "trialPeriod");
            if (Array.isArray(u.hideTabs)) u.hideTabs = u.hideTabs.filter(t => t !== "trialPeriod");
            const st = Array.isArray(u.showTabs) ? u.showTabs : [];
            if (!st.includes("trialPeriod")) u.showTabs = [...st, "trialPeriod"];
          }
        });
        // V4 migration: introduces the Office Staff List tab. It exposes the
        // Head Office / CC&S directory (permits, maternity dates, tenure) —
        // the same sensitivity class as the salon Staff List, which owners
        // curate per user. Tab visibility is deny-list based, so without this
        // the new key is visible to EVERYONE with the People category,
        // including users whose owner explicitly hid "staff". Hidden by
        // default for non-owners; owners grant specific people in
        // Settings → Users → Edit (People › Office Staff List).
        Object.keys(dynamic).forEach(pin => {
          const u = dynamic[pin];
          if (u._officeStaffMigrated) return;
          u._officeStaffMigrated = true;
          dashMigrated = true;
          if (u.isOwner) return;
          const ht = Array.isArray(u.hideTabs) ? u.hideTabs : [];
          if (!ht.includes("officeStaff")) {
            u.hideTabs = [...ht, "officeStaff"];
          }
        });
        if (dashMigrated) { try { await saveAppUsersToDb(dynamic); } catch (_) { } }
      }
      if (cancelled) return;
      window.__BOA_APP_USERS = dynamic;
      setAppUsers(dynamic);

      // Restore session if the saved PIN still exists in the live store.
      try {
        const raw = sessionStorage.getItem(PIN_SESSION_KEY);
        if (raw) {
          const s = JSON.parse(raw);
          const u = (dynamic && dynamic[s.pin]) || STAFF_USERS[s.pin];
          if (u) {
            const merged = {
              ...s,
              name: u.name, role: u.role,
              demo: !!u.demo, isOwner: !!u.isOwner,
              voucherEntryOnly: !!u.voucherEntryOnly,
              ccOnly: !!u.ccOnly,
              hideCategories: u.hideCategories || [],
              hideTabs: u.hideTabs || [],
              showTabs: u.showTabs || [],
              readOnlyTabs: u.readOnlyTabs || [],
              stores: Array.isArray(u.stores) ? u.stores.slice() : []
            };
            window.BOA_CURRENT_USER = merged;
            setCurrentUser(merged);
          } else {
            // Saved user no longer exists — drop the session.
            try { sessionStorage.removeItem(PIN_SESSION_KEY); } catch (_) { }
          }
        }
      } catch (_) { }
      setBootDone(true);
    })();
    return () => { cancelled = true; };
  }, []);

  const signOut = () => {
    try { sessionStorage.removeItem(PIN_SESSION_KEY); } catch (_) { }
    window.BOA_CURRENT_USER = null;
    setCurrentUser(null);
  };

  const onUsersUpdate = async (next) => {
    const cleaned = { ...next };
    Object.keys(cleaned).forEach(pin => {
      const u = cleaned[pin];
      const rec = {
        ...u,
        name: u.name, role: u.role,
        demo: !!u.demo, isOwner: !!u.isOwner,
        hideCategories: u.hideCategories || [],
        hideTabs: u.hideTabs || [],
        readOnlyTabs: u.readOnlyTabs || []
      };
      // ROM store allocation — only stamp the field when actually set, so
      // the user record stays tidy for non-ROM roles.
      if (Array.isArray(u.stores) && u.stores.length > 0) rec.stores = u.stores.slice();
      cleaned[pin] = rec;
    });
    await saveAppUsersToDb(cleaned);
    window.__BOA_APP_USERS = cleaned;
    setAppUsers(cleaned);
    if (currentUser) {
      const u = cleaned[currentUser.pin];
      if (!u) {
        // Current user was deleted — sign out.
        signOut();
        return;
      }
      const merged = {
        ...currentUser,
        name: u.name, role: u.role,
        demo: !!u.demo, isOwner: !!u.isOwner,
        ccOnly: !!u.ccOnly,
        hideCategories: u.hideCategories || [],
        hideTabs: u.hideTabs || [],
        readOnlyTabs: u.readOnlyTabs || [],
        stores: Array.isArray(u.stores) ? u.stores.slice() : []
      };
      window.BOA_CURRENT_USER = merged;
      setCurrentUser(merged);
      try { sessionStorage.setItem(PIN_SESSION_KEY, JSON.stringify(merged)); } catch (_) { }
    }
  };

  if (!bootDone) {
    return (
      <div style={{ minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center", flexDirection: "column", gap: 12, fontFamily: "'Outfit',system-ui,sans-serif", color: "#831843" }}>
        <div style={{ width: 28, height: 28, border: "3px solid #FBCFE8", borderTopColor: "#BE185D", borderRadius: "50%", animation: "spin 0.9s linear infinite" }} />
        <div style={{ fontSize: 13, letterSpacing: "0.18em", fontWeight: 700, textTransform: "uppercase" }}>BOA HR · Loading…</div>
        <style>{"@keyframes spin{to{transform:rotate(360deg)}}"}</style>
      </div>
    );
  }

  if (!currentUser) {
    return <PinLogin users={appUsers} onUnlock={(s) => setCurrentUser(s)} />;
  }

  // Voucher-entry login: bare, stripped view — no nav, tabs or categories.
  if (currentUser.voucherEntryOnly) {
    return <VoucherEntryApp user={currentUser} onSignOut={signOut} />;
  }

  return <App currentUser={currentUser} onSignOut={signOut} appUsers={appUsers} onUsersUpdate={onUsersUpdate} />;
}

// ─── SETTINGS / USER ADMIN ──────────────────────────────────────────────────
// Owner-only screen for managing PIN logins. Lists every user, lets the
// owner add new ones, edit permissions, reset PINs and delete accounts.
// All changes flow through `onUsersUpdate` (defined in AppGate) which
// upserts the live user store into Supabase under APP_USERS_KEY.
