  // managers, loaded via loadClockinMeta.
  const [hoClockinRows, setHoClockinRows] = useState([]);
  const [hoClockinMeta, setHoClockinMeta] = useState({});  // {clockinId: meta}
  const [hoClockinDays] = useState(31);                    // how far back HO rows load
  const [hoClockinDay, setHoClockinDay] = useState(() => { const d = new Date(); return d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0") + "-" + String(d.getDate()).padStart(2, "0"); });

  // ── Office Hours (Payroll) state ───────────────────────────────────
  // Its own clock-in feed rather than reusing hoClockinRows: that one is a
  // rolling 31-day window pinned to the Check-ins tabs, while this one must
  // cover an exact pay cycle (25th → 24th) that payroll can step back through.
  const [officeHoursYm, setOfficeHoursYm] = useState(() => {
    const d = new Date(), y = d.getFullYear();
    let m = d.getMonth() + 1;
    if (d.getDate() <= 24) { m -= 1; }        // START-month convention (currentAttYm)
    let yy = y; if (m < 1) { m = 12; yy -= 1; }
    return yy + "-" + String(m).padStart(2, "0");
  });
  const [officeHoursRows, setOfficeHoursRows] = useState([]);       // clockins for the cycle
  const [officeHoursSched, setOfficeHoursSched] = useState(null);   // {ho:{}, cc:{}, hoPub, ccPub} | null = not loaded
  const [officeHoursReview, setOfficeHoursReview] = useState({});   // durable review ledger
  const [officeHoursBusy, setOfficeHoursBusy] = useState("");       // key of the row mid-write

  // ── Manager Clock-ins viewer state ─────────────────────────────────
  const [mgrClockinRows, setMgrClockinRows] = useState([]);
  // ROM-managed reasons for manager absences. Loaded on dashboard,
  // mgrclockins and attendance tabs so the grid + dashboard tile + the
  // no-show banner all see the same data.
  const [mgrDayStatuses, setMgrDayStatuses] = useState([]);
  // Have the manager clock-ins / day-status feeds loaded at least once?
  // Both start as [] and arrive via async fetches, so the attendance grid
  // can render before they land. While they're still empty-because-loading,
  // the manager auto-absent rule must stay quiet — otherwise it briefly
  // fabricates "Absent" over a real ROM "Sick + note", which in turn looks
  // like the cell's confirmed review just expired. Gating on these flags
  // keeps that flash from happening.
  const [mgrClockinsLoaded, setMgrClockinsLoaded] = useState(false);
  const [mgrDayStatusesLoaded, setMgrDayStatusesLoaded] = useState(false);
  // Modal state for the "Mark reason" flow. null when closed; otherwise
  // { staffId, ec, name, branch, date, existing? }.
  const [mgrReasonModal, setMgrReasonModal] = useState(null);
  // Picker modal for the "Tag absence" button — lets a ROM pick any
  // branch + manager + date and feed them into mgrReasonModal. Used for
  // early sick calls and for days where the no-show banner didn't surface
  // a name (e.g. schedule not loaded).
  const [mgrAbsencePicker, setMgrAbsencePicker] = useState(null);
  const [mgrClockinMeta, setMgrClockinMeta] = useState({});  // {clockinId: meta}
  const [mgrClockinFilterBranch, setMgrClockinFilterBranch] = useState("All");
  const [mgrClockinDays, setMgrClockinDays] = useState(31);        // how far back rows are loaded
  const [mgrClockinDay, setMgrClockinDay] = useState(() => { const d = new Date(); return d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0") + "-" + String(d.getDate()).padStart(2, "0"); });
  // Witness reports submitted via the kiosk's clock-out "Did anyone leave
  // early today?" prompt. Loaded on the Manager Check-ins tab so they
  // surface alongside today's roster.
  const [mgrEarlyLeaveReports, setMgrEarlyLeaveReports] = useState([]);
  const [mgrClockinPhoto, setMgrClockinPhoto] = useState(null);   // {url, name, ts, ...}
  const [mgrClockinSchedCache, setMgrClockinSchedCache] = useState({});  // {branch|ym: grid}
  const [mgrAttGridCache, setMgrAttGridCache] = useState({});            // {branch|attYm: grid} — payroll attendance sheet, used as the no-show fallback
  // {branch|ym: {ec:name}} — ec→name map saved with each manager schedule, so
  // Coverage can re-home a row to a renamed employee code by matching the name.
  const [mgrSchedNamesCache, setMgrSchedNamesCache] = useState({});
  // Manual clock-in modal — opened from the Manager Check-ins no-show
  // cards or the "+ Log manual shift" button so a ROM can backfill a
