  //   { staffId, ec, name, branch, ymd, time, note, _saving, _err }
  const [manualMgrClockinModal, setManualMgrClockinModal] = useState(null);

  // Head Office manual clock-in modal — same shape as the manager one, but the
  // staff picker draws from hoStaff and the branch is always Head Office.
  //   { staffId, ec, name, ymd, time, note, _saving, _err }
  const [manualHoClockinModal, setManualHoClockinModal] = useState(null);

  // ── Manager Coverage tab state ─────────────────────────────────────
  // Week-at-a-glance roster of every manager grouped by branch (and
  // region) so a ROM can spot coverage gaps and decide where to borrow.
  // Defaults to the current ISO week (Monday-start). Schedule grids
  // reuse mgrClockinSchedCache; we load whichever cycle ym(s) the
  // visible week touches on tab open.
  const [mgrCoverageWeekStart, setMgrCoverageWeekStart] = useState(() => {
    const d = new Date();
    const dow = d.getDay();          // 0=Sun, 1=Mon, …
    const offset = (dow + 6) % 7;    // Mon=0, Sun=6
    d.setHours(0, 0, 0, 0);
    d.setDate(d.getDate() - offset);
    return d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0") + "-" + String(d.getDate()).padStart(2, "0");
  });
  const [mgrCoverageView, setMgrCoverageView] = useState("byBranch");   // "byBranch" | "byManager"
  const [mgrCoverageRegion, setMgrCoverageRegion] = useState("all");
  // "Publish current cycle" review modal. rows: null = not scanned yet,
  // [] = scanned/nothing pending. skip: { rowId: true } for opted-out rows.
  const [pubCycleOpen, setPubCycleOpen] = useState(false);
  const [pubCycleRows, setPubCycleRows] = useState(null);
  const [pubCycleSkip, setPubCycleSkip] = useState({});
  const [pubCycleBusy, setPubCycleBusy] = useState(false);
  const [pubCycleErr, setPubCycleErr] = useState("");
  // EC → display name across every population (techs, managers, HO), keyed by
  // the tolerant _normEc so a dash/space/case variant still resolves. A missing
  // name flags a placeholder slot (T001-style) in the publish preview.
  const _pubCycleNameMap = useMemo(() => {
    const m = {};
    const add = (arr) => (arr || []).forEach(p => {
      const ec = _normEc(p && (p.employee_code || p.ec || p.code));
      if (ec && !(ec in m)) m[ec] = (p && (p.name || p.full_name)) || "";
    });
    add(staff); add(managers); add(hoStaff);
    return m;
  }, [staff, managers, hoStaff]);

  // Dashboard "changes awaiting publish" alert (Owner + National Ops): a
  // passive run of the SAME scan the review modal uses, summarised, so a
  // leave approval / extra day / loan that only lives in the draft can't sit
  // unnoticed until someone happens to open the publisher.
  // null = not scanned yet; {count, branches, kinds, scannedAt} after a scan.
  const [pubCycleAlert, setPubCycleAlert] = useState(null);
  // Leave-balance anchor freshness. The hub computes balances from payroll's
  // last uploaded figures (opening + accrual − taken), so they only stay
  // trustworthy while the upload keeps pace with Sage's payroll runs. The habit
  // is meant to be monthly; the dashboard card nags when a run has closed
  // without one. null = not checked yet; {stale, cyclesBehind, asOf} after.
  // (The scan effect lives further down — it needs leaveBalancesCfg, which is
  // declared below this point.)
  const [balAnchorAlert, setBalAnchorAlert] = useState(null);
  const _summarizePendingRows = (rows) => {
    // Placeholder rows (codes with no employee record) are excluded — the
    // modal pre-unchecks them, and they shouldn't nag anyone to publish.
    const real = (rows || []).filter(r => r && !r.isPlaceholder);
    const branches = {}, kinds = {};
    real.forEach(r => {
      branches[r.branch] = 1;
      kinds[r.changeType] = (kinds[r.changeType] || 0) + 1;
    });
    return { count: real.length, branches: Object.keys(branches).length, kinds, scannedAt: Date.now() };
  };
  useEffect(() => {
    if (tab !== "dashboard") return;
    const _senior = currentUser?.isOwner || (currentUser?.role || "").toLowerCase().includes("national");
    if (!_senior) return;
    // Names must be loaded first, or every row misreads as a placeholder
    // (isPlaceholder = no resolvable name) and the alert under-counts.
    if (!((staff && staff.length) || (managers && managers.length))) return;
    if (pubCycleAlert && Date.now() - pubCycleAlert.scannedAt < 5 * 60 * 1000) return;   // throttle re-scans
    if (!window.BOA_DB || !window.BOA_DB.loadCycleScheduleGrids) return;
    let cancelled = false;
    (async () => {
      try {
        const techYm = window.BOA_DB.currentSchedYm();
        const mgrYm = window.BOA_DB.currentAttYm();
        const p2 = n => String(n).padStart(2, "0");
        const ymd = d => d.getFullYear() + "-" + p2(d.getMonth() + 1) + "-" + p2(d.getDate());
        const now = new Date();
        const cs = _cycleStartDate(now);
        const ce = new Date(cs.getFullYear(), cs.getMonth() + 1, 24);
        const surfaces = await window.BOA_DB.loadCycleScheduleGrids(techYm, mgrYm);
        const rows = computeCyclePendingRows(surfaces, {
          techYm, cycStart: ymd(cs), cycEnd: ymd(ce), todayYmd: ymd(now),
          nameFor: (ec) => _pubCycleNameMap[_normEc(ec)] || null
        });
        if (!cancelled) setPubCycleAlert(_summarizePendingRows(rows));
      } catch (e) {
        console.warn("[publish alert] scan failed (non-fatal):", e);
        if (!cancelled) setPubCycleAlert({ count: 0, branches: 0, kinds: {}, scannedAt: Date.now() });
      }
    })();
    return () => { cancelled = true; };
  }, [tab, currentUser, pubCycleAlert, _pubCycleNameMap, staff, managers]);

  // Scan every branch's draft-vs-published for the current cycle and open the
  // review modal. Mirrors SQL Q7 — see computeCyclePendingRows.
  const openPublishCycle = async () => {
    setPubCycleErr(""); setPubCycleRows(null); setPubCycleSkip({});
    setPubCycleOpen(true); setPubCycleBusy(true);
    try {
      if (!window.BOA_DB || !window.BOA_DB.loadCycleScheduleGrids) {
        throw new Error("This deploy doesn't have the cycle-scan API yet — redeploy data.js.");
      }
      const techYm = window.BOA_DB.currentSchedYm();   // END-month ym (tech grids)
      const mgrYm = window.BOA_DB.currentAttYm();      // START-month ym (mgr grids)
      const p2 = n => String(n).padStart(2, "0");
      const ymd = d => d.getFullYear() + "-" + p2(d.getMonth() + 1) + "-" + p2(d.getDate());
      const now = new Date();
      const cs = _cycleStartDate(now);
      const ce = new Date(cs.getFullYear(), cs.getMonth() + 1, 24);
      const surfaces = await window.BOA_DB.loadCycleScheduleGrids(techYm, mgrYm);
      const rows = computeCyclePendingRows(surfaces, {
        techYm, cycStart: ymd(cs), cycEnd: ymd(ce), todayYmd: ymd(now),
        nameFor: (ec) => _pubCycleNameMap[_normEc(ec)] || null
      });
      // Safety default: pre-uncheck placeholder rows (a code with no employee
      // record — e.g. T002 draft slots or the B563M relabel ghost) so a blind
      // "publish all" can never push them. The user can re-check individually.
      const initSkip = {};
      rows.forEach(r => { if (r.isPlaceholder) initSkip[r.id] = true; });
      setPubCycleSkip(initSkip);
      setPubCycleRows(rows);
      setPubCycleAlert(_summarizePendingRows(rows));   // keep the dashboard alert in step with the fresh scan
    } catch (e) {
      setPubCycleErr(e && e.message ? e.message : String(e));
      setPubCycleRows([]);
    } finally { setPubCycleBusy(false); }
  };

  // Publish the SELECTED pending changes by patching each affected published
  // snapshot in place (patchApprovedSnapshotGrid preserves pins / loans /
  // custom-hours — never a full republish). Grouped one patch per surface.
  const doPublishCycle = async () => {
    const chosen = (pubCycleRows || []).filter(r => !pubCycleSkip[r.id]);
    if (!chosen.length) { alert("Nothing selected — every row is unchecked."); return; }
    const loanRows = chosen.filter(r => r.needsLoanRecord);
    if (loanRows.length && !window.confirm(
      loanRows.length + " loan-out day" + (loanRows.length === 1 ? "" : "s") +
      " will be published. A loan-out only shows the HOME branch — you must still add the matching loan record (from → to) on each so a later re-publish can't double-book them.\n\nPublish anyway?")) return;
    setPubCycleBusy(true);
    try {
      const groups = {};
      chosen.forEach(r => {
        const k = (r.isMgr ? "m" : "t") + "|" + r.branch + "|" + r.ym;
        (groups[k] = groups[k] || { isMgr: r.isMgr, branch: r.branch, ym: r.ym, cells: [] }).cells.push(r);
      });
      let okSurfaces = 0; const notPublished = [];
      const _mgrCacheUpdates = {};   // branch|ym -> patched manager snapshot grid
      for (const k of Object.keys(groups)) {
        const g = groups[k];
        let _patchedGrid = null;
        const applied = await patchApprovedSnapshotGrid(g.branch, g.ym, g.isMgr, (grid) => {
          let changed = false;
          g.cells.forEach(r => {
            const want = _normEc(r.ec);
            const ecKey = Object.keys(grid).find(kk => _normEc(kk) === want) || String(r.ec).trim();
            const row = grid[ecKey] || (grid[ecKey] = {});
            let wk;
            if (r.isMgr) { wk = r.cal; }
            else {
              const n = String(parseInt(r.cellKey, 10));
              const pad = n.length === 1 ? "0" + n : n;
              wk = (row[pad] !== undefined && row[n] === undefined) ? pad : n;
            }
            if (row[wk] !== r.draftCode) { row[wk] = r.draftCode; changed = true; }
          });
          if (changed) _patchedGrid = grid;   // reference to the just-mutated snapshot grid
          return changed;
        });
        if (applied) {
          okSurfaces++;
          // Keep Manager Coverage's in-memory snapshot cache in lock-step so the
          // "Unpublished changes" badge + no-show scanners judge against THIS
          // publish immediately — same cache the branch-level publish refreshes
          // (app.jsx:34894). Manager surfaces only; tech viewers read the DB
          // snapshot directly, no portal cache to update.
          if (g.isMgr && _patchedGrid) _mgrCacheUpdates[g.branch + "|" + g.ym] = JSON.parse(JSON.stringify(_patchedGrid));
        } else notPublished.push(g.branch + (g.isMgr ? " · mgr" : " · tech"));
      }
      if (Object.keys(_mgrCacheUpdates).length) setMgrApprovedFallbackCache(prev => ({ ...prev, ..._mgrCacheUpdates }));
      try { await logActivity("Published current cycle", chosen.length + " change" + (chosen.length === 1 ? "" : "s"), "Patched " + okSurfaces + " published snapshot" + (okSurfaces === 1 ? "" : "s"), "Schedule"); } catch (_e) { }
      alert("✓ Published " + chosen.length + " change" + (chosen.length === 1 ? "" : "s") + " across " + okSurfaces + " schedule" + (okSurfaces === 1 ? "" : "s") + "." +
        (notPublished.length ? "\n\n⚠ Skipped (cycle has no published snapshot yet — use that branch's own Approve & Publish): " + notPublished.join(", ") : ""));
      // Whatever stayed unchecked is still pending — the dashboard alert
      // shows the remainder instead of waiting for the next throttled scan.
      setPubCycleAlert(_summarizePendingRows((pubCycleRows || []).filter(r => pubCycleSkip[r.id] && !r.isPlaceholder)));
      setPubCycleOpen(false); setPubCycleRows(null); setPubCycleSkip({});
    } catch (e) {
      alert("Publish failed: " + (e && e.message ? e.message : e));
    } finally { setPubCycleBusy(false); }
  };
  // Most-recent-approved schedule cache for the Manager Coverage tab,
  // used as a fallback when the working draft grid has no entry for a
  // manager — keyed `<branch>|<ym>` like mgrClockinSchedCache.
  const [mgrApprovedFallbackCache, setMgrApprovedFallbackCache] = useState({});
  // Tolerant EC-row lookup for a schedule grid — matches a legacy/dash/space
  // key ("B941-M") to the current code ("B941M") the way _canonicalizeGrid does
  // for the editor, so a snapshot row keyed under an old code is still found.
  const _gridEcRow = (grid, ec) => {
    if (!grid || ec == null) return undefined;
    if (grid[ec]) return grid[ec];
    const want = String(ec).replace(/[^A-Za-z0-9]/g, "").toUpperCase();
    const k = Object.keys(grid).find(kk => String(kk).replace(/[^A-Za-z0-9]/g, "").toUpperCase() === want);
    return k ? grid[k] : undefined;
  };
  // Single accessor for the manager no-show scanners: judge "expected to work"
  // against what staff SAW — the published snapshot — and fall back to the draft
  // ONLY when the cycle was never published (a null OR truthy-but-empty snapshot
  // grid must not mask a populated draft). One place so the next scanner added
  // can't reintroduce the draft-first read this plan exists to kill.
  const mgrPublishedFirstGrid = (branch, ym) => {
    const k = (branch || "") + "|" + ym;
    const pub = mgrApprovedFallbackCache[k];
    if (pub && Object.keys(pub).length > 0) return pub;
    return mgrClockinSchedCache[k];
  };
  // Per-user custom branch groupings for the Manager Coverage tab. Lets a
  // ROM organise stores into clusters that make sense for their region
  // (e.g. "Cape Town city bowl", "Southern suburbs"). Falls back to the
  // built-in region grouping (WC / Gauteng / KZN) when the user hasn't
  // defined any groups yet. Stored per signed-in user PIN.
  const [mgrCoverageGroups, setMgrCoverageGroups] = useState(null);   // null = loading; [] = none; [{id,name,branches:[]}]
  const [mgrCoverageGroupsEditor, setMgrCoverageGroupsEditor] = useState(null);   // null = closed; {groups, newName}
  // Cell-edit popover on the Manager Coverage view. Lets a ROM change a
  // shift code or loan the manager to another store for that day.
  const [mgrCellEditor, setMgrCellEditor] = useState(null);     // null | { branch, mgrYm, ec, name, role, ymd, dom, currentCell }
  // Loaded manager loan records, keyed for fast (ec,date) lookup. Refreshed
  // when the coverage tab opens and whenever a save completes.
  const [mgrLoanRows, setMgrLoanRows] = useState([]);
  // Extra-Day (ED) offers + claim requests (boa_mgr_ed_offers_v1 /
  // boa_mgr_ed_requests_v1). Offers are published from Manager Coverage; managers
  // claim them on the kiosk; Owner/National-Ops review + approve on the dashboard.
  const [edOffers, setEdOffers] = useState([]);
  const [edRequests, setEdRequests] = useState([]);
  const [edPublish, setEdPublish] = useState(null);   // null = closed | { branch, date, shiftCode, start, end, note, busy, err }
  const [edEdit, setEdEdit] = useState(null);         // null = closed | { id, date, shiftCode, start, end, note } — amend an open offer
  const [edBusy, setEdBusy] = useState(false);
  // Soft in-app confirm/alert driving <AlertModal/> — replaces the native
  // window.confirm/alert for the extra-day flows. askConfirm/notify return a
  // Promise so they slot straight into the async handlers; resolveUiDialog
  // fires the stored resolver and clears the dialog.
  const [uiDialog, setUiDialog] = useState(null);
  const askConfirm = (opts) => new Promise((resolve) => setUiDialog({ kind: "confirm", _resolve: resolve, ...opts }));
  const notify = (opts) => new Promise((resolve) => setUiDialog({ kind: "alert", _resolve: resolve, ...opts }));
  const resolveUiDialog = (val) => setUiDialog((d) => { if (d && d._resolve) d._resolve(val); return null; });
  // Kiosk "Daily Updates" feed (boa_news_v1) — loaded so owners can prune stale
  // posts. null = not yet loaded.
  const [newsPosts, setNewsPosts] = useState(null);
  const refreshNews = async () => {
    if (!window.BOA_DB || !window.BOA_DB.loadByKey) return;
    try { const v = await window.BOA_DB.loadByKey("boa_news_v1"); setNewsPosts(Array.isArray(v) ? v : []); }
    catch (e) { console.warn("Failed to load news:", e); setNewsPosts([]); }
  };
  useEffect(() => { refreshNews(); }, []);
  const deleteNewsPost = async (post) => {
    const ok = await askConfirm({ tone: "danger", icon: "🗑", title: "Remove this update?", body: "Delete this Daily Updates post from the kiosk?\n\n“" + (post.body || "") + "”", confirmLabel: "Remove", cancelLabel: "Keep it" });
    if (!ok) return;
    try {
      const v = (await window.BOA_DB.loadByKey("boa_news_v1")) || [];
      const next = (Array.isArray(v) ? v : []).filter(n => !(n && n.ts === post.ts && n.body === post.body));
      await window.BOA_DB.saveByKey("boa_news_v1", next);
      setNewsPosts(next);
    } catch (e) { notify({ tone: "danger", title: "Could not remove", body: String((e && e.message) || e) }); }
  };
  const clearAllNews = async () => {
    const ok = await askConfirm({ tone: "danger", icon: "🗑", title: "Clear all updates?", body: "Remove every Daily Updates post from the kiosk feed? This can't be undone.", confirmLabel: "Clear all", cancelLabel: "Cancel" });
    if (!ok) return;
    try { await window.BOA_DB.saveByKey("boa_news_v1", []); setNewsPosts([]); }
    catch (e) { notify({ tone: "danger", title: "Could not clear", body: String((e && e.message) || e) }); }
  };
  // Manager Coverage DRAFT mode. Drag-and-drop and popover edits write
  // here first; nothing is persisted until the ROM clicks "Apply to live"
  // on the banner at the top of the coverage tab. Shape:
  //   mgrCoverageDraft       = { "<branch>|<ym>": { [ec]: { [dom]: code|"" } } }
  //   mgrCoverageDraftLoans  = [{ _op:"upsert"|"remove", ec, name, date, fromBranch, toBranch, note }]
  const [mgrCoverageDraft, setMgrCoverageDraft] = useState({});
  const [mgrCoverageDraftLoans, setMgrCoverageDraftLoans] = useState([]);
  const [mgrCoverageDraftApplying, setMgrCoverageDraftApplying] = useState(false);
  // Manual per-day manager shift-hour overrides (e.g. open early / stay to
  // close when cover falls short). Live map loaded from boa_mgr_times_v1;
  // draft staged alongside the coverage draft and committed by "Apply to
  // live". Shape (both): { [ec]: { "YYYY-MM-DD": "HH:MM - HH:MM" } }; a ""
  // value in the draft means "clear this override on apply".
  const [mgrCustomTimes, setMgrCustomTimes] = useState({});
  const [mgrCustomTimesDraft, setMgrCustomTimesDraft] = useState({});
  // Pinned manager shift codes — { [ec]: { "YYYY-MM-DD": "WL" } }. A pin
  // forces ONE cell to a chosen WE/WM/WL/WB variant, overlaid AFTER the
  // auto-labeller, so it changes only that cell. `mgrShiftPins` is the
  // saved/live map (used by Coverage); `mgrShiftPinsDraft` holds the
  // schedule-tab's pending edits (a "" value means "clear this pin"),
  // merged on top at render and persisted by the schedule Save button.
  const [mgrShiftPins, setMgrShiftPins] = useState({});
  const [mgrShiftPinsDraft, setMgrShiftPinsDraft] = useState({});
  // Open shift-picker popover on the manager Scheduling grid: { ec, d, name, x, y }.
  const [mgrShiftMenu, setMgrShiftMenu] = useState(null);
  // When the first pending coverage change was staged. Drafts are a pure
  // browser-tab preview — Manager Coverage shows them, but the kiosk / myboa /
  // Scheduling keep the saved state, so a draft left unapplied for hours makes
  // every other screen look "wrong" (this is exactly what happened with
  // Nicole's Riverlands shifts). Used to escalate the Apply banner and to warn
  // before the tab closes (closing silently discards the draft).
  const [mgrCoverageDraftSince, setMgrCoverageDraftSince] = useState(null);
